### Part 1: Vue 3 Frontend Implementation

Replace the content of `src/App.vue` in your Vue project with the following code.

**`src/App.vue`**

```vue
<template>
  <div class="uploader-container">
    <h1>Large File Upload with Breakpoint Continuation</h1>
    <div class="uploader-panel">
      <input type="file" @change="handleFileChange" :disabled="status !== 'wait'" />

      <div class="button-group">
        <button @click="handleUpload" :disabled="!file || status === 'uploading' || status === 'done'">Upload</button>
        <button @click="handlePause" v-if="status === 'uploading'">Pause</button>
        <button @click="handleResume" v-if="status === 'paused'">Resume</button>
      </div>

      <div class="progress-container" v-if="file">
        <p><strong>File:</strong> {{ file.name }}</p>
        <p><strong>Status:</strong> {{ statusText }}</p>
        <p><strong>File Hash:</strong> {{ fileHash }}</p>
        <div class="total-progress-bar">
          <div class="progress" :style="{ width: totalProgress + '%' }"></div>
        </div>
        <span>{{ totalProgress.toFixed(2) }}%</span>
      </div>

      <div class="chunk-list" v-if="chunks.length > 0">
        <h3>Chunks Status</h3>
        <table>
          <thead>
            <tr>
              <th>Chunk Index</th>
              <th>Size (KB)</th>
              <th>Status</th>
              <th>Progress</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="chunk in chunks" :key="chunk.hash">
              <td>{{ chunk.index }}</td>
              <td>{{ (chunk.chunk.size / 1024).toFixed(2) }}</td>
              <td :class="chunk.status">{{ chunk.status }}</td>
              <td>
                <div class="chunk-progress-bar">
                  <div class="progress" :style="{ width: chunk.progress + '%' }"></div>
                </div>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue';
import axios from 'axios';
import SparkMD5 from 'spark-md5';

// --- Constants and State ---
const API_BASE_URL = 'http://localhost:3000';
const CHUNK_SIZE = 5 * 1024 * 1024; // 5MB

const file = ref(null);
const status = ref('wait'); // wait, uploading, paused, done, error
const chunks = ref([]);
const fileHash = ref('');
const totalProgress = ref(0);

// Abort controllers for pausing requests
let requestControllers = [];

// --- Computed Properties ---
const statusText = computed(() => {
  switch (status.value) {
    case 'wait': return 'Waiting for file selection';
    case 'uploading': return 'Uploading...';
    case 'paused': return 'Paused';
    case 'done': return 'Upload complete!';
    case 'error': return 'An error occurred';
    default: return 'Idle';
  }
});

// --- Core Functions ---

/**
 * Handles the file input change event.
 */
const handleFileChange = (e) => {
  const selectedFile = e.target.files[0];
  if (!selectedFile) return;

  resetState();
  file.value = selectedFile;
};

/**
 * Resets the component state to its initial values.
 */
const resetState = () => {
  file.value = null;
  status.value = 'wait';
  chunks.value = [];
  fileHash.value = '';
  totalProgress.value = 0;
  cancelAllRequests();
};

/**
 * Creates file chunks based on the CHUNK_SIZE.
 */
const createChunks = () => {
  if (!file.value) return;
  const chunkList = [];
  let start = 0;
  let index = 0;
  while (start < file.value.size) {
    const end = Math.min(start + CHUNK_SIZE, file.value.size);
    const chunk = file.value.slice(start, end);
    chunkList.push({
      chunk,
      index,
      hash: `${fileHash.value}-${index}`,
      size: chunk.size,
      progress: 0,
      status: 'wait', // wait, uploading, done, error
    });
    start += CHUNK_SIZE;
    index++;
  }
  chunks.value = chunkList;
};

/**
 * Calculates the MD5 hash of the file incrementally.
 * @returns {Promise<string>} The calculated file hash.
 */
const calculateHash = () => {
  return new Promise((resolve, reject) => {
    if (!file.value) {
      reject('No file selected');
      return;
    }

    const spark = new SparkMD5.ArrayBuffer();
    const reader = new FileReader();
    const totalChunks = Math.ceil(file.value.size / CHUNK_SIZE);
    let currentChunk = 0;

    reader.onload = (e) => {
      spark.append(e.target.result);
      currentChunk++;

      if (currentChunk < totalChunks) {
        loadNext();
      } else {
        const hash = spark.end();
        fileHash.value = hash;
        resolve(hash);
      }
    };

    reader.onerror = (e) => reject(e);

    function loadNext() {
      const start = currentChunk * CHUNK_SIZE;
      const end = Math.min(start + CHUNK_SIZE, file.value.size);
      reader.readAsArrayBuffer(file.value.slice(start, end));
    }

    loadNext();
  });
};

/**
 * Main upload handler.
 */
const handleUpload = async () => {
  if (!file.value) {
    alert('Please select a file first!');
    return;
  }

  status.value = 'uploading';

  try {
    // 1. Calculate hash if not already calculated
    if (!fileHash.value) {
      await calculateHash();
    }

    // 2. Create chunks
    createChunks();

    // 3. Verify which chunks are already on the server
    const { uploadedChunks } = await verifyUpload(file.value.name, fileHash.value);

    // 4. Filter out chunks that are already uploaded
    const chunksToUpload = chunks.value.filter(chunk => {
      if (uploadedChunks.includes(chunk.hash)) {
        chunk.progress = 100;
        chunk.status = 'done';
        return false;
      }
      return true;
    });

    updateTotalProgress();

    if (chunksToUpload.length === 0) {
      await mergeChunks();
      return;
    }

    // 5. Upload remaining chunks concurrently
    await uploadChunks(chunksToUpload);

  } catch (error) {
    console.error('Upload failed:', error);
    status.value = 'error';
  }
};

/**
 * Uploads chunks with concurrency control.
 * @param {Array} chunksToUpload - The list of chunks to upload.
 */
const uploadChunks = async (chunksToUpload) => {
  const CONCURRENCY_LIMIT = 4;
  const queue = [...chunksToUpload];
  let inFlight = 0;

  const processQueue = async () => {
    while (queue.length > 0 && inFlight < CONCURRENCY_LIMIT) {
      inFlight++;
      const chunk = queue.shift();
      if (!chunk) continue;

      try {
        await uploadSingleChunk(chunk);
      } catch (error) {
        // If a chunk fails, put it back in the queue to retry later
        // Or handle the error more gracefully
        chunk.status = 'error';
        console.error(`Failed to upload chunk ${chunk.index}`, error);
      } finally {
        inFlight--;
        processQueue(); // Process next in queue
      }
    }

    if (queue.length === 0 && inFlight === 0) {
      // All chunks processed, check if all are 'done'
      if (chunks.value.every(c => c.status === 'done')) {
        await mergeChunks();
      }
    }
  };

  // Start processing
  processQueue();
};

/**
 * Uploads a single chunk to the server.
 * @param {object} chunk - The chunk object.
 */
const uploadSingleChunk = (chunk) => {
  return new Promise((resolve, reject) => {
    const formData = new FormData();
    formData.append('chunk', chunk.chunk);
    formData.append('hash', chunk.hash);
    formData.append('fileHash', fileHash.value);

    const controller = new AbortController();
    requestControllers.push(controller);
    chunk.status = 'uploading';

    axios.post(`${API_BASE_URL}/upload`, formData, {
      signal: controller.signal,
      onUploadProgress: (progressEvent) => {
        const percent = (progressEvent.loaded / progressEvent.total) * 100;
        chunk.progress = percent;
        updateTotalProgress();
      },
    }).then(response => {
      chunk.status = 'done';
      resolve(response.data);
    }).catch(error => {
      if (axios.isCancel(error)) {
        console.log(`Upload of chunk ${chunk.index} canceled.`);
        chunk.status = 'paused';
      } else {
        chunk.status = 'error';
        console.error(`Error uploading chunk ${chunk.index}:`, error);
      }
      reject(error);
    }).finally(() => {
      // Remove controller from the list
      requestControllers = requestControllers.filter(c => c !== controller);
    });
  });
};

/**
 * Asks the server which chunks have already been uploaded.
 * @param {string} fileName - The name of the file.
 * @param {string} fileHash - The hash of the file.
 * @returns {Promise<object>} Server response with uploaded chunks.
 */
const verifyUpload = async (fileName, fileHash) => {
  const { data } = await axios.post(`${API_BASE_URL}/verify`, { fileName, fileHash });
  return data;
};

/**
 * Sends a request to the server to merge the uploaded chunks.
 */
const mergeChunks = async () => {
  try {
    await axios.post(`${API_BASE_URL}/merge`, {
      fileName: file.value.name,
      fileHash: fileHash.value,
      chunkSize: CHUNK_SIZE,
    });
    status.value = 'done';
  } catch (error) {
    console.error('Merge failed:', error);
    status.value = 'error';
  }
};

/**
 * Updates the total upload progress based on individual chunk progress.
 */
const updateTotalProgress = () => {
  if (!file.value) return;
  const totalUploadedSize = chunks.value
    .map(chunk => chunk.size * (chunk.progress / 100))
    .reduce((acc, cur) => acc + cur, 0);

  totalProgress.value = (totalUploadedSize / file.value.size) * 100;
};

/**
 * Pauses the upload by canceling ongoing requests.
 */
const handlePause = () => {
  status.value = 'paused';
  cancelAllRequests();
};

/**
 * Resumes the upload. The `handleUpload` function will automatically
 * verify and upload only the missing chunks.
 */
const handleResume = () => {
  status.value = 'uploading';
  handleUpload();
};

/**
 * Cancels all in-flight axios requests.
 */
const cancelAllRequests = () => {
  requestControllers.forEach(controller => controller.abort());
  requestControllers = [];
};

</script>

