### Part 2: Node.js Backend Implementation

In the `server` directory, create the `server.js` file with the following content.

**`server/server.js`**

```javascript
const express = require('express');
const multer = require('multer');
const cors = require('cors');
const path = require('path');
const fs = require('fs-extra');

const app = express();
const PORT = 3000;

// --- Paths ---
const UPLOAD_DIR = path.join(__dirname, 'uploads'); // For chunks
const FINAL_DIR = path.join(__dirname, 'final_uploads'); // For merged files

// Ensure directories exist
fs.ensureDirSync(UPLOAD_DIR);
fs.ensureDirSync(FINAL_DIR);

// --- Middleware ---
app.use(cors());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Multer setup for handling file uploads
const upload = multer({ dest: UPLOAD_DIR });

// --- API Endpoints ---

/**
 * POST /verify
 * Checks which chunks for a given file hash already exist on the server.
 */
app.post('/verify', async (req, res) => {
  const { fileName, fileHash } = req.body;
  const chunkDir = path.join(UPLOAD_DIR, fileHash);

  try {
    // Check if the final file already exists
    const finalFilePath = path.join(FINAL_DIR, fileName);
    if (await fs.pathExists(finalFilePath)) {
      return res.json({
        shouldUpload: false,
        message: 'File already exists.',
      });
    }

    // Check for existing chunks
    if (await fs.pathExists(chunkDir)) {
      const uploadedChunks = await fs.readdir(chunkDir);
      return res.json({
        shouldUpload: true,
        uploadedChunks,
      });
    }

    // No chunks found, proceed with new upload
    res.json({
      shouldUpload: true,
      uploadedChunks: [],
    });
  } catch (error) {
    console.error('Error in /verify:', error);
    res.status(500).send('Server error during verification.');
  }
});

/**
 * POST /upload
 * Receives a single file chunk and saves it.
 */
app.post('/upload', upload.single('chunk'), async (req, res) => {
  const { hash, fileHash } = req.body;
  const chunk = req.file;

  if (!chunk) {
    return res.status(400).send('No chunk uploaded.');
  }

  const chunkDir = path.join(UPLOAD_DIR, fileHash);
  await fs.ensureDir(chunkDir);
  const chunkPath = path.join(chunkDir, hash);

  try {
    // Move the temporary file to the correct chunk path
    await fs.move(chunk.path, chunkPath, { overwrite: true });
    res.status(200).send('Chunk uploaded successfully.');
  } catch (error) {
    console.error('Error in /upload:', error);
    res.status(500).send('Error saving chunk.');
  }
});

/**
 * POST /merge
 * Merges all chunks for a given file hash into a single file.
 */
app.post('/merge', async (req, res) => {
  const { fileName, fileHash, chunkSize } = req.body;
  const chunkDir = path.join(UPLOAD_DIR, fileHash);
  const finalFilePath = path.join(FINAL_DIR, fileName);

  try {
    const chunkFiles = await fs.readdir(chunkDir);
    if (chunkFiles.length === 0) {
      return res.status(400).send('No chunks found to merge.');
    }

    // Sort chunks by their index number
    chunkFiles.sort((a, b) => {
      const indexA = parseInt(a.split('-').pop(), 10);
      const indexB = parseInt(b.split('-').pop(), 10);
      return indexA - indexB;
    });

    // Create a write stream for the final file
    const writeStream = fs.createWriteStream(finalFilePath);

    // Sequentially read each chunk and pipe it to the write stream
    for (const chunkFile of chunkFiles) {
      const chunkPath = path.join(chunkDir, chunkFile);
      const readStream = fs.createReadStream(chunkPath);
      await new Promise((resolve, reject) => {
        readStream.pipe(writeStream, { end: false });
        readStream.on('end', resolve);
        readStream.on('error', reject);
      });
      // Optionally, you can remove the chunk after it's been written
      // await fs.unlink(chunkPath); 
    }

    writeStream.end();

    // Clean up the chunk directory
    await fs.remove(chunkDir);

    res.status(200).json({ message: 'File merged successfully.' });
  } catch (error) {
    console.error('Error in /merge:', error);
    res.status(500).send('Error merging chunks.');
  }
});

// --- Start Server ---
app.listen(PORT, () => {
  console.log(`Server is running on http://localhost:${PORT}`);
});
```

