#### **`HikvisionSwingDemo.java` - Main Application**

This class ties everything together. It creates the GUI, handles SDK initialization, login, and defines the callback logic for processing video frames.

```java
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferByte;
import java.awt.image.DataBufferInt;
import com.sun.jna.Pointer;

public class HikvisionSwingDemo {

    private static HCNetSDK sdk = HCNetSDK.INSTANCE;
    private int lUserID = -1;
    private int lRealPlayHandle = -1;
    private VideoPanel videoPanel;

    // --- Configuration ---
    private static final String CAMERA_IP = "192.168.1.64"; // Your camera IP
    private static final short CAMERA_PORT = 8000;
    private static final String CAMERA_USER = "admin";
    private static final String CAMERA_PASS = "your_password";
    private static final int CHANNEL = 1;

    // --- Frame dimensions (must be known or retrieved from SDK) ---
    // For simplicity, we hardcode them. A real app might get this from stream info.
    private static final int FRAME_WIDTH = 1920;
    private static final int FRAME_HEIGHT = 1080;

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new HikvisionSwingDemo().createAndShowGUI());
    }

    private void createAndShowGUI() {
        JFrame frame = new JFrame("Hikvision Linux Swing Demo");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setSize(800, 600);

        videoPanel = new VideoPanel();
        videoPanel.setBackground(Color.BLACK);
        frame.add(videoPanel, BorderLayout.CENTER);

        JPanel controlPanel = new JPanel();
        JButton startButton = new JButton("Start");
        JButton stopButton = new JButton("Stop");
        controlPanel.add(startButton);
        controlPanel.add(stopButton);
        frame.add(controlPanel, BorderLayout.SOUTH);

        // Initialize SDK
        if (!sdk.NET_DVR_Init()) {
            System.err.println("SDK Initialization failed. Error code: " + sdk.NET_DVR_GetLastError());
            JOptionPane.showMessageDialog(frame, "SDK Initialization Failed!", "Error", JOptionPane.ERROR_MESSAGE);
            return;
        }
        System.out.println("SDK Initialized successfully.");

        startButton.addActionListener(e -> startPreview());
        stopButton.addActionListener(e -> stopPreview());

        frame.addWindowListener(new java.awt.event.WindowAdapter() {
            @Override
            public void windowClosing(java.awt.event.WindowEvent windowEvent) {
                stopPreview();
                sdk.NET_DVR_Cleanup();
                System.out.println("SDK Cleaned up.");
            }
        });

        frame.setLocationRelativeTo(null);
        frame.setVisible(true);
    }

    private void login() {
        if (lUserID >= 0) {
            return; // Already logged in
        }

        HCNetSDK.NET_DVR_DEVICEINFO_V30 deviceInfo = new HCNetSDK.NET_DVR_DEVICEINFO_V30();
        lUserID = sdk.NET_DVR_Login_V30(CAMERA_IP, CAMERA_PORT, CAMERA_USER, CAMERA_PASS, deviceInfo);

        if (lUserID < 0) {
            System.err.println("Login failed. Error code: " + sdk.NET_DVR_GetLastError());
            JOptionPane.showMessageDialog(null, "Login Failed!", "Error", JOptionPane.ERROR_MESSAGE);
        } else {
            System.out.println("Login successful. UserID: " + lUserID);
            System.out.println("Device Serial Number: " + new String(deviceInfo.sSerialNumber).trim());
        }
    }

    private void startPreview() {
        if (lUserID < 0) {
            login();
            if (lUserID < 0) return;
        }

        if (lRealPlayHandle >= 0) {
            System.out.println("Preview is already running.");
            return;
        }

        HCNetSDK.NET_DVR_PREVIEWINFO previewInfo = new HCNetSDK.NET_DVR_PREVIEWINFO();
        previewInfo.lChannel = CHANNEL;
        previewInfo.dwStreamType = 0; // 0: Main stream, 1: Sub stream
        previewInfo.dwLinkMode = 0;   // 0: TCP
        previewInfo.hPlayWnd = null;  // CRITICAL: Must be null on Linux for callback to work

        // The callback function that will process the video data
        HCNetSDK.FRealDataCallBack_V30 realDataCallBack = (lRealHandle, dwDataType, pBuffer, dwBufSize, pUser) -> {
            if (dwDataType == HCNetSDK.NET_DVR_STREAMDATA) {
                // The SDK on Linux often provides decoded YV12 data via this callback
                // when hPlayWnd is null. We need to convert YV12 to RGB.
                processYV12Frame(pBuffer, dwBufSize);
            }
        };

        lRealPlayHandle = sdk.NET_DVR_RealPlay_V40(lUserID, previewInfo, realDataCallBack, null);

        if (lRealPlayHandle < 0) {
            System.err.println("Real-time preview failed. Error code: " + sdk.NET_DVR_GetLastError());
            JOptionPane.showMessageDialog(null, "Preview Failed!", "Error", JOptionPane.ERROR_MESSAGE);
        } else {
            System.out.println("Real-time preview started. Handle: " + lRealPlayHandle);
        }
    }

    private void stopPreview() {
        if (lRealPlayHandle >= 0) {
            if (sdk.NET_DVR_StopRealPlay(lRealPlayHandle)) {
                System.out.println("Preview stopped.");
                lRealPlayHandle = -1;
            } else {
                System.err.println("Failed to stop preview. Error: " + sdk.NET_DVR_GetLastError());
            }
        }

        if (lUserID >= 0) {
            if (sdk.NET_DVR_Logout(lUserID)) {
                System.out.println("Logged out.");
                lUserID = -1;
            }
        }
    }

    private BufferedImage currentImage = new BufferedImage(FRAME_WIDTH, FRAME_HEIGHT, BufferedImage.TYPE_INT_RGB);

    private void processYV12Frame(Pointer pBuffer, int bufferSize) {
        // YV12 format: Y plane, then V plane, then U plane.
        // Size of Y plane = width * height
        // Size of U/V planes = (width/2) * (height/2) = width * height / 4
        int ySize = FRAME_WIDTH * FRAME_HEIGHT;
        if (bufferSize < ySize * 1.5) {
            // Not enough data for a full YV12 frame
            return;
        }

        byte[] yuvData = pBuffer.getByteArray(0, (int) (ySize * 1.5));
        int[] rgbData = ((DataBufferInt) currentImage.getRaster().getDataBuffer()).getData();

        convertYV12ToRGB(yuvData, rgbData, FRAME_WIDTH, FRAME_HEIGHT);

        // Update the panel on the Event Dispatch Thread
        SwingUtilities.invokeLater(() -> videoPanel.updateImage(currentImage));
    }

    /**
     * Converts a YV12 (YYYY...VV...UU...) byte array to an ARGB integer array.
     * This is a performance-critical section. For production, native code (JNI) would be faster.
     */
    public static void convertYV12ToRGB(byte[] yuv, int[] rgb, int width, int height) {
        int yPlaneSize = width * height;
        int uvPlaneSize = yPlaneSize / 4;

        int yIndex = 0;
        for (int j = 0; j < height; j++) {
            for (int i = 0; i < width; i++) {
                int uvIndex = yPlaneSize + (j / 2) * (width / 2) + (i / 2);
                int y = yuv[yIndex] & 0xff;
                int v = yuv[uvIndex] & 0xff;
                int u = yuv[uvIndex + uvPlaneSize] & 0xff;

                // Formula for YUV to RGB conversion
                y = y < 16 ? 16 : y;
                int c = y - 16;
                int d = u - 128;
                int e = v - 128;

                int r = (298 * c + 409 * e + 128) >> 8;
                int g = (298 * c - 100 * d - 208 * e + 128) >> 8;
                int b = (298 * c + 516 * d + 128) >> 8;

                // Clamp values to 0-255
                r = Math.max(0, Math.min(255, r));
                g = Math.max(0, Math.min(255, g));
                b = Math.max(0, Math.min(255, b));

                rgb[yIndex++] = 0xff000000 | (r << 16) | (g << 8) | b;
            }
        }
    }
}
