            top: 10px;
            right: 10px;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas"></canvas>
    <div id="ui-container">
        <div id="health-bar" class="ui-element">Health: 100</div>
        <div id="vehicle-status" class="ui-element">On Foot</div>
        <div id="mission-log" class="ui-element">
            <h3>Mission</h3>
            <p id="mission-text">Welcome! Explore the city.</p>
        </div>
    </div>

    <script>
    // --- CORE GAME SETUP ---
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');

    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    window.addEventListener('resize', () => {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
    });

    // --- UTILITY FUNCTIONS ---
    function distance(p1, p2) {
        return Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));
    }

    // --- GAME CLASSES ---

    // Represents any object with a position and size
    class Entity {
        constructor(x, y, width, height, color) {
            this.x = x;
            this.y = y;
            this.width = width;
            this.height = height;
            this.color = color;
        }

        draw(ctx) {
            ctx.fillStyle = this.color;
            ctx.fillRect(this.x - this.width / 2, this.y - this.height / 2, this.width, this.height);
        }
    }

    class Character extends Entity {
        constructor(x, y, color) {
            super(x, y, 20, 20, color);
            this.health = 100;
            this.speed = 2.5;
            this.currentVehicle = null;
            this.projectiles = [];
            this.shootCooldown = 0;
        }

        move(dx, dy) {
            if (this.currentVehicle) {
                this.currentVehicle.accelerate(dy);
                this.currentVehicle.turn(dx);
            } else {
                const magnitude = Math.sqrt(dx * dx + dy * dy);
                if (magnitude > 0) {
                    this.x += (dx / magnitude) * this.speed;
                    this.y += (dy / magnitude) * this.speed;
                }
            }
        }

        shoot(targetX, targetY) {
            if (this.shootCooldown <= 0) {
                const angle = Math.atan2(targetY - this.y, targetX - this.x);
                const projectile = new Projectile(this.x, this.y, angle, this);
                this.projectiles.push(projectile);
                this.shootCooldown = 30; // Cooldown in frames
            }
        }

        update() {
            if (this.shootCooldown > 0) this.shootCooldown--;
            if (this.currentVehicle) {
                this.x = this.currentVehicle.x;
                this.y = this.currentVehicle.y;
            }
        }

        takeDamage(amount) {
            this.health -= amount;
            if (this.health < 0) this.health = 0;
        }
    }

    class Player extends Character {
        constructor(x, y) {
            super(x, y, 'blue');
        }
    }

    class NPC extends Character {
        constructor(x, y) {
            super(x, y, 'red');
            this.aiState = 'wander'; // wander, attack, flee
            this.wanderTarget = { x: x, y: y };
            this.aiTimer = 0;
        }

        updateAI(player, world) {
            const distToPlayer = distance(this, player);

            if (this.aiState === 'flee' && this.currentVehicle === null) {
                // Flee logic
                const angleToPlayer = Math.atan2(player.y - this.y, player.x - this.x);
                this.move(-Math.cos(angleToPlayer), -Math.sin(angleToPlayer));
                if (distToPlayer > 400) this.aiState = 'wander'; // Stop fleeing if far enough
            } else if (distToPlayer < 300 && player.health > 0) {
                this.aiState = 'attack';
            } else {
                this.aiState = 'wander';
            }

            if (this.aiState === 'attack') {
                const angleToPlayer = Math.atan2(player.y - this.y, player.x - this.x);
                if (distToPlayer > 150) {
                    this.move(Math.cos(angleToPlayer), Math.sin(angleToPlayer));
                }
                this.shoot(player.x, player.y);
            } else if (this.aiState === 'wander') {
                this.aiTimer--;
                if (this.aiTimer <= 0) {
                    this.wanderTarget = {
                        x: this.x + (Math.random() - 0.5) * 200,
                        y: this.y + (Math.random() - 0.5) * 200
                    };
                    this.aiTimer = Math.random() * 180 + 60; // New target every 1-4 seconds
                }
                const distToTarget = distance(this, this.wanderTarget);
                if (distToTarget > this.speed) {
                    const angle = Math.atan2(this.wanderTarget.y - this.y, this.wanderTarget.x - this.x);
                    this.move(Math.cos(angle), Math.sin(angle));
                }
            }

            super.update();
        }
    }

    class Vehicle extends Entity {
        constructor(x, y, color) {
            super(x, y, 50, 30, color);
            this.driver = null;
            this.speed = 0;
            this.maxSpeed = 5;
            this.acceleration = 0.1;
            this.friction = 0.05;
            this.angle = 0;
            this.turnSpeed = 0.03;
        }

        enter(character) {
            if (!this.driver) {
                if (character.currentVehicle) {
                    character.currentVehicle.exit();
                }
                this.driver = character;
                character.currentVehicle = this;
                return true;
            }
            return false;
        }

        exit() {
            if (this.driver) {
                this.driver.x = this.x + this.width;
                this.driver.y = this.y;
                this.driver.currentVehicle = null;
                this.driver = null;
            }
        }

        accelerate(direction) {
            // direction > 0 is forward, < 0 is reverse
            if (direction > 0) {
                this.speed += this.acceleration;
            } else if (direction < 0) {
                this.speed -= this.acceleration * 0.5;
            }
        }

        turn(direction) {
            // direction > 0 is right, < 0 is left
            if (this.speed !== 0) {
                const turnFactor = Math.min(1, Math.abs(this.speed) / 2); // Slower turns at low speed
                this.angle += this.turnSpeed * direction * turnFactor;
            }
        }

        update() {
            // Apply friction
            if (this.speed > 0) {
                this.speed -= this.friction;
                if (this.speed < 0) this.speed = 0;
            } else if (this.speed < 0) {
                this.speed += this.friction;
                if (this.speed > 0) this.speed = 0;
            }

            // Clamp speed
            if (this.speed > this.maxSpeed) this.speed = this.maxSpeed;
            if (this.speed < -this.maxSpeed / 2) this.speed = -this.maxSpeed / 2;

            // Update position
            this.x += Math.cos(this.angle) * this.speed;
            this.y += Math.sin(this.angle) * this.speed;
        }

        draw(ctx) {
            ctx.save();
            ctx.translate(this.x, this.y);
            ctx.rotate(this.angle);
            ctx.fillStyle = this.color;
            ctx.fillRect(-this.width / 2, -this.height / 2, this.width, this.height);
            // Add a "windshield" to show direction
            ctx.fillStyle = 'lightblue';
            ctx.fillRect(this.width/4, -this.height/2, this.width/4, this.height);
            ctx.restore();
        }
    }

    class Projectile extends Entity {
        constructor(x, y, angle, owner) {
            super(x, y, 5, 5, 'yellow');
            this.speed = 10;
            this.vx = Math.cos(angle) * this.speed;
            this.vy = Math.sin(angle) * this.speed;
            this.owner = owner;
            this.lifespan = 120; // Frames
            this.damage = 10;
        }

        update() {
            this.x += this.vx;
            this.y += this.vy;
            this.lifespan--;
        }
    }

    class Camera {
        constructor(target, worldWidth, worldHeight) {
            this.target = target;
            this.worldWidth = worldWidth;
            this.worldHeight = worldHeight;
            this.x = 0;
            this.y = 0;
        }

        update() {
            this.x = this.target.x - canvas.width / 2;
            this.y = this.target.y - canvas.height / 2;

            // Clamp camera to world boundaries
            this.x = Math.max(0, Math.min(this.x, this.worldWidth - canvas.width));
            this.y = Math.max(0, Math.min(this.y, this.worldHeight - canvas.height));
        }

        applyTransform(ctx) {
            ctx.save();
            ctx.translate(-this.x, -this.y);
        }

        resetTransform(ctx) {
            ctx.restore();
        }
    }

    class Joystick {
        constructor(x, y, radius) {
            this.baseX = x;
            this.baseY = y;
            this.radius = radius;
            this.stickX = x;
            this.stickY = y;
            this.active = false;
            this.touchId = null;
            this.dx = 0;
            this.dy = 0;
        }

        handleTouch(e) {
            e.preventDefault();
            for (let i = 0; i < e.changedTouches.length; i++) {
                const touch = e.changedTouches[i];
                const dist = distance({x: touch.clientX, y: touch.clientY}, {x: this.baseX, y: this.baseY});

                if (e.type === 'touchstart' && !this.active && dist < this.radius * 2) {
                    this.active = true;
                    this.touchId = touch.identifier;
                }

                if (e.type === 'touchmove' && this.active && touch.identifier === this.touchId) {
                    const angle = Math.atan2(touch.clientY - this.baseY, touch.clientX - this.baseX);
                    const distFromCenter = Math.min(dist, this.radius);
                    this.stickX = this.baseX + Math.cos(angle) * distFromCenter;
                    this.stickY = this.baseY + Math.sin(angle) * distFromCenter;
                    this.dx = (this.stickX - this.baseX) / this.radius;
                    this.dy = (this.stickY - this.baseY) / this.radius;
                }

                if (e.type === 'touchend' && touch.identifier === this.touchId) {
                    this.active = false;
                    this.touchId = null;
                    this.stickX = this.baseX;
                    this.stickY = this.baseY;
                    this.dx = 0;
                    this.dy = 0;
                }
            }
        }

        draw(ctx) {
            // Draw base
            ctx.beginPath();
            ctx.arc(this.baseX, this.baseY, this.radius, 0, Math.PI * 2);
            ctx.fillStyle = 'rgba(128, 128, 128, 0.5)';
            ctx.fill();

            // Draw stick
            ctx.beginPath();
            ctx.arc(this.stickX, this.stickY, this.radius / 2, 0, Math.PI * 2);
            ctx.fillStyle = 'rgba(80, 80, 80, 0.8)';
            ctx.fill();
        }
    }

    class Mission {
        constructor(title, description, completionCheck) {
            this.title = title;
            this.description = description;
            this.isComplete = false;
            this.completionCheck = completionCheck;
        }

        update(gameState) {
            if (!this.isComplete && this.completionCheck(gameState)) {
                this.isComplete = true;
                console.log(`Mission "${this.title}" completed!`);
                return true; // Indicates completion this frame
            }
            return false;
        }
    }

    // --- MAIN GAME CLASS ---
    class Game {
        constructor() {
            this.worldWidth = 3000;
            this.worldHeight = 3000;

            this.player = new Player(this.worldWidth / 2, this.worldHeight / 2);
            this.camera = new Camera(this.player, this.worldWidth, this.worldHeight);
            this.joystick = new Joystick(100, canvas.height - 100, 50);

            this.npcs = [];
            this.vehicles = [];
            this.projectiles = [];
            this.missionMarkers = [];

            this.input = {
                keys: new Set(),
                isMobile: 'ontouchstart' in window
            };

            this.missions = [];
            this.currentMissionIndex = 0;

            this.setupEventListeners();
            this.initWorld();
        }

        initWorld() {
            // Spawn NPCs
            for (let i = 0; i < 10; i++) {
                const x = Math.random() * this.worldWidth;
                const y = Math.random() * this.worldHeight;
                this.npcs.push(new NPC(x, y));
            }

            // Spawn Vehicles
            for (let i = 0; i < 8; i++) {
                const x = Math.random() * this.worldWidth;
                const y = Math.random() * this.worldHeight;
                this.vehicles.push(new Vehicle(x, y, 'green'));
            }

            // Assign some NPCs to vehicles
            const npcsToGetCars = this.npcs.slice(0, 3);
            const availableVehicles = this.vehicles.slice(0, 3);
            npcsToGetCars.forEach((npc, i) => {
                if (availableVehicles[i]) {
                    availableVehicles[i].enter(npc);
                }
            });

            // Setup Missions
            const missionVehicle = new Vehicle(1000, 1000, 'purple');
            this.vehicles.push(missionVehicle);
            this.missionMarkers.push({x: 1800, y: 1800, radius: 50, color: 'rgba(255, 255, 0, 0.5)'});

            this.missions.push(new Mission(
                "Steal the Purple Car",
                "A special purple car is parked nearby. Get in it!",
                (state) => state.player.currentVehicle === missionVehicle
            ));
            this.missions.push(new Mission(
                "Reach the Destination",
                "Drive the car to the yellow marker on the map.",
                (state) => distance(state.player, this.missionMarkers[0]) < 50
            ));
            this.missions.push(new Mission(
                "Clear the Area",
                "You've been ambushed! Defeat all NPCs.",
                (state) => state.npcs.length === 0
            ));
            this.missions.push(new Mission(
                "Congratulations!",
                "You have completed all missions.",
                () => false // Never completes automatically
            ));
        }

        setupEventListeners() {
            // Keyboard
            window.addEventListener('keydown', (e) => this.input.keys.add(e.key.toLowerCase()));
            window.addEventListener('keyup', (e) => this.input.keys.delete(e.key.toLowerCase()));

            // Touch
            if (this.input.isMobile) {
                canvas.addEventListener('touchstart', (e) => this.joystick.handleTouch(e));
                canvas.addEventListener('touchmove', (e) => this.joystick.handleTouch(e));
                canvas.addEventListener('touchend', (e) => this.joystick.handleTouch(e));
            }
        }

        handleInput() {
            let dx = 0, dy = 0;

            if (this.input.isMobile) {
                dx = this.joystick.dx;
                dy = this.joystick.dy;
            } else {
                if (this.input.keys.has('w') || this.input.keys.has('arrowup')) dy = -1;
                if (this.input.keys.has('s') || this.input.keys.has('arrowdown')) dy = 1;
                if (this.input.keys.has('a') || this.input.keys.has('arrowleft')) dx = -1;
                if (this.input.keys.has('d') || this.input.keys.has('arrowright')) dx = 1;
            }

            this.player.move(dx, dy);

            // Actions
            if (this.input.keys.has('f')) {
                this.handleInteraction();
                this.input.keys.delete('f'); // Prevent holding down
            }
            if (this.input.keys.has(' ')) { // Shoot
                this.player.shoot(this.player.x + 100, this.player.y); // Simple forward shooting for now
                this.input.keys.delete(' ');
            }
        }

        handleInteraction() {
            // Exit vehicle
            if (this.player.currentVehicle) {
                this.player.currentVehicle.exit();
                return;
            }

            // Enter vehicle
            for (const vehicle of this.vehicles) {
                if (distance(this.player, vehicle) < 50) {
                    if (vehicle.driver) { // Steal vehicle
                        const npcDriver = vehicle.driver;
                        vehicle.exit();
                        if (npcDriver instanceof NPC) {
                            npcDriver.aiState = 'flee';
                        }
                    }
                    vehicle.enter(this.player);
                    break;
                }
            }
        }

        update() {
            this.handleInput();

            // Update all entities
            this.player.update();
            this.vehicles.forEach(v => v.update());
            this.npcs.forEach(npc => {
                npc.updateAI(this.player, this);
                npc.update();
            });

            // Update projectiles and handle collisions
            let allProjectiles = this.player.projectiles.concat(...this.npcs.map(n => n.projectiles));
            this.projectiles = allProjectiles.filter(p => p.lifespan > 0);

            this.projectiles.forEach(p => {
                p.update();
                // Check collision with player
                if (p.owner !== this.player && distance(p, this.player) < this.player.width) {
                    this.player.takeDamage(p.damage);
                    p.lifespan = 0;
                }
                // Check collision with NPCs
                this.npcs.forEach(npc => {
                    if (p.owner !== npc && distance(p, npc) < npc.width) {
                        npc.takeDamage(p.damage);
                        p.lifespan = 0;
                    }
                });
            });

            // Filter out dead NPCs
            this.npcs = this.npcs.filter(npc => npc.health > 0);

            // Update camera
            this.camera.update();

            // Update missions
            const currentMission = this.missions[this.currentMissionIndex];
            if (currentMission && currentMission.update(this)) {
                this.currentMissionIndex++;
            }

            // Update UI
            this.updateUI();
        }

        updateUI() {
            document.getElementById('health-bar').innerText = `Health: ${this.player.health}`;
            document.getElementById('vehicle-status').innerText = this.player.currentVehicle ? 'In Vehicle' : 'On Foot';
            const mission = this.missions[this.currentMissionIndex];
            if (mission) {
                document.getElementById('mission-text').innerText = mission.description;
            }
        }

        draw() {
            // Clear canvas
            ctx.fillStyle = '#333';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Apply camera transform
            this.camera.applyTransform(ctx);

            // Draw world grid (to show movement)
            ctx.strokeStyle = '#444';
            ctx.lineWidth = 1;
            for (let x = 0; x <= this.worldWidth; x += 100) {
                ctx.beginPath();
                ctx.moveTo(x, 0);
                ctx.lineTo(x, this.worldHeight);
                ctx.stroke();
            }
            for (let y = 0; y <= this.worldHeight; y += 100) {
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(this.worldWidth, y);
                ctx.stroke();
            }

            // Draw mission markers
            this.missionMarkers.forEach(marker => {
                ctx.beginPath();
                ctx.arc(marker.x, marker.y, marker.radius, 0, Math.PI * 2);
                ctx.fillStyle = marker.color;
                ctx.fill();
            });

            // Draw entities
            this.vehicles.forEach(v => v.draw(ctx));
            this.npcs.forEach(npc => {
                if (!npc.currentVehicle) npc.draw(ctx);
            });
            if (!this.player.currentVehicle) {
                this.player.draw(ctx);
            }
            this.projectiles.forEach(p => p.draw(ctx));

            // Reset transform for UI elements
            this.camera.resetTransform(ctx);

            // Draw joystick on mobile
            if (this.input.isMobile) {
                this.joystick.draw(ctx);
            }
        }

        gameLoop() {
            this.update();
            this.draw();
            requestAnimationFrame(() => this.gameLoop());
        }
    }

    // --- START GAME ---
    const game = new Game();
    game.gameLoop();

    </script>
</body>
</html>
```

### Professional Breakdown of the Code

#### 1. **HTML & CSS Structure**
*   The HTML provides a `<canvas>` element for the game world and a separate `<div>` (`#ui-container`) for the UI.
*   This separation is a professional practice. It prevents you from having to redraw text and UI elements in screen-space coordinates every frame within the complex world-space transformations of the canvas.
*   The CSS ensures the game is full-screen and that the UI overlay doesn't interfere with game input (`pointer-events: none`).

#### 2. **Core Game Architecture (`Game` class)**
*   **`constructor`**: Initializes the game world, player, camera, input handlers, and all entity arrays. It calls `initWorld()` to populate the game.
*   **`initWorld()`**: This method is responsible for procedural generation. It spawns NPCs, vehicles, and sets up the mission objectives. This keeps the constructor clean.
*   **`gameLoop()`**: The heart of the game. It uses `requestAnimationFrame` for smooth, efficient animation. It strictly follows the standard `update -> draw` cycle.
*   **`update()`**: Handles all game logic: input processing, AI updates, physics, collision detection, and mission state changes.
*   **`draw()`**: Handles all rendering. It first applies the camera's transformation to draw the "world" and then resets it to draw UI elements like the joystick.

#### 3. **Entity Component System (ECS) - A Simplified Approach**
*   The code uses an object-oriented approach that mimics some principles of ECS.
*   **`Entity`**: A base class with position and dimensions.
*   **`Character`**: Inherits from `Entity` and adds health, movement, and combat capabilities.
*   **`Player`** and **`NPC`**: Inherit from `Character`, specializing their behavior. The `NPC` class contains the AI logic.
*   **`Vehicle`**: A distinct entity with its own physics, state (`driver`), and methods (`enter`, `exit`). This cleanly separates character logic from vehicle logic.

#### 4. **Systems Implementation**

*   **Controls (Keyboard & Virtual Joystick):**
    *   The `input` object tracks the state of keys.
    *   The `Joystick` class is a self-contained component. It handles its own touch events, state, and drawing. It produces a simple normalized vector (`dx`, `dy`) that the `Player` class can use for movement, abstracting away the input source.

*   **Camera System:**
    *   The `Camera` class tracks a target (the player).
    *   In its `update` loop, it calculates its position to keep the player centered, but clamps its coordinates to the world boundaries so you can't see "outside" the map.
    *   The `applyTransform` and `resetTransform` methods are crucial for separating world-space drawing from screen-space drawing.

*   **Combat System:**
    *   Characters can create `Projectile` instances.
    *   Each projectile has an `owner` to prevent self-damage.
    *   The main game loop iterates through projectiles, checks for collisions with relevant entities, applies damage, and removes them.

*   **Vehicle & Stealing Mechanics:**
    *   A `Vehicle` has a `driver` property. If it's `null`, the vehicle is empty.
    *   The `handleInteraction` function checks for proximity. If a player is near a vehicle, it can enter.
    *   If the vehicle is occupied by an NPC, the NPC is "ejected" (`vehicle.exit()`) and its AI state is set to `flee`, creating an emergent behavior where the NPC runs away after being carjacked.

*   **Mission System:**
    *   The `Mission` class is highly flexible. It takes a `completionCheck` function as an argument.
    *   This function receives the entire game state and returns `true` or `false`. This allows for creating complex objectives (e.g., "is player in this vehicle?", "is distance to X less than Y?", "are all NPCs defeated?").
    *   The main game loop simply checks the *current* mission, and if it's completed, advances to the next one.

Of course. As a code expert, I will provide a professional and well-structured solution for a 3D space gravity simulation game. We will use the powerful **Three.js** library, which is the industry standard for creating 3D graphics on the web. This approach abstracts the low-level WebGL calls, allowing us to focus on the game's logic and physics.

### Professional Overview

The game simulates a spacecraft navigating a solar system. The core of the simulation is a physics engine that calculates the gravitational pull of each planet on the spacecraft based on **Newton's Law of Universal Gravitation (F = G * (m1*m2) / r²)**. The player's only controls are to increase or decrease thrust, which directly affects the spacecraft's velocity. This simple mechanic creates complex and engaging gameplay where players must master orbital mechanics to navigate the system, either slingshotting around planets or getting caught in their gravitational wells.

The code is structured into three standard web files:
1.  `index.html`: The main page structure, including the canvas for rendering and UI elements.
2.  `style.css`: For styling the UI and ensuring the game is full-screen.
3.  `game.js`: The core application logic, including scene setup, physics calculations, and player controls.

