### File 3: `game.js`

This is the heart of the game. It contains all the logic for setting up the 3D world, defining the physics, handling controls, and running the game loop.

```javascript
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// --- SCENE SETUP ---
let scene, camera, renderer, controls;
let clock = new THREE.Clock();

// --- GAME OBJECTS ---
let spacecraft;
const planets = [];
let starfield;

// --- PHYSICS CONSTANTS ---
const G = 0.1; // Gravitational constant (tuned for gameplay)
const SHIP_MASS = 1;
const THRUST_FORCE = 0.05;
const MAX_VELOCITY = 5;

// --- PLAYER INPUT ---
const keyState = {};

// --- UI ELEMENTS ---
const speedDisplay = document.getElementById('speed-display');

function init() {
    // Scene
    scene = new THREE.Scene();

    // Camera
    camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 2000);
    camera.position.set(0, 20, 50);

    // Renderer
    renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.getElementById('scene-container').appendChild(renderer.domElement);

    // Lighting
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.2);
    scene.add(ambientLight);

    const pointLight = new THREE.PointLight(0xffffff, 1.5, 2000);
    pointLight.position.set(0, 0, 0); // Sun is at the center
    scene.add(pointLight);

    // Controls (for debugging/free-cam)
    // controls = new OrbitControls(camera, renderer.domElement);

    // --- CREATE GAME WORLD ---
    createStarfield();
    createSun();
    createPlanets();
    createSpacecraft();

    // --- EVENT LISTENERS ---
    window.addEventListener('resize', onWindowResize, false);
    window.addEventListener('keydown', (event) => { keyState[event.code] = true; });
    window.addEventListener('keyup', (event) => { keyState[event.code] = false; });

    // Start the game loop
    animate();
}

function createStarfield() {
    const starGeometry = new THREE.SphereGeometry(1000, 64, 64);
    const starMaterial = new THREE.MeshBasicMaterial({
        map: new THREE.TextureLoader().load('https://i.imgur.com/JRELpEl.jpeg'),
        side: THREE.BackSide
    });
    starfield = new THREE.Mesh(starGeometry, starMaterial);
    scene.add(starfield);
}

function createSun() {
    const sunGeometry = new THREE.SphereGeometry(10, 32, 32);
    const sunMaterial = new THREE.MeshBasicMaterial({ color: 0xffdd00 });
    const sun = new THREE.Mesh(sunGeometry, sunMaterial);
    scene.add(sun);
    // The sun is also a "planet" for gravity calculation
    planets.push({
        mesh: sun,
        mass: 1000,
        radius: 10
    });
}

function createPlanets() {
    // Planet 1 (Earth-like)
    const planet1Geo = new THREE.SphereGeometry(4, 32, 32);
    const planet1Mat = new THREE.MeshStandardMaterial({
        map: new THREE.TextureLoader().load('https://i.imgur.com/x2hJqQ5.jpeg')
    });
    const planet1 = new THREE.Mesh(planet1Geo, planet1Mat);
    planet1.position.set(50, 0, 0);
    scene.add(planet1);
    planets.push({ mesh: planet1, mass: 200, radius: 4 });

    // Planet 2 (Mars-like, with a moon)
    const planet2Geo = new THREE.SphereGeometry(3, 32, 32);
    const planet2Mat = new THREE.MeshStandardMaterial({
        map: new THREE.TextureLoader().load('https://i.imgur.com/bWb6D.jpeg')
    });
    const planet2 = new THREE.Mesh(planet2Geo, planet2Mat);
    planet2.position.set(-80, 0, 20);
    scene.add(planet2);
    planets.push({ mesh: planet2, mass: 150, radius: 3 });

    // Moon for Planet 2
    const moonGeo = new THREE.SphereGeometry(0.8, 16, 16);
    const moonMat = new THREE.MeshStandardMaterial({ color: 0xaaaaaa });
    const moon = new THREE.Mesh(moonGeo, moonMat);
    moon.position.set(-87, 0, 20); // Orbiting planet 2
    scene.add(moon);
    planets.push({ mesh: moon, mass: 20, radius: 0.8 });
}

function createSpacecraft() {
    const geometry = new THREE.ConeGeometry(1, 3, 8);
    const material = new THREE.MeshStandardMaterial({ color: 0x00aaff, metalness: 0.5, roughness: 0.5 });
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.set(0, 0, 30);
    mesh.rotation.x = Math.PI / 2; // Point forward
    scene.add(mesh);

    spacecraft = {
        mesh: mesh,
        velocity: new THREE.Vector3(2, 0, 0), // Initial velocity to start moving
        acceleration: new THREE.Vector3(0, 0, 0)
    };
}

function updatePhysics(deltaTime) {
    // Reset acceleration for this frame
    spacecraft.acceleration.set(0, 0, 0);

    // 1. Calculate Gravitational Forces
    planets.forEach(planet => {
        const distanceVec = new THREE.Vector3().subVectors(planet.mesh.position, spacecraft.mesh.position);
        const distanceSq = distanceVec.lengthSq();

        // Avoid division by zero if inside a planet
        if (distanceSq > planet.radius * planet.radius) {
            const forceDirection = distanceVec.normalize();
            const forceMagnitude = (G * planet.mass * SHIP_MASS) / distanceSq;
            const forceVector = forceDirection.multiplyScalar(forceMagnitude);
            spacecraft.acceleration.add(forceVector);
        }
    });

    // 2. Apply Player Thrust
    const forwardDirection = new THREE.Vector3(0, 0, -1);
    forwardDirection.applyQuaternion(spacecraft.mesh.quaternion);

    if (keyState['KeyW'] || keyState['ArrowUp']) {
        const thrustVector = spacecraft.velocity.clone().normalize().multiplyScalar(THRUST_FORCE);
        spacecraft.velocity.add(thrustVector);
    }
    if (keyState['KeyS'] || keyState['ArrowDown']) {
        const brakeVector = spacecraft.velocity.clone().normalize().multiplyScalar(-THRUST_FORCE);
        spacecraft.velocity.add(brakeVector);
    }

    // Clamp velocity to a maximum speed
    if (spacecraft.velocity.length() > MAX_VELOCITY) {
        spacecraft.velocity.normalize().multiplyScalar(MAX_VELOCITY);
    }

    // 3. Update Velocity and Position (Euler integration)
    spacecraft.velocity.add(spacecraft.acceleration.multiplyScalar(deltaTime));
    spacecraft.mesh.position.add(spacecraft.velocity.clone().multiplyScalar(deltaTime));

    // Make the ship point in the direction of its velocity
    if (spacecraft.velocity.lengthSq() > 0.001) {
        const lookAtPosition = new THREE.Vector3().addVectors(spacecraft.mesh.position, spacecraft.velocity);
        spacecraft.mesh.lookAt(lookAtPosition);
    }
}

function updateCamera() {
    // Camera follows the spacecraft from a distance
    const offset = new THREE.Vector3(0, 5, 15);
    offset.applyQuaternion(spacecraft.mesh.quaternion); // Rotate offset to be behind the ship
    const cameraPosition = new THREE.Vector3().addVectors(spacecraft.mesh.position, offset);

    camera.position.lerp(cameraPosition, 0.1); // Smoothly move camera
    camera.lookAt(spacecraft.mesh.position);
}

function updateUI() {
    const speed = spacecraft.velocity.length();
    speedDisplay.textContent = speed.toFixed(2);
}

function onWindowResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
}

function animate() {
    requestAnimationFrame(animate);

    const deltaTime = clock.getDelta();

    // Update physics simulation
    updatePhysics(deltaTime);

    // Update camera and UI
    updateCamera();
    updateUI();

    // Rotate planets for visual effect
    planets.forEach((p, i) => {
        if (i > 0) { // Don't rotate the sun
            p.mesh.rotation.y += 0.1 * deltaTime;
        }
    });

    renderer.render(scene, camera);
}

// --- START THE GAME ---
init();
```

### Potential Enhancements for Further Development

*   **Collision Detection:** Add logic to detect when the spacecraft collides with a planet, resulting in a "game over" or "landing" state.
*   **Orbital Path Prediction:** Draw a line showing the spacecraft's predicted trajectory based on current velocity and gravitational forces. This is a common feature in space simulation games like Kerbal Space Program.
*   **Fuel/Energy System:** Introduce a limited resource for thrust, adding a layer of resource management.
*   **Sound Effects:** Add sounds for thrust, background ambient music, and alerts.
