### Executable Code

You can copy and paste the following code into a single `index.html` file and open it in any modern web browser to see the simulation.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Celestial Sun Simulation</title>
    <style>
        body {
            margin: 0;
            overflow: hidden; /* Prevents scrollbars */
            background-color: #000;
        }
        canvas {
            display: block; /* Removes default bottom margin */
        }
    </style>
</head>
<body>
    <canvas id="solarCanvas"></canvas>

    <script>
        // --- 1. INITIALIZATION ---
        const canvas = document.getElementById('solarCanvas');
        const ctx = canvas.getContext('2d');

        // --- 2. CONFIGURATION ---
        const DAY_DURATION = 20000; // Full day cycle in milliseconds (20 seconds)

        // Color stops for the sky gradient throughout the day (t = time, 0 to 1)
        const skyColorStops = [
            { t: 0.0,  color: [0, 5, 20] },      // Midnight
            { t: 0.20, color: [0, 10, 40] },     // Pre-dawn
            { t: 0.25, color: [255, 150, 30] },  // Sunrise
            { t: 0.30, color: [255, 200, 100] }, // Post-sunrise
            { t: 0.5,  color: [135, 206, 235] }, // Noon (Sky Blue)
            { t: 0.70, color: [255, 200, 100] }, // Pre-sunset
            { t: 0.75, color: [255, 100, 30] },  // Sunset
            { t: 0.80, color: [0, 10, 40] },     // Post-sunset
            { t: 1.0,  color: [0, 5, 20] }       // Midnight
        ];

        // --- 3. RESPONSIVE CANVAS SETUP ---
        function resizeCanvas() {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        }
        window.addEventListener('resize', resizeCanvas);
        resizeCanvas(); // Initial size

        // --- 4. HELPER FUNCTIONS ---

        /**
         * Linearly interpolates between two values.
         * @param {number} a - Start value.
         * @param {number} b - End value.
         * @param {number} t - Interpolation factor (0 to 1).
         * @returns {number} The interpolated value.
         */
        function lerp(a, b, t) {
            return a + (b - a) * t;
        }

        /**
         * Gets the interpolated RGB color at a specific time of day.
         * @param {number} time - The current time (0 to 1).
         * @returns {string} The CSS rgb() color string.
         */
        function getColorAtTime(time) {
            // Find the two color stops the current time is between
            let startStop, endStop;
            for (let i = 0; i < skyColorStops.length - 1; i++) {
                if (time >= skyColorStops[i].t && time <= skyColorStops[i + 1].t) {
                    startStop = skyColorStops[i];
                    endStop = skyColorStops[i + 1];
                    break;
                }
            }

            // Calculate the interpolation factor within this segment
            const segmentDuration = endStop.t - startStop.t;
            const timeIntoSegment = time - startStop.t;
            const t = timeIntoSegment / segmentDuration;

            // Interpolate each color channel (R, G, B)
            const r = Math.round(lerp(startStop.color[0], endStop.color[0], t));
            const g = Math.round(lerp(startStop.color[1], endStop.color[1], t));
            const b = Math.round(lerp(startStop.color[2], endStop.color[2], t));

            return `rgb(${r}, ${g}, ${b})`;
        }

        // --- 5. DRAWING FUNCTIONS ---

        /**
         * Draws the sky with a vertical gradient.
         * @param {number} time - The current time (0 to 1).
         */
        function drawSky(time) {
            const horizonY = canvas.height * 0.7;
            const topColor = getColorAtTime(time);

            // Create a gradient from the top of the sky to the horizon
            const skyGradient = ctx.createLinearGradient(0, 0, 0, horizonY);
            skyGradient.addColorStop(0, topColor);
            skyGradient.addColorStop(1, 'rgba(255, 255, 255, 0.5)'); // Fades to a lighter tone at horizon

            ctx.fillStyle = skyGradient;
            ctx.fillRect(0, 0, canvas.width, canvas.height);
        }

        /**
         * Draws the sun at its calculated position.
         * @param {number} sunX - The x-coordinate of the sun.
         * @param {number} sunY - The y-coordinate of the sun.
         */
        function drawSun(sunX, sunY) {
            // Sun color changes based on its height (more red near horizon)
            const sunGlowFactor = Math.max(0, (sunY / (canvas.height * 0.7)) - 0.2);
            const sunColor = `rgb(255, ${Math.round(240 - 100 * sunGlowFactor)}, ${Math.round(180 - 180 * sunGlowFactor)})`;

            // Draw the sun's glow
            ctx.fillStyle = sunColor;
            ctx.shadowColor = sunColor;
            ctx.shadowBlur = 50;

            ctx.beginPath();
            ctx.arc(sunX, sunY, 30, 0, 2 * Math.PI);
            ctx.fill();

            // Reset shadow for other elements
            ctx.shadowBlur = 0;
        }

        /**
         * Draws the ground.
         * @param {number} time - The current time (0 to 1).
         */
        function drawGround(time) {
            const horizonY = canvas.height * 0.7;

            // Ground brightness depends on the time of day
            const lightLevel = Math.sin(time * Math.PI); // Peaks at noon (time=0.5)
            const groundBrightness = 30 + 70 * lightLevel;

            const groundGradient = ctx.createLinearGradient(0, horizonY, 0, canvas.height);
            groundGradient.addColorStop(0, `rgb(${groundBrightness * 0.6}, ${groundBrightness * 0.9}, ${groundBrightness * 0.4})`);
            groundGradient.addColorStop(1, `rgb(${groundBrightness * 0.3}, ${groundBrightness * 0.5}, ${groundBrightness * 0.2})`);

            ctx.fillStyle = groundGradient;
            ctx.fillRect(0, horizonY, canvas.width, canvas.height - horizonY);
        }

        // --- 6. ANIMATION LOOP ---
        let lastTime = 0;

        function animate(timestamp) {
            // Calculate time delta for smooth animation regardless of frame rate
            const deltaTime = timestamp - (lastTime || timestamp);
            lastTime = timestamp;

            // Calculate the current time of day (0 to 1)
            const time = (timestamp % DAY_DURATION) / DAY_DURATION;

            // Clear the canvas
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // --- Calculations ---
            const horizonY = canvas.height * 0.7;
            const pathRadiusX = canvas.width / 2 * 0.9;
            const pathRadiusY = horizonY * 0.9;
            const pathCenterX = canvas.width / 2;
            const pathCenterY = horizonY;

            // Calculate sun's position on an elliptical arc
            // We use Math.PI to map the time (0 to 1) to a semi-circle (0 to 180 degrees)
            const angle = time * Math.PI;
            const sunX = pathCenterX - pathRadiusX * Math.cos(angle);
            const sunY = pathCenterY - pathRadiusY * Math.sin(angle);

            // --- Drawing ---
            drawSky(time);
            drawGround(time);

            // Only draw the sun when it's above the horizon
            if (sunY < horizonY) {
                drawSun(sunX, sunY);
            }

            // Request the next frame
            requestAnimationFrame(animate);
        }

        // Start the animation
        requestAnimationFrame(animate);
    </script>
</body>
</html>
```

### Professional Breakdown of the Code

#### 1. HTML Structure
The HTML is minimal, containing only a `<title>` and a `<canvas>` element. The canvas, with the ID `solarCanvas`, serves as our drawing board for the entire simulation.

#### 2. CSS Styling
The CSS ensures that the canvas fills the entire browser viewport without any margins or scrollbars, providing an immersive experience.
*   `body { margin: 0; overflow: hidden; }`: Removes default spacing and hides scrollbars.
*   `canvas { display: block; }`: A common fix to remove a small, unwanted space that can appear below a canvas element.

#### 3. JavaScript Logic

The script is organized into logical sections for clarity and maintainability.

*   **Initialization & Configuration:**
    *   We get the canvas element and its 2D rendering context (`ctx`), which is the object containing all the drawing methods.
    *   `DAY_DURATION` is a constant that defines the length of a full day-night cycle in milliseconds. This makes it easy to adjust the speed of the simulation.
    *   `skyColorStops` is a data-driven array of objects. This is a professional way to manage complex color transitions. Each object defines a color at a specific point in time (`t` from 0.0 to 1.0). This makes it easy to add more colors or tweak the timing of sunrise/sunset.

*   **Responsive Canvas Setup:**
    *   The `resizeCanvas` function sets the canvas dimensions to match the window's inner width and height.
    *   An event listener on `window` calls this function whenever the browser is resized, ensuring the simulation always looks correct.

*   **Helper Functions:**
    *   `lerp(a, b, t)`: A standard linear interpolation function. It's a fundamental tool in graphics programming for creating smooth transitions between two states (in this case, color values).
    *   `getColorAtTime(time)`: This is the core of the atmospheric effect. It finds which two color stops the current `time` falls between and then uses `lerp` to calculate the precise intermediate color. This produces the smooth, continuous gradient changes in the sky.

*   **Drawing Functions:**
    *   The code is modularized into `drawSky`, `drawSun`, and `drawGround`. This separation of concerns makes the main animation loop cleaner and easier to understand.
    *   `drawSky`: Uses `createLinearGradient` to create a more realistic sky that is slightly lighter near the horizon.
    *   `drawSun`: Calculates the sun's color based on its vertical position to make it appear more reddish near the horizon. It also uses `shadowBlur` to create a beautiful, soft glow effect.
    *   `drawGround`: The ground's brightness is dynamically calculated based on the time of day using `Math.sin`, making it appear illuminated by the sun.

*   **The Animation Loop (`animate`):**
    *   **`requestAnimationFrame(animate)`:** This is the modern, browser-optimized way to create animations. It tells the browser to call the `animate` function right before the next repaint, resulting in smoother, more efficient animations than using `setInterval`.
    *   **Delta Time (`deltaTime`):** The code calculates the time elapsed since the last frame. While not used to advance the simulation here (we use a timestamp-based approach), this is a crucial pattern for frame-rate independent physics and movement.
    *   **Time Calculation:** The current time of day (a value from 0 to 1) is calculated using the modulo operator (`%`) on the high-resolution `timestamp` provided by `requestAnimationFrame`. This ensures the cycle repeats seamlessly.
    *   **Celestial Mechanics:** The sun's position is calculated using basic trigonometry. By mapping the `time` to an angle and using `Math.cos` for the x-coordinate and `Math.sin` for the y-coordinate, we can plot the sun's position along a perfect semi-elliptical path.
    *   **Drawing Order:** The elements are drawn in a specific order (sky, ground, then sun) to ensure they are layered correctly, just like in a real landscape.

