### How to Run This Demonstration

1.  Create the folder structure as outlined above (`my-blog/`, `css/`, `img/`).
2.  Save each code block into its corresponding file (e.g., the CSS code into `css/style.css`).
3.  (Optional) Place an image named `avatar.jpg` in the `img/` folder, or just use the placeholder links.
4.  Open the `index.html` file in your web browser (e.g., Chrome, Firefox).

You can now navigate through your blog's frontend, see the professional layout, and understand how the different pages connect. To make this fully functional, the next step would be to integrate a backend technology like Node.js, Django, or Laravel.

An elegant and complete project code is provided below. You can copy the complete code into an `index.html` file and open it with a browser to see the running effect.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Dynamic Background Video Generator</title>
    <style>
        body {
            margin: 0;
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
            color: #fff;
            background-color: #111;
            overflow: hidden; /* Hide scrollbars */
        }

        #container {
            width: 100vw;
            height: 100vh;
            position: relative;
            display: flex;
        }

        #preview-panel {
            flex-grow: 1;
            position: relative;
            display: flex;
            justify-content: center;
            align-items: center;
            background-color: #000;
        }

        #renderer-canvas {
            display: block;
            max-width: 100%;
            max-height: 100%;
            aspect-ratio: 16 / 9;
            background-color: #1a1a1a;
        }

        /* Make lil-gui panel blend in */
        .lil-gui {
            --background-color: #1a1a1a;
            --widget-color: #444;
            --hover-color: #555;
            --focus-color: #5a7ec4;
            --number-color: #2cc9ff;
            --string-color: #b4d883;
            --font-size: 14px;
            --input-font-size: 14px;
        }

        .lil-gui.root {
            width: 320px;
        }

        /* Status overlay for recording */
        #status-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.7);
            color: white;
            display: none; /* Hidden by default */
            justify-content: center;
            align-items: center;
            font-size: 2em;
            z-index: 1000;
            flex-direction: column;
        }

        #status-overlay .progress-bar {
            width: 50%;
            height: 20px;
            background-color: #333;
            border-radius: 10px;
            margin-top: 20px;
            overflow: hidden;
        }

        #status-overlay .progress-bar-inner {
            width: 0%;
            height: 100%;
            background-color: #2cc9ff;
            transition: width 0.1s linear;
        }
    </style>
</head>
<body>

    <div id="container">
        <!-- The main canvas for Three.js rendering -->
        <div id="preview-panel">
            <canvas id="renderer-canvas"></canvas>
        </div>
    </div>

    <!-- Status overlay for recording progress -->
    <div id="status-overlay">
        <div id="status-text">Initializing...</div>
        <div class="progress-bar">
            <div id="progress-bar-inner"></div>
        </div>
    </div>

    <!-- Import maps for ES6 modules -->
    <script type="importmap">
    {
        "imports": {
            "three": "https://cdn.skypack.dev/three@0.136.0",
            "lil-gui": "https://cdn.skypack.dev/lil-gui@0.16.1"
        }
    }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { GUI } from 'lil-gui';

        // --- GLOBAL CONFIGURATION AND STATE ---
        const CONFIG = {
            resolution: { width: 1280, height: 720 },
            totalDuration: 10, // in seconds
            background: 'Particles',
            export: exportVideo,
        };

        let scene, camera, renderer, clock;
        let activeBackground = null;
        let elements = []; // To store text and image objects
        let isRecording = false;
        let recordedTime = 0;

        // --- BACKGROUND GENERATORS ---

        /**
         * Creates a dynamic particle background.
         * @param {THREE.Scene} scene - The scene to add the particles to.
         * @returns {object} An object with an update function.
         */
        function createParticleBackground(scene) {
            const particleCount = 5000;
            const positions = new Float32Array(particleCount * 3);
            const colors = new Float32Array(particleCount * 3);
            const color = new THREE.Color();

            for (let i = 0; i < particleCount; i++) {
                const x = THREE.MathUtils.randFloatSpread(20);
                const y = THREE.MathUtils.randFloatSpread(10);
                const z = THREE.MathUtils.randFloatSpread(10) - 5;
                positions[i * 3] = x;
                positions[i * 3 + 1] = y;
                positions[i * 3 + 2] = z;

                color.setHSL(Math.random(), 1.0, 0.7);
                colors[i * 3] = color.r;
                colors[i * 3 + 1] = color.g;
                colors[i * 3 + 2] = color.b;
            }

            const geometry = new THREE.BufferGeometry();
            geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
            geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

            const material = new THREE.PointsMaterial({
                size: 0.05,
                vertexColors: true,
                blending: THREE.AdditiveBlending,
                transparent: true,
                opacity: 0.8,
            });

            const points = new THREE.Points(geometry, material);
            scene.add(points);

            const update = (time) => {
                const positions = points.geometry.attributes.position.array;
                for (let i = 0; i < particleCount; i++) {
                    // Simple upward movement, wrapping around
                    positions[i * 3 + 1] += 0.01;
                    if (positions[i * 3 + 1] > 5) {
                        positions[i * 3 + 1] = -5;
                    }
                }
                points.geometry.attributes.position.needsUpdate = true;
            };

            const dispose = () => {
                scene.remove(points);
                geometry.dispose();
                material.dispose();
            };

            return { mesh: points, update, dispose };
        }

        /**
         * Creates an animated smoke/noise background.
         * @param {THREE.Scene} scene - The scene to add the smoke plane to.
         * @returns {object} An object with an update function.
         */
        function createSmokeBackground(scene) {
            const geometry = new THREE.PlaneGeometry(25, 15);
            const material = new THREE.ShaderMaterial({
                uniforms: {
                    u_time: { value: 0.0 },
                    u_color1: { value: new THREE.Color(0x001133) },
                    u_color2: { value: new THREE.Color(0x330022) },
                },
                vertexShader: `
                    varying vec2 vUv;
                    void main() {
                        vUv = uv;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform float u_time;
                    uniform vec3 u_color1;
                    uniform vec3 u_color2;
                    varying vec2 vUv;

                    // 2D Random function
                    float random(vec2 st) {
                        return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
                    }

                    // 2D Noise function
                    float noise(vec2 st) {
                        vec2 i = floor(st);
                        vec2 f = fract(st);
                        float a = random(i);
                        float b = random(i + vec2(1.0, 0.0));
                        float c = random(i + vec2(0.0, 1.0));
                        float d = random(i + vec2(1.0, 1.0));
                        vec2 u = f * f * (3.0 - 2.0 * f);
                        return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.y * u.x;
                    }

                    void main() {
                        vec2 uv = vUv * 4.0;
                        float n = noise(uv + u_time * 0.1);
                        gl_FragColor = vec4(mix(u_color1, u_color2, n), 1.0);
                    }
                `,
            });

            const mesh = new THREE.Mesh(geometry, material);
            mesh.position.z = -5;
            scene.add(mesh);

            const update = (time) => {
                material.uniforms.u_time.value = time;
            };

            const dispose = () => {
                scene.remove(mesh);
                geometry.dispose();
                material.dispose();
            };

            return { mesh, update, dispose };
        }

        // --- SCENE ELEMENT MANAGEMENT ---

        /**
         * Base class for scene elements like text and images.
         */
        class SceneElement {
            constructor(name) {
                this.name = name;
                this.mesh = null;
                this.config = {
                    visible: true,
                    position: { x: 0, y: 0, z: 0 },
                    scale: { x: 1, y: 1 },
                    rotation: 0,
                    opacity: 1.0,
                    startTime: 0.0,
                    duration: 5.0,
                    fadeIn: 0.5,
                    fadeOut: 0.5,
                };
            }

            // Updates the element's state based on the current time
            update(time) {
                if (!this.mesh) return;

                const localTime = time - this.config.startTime;
                const isVisible = time >= this.config.startTime && localTime < this.config.duration;

                this.mesh.visible = isVisible;

                if (isVisible) {
                    // Handle fade in/out
                    let currentOpacity = this.config.opacity;
                    if (localTime < this.config.fadeIn) {
                        currentOpacity *= localTime / this.config.fadeIn;
                    } else if (localTime > this.config.duration - this.config.fadeOut) {
                        currentOpacity *= (this.config.duration - localTime) / this.config.fadeOut;
                    }
                    this.mesh.material.opacity = Math.max(0, Math.min(1, currentOpacity));

                    // Update transform
                    this.mesh.position.set(this.config.position.x, this.config.position.y, this.config.position.z);
                    this.mesh.scale.set(this.config.scale.x, this.config.scale.y, 1);
                    this.mesh.rotation.z = THREE.MathUtils.degToRad(this.config.rotation);
                }
            }

            // Adds controls for this element to the GUI
            addToGUI(gui) {
                const folder = gui.addFolder(this.name);
                folder.add(this.config, 'startTime', 0, CONFIG.totalDuration, 0.1).name('Start Time (s)');
                folder.add(this.config, 'duration', 0, CONFIG.totalDuration, 0.1).name('Duration (s)');
                folder.add(this.config.position, 'x', -5, 5, 0.1);
                folder.add(this.config.position, 'y', -5, 5, 0.1);
                folder.add(this.config.scale, 'x', 0.1, 10, 0.1).name('Scale X');
                folder.add(this.config.scale, 'y', 0.1, 10, 0.1).name('Scale Y');
                folder.add(this.config, 'rotation', -180, 180, 1).name('Rotation');
                folder.add(this.config, 'opacity', 0, 1, 0.01);
                folder.add(this.config, 'fadeIn', 0, 5, 0.1).name('Fade In (s)');
                folder.add(this.config, 'fadeOut', 0, 5, 0.1).name('Fade Out (s)');
                return folder;
            }

            dispose() {
                if (this.mesh) {
                    scene.remove(this.mesh);
                    this.mesh.geometry.dispose();
                    this.mesh.material.dispose();
                    if (this.mesh.material.map) {
                        this.mesh.material.map.dispose();
                    }
                }
            }
        }

        /**
         * Manages a text element in the scene.
         */
        class TextElement extends SceneElement {
            constructor(name, text) {
                super(name);
                this.config.text = text;
                this.config.fontSize = 64;
                this.config.color = '#ffffff';
                this.config.scale.x = 4;
                this.config.scale.y = 2;
                this.createTextMesh();
            }

            createTextMesh() {
                if (this.mesh) this.dispose();

                const canvas = document.createElement('canvas');
                const context = canvas.getContext('2d');
                const font = `${this.config.fontSize}px Arial`;
                context.font = font;
                const textWidth = context.measureText(this.config.text).width;

                canvas.width = THREE.MathUtils.ceilPowerOfTwo(textWidth);
                canvas.height = THREE.MathUtils.ceilPowerOfTwo(this.config.fontSize * 1.5);

                context.font = font;
                context.fillStyle = this.config.color;
                context.textAlign = 'center';
                context.textBaseline = 'middle';
                context.fillText(this.config.text, canvas.width / 2, canvas.height / 2);

                const texture = new THREE.CanvasTexture(canvas);
                const material = new THREE.MeshBasicMaterial({
                    map: texture,
                    transparent: true,
                    opacity: this.config.opacity,
                });
                const aspect = canvas.width / canvas.height;
                const geometry = new THREE.PlaneGeometry(aspect, 1);

                this.mesh = new THREE.Mesh(geometry, material);
                scene.add(this.mesh);
            }

            addToGUI(gui) {
                const folder = super.addToGUI(gui);
                folder.add(this.config, 'text').name('Content').onFinishChange(() => this.createTextMesh());
                folder.add(this.config, 'fontSize', 16, 128, 1).name('Font Size').onFinishChange(() => this.createTextMesh());
                folder.addColor(this.config, 'color').name('Color').onFinishChange(() => this.createTextMesh());
            }
        }

        /**
         * Manages an image element in the scene.
         */
        class ImageElement extends SceneElement {
            constructor(name, imageUrl) {
                super(name);
                this.config.scale.x = 3;
                this.config.scale.y = 3;
                this.config.position.y = -1;
                this.config.startTime = 3.0;
                this.config.duration = 6.0;
                this.loadImage(imageUrl);
            }

            loadImage(url) {
                if (this.mesh) this.dispose();

                const loader = new THREE.TextureLoader();
                loader.load(url, (texture) => {
                    const aspect = texture.image.width / texture.image.height;
                    const geometry = new THREE.PlaneGeometry(aspect, 1);
                    const material = new THREE.MeshBasicMaterial({
                        map: texture,
                        transparent: true,
                        opacity: this.config.opacity,
                    });
                    this.mesh = new THREE.Mesh(geometry, material);
                    scene.add(this.mesh);
                });
            }

            addToGUI(gui) {
                const folder = super.addToGUI(gui);
                const imageController = {
                    upload: () => {
                        const input = document.createElement('input');
                        input.type = 'file';
                        input.accept = 'image/*';
                        input.onchange = (e) => {
                            const file = e.target.files[0];
                            if (file) {
                                const reader = new FileReader();
                                reader.onload = (event) => {
                                    this.loadImage(event.target.result);
                                };
                                reader.readAsDataURL(file);
                            }
                        };
                        input.click();
                    }
                };
                folder.add(imageController, 'upload').name('Upload Image');
            }
        }

        // --- INITIALIZATION ---

        function init() {
            // Scene
            scene = new THREE.Scene();
            clock = new THREE.Clock();

            // Camera
            const aspect = CONFIG.resolution.width / CONFIG.resolution.height;
            camera = new THREE.PerspectiveCamera(75, aspect, 0.1, 1000);
            camera.position.z = 5;

            // Renderer
            const canvas = document.getElementById('renderer-canvas');
            renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
            renderer.setSize(CONFIG.resolution.width, CONFIG.resolution.height, false);

            // Initial background
            switchBackground();

            // Initial elements
            const text1 = new TextElement('Title Text', 'Hello World!');
            // Simulated image data (Base64 encoded 1x1 transparent pixel)
            const placeholderImg = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=';
            const image1 = new ImageElement('Logo Image', placeholderImg);
            elements.push(text1, image1);

            // UI
            setupGUI();

            // Start animation loop
            animate();
        }

        // --- UI SETUP ---

        function setupGUI() {
            const gui = new GUI();
            gui.title("Video Generator Controls");

            gui.add(CONFIG, 'totalDuration', 5, 30, 1).name('Total Duration (s)');
            gui.add(CONFIG, 'background', ['Particles', 'Smoke']).name('Background').onChange(switchBackground);

            elements.forEach(el => el.addToGUI(gui));

            gui.add(CONFIG, 'export').name('Export Video');
        }

        function switchBackground() {
            if (activeBackground) {
                activeBackground.dispose();
            }
            if (CONFIG.background === 'Particles') {
                activeBackground = createParticleBackground(scene);
            } else if (CONFIG.background === 'Smoke') {
                activeBackground = createSmokeBackground(scene);
            }
        }

        // --- ANIMATION LOOP ---

        function animate() {
            // If not recording, loop normally
            if (!isRecording) {
                requestAnimationFrame(animate);
            }

            const time = isRecording ? recordedTime : clock.getElapsedTime();

            // Update background
            if (activeBackground && activeBackground.update) {
                activeBackground.update(time);
            }

            // Update elements
            elements.forEach(el => el.update(time));

            // Render scene
            renderer.render(scene, camera);
        }

        // --- VIDEO EXPORT ---

        function exportVideo() {
            if (isRecording) return;

            isRecording = true;
            recordedTime = 0;
            const frameRate = 30;
            const frameDuration = 1 / frameRate;
            const totalFrames = CONFIG.totalDuration * frameRate;
            let currentFrame = 0;

            const stream = renderer.domElement.captureStream(frameRate);
            const mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' });
            const chunks = [];

            mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
            mediaRecorder.onstop = () => {
                const blob = new Blob(chunks, { type: 'video/webm' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = 'dynamic-background.webm';
                a.click();
                URL.revokeObjectURL(url);

                // Reset state
                isRecording = false;
                document.getElementById('status-overlay').style.display = 'none';
                clock.start(); // Resume normal animation clock
                animate(); // Restart the animation loop
            };

            // Show status overlay
            const statusOverlay = document.getElementById('status-overlay');
            const statusText = document.getElementById('status-text');
            const progressBar = document.getElementById('progress-bar-inner');
            statusOverlay.style.display = 'flex';

            mediaRecorder.start();
            clock.stop(); // Pause the normal animation clock

            function recordFrame() {
                if (currentFrame > totalFrames) {
                    mediaRecorder.stop();
                    return;
                }

                // Update status
                const progress = (currentFrame / totalFrames) * 100;
                statusText.textContent = `Recording... ${Math.round(progress)}%`;
                progressBar.style.width = `${progress}%`;

                // Set the exact time for this frame
                recordedTime = currentFrame * frameDuration;

                // Render the frame
                animate();

                // Schedule the next frame
                setTimeout(() => {
                    currentFrame++;
                    recordFrame();
                }, 0); // Use setTimeout(0) for non-blocking rendering
            }

            recordFrame();
        }

        // --- STARTUP ---
        init();

    </script>
</body>
