    <script>
        // ===================================================================================
        // MOCK SERVER & GAME CONSTANTS
        // In a real application, this would be a WebSocket server.
        // Here, we simulate it to create a dynamic single-player experience with AI.
        // ===================================================================================

        const MOCK_SERVER_TICK_RATE = 1000 / 30; // 30 updates per second
        const GAME_WIDTH = 1000;
        const GAME_HEIGHT = 700;
        const PLAYER_SIZE = 20;
        const PLAYER_SPEED = 3;
        const MAX_HEALTH = 100;
        const RESPAWN_TIME = 3000; // 3 seconds

        // Weapon definitions
        const WEAPONS = {
            'pistol': {
                id: 1,
                name: 'Pistol',
                damage: 10,
                fireRate: 400, // ms between shots
                projectileSpeed: 8,
                projectileSize: 3,
                color: '#c5c5c5'
            },
            'rifle': {
                id: 2,
                name: 'Rifle',
                damage: 25,
                fireRate: 150,
                projectileSpeed: 12,
                projectileSize: 4,
                color: '#ffc107'
            }
        };

        // ===================================================================================
        // GAME CLASSES
        // ===================================================================================

        /**
         * Represents a player in the game (can be human or AI).
         */
        class Player {
            constructor(id, name, color, isAI = false) {
                this.id = id;
                this.name = name;
                this.color = color;
                this.isAI = isAI;

                this.x = Math.random() * (GAME_WIDTH - PLAYER_SIZE);
                this.y = Math.random() * (GAME_HEIGHT - PLAYER_SIZE);
                this.health = MAX_HEALTH;
                this.kills = 0;
                this.deaths = 0;

                this.vx = 0; // Velocity x
                this.vy = 0; // Velocity y

                this.weapon = WEAPONS.pistol;
                this.lastShotTime = 0;
                this.isDead = false;

                // AI-specific properties
                this.aiTarget = null;
                this.aiMoveTicker = 0;
                this.aiChangeDirectionInterval = Math.random() * 100 + 50;
            }

            /**
             * Reduces player health and handles death.
             * @param {number} damage - The amount of damage to take.
             * @param {string} killerName - The name of the player who dealt the damage.
             * @returns {boolean} - True if the player died, false otherwise.
             */
            takeDamage(damage, killerName) {
                if (this.isDead) return false;

                this.health -= damage;
                if (this.health <= 0) {
                    this.health = 0;
                    this.isDead = true;
                    this.deaths++;
                    mockServer.broadcastMessage('kill', { victimName: this.name, killerName });

                    // Schedule respawn
                    setTimeout(() => this.respawn(), RESPAWN_TIME);
                    return true;
                }
                return false;
            }

            /**
             * Respawns the player at a random location with full health.
             */
            respawn() {
                this.health = MAX_HEALTH;
                this.isDead = false;
                this.x = Math.random() * (GAME_WIDTH - PLAYER_SIZE);
                this.y = Math.random() * (GAME_HEIGHT - PLAYER_SIZE);
            }

            /**
             * Updates the player's position based on their velocity.
             */
            update() {
                if (this.isDead) return;

                // Update position
                this.x += this.vx;
                this.y += this.vy;

                // Boundary checks to keep player within the canvas
                this.x = Math.max(PLAYER_SIZE, Math.min(GAME_WIDTH - PLAYER_SIZE, this.x));
                this.y = Math.max(PLAYER_SIZE, Math.min(GAME_HEIGHT - PLAYER_SIZE, this.y));
            }

            /**
             * Draws the player on the canvas.
             * @param {CanvasRenderingContext2D} ctx - The canvas rendering context.
             */
            draw(ctx) {
                if (this.isDead) return;

                // Draw player circle
                ctx.fillStyle = this.color;
                ctx.beginPath();
                ctx.arc(this.x, this.y, PLAYER_SIZE, 0, Math.PI * 2);
                ctx.fill();

                // Draw player name
                ctx.fillStyle = 'white';
                ctx.font = '12px sans-serif';
                ctx.textAlign = 'center';
                ctx.fillText(this.name, this.x, this.y - PLAYER_SIZE - 10);

                // Draw health bar above player
                const healthBarWidth = 40;
                const healthBarHeight = 5;
                ctx.fillStyle = '#333';
                ctx.fillRect(this.x - healthBarWidth / 2, this.y - PLAYER_SIZE - 8, healthBarWidth, healthBarHeight);
                ctx.fillStyle = 'red';
                ctx.fillRect(this.x - healthBarWidth / 2, this.y - PLAYER_SIZE - 8, healthBarWidth * (this.health / MAX_HEALTH), healthBarHeight);
            }
        }

        /**
         * Represents a projectile (bullet) in the game.
         */
        class Projectile {
            constructor(id, ownerId, x, y, angle, weapon) {
                this.id = id;
                this.ownerId = ownerId;
                this.x = x;
                this.y = y;
                this.speed = weapon.projectileSpeed;
                this.damage = weapon.damage;
                this.size = weapon.projectileSize;
                this.color = weapon.color;
                this.vx = Math.cos(angle) * this.speed;
                this.vy = Math.sin(angle) * this.speed;
            }

            /**
             * Updates the projectile's position.
             */
            update() {
                this.x += this.vx;
                this.y += this.vy;
            }

            /**
             * Draws the projectile on the canvas.
             * @param {CanvasRenderingContext2D} ctx - The canvas rendering context.
             */
            draw(ctx) {
                ctx.fillStyle = this.color;
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                ctx.fill();
            }
        }

        /**
         * Simulates a server to manage game state, AI, and events.
         */
        class MockServer {
            constructor() {
                this.players = {};
                this.projectiles = {};
                this.lastProjectileId = 0;
                this.lastPlayerId = 0;
            }

            /**
             * Starts the server's update loop.
             */
            start() {
                setInterval(() => this.update(), MOCK_SERVER_TICK_RATE);
            }

            /**
             * Adds a new player to the game.
             * @param {string} name - The name of the new player.
             * @param {boolean} isAI - Whether the player is an AI.
             * @returns {Player} The created player object.
             */
            addPlayer(name, isAI = false) {
                const id = ++this.lastPlayerId;
                const colors = ['#e63946', '#f1faee', '#a8dadc', '#457b9d', '#1d3557'];
                const color = colors[id % colors.length];
                const player = new Player(id, name, color, isAI);
                this.players[id] = player;
                return player;
            }

            /**
             * Handles incoming messages from clients (in this simulation, from the main game logic).
             * @param {string} type - The type of message (e.g., 'move', 'shoot').
             * @param {object} data - The message payload.
             */
            handleMessage(type, data) {
                switch (type) {
                    case 'move': {
                        const player = this.players[data.id];
                        if (player) {
                            player.vx = data.vx;
                            player.vy = data.vy;
                        }
                        break;
                    }
                    case 'shoot': {
                        const player = this.players[data.id];
                        const now = Date.now();
                        if (player && !player.isDead && (now - player.lastShotTime) > player.weapon.fireRate) {
                            player.lastShotTime = now;
                            const projectileId = ++this.lastProjectileId;
                            const projectile = new Projectile(projectileId, player.id, player.x, player.y, data.angle, player.weapon);
                            this.projectiles[projectileId] = projectile;
                        }
                        break;
                    }
                    case 'switch_weapon': {
                        const player = this.players[data.id];
                        if (player && !player.isDead) {
                            player.weapon = data.weapon;
                        }
                        break;
                    }
                }
            }

            /**
             * Broadcasts a message to the game client (in this case, calls a method on the game instance).
             * @param {string} type - The type of message.
             * @param {object} data - The message payload.
             */
            broadcastMessage(type, data) {
                game.handleServerMessage(type, data);
            }

            /**
             * The main server loop: updates game state, AI, and checks for collisions.
             */
            update() {
                // Update all players and run AI logic
                Object.values(this.players).forEach(player => {
                    if (player.isAI) {
                        this.updateAI(player);
                    }
                    player.update();
                });

                // Update projectiles and check for collisions
                Object.values(this.projectiles).forEach(proj => {
                    proj.update();

                    // Check for collision with players
                    Object.values(this.players).forEach(player => {
                        if (proj.ownerId !== player.id && !player.isDead) {
                            const dist = Math.hypot(proj.x - player.x, proj.y - player.y);
                            if (dist < PLAYER_SIZE + proj.size) {
                                const owner = this.players[proj.ownerId];
                                const died = player.takeDamage(proj.damage, owner.name);
                                if (died) {
                                    owner.kills++;
                                }
                                delete this.projectiles[proj.id]; // Remove projectile on hit
                            }
                        }
                    });

                    // Remove projectiles that go off-screen
                    if (proj.x < 0 || proj.x > GAME_WIDTH || proj.y < 0 || proj.y > GAME_HEIGHT) {
                        delete this.projectiles[proj.id];
                    }
                });

                // Send the complete game state to the client
                this.broadcastMessage('game_state', {
                    players: this.players,
                    projectiles: this.projectiles
                });
            }

            /**
             * Simple AI logic for computer-controlled players.
             * @param {Player} aiPlayer - The AI player to update.
             */
            updateAI(aiPlayer) {
                if (aiPlayer.isDead) {
                    aiPlayer.vx = 0;
                    aiPlayer.vy = 0;
                    return;
                }

                // Periodically change direction
                aiPlayer.aiMoveTicker++;
                if (aiPlayer.aiMoveTicker > aiPlayer.aiChangeDirectionInterval) {
                    const moveAngle = Math.random() * Math.PI * 2;
                    aiPlayer.vx = Math.cos(moveAngle) * PLAYER_SPEED / 2; // AI moves slower
                    aiPlayer.vy = Math.sin(moveAngle) * PLAYER_SPEED / 2;
                    aiPlayer.aiMoveTicker = 0;
                    aiPlayer.aiChangeDirectionInterval = Math.random() * 100 + 50;
                }

                // Find the closest non-AI player to target
                let closestPlayer = null;
                let minDistance = Infinity;
                Object.values(this.players).forEach(p => {
                    if (!p.isAI && !p.isDead) {
                        const dist = Math.hypot(aiPlayer.x - p.x, aiPlayer.y - p.y);
                        if (dist < minDistance) {
                            minDistance = dist;
                            closestPlayer = p;
                        }
                    }
                });

                // If a target is found, shoot at them
                if (closestPlayer) {
                    const angle = Math.atan2(closestPlayer.y - aiPlayer.y, closestPlayer.x - aiPlayer.x);
                    this.handleMessage('shoot', { id: aiPlayer.id, angle });
                }
            }
        }

        /**
         * Main game class to manage rendering, user input, and UI.
         */
        class Game {
            constructor() {
                // HTML Elements
                this.lobbyEl = document.getElementById('lobby');
                this.gameContainerEl = document.getElementById('game-container');
                this.canvas = document.getElementById('game-canvas');
                this.ctx = this.canvas.getContext('2d');
                this.playerNameInput = document.getElementById('player-name-input');
                this.joinGameBtn = document.getElementById('join-game-btn');

                // UI Elements
                this.scoreboardBody = document.querySelector('#scoreboard-table tbody');
                this.healthBar = document.getElementById('health-bar');
                this.weaponInfo = document.getElementById('weapon-info');
                this.chatMessages = document.getElementById('chat-messages');
                this.chatInput = document.getElementById('chat-input');
                this.killFeed = document.getElementById('kill-feed');

                // Game State
                this.localPlayer = null;
                this.gameState = { players: {}, projectiles: {} };
                this.keys = {}; // For tracking pressed keys
                this.mouse = { x: 0, y: 0, down: false };
            }

            /**
             * Initializes the game, sets up event listeners, and starts the game loop.
             */
            init() {
                this.canvas.width = GAME_WIDTH;
                this.canvas.height = GAME_HEIGHT;

                // Event Listeners
                this.joinGameBtn.addEventListener('click', () => this.joinGame());
                this.playerNameInput.addEventListener('keyup', (e) => {
                    if (e.key === 'Enter') this.joinGame();
                });

                // Input handling
                window.addEventListener('keydown', (e) => { this.keys[e.key.toLowerCase()] = true; this.handleWeaponSwitch(e); });
                window.addEventListener('keyup', (e) => { this.keys[e.key.toLowerCase()] = false; });
                this.canvas.addEventListener('mousemove', (e) => this.updateMousePos(e));
                this.canvas.addEventListener('mousedown', () => { this.mouse.down = true; });
                this.canvas.addEventListener('mouseup', () => { this.mouse.down = false; });

                // Chat
                this.chatInput.addEventListener('keyup', (e) => {
                    if (e.key === 'Enter' && this.chatInput.value.trim() !== '') {
                        this.addChatMessage(this.localPlayer.name, this.chatInput.value);
                        this.chatInput.value = '';
                    }
                });
            }

            /**
             * Handles the player joining the game from the lobby.
             */
            joinGame() {
                const playerName = this.playerNameInput.value.trim() || 'Player';

                this.lobbyEl.style.display = 'none';
                this.gameContainerEl.style.display = 'block';

                // "Connect" to the server and create the local player
                this.localPlayer = mockServer.addPlayer(playerName);

                // Add some AI players for fun
                mockServer.addPlayer('Bot Alice', true);
                mockServer.addPlayer('Bot Bob', true);
                mockServer.addPlayer('Bot Charlie', true);

                // Start the server and the game loop
                mockServer.start();
                this.gameLoop();
            }

            /**
             * The main rendering and input loop.
             */
            gameLoop() {
                this.handleInput();
                this.render();
                requestAnimationFrame(() => this.gameLoop());
            }

            /**
             * Handles user input for movement and shooting.
             */
            handleInput() {
                if (!this.localPlayer || this.localPlayer.isDead) {
                    mockServer.handleMessage('move', { id: this.localPlayer.id, vx: 0, vy: 0 });
                    return;
                }

                // Movement
                let vx = 0;
                let vy = 0;
                if (this.keys['w']) vy = -PLAYER_SPEED;
                if (this.keys['s']) vy = PLAYER_SPEED;
                if (this.keys['a']) vx = -PLAYER_SPEED;
                if (this.keys['d']) vx = PLAYER_SPEED;
                mockServer.handleMessage('move', { id: this.localPlayer.id, vx, vy });

                // Shooting
                if (this.mouse.down) {
                    const angle = Math.atan2(this.mouse.y - this.localPlayer.y, this.mouse.x - this.localPlayer.x);
                    mockServer.handleMessage('shoot', { id: this.localPlayer.id, angle });
                }
            }

            /**
             * Handles weapon switching based on key presses.
             * @param {KeyboardEvent} e - The keyboard event.
             */
            handleWeaponSwitch(e) {
                if (!this.localPlayer || this.localPlayer.isDead) return;

                let newWeapon = null;
                if (e.key === '1') newWeapon = WEAPONS.pistol;
                if (e.key === '2') newWeapon = WEAPONS.rifle;

                if (newWeapon && this.localPlayer.weapon.id !== newWeapon.id) {
                    mockServer.handleMessage('switch_weapon', { id: this.localPlayer.id, weapon: newWeapon });
                }
            }

            /**
             * Renders the entire game state onto the canvas.
             */
            render() {
                // Clear canvas
                this.ctx.clearRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

                // Draw players
                Object.values(this.gameState.players).forEach(p => {
                    const player = new Player(p.id, p.name, p.color);
                    Object.assign(player, p); // Sync state
                    player.draw(this.ctx);
                });

                // Draw projectiles
                Object.values(this.gameState.projectiles).forEach(p => {
                    const projectile = new Projectile(p.id, p.ownerId, p.x, p.y, 0, {
                        projectileSpeed: 0, damage: p.damage, projectileSize: p.size, color: p.color
                    });
                    Object.assign(projectile, p); // Sync state
                    projectile.draw(this.ctx);
                });
            }

            /**
             * Handles messages received from the mock server.
             * @param {string} type - The message type.
             * @param {object} data - The message payload.
             */
            handleServerMessage(type, data) {
                switch (type) {
                    case 'game_state':
                        this.gameState = data;
                        // Update local player reference from the new state
                        this.localPlayer = this.gameState.players[this.localPlayer.id];
                        this.updateUI();
                        break;
                    case 'kill':
                        this.addKillFeedMessage(data.killerName, data.victimName);
                        break;
                }
            }

            /**
             * Updates all HTML-based UI elements.
             */
            updateUI() {
                if (!this.localPlayer) return;

                // Update health bar
                this.healthBar.style.width = `${(this.localPlayer.health / MAX_HEALTH) * 100}%`;
                this.healthBar.style.backgroundColor = this.localPlayer.health > 50 ? '#4CAF50' : (this.localPlayer.health > 25 ? '#ffc107' : '#e63946');

                // Update weapon info
                this.weaponInfo.textContent = this.localPlayer.weapon.name;

                // Update scoreboard
                const sortedPlayers = Object.values(this.gameState.players).sort((a, b) => b.kills - a.kills);
                this.scoreboardBody.innerHTML = sortedPlayers.map(p => `
                    <tr style="color: ${p.id === this.localPlayer.id ? '#4CAF50' : 'white'}">
                        <td>${p.name} ${p.id === this.localPlayer.id ? '(You)' : ''}</td>
                        <td>${p.kills}</td>
                        <td>${p.deaths}</td>
                    </tr>
                `).join('');
            }

            /**
             * Adds a message to the chat box.
             * @param {string} sender - The name of the message sender.
             * @param {string} message - The chat message.
             */
            addChatMessage(sender, message) {
                const messageEl = document.createElement('div');
                messageEl.innerHTML = `<strong>${sender}:</strong> ${message}`;
                this.chatMessages.appendChild(messageEl);
                this.chatMessages.scrollTop = this.chatMessages.scrollHeight; // Auto-scroll
            }

            /**
             * Adds a message to the kill feed.
             * @param {string} killer - The killer's name.
             * @param {string} victim - The victim's name.
             */
            addKillFeedMessage(killer, victim) {
                const messageEl = document.createElement('div');
                messageEl.innerHTML = `<strong>${killer}</strong> eliminated <strong>${victim}</strong>`;
                this.killFeed.prepend(messageEl);
                // Limit kill feed messages to 5
                if (this.killFeed.children.length > 5) {
                    this.killFeed.removeChild(this.killFeed.lastChild);
                }
            }

            /**
             * Updates the stored mouse position relative to the canvas.
             * @param {MouseEvent} e - The mouse event.
             */
            updateMousePos(e) {
                const rect = this.canvas.getBoundingClientRect();
                this.mouse.x = e.clientX - rect.left;
                this.mouse.y = e.clientY - rect.top;
            }
        }

        // ===================================================================================
        // APP INITIALIZATION
        // ===================================================================================

        const mockServer = new MockServer();
        const game = new Game();
