#### `monitor.py` - The Core Monitoring Engine

This file defines the database structure and the function that probes a website.

```python
# monitor.py
import requests
import time
from sqlalchemy import create_engine, Column, Integer, String, Float, DateTime, func
from sqlalchemy.orm import sessionmaker
from sqlalchemy.ext.declarative import declarative_base

# --- Database Setup ---
DATABASE_URL = "sqlite:///monitoring_data.db"
engine = create_engine(DATABASE_URL)
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)
Base = declarative_base()

class MonitoringResult(Base):
    __tablename__ = "monitoring_results"
    id = Column(Integer, primary_key=True, index=True)
    region_name = Column(String, index=True)
    probe_url = Column(String)
    http_status = Column(Integer)
    response_time_ms = Column(Float)
    error_message = Column(String, nullable=True)
    timestamp = Column(DateTime, server_default=func.now())

# Create the table if it doesn't exist
Base.metadata.create_all(bind=engine)

# --- Monitoring Logic ---
def probe_site(url: str, region_name: str):
    """
    Probes a given URL and returns performance metrics.
    In a real-world scenario, this function would be executed on a server
    physically located in the specified region.
    """
    result = {
        "region_name": region_name,
        "probe_url": url,
        "http_status": 0,
        "response_time_ms": -1.0,
        "error_message": None,
    }
    try:
        start_time = time.perf_counter()
        response = requests.get(url, timeout=10) # 10-second timeout
        end_time = time.perf_counter()

        result["response_time_ms"] = (end_time - start_time) * 1000
        result["http_status"] = response.status_code

        if response.status_code >= 400:
            result["error_message"] = f"HTTP Error: {response.status_code}"

    except requests.exceptions.RequestException as e:
        result["error_message"] = str(e)
        result["response_time_ms"] = 10000 # Penalize with max timeout

    return result

def save_result(result_data: dict):
    """Saves a monitoring result to the database."""
    db = SessionLocal()
    try:
        db_result = MonitoringResult(**result_data)
        db.add(db_result)
        db.commit()
    finally:
        db.close()

```

