# app.py
from flask import Flask, jsonify, render_template
from apscheduler.schedulers.background import BackgroundScheduler
from datetime import datetime, timedelta
import pandas as pd

from monitor import probe_site, save_result, SessionLocal, MonitoringResult

# --- Configuration ---
# The URL of the website you want to monitor
TARGET_URL = "https://www.wikipedia.org" 

# Define probe locations (Region Name, Latitude, Longitude)
# In a real system, you'd have actual servers at these locations.
PROBE_REGIONS = {
    "US-East (Virginia)": (37.47, -77.45),
    "US-West (California)": (34.05, -118.24),
    "EU-West (Ireland)": (53.34, -6.26),
    "EU-Central (Frankfurt)": (50.11, 6.86),
    "Asia-Pacific (Tokyo)": (35.68, 139.69),
    "Asia-Pacific (Sydney)": (-33.86, 151.20),
    "South America (São Paulo)": (-23.55, -46.63),
}

# Detection frequency in seconds
DETECTION_FREQUENCY_SECONDS = 300 # 5 minutes

# Alerting conditions
ALERT_LATENCY_THRESHOLD_MS = 1000  # Alert if latency > 1000ms
ALERT_ERROR_RATE_THRESHOLD = 0.1 # Alert if error rate > 10% in the last hour

# --- Flask App Initialization ---
app = Flask(__name__)

# --- Monitoring Job ---
def run_monitoring_job():
    """Scheduled job to probe the target URL from all defined regions."""
    print(f"[{datetime.now()}] Running monitoring job for {TARGET_URL}...")
    for region_name, _ in PROBE_REGIONS.items():
        result = probe_site(TARGET_URL, region_name)
        save_result(result)
        print(f"  - {region_name}: {result['response_time_ms']:.2f} ms, Status: {result['http_status']}")

# --- Scheduler Setup ---
scheduler = BackgroundScheduler(daemon=True)
scheduler.add_job(run_monitoring_job, 'interval', seconds=DETECTION_FREQUENCY_SECONDS)
scheduler.start()

# --- API Endpoints ---
@app.route('/')
def index():
    """Serves the main dashboard page."""
    return render_template('index.html')

@app.route('/api/data')
def get_monitoring_data():
    """API endpoint to get the latest monitoring data for all regions."""
    db = SessionLocal()
    latest_data = []
    try:
        for region_name, coords in PROBE_REGIONS.items():
            latest_result = db.query(MonitoringResult)\
                .filter(MonitoringResult.region_name == region_name)\
                .order_by(MonitoringResult.timestamp.desc())\
                .first()

            if latest_result:
                latest_data.append({
                    "region": region_name,
                    "lat": coords[0],
                    "lon": coords[1],
                    "latency": latest_result.response_time_ms,
                    "status": latest_result.http_status,
                    "error": latest_result.error_message,
                    "timestamp": latest_result.timestamp.isoformat()
                })
    finally:
        db.close()
    return jsonify(latest_data)

@app.route('/api/analysis/<region_name>')
def get_analysis(region_name):
    """API endpoint for historical data, trend analysis, and recommendations."""
    db = SessionLocal()
    try:
        # 1. Historical Data (last 24 hours)
        time_filter = datetime.utcnow() - timedelta(hours=24)
        historical_results = db.query(MonitoringResult)\
            .filter(MonitoringResult.region_name == region_name)\
            .filter(MonitoringResult.timestamp >= time_filter)\
            .order_by(MonitoringResult.timestamp.asc())\
            .all()

        if not historical_results:
            return jsonify({"error": "No data for this region in the last 24 hours"}), 404

        df = pd.DataFrame([{
            "timestamp": r.timestamp,
            "latency": r.response_time_ms,
            "is_error": 1 if r.http_status == 0 or r.http_status >= 400 else 0
        } for r in historical_results])

        # 2. Trend Analysis (Simple Moving Average)
        df['latency_sma'] = df['latency'].rolling(window=5, min_periods=1).mean()

        # 3. Alerting & Recommendations
        alert_status = "OK"
        recommendation = "System performance is nominal."

        last_hour_df = df[df['timestamp'] > datetime.utcnow() - timedelta(hours=1)]
        if not last_hour_df.empty:
            avg_latency_last_hour = last_hour_df['latency'].mean()
            error_rate_last_hour = last_hour_df['is_error'].mean()

            if avg_latency_last_hour > ALERT_LATENCY_THRESHOLD_MS:
                alert_status = "High Latency"
                recommendation = (f"High latency detected in {region_name} (avg {avg_latency_last_hour:.0f}ms). "
                                  f"Consider routing traffic through an alternative CDN node or investigating network path.")

            if error_rate_last_hour > ALERT_ERROR_RATE_THRESHOLD:
                alert_status = "High Error Rate"
                recommendation = (f"High error rate ({error_rate_last_hour:.1%}) in {region_name}. "
                                  f"Investigate origin server health for this region. Recommend failing over to a secondary CDN provider if available.")

        response = {
            "region": region_name,
            "alert_status": alert_status,
            "recommendation": recommendation,
            "historical_data": {
                "timestamps": [ts.isoformat() for ts in df['timestamp']],
                "latencies": df['latency'].tolist(),
                "latencies_sma": df['latency_sma'].tolist()
            }
        }
        return jsonify(response)
    finally:
        db.close()

if __name__ == '__main__':
    # Run an initial check to populate data immediately
    run_monitoring_job()
    # Start the Flask app
    app.run(debug=True, use_reloader=False) # use_reloader=False is important for APScheduler
