        if (status === 0 || status >= 400) return '#e74c3c'; // Red for error
        if (latency > 1000) return '#f39c12'; // Orange for slow
        return '#2ecc71'; // Green for OK
    }

    async function updateMap() {
        try {
            const response = await fetch('/api/data');
            const data = await response.json();

            data.forEach(regionData => {
                const color = getStatusColor(regionData.latency, regionData.status);
                const popupContent = `
                    <b>${regionData.region}</b><br>
                    Latency: ${regionData.latency.toFixed(2)} ms<br>
                    Status: ${regionData.status}<br>
                    Timestamp: ${new Date(regionData.timestamp).toLocaleString()}
                `;

                if (markers[regionData.region]) {
                    markers[regionData.region].setLatLng([regionData.lat, regionData.lon])
                        .setPopupContent(popupContent)
                        .setStyle({ color: color, fillColor: color });
                } else {
                    markers[regionData.region] = L.circleMarker([regionData.lat, regionData.lon], {
                        radius: 8,
                        color: color,
                        fillColor: color,
                        fillOpacity: 0.8
                    }).addTo(map)
                      .bindPopup(popupContent)
                      .on('click', () => fetchRegionDetails(regionData.region));
                }
            });
        } catch (error) {
            console.error('Failed to fetch map data:', error);
        }
    }

    async function fetchRegionDetails(regionName) {
        detailsPanel.classList.remove('hidden');
        detailsRegion.textContent = regionName;
        alertStatusEl.textContent = 'Loading...';
        recommendationEl.textContent = 'Loading...';

        try {
            const response = await fetch(`/api/analysis/${regionName}`);
            if (!response.ok) throw new Error('Failed to load analysis data');
            const data = await response.json();

            // Update status and recommendation
            alertStatusEl.textContent = data.alert_status;
            alertStatusEl.className = ''; // Clear previous classes
            if (data.alert_status === 'OK') alertStatusEl.classList.add('status-ok');
            else if (data.alert_status === 'High Latency') alertStatusEl.classList.add('status-warning');
            else alertStatusEl.classList.add('status-error');

            recommendationEl.textContent = data.recommendation;

            // Update chart
            const chartData = {
                labels: data.historical_data.timestamps,
                datasets: [{
                    label: 'Latency (ms)',
                    data: data.historical_data.latencies,
                    borderColor: '#3498db',
                    tension: 0.1,
                    pointRadius: 0
                }, {
                    label: '5-Point SMA',
                    data: data.historical_data.latencies_sma,
                    borderColor: '#e74c3c',
                    borderDash: [5, 5],
                    tension: 0.1,
                    pointRadius: 0
                }]
            };

            if (historyChart) {
                historyChart.data = chartData;
                historyChart.update();
            } else {
                historyChart = new Chart(chartCanvas, {
                    type: 'line',
                    data: chartData,
                    options: {
