                                time: { unit: 'hour' },
                                title: { display: true, text: 'Time' }
                            },
                            y: {
                                title: { display: true, text: 'Latency (ms)' },
                                beginAtZero: true
                            }
                        },
                        responsive: true,
                        maintainAspectRatio: false
                    }
                });
            }

        } catch (error) {
            console.error('Failed to fetch region details:', error);
            alertStatusEl.textContent = 'Error';
            recommendationEl.textContent = 'Could not load analysis data.';
        }
    }

    // Initial load and periodic refresh
    updateMap();
    setInterval(updateMap, 30000); // Refresh map every 30 seconds
});
