```javascript
import React, { useState, useCallback } from 'react';
import { DndProvider } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import FurnitureList from './components/FurnitureList';
import VirtualRoom from './components/VirtualRoom';
import ShoppingCart from './components/ShoppingCart';
import './App.css';

// Mock data for our furniture catalog
const FURNITURE_CATALOG = [
  { id: 1, name: 'Modern Sofa', price: 799.99, image: 'https://via.placeholder.com/80x60.png?text=Sofa' },
  { id: 2, name: 'Coffee Table', price: 149.99, image: 'https://via.placeholder.com/60x40.png?text=Table' },
  { id: 3, name: 'Floor Lamp', price: 89.99, image: 'https://via.placeholder.com/30x80.png?text=Lamp' },
  { id: 4, name: 'Bookshelf', price: 249.99, image: 'https://via.placeholder.com/70x90.png?text=Shelf' },
];

function App() {
  const [roomItems, setRoomItems] = useState([]);
  const [cartItems, setCartItems] = useState([]);
  const [nextId, setNextId] = useState(1);

  const handleDropInRoom = (item) => {
    const newItem = { ...item, instanceId: nextId, top: 100, left: 100 };
    setNextId(nextId + 1);
    setRoomItems((prev) => [...prev, newItem]);
    setCartItems((prev) => [...prev, newItem]);
  };

  const moveRoomItem = useCallback((id, left, top) => {
    setRoomItems((prevItems) =>
      prevItems.map((item) => (item.instanceId === id ? { ...item, left, top } : item))
    );
  }, []);

  const removeFromCart = (instanceId) => {
    setCartItems(prev => prev.filter(item => item.instanceId !== instanceId));
    setRoomItems(prev => prev.filter(item => item.instanceId !== instanceId));
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="app-container">
        <h1 className="app-title">My Virtual Furniture Store</h1>
        <div className="main-layout">
          <FurnitureList catalog={FURNITURE_CATALOG} />
          <VirtualRoom items={roomItems} onDrop={handleDropInRoom} moveItem={moveRoomItem} />
          <ShoppingCart items={cartItems} onRemove={removeFromCart} />
        </div>
      </div>
    </DndProvider>
  );
}

export default App;
```

