**`src/components/VirtualRoom.js`**
```javascript
import React from 'react';
import { useDrop } from 'react-dnd';
import { ItemTypes } from '../itemTypes';
import RoomItem from './RoomItem';

const VirtualRoom = ({ items, onDrop, moveItem }) => {
  const [, drop] = useDrop(() => ({
    accept: [ItemTypes.FURNITURE, ItemTypes.ROOM_ITEM],
    drop: (item, monitor) => {
      const delta = monitor.getDifferenceFromInitialOffset();
      if (item.instanceId) { // It's an existing RoomItem
        const left = Math.round(item.left + delta.x);
        const top = Math.round(item.top + delta.y);
        moveItem(item.instanceId, left, top);
      } else { // It's a new item from the list
        onDrop(item);
      }
    },
  }), [moveItem, onDrop]);

  return (
    <div ref={drop} className="panel virtual-room">
      <h2>Virtual Room Preview</h2>
      <p className="instructions">Drag furniture from the catalog here!</p>
      {items.map((item) => (
        <RoomItem key={item.instanceId} item={item} />
      ))}
    </div>
  );
};

export default VirtualRoom;
```

