This module encapsulates all the musical knowledge. It defines notes, frequencies, and functions to build scales and chords. This separation of concerns is a key professional practice.

```javascript
const MusicTheory = (() => {
    const NOTES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
    const BASE_FREQUENCIES = {
        'A4': 440.00,
        'A#4': 466.16,
        'B4': 493.88,
        'C4': 261.63,
        'C#4': 277.18,
        'D4': 293.66,
        'D#4': 311.13,
        'E4': 329.63,
        'F4': 349.23,
        'F#4': 369.99,
        'G4': 392.00,
        'G#4': 415.30,
    };

    const SCALE_INTERVALS = {
        major: [0, 2, 4, 5, 7, 9, 11], // W-W-H-W-W-W-H
        natural_minor: [0, 2, 3, 5, 7, 8, 10], // W-H-W-W-H-W-W
        harmonic_minor: [0, 2, 3, 5, 7, 8, 11],
        major_pentatonic: [0, 2, 4, 7, 9],
    };

    const CHORD_INTERVALS = {
        major: [0, 4, 7],
        minor: [0, 3, 7],
        diminished: [0, 3, 6],
        augmented: [0, 4, 8],
        major_seventh: [0, 4, 7, 11],
    };

    const DIATONIC_CHORDS = { // In a major key
        major: ['major', 'minor', 'minor', 'major', 'major', 'minor', 'diminished']
    };

    const ROMAN_NUMERALS = ['I', 'ii', 'iii', 'IV', 'V', 'vi', 'vii°'];

    function getNoteFromInterval(rootNote, interval) {
        const rootIndex = NOTES.indexOf(rootNote.slice(0, -1));
        const octave = parseInt(rootNote.slice(-1));
        const newIndex = (rootIndex + interval) % 12;
        // Simple octave handling for this demo
        const newOctave = (rootIndex + interval >= 12) ? octave + 1 : octave;
        return `${NOTES[newIndex]}${newOctave}`;
    }

    return {
        getScale: (rootNote, type) => {
            const intervals = SCALE_INTERVALS[type];
            if (!intervals) return [];
            return intervals.map(interval => getNoteFromInterval(rootNote, interval));
        },

        getChord: (rootNote, type) => {
            const intervals = CHORD_INTERVALS[type];
            if (!intervals) return [];
            return intervals.map(interval => getNoteFromInterval(rootNote, interval));
        },

        getDiatonicChords: (rootNote, scaleType) => {
            const scaleNotes = MusicTheory.getScale(rootNote, scaleType);
            const chordTypes = DIATONIC_CHORDS[scaleType];
            if (!scaleNotes || !chordTypes) return [];

            return scaleNotes.map((note, index) => {
                return {
                    roman: ROMAN_NUMERALS[index],
                    root: note,
                    type: chordTypes[index],
                    notes: MusicTheory.getChord(note, chordTypes[index])
                };
            });
        },

        getFrequency: (note) => {
            const noteName = note.slice(0, -1);
            const octave = parseInt(note.slice(-1));
            const baseNote = `${noteName}4`; // Use 4th octave as reference
            const baseFreq = BASE_FREQUENCIES[baseNote];
            if (!baseFreq) return null;
            return baseFreq * Math.pow(2, octave - 4);
        }
    };
})();
```

