### Step 4: Audio Generation (`js/audio.js`)

This module handles all interactions with the Web Audio API. It's responsible for creating and playing sounds.

```javascript
const AudioPlayer = (() => {
    let audioContext;

    // It's best practice to create the AudioContext after a user gesture.
    function getAudioContext() {
        if (!audioContext) {
            audioContext = new (window.AudioContext || window.webkitAudioContext)();
        }
        return audioContext;
    }

    function playNote(frequency, duration, startTime) {
        const context = getAudioContext();
        const oscillator = context.createOscillator();
        const gainNode = context.createGain();

        oscillator.type = 'sine'; // 'sine', 'square', 'sawtooth', 'triangle'
        oscillator.frequency.setValueAtTime(frequency, context.currentTime);

        // Fade out to prevent clicking
        gainNode.gain.setValueAtTime(1, startTime);
        gainNode.gain.exponentialRampToValueAtTime(0.001, startTime + duration);

        oscillator.connect(gainNode);
        gainNode.connect(context.destination);

        oscillator.start(startTime);
        oscillator.stop(startTime + duration);
    }

    return {
        // Plays notes one after another
        playSequence: (notes, noteDuration = 0.4, delay = 0.1) => {
            const context = getAudioContext();
            notes.forEach((note, index) => {
                const freq = MusicTheory.getFrequency(note);
                if (freq) {
                    const startTime = context.currentTime + index * (noteDuration + delay);
                    playNote(freq, noteDuration, startTime);
                }
            });
        },

        // Plays notes simultaneously
        playChord: (notes, duration = 1.0) => {
            const context = getAudioContext();
            notes.forEach(note => {
                const freq = MusicTheory.getFrequency(note);
                if (freq) {
                    playNote(freq, duration, context.currentTime);
                }
            });
        }
    };
})();
```

