### Step 5: Main Application Logic (`js/main.js`)

This is the orchestrator. It connects the UI, the theory logic, and the audio player by setting up event listeners and managing the application's state.

```javascript
document.addEventListener('DOMContentLoaded', () => {
    // --- Navigation ---
    const pages = document.querySelectorAll('.page');
    const navLinks = document.querySelectorAll('nav a');

    function showPage(pageId) {
        pages.forEach(page => {
            page.classList.toggle('active', page.id === `${pageId}-page`);
        });
        navLinks.forEach(link => {
            link.classList.toggle('active', link.dataset.page === pageId);
        });
    }

    navLinks.forEach(link => {
        link.addEventListener('click', (e) => {
            e.preventDefault();
            showPage(e.target.dataset.page);
        });
    });

    // --- Scales Page ---
    const playScaleBtn = document.getElementById('play-scale-btn');
    const scaleRootSelect = document.getElementById('scale-root');
    const scaleTypeSelect = document.getElementById('scale-type');
    const scaleDisplay = document.getElementById('scale-display');

    playScaleBtn.addEventListener('click', () => {
        const root = scaleRootSelect.value;
        const type = scaleTypeSelect.value;
        const scaleNotes = MusicTheory.getScale(root, type);
        scaleDisplay.textContent = scaleNotes.join(' - ');
        AudioPlayer.playSequence(scaleNotes);
    });

    // --- Chords Page ---
    const playChordBtn = document.getElementById('play-chord-btn');
    const chordRootSelect = document.getElementById('chord-root');
    const chordTypeSelect = document.getElementById('chord-type');
    const chordDisplay = document.getElementById('chord-display');

    playChordBtn.addEventListener('click', () => {
        const root = chordRootSelect.value;
        const type = chordTypeSelect.value;
        const chordNotes = MusicTheory.getChord(root, type);
        chordDisplay.textContent = chordNotes.join(' - ');
        AudioPlayer.playChord(chordNotes);
    });

    // --- Practice Page ---
    const newProgressionBtn = document.getElementById('new-progression-btn');
    const challengeDisplay = document.getElementById('progression-challenge');
    const userDisplay = document.getElementById('user-progression-display');
    const chordsContainer = document.getElementById('diatonic-chords-container');
    const feedbackDisplay = document.getElementById('feedback');

    let currentChallenge = {
        key: '',
        progression: [],
        diatonicChords: []
    };
    let userProgression = [];

    const progressions = [
        ['I', 'V', 'vi', 'IV'],
        ['I', 'IV', 'V', 'I'],
        ['ii', 'V', 'I'],
        ['vi', 'IV', 'I', 'V']
    ];

    function generateNewProgression() {
        const keys = ['C4', 'G4', 'D4', 'A4', 'E4'];
        currentChallenge.key = keys[Math.floor(Math.random() * keys.length)];
        currentChallenge.progression = progressions[Math.floor(Math.random() * progressions.length)];
        currentChallenge.diatonicChords = MusicTheory.getDiatonicChords(currentChallenge.key, 'major');

        userProgression = [];
        updateDisplays();
        renderDiatonicChordButtons();
    }

    function renderDiatonicChordButtons() {
        chordsContainer.innerHTML = '';
        currentChallenge.diatonicChords.forEach(chord => {
            const button = document.createElement('button');
            button.textContent = `${chord.roman} (${chord.root.slice(0,-1)} ${chord.type})`;
            button.dataset.roman = chord.roman;
            button.addEventListener('click', () => handleChordButtonClick(chord));
            chordsContainer.appendChild(button);
        });
    }

    function handleChordButtonClick(chord) {
        userProgression.push(chord.roman);
        AudioPlayer.playChord(chord.notes);
        updateDisplays();
        checkProgression();
    }


    function checkProgression() {
        if (userProgression.length === currentChallenge.progression.length) {
            const isCorrect = JSON.stringify(userProgression) === JSON.stringify(currentChallenge.progression);
            feedbackDisplay.textContent = isCorrect ? 'Correct! Well done!' : 'Not quite. Try again or get a new progression.';
            feedbackDisplay.className = `feedback-box ${isCorrect ? 'correct' : 'incorrect'}`;
        }
    }

    function updateDisplays() {
        const keyName = currentChallenge.key.slice(0, -1);
        challengeDisplay.textContent = `Play: ${currentChallenge.progression.join(' - ')} in ${keyName} Major`;
        userDisplay.textContent = userProgression.join(' - ') || '...';
        feedbackDisplay.textContent = '';
        feedbackDisplay.className = 'feedback-box';
    }

    newProgressionBtn.addEventListener('click', generateNewProgression);

    // Initialize the first challenge
    generateNewProgression();
    // Set the initial page
    showPage('introduction');
});
```

