**`server/server.js`**
```javascript
const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const multer = require('multer');
const path = require('path');
const cors = require('cors');
const fs = require('fs');

const app = express();
const PORT = 3001;

// --- Middleware ---
app.use(cors());
app.use(express.json());
// Serve static files from the 'uploads' directory
app.use('/uploads', express.static(path.join(__dirname, 'uploads')));

// --- Database Setup ---
const dbPath = path.resolve(__dirname, 'menu.db');
const db = new sqlite3.Database(dbPath, (err) => {
    if (err) {
        console.error("Error opening database", err.message);
    } else {
        console.log("Connected to the SQLite database.");
        // Create table if it doesn't exist
        db.run(`CREATE TABLE IF NOT EXISTS menus (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            description TEXT,
            price REAL NOT NULL,
            category TEXT NOT NULL,
            image_path TEXT,
            status TEXT NOT NULL DEFAULT 'pending', -- pending, approved, rejected
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )`, (err) => {
            if (err) {
                console.error("Error creating table", err.message);
            }
        });
    }
});

// --- File Upload Setup (Multer) ---
const storage = multer.diskStorage({
    destination: (req, file, cb) => {
        const dir = './uploads';
        if (!fs.existsSync(dir)){
            fs.mkdirSync(dir);
        }
        cb(null, dir);
    },
    filename: (req, file, cb) => {
        // Create a unique filename to avoid conflicts
        cb(null, `${Date.now()}-${file.originalname}`);
    }
});
const upload = multer({ storage: storage });

// --- API Endpoints ---

// [CHEF] Upload a new menu item
app.post('/api/menus', upload.single('image'), (req, res) => {
    const { name, description, price, category } = req.body;
    const imagePath = req.file ? `/uploads/${req.file.filename}` : null;

    if (!name || !price || !category || !imagePath) {
        return res.status(400).json({ error: 'Missing required fields.' });
    }

    const sql = `INSERT INTO menus (name, description, price, category, image_path, status) VALUES (?, ?, ?, ?, ?, 'pending')`;
    db.run(sql, [name, description, price, category, imagePath], function(err) {
        if (err) {
            return res.status(500).json({ error: err.message });
        }
        res.status(201).json({ id: this.lastID, message: 'Menu item submitted for review.' });
    });
});

// [MANAGER] Get all pending menu items for review
app.get('/api/menus/pending', (req, res) => {
    const sql = `SELECT * FROM menus WHERE status = 'pending' ORDER BY created_at DESC`;
    db.all(sql, [], (err, rows) => {
        if (err) {
            return res.status(500).json({ error: err.message });
        }
        res.json(rows);
    });
});

// [MANAGER] Update a menu item's status (approve/reject)
app.put('/api/menus/:id/status', (req, res) => {
    const { status } = req.body;
    const { id } = req.params;

    if (!['approved', 'rejected'].includes(status)) {
        return res.status(400).json({ error: 'Invalid status.' });
    }

    const sql = `UPDATE menus SET status = ? WHERE id = ?`;
    db.run(sql, [status, id], function(err) {
        if (err) {
            return res.status(500).json({ error: err.message });
        }
        if (this.changes === 0) {
            return res.status(404).json({ error: 'Menu item not found.' });
        }
        res.json({ message: `Menu item has been ${status}.` });
    });
});

// [CUSTOMER] Get all approved menu items
app.get('/api/menus/approved', (req, res) => {
    const sql = `SELECT * FROM menus WHERE status = 'approved' ORDER BY category, name`;
    db.all(sql, [], (err, rows) => {
        if (err) {
            return res.status(500).json({ error: err.message });
        }
        res.json(rows);
    });
});


// --- Start Server ---
app.listen(PORT, () => {
    console.log(`Server is running on http://localhost:${PORT}`);
});
```

