import React, { useState } from 'react';
import axios from 'axios';

function ChefDashboard() {
    const [formData, setFormData] = useState({
        name: '',
        description: '',
        price: '',
        category: 'Appetizer',
        image: null
    });
    const [message, setMessage] = useState('');

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData({ ...formData, [name]: value });
    };

    const handleFileChange = (e) => {
        setFormData({ ...formData, image: e.target.files[0] });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setMessage('');

        const data = new FormData();
        data.append('name', formData.name);
        data.append('description', formData.description);
        data.append('price', formData.price);
        data.append('category', formData.category);
        data.append('image', formData.image);

        try {
            const response = await axios.post('/api/menus', data, {
                headers: {
                    'Content-Type': 'multipart/form-data'
                }
            });
            setMessage(response.data.message);
            // Reset form
            setFormData({ name: '', description: '', price: '', category: 'Appetizer', image: null });
            e.target.reset();
        } catch (error) {
            setMessage('Error uploading menu item: ' + (error.response?.data?.error || error.message));
        }
    };

    return (
        <div className="form-container">
            <h1>Chef Dashboard</h1>
            <h2>Upload New Menu Item</h2>
            <form onSubmit={handleSubmit}>
                <div className="form-group">
                    <label>Dish Name</label>
                    <input type="text" name="name" value={formData.name} onChange={handleChange} required />
                </div>
                <div className="form-group">
                    <label>Description</label>
                    <textarea name="description" value={formData.description} onChange={handleChange}></textarea>
                </div>
                <div className="form-group">
                    <label>Price ($)</label>
                    <input type="number" name="price" step="0.01" value={formData.price} onChange={handleChange} required />
                </div>
                <div className="form-group">
                    <label>Category</label>
                    <select name="category" value={formData.category} onChange={handleChange}>
                        <option value="Appetizer">Appetizer</option>
                        <option value="Main Course">Main Course</option>
                        <option value="Dessert">Dessert</option>
                        <option value="Beverage">Beverage</option>
                    </select>
                </div>
                <div className="form-group">
                    <label>Dish Image</label>
                    <input type="file" name="image" onChange={handleFileChange} required />
                </div>
                <button type="submit" className="btn">Submit for Review</button>
            </form>
            {message && <p>{message}</p>}
        </div>
    );
}

export default ChefDashboard;
```

