import React, { useState, useEffect } from 'react';
import axios from 'axios';

function ManagerDashboard() {
    const [pendingMenus, setPendingMenus] = useState([]);
    const [message, setMessage] = useState('');

    useEffect(() => {
        fetchPendingMenus();
    }, []);

    const fetchPendingMenus = async () => {
        try {
            const response = await axios.get('/api/menus/pending');
            setPendingMenus(response.data);
        } catch (error) {
            console.error('Error fetching pending menus:', error);
            setMessage('Failed to fetch pending items.');
        }
    };

    const handleStatusUpdate = async (id, status) => {
        try {
            await axios.put(`/api/menus/${id}/status`, { status });
            setMessage(`Menu item ${id} has been ${status}.`);
            // Refresh the list by filtering out the updated item
            setPendingMenus(pendingMenus.filter(menu => menu.id !== id));
        } catch (error) {
            console.error(`Error updating status for menu ${id}:`, error);
            setMessage(`Failed to update item ${id}.`);
        }
    };

    return (
        <div>
            <h1>Manager Dashboard</h1>
            <h2>Pending Menu Items for Review</h2>
            {message && <p>{message}</p>}
            {pendingMenus.length === 0 ? (
                <p>No pending menu items to review.</p>
            ) : (
                <div className="menu-grid">
                    {pendingMenus.map(menu => (
                        <div key={menu.id} className="menu-card">
                            <img src={menu.image_path} alt={menu.name} />
                            <div className="menu-card-content">
                                <div className="menu-card-header">
                                    <h3>{menu.name}</h3>
                                    <span className="menu-card-price">${parseFloat(menu.price).toFixed(2)}</span>
                                </div>
                                <p className="menu-card-description">{menu.description}</p>
                                <p><strong>Category:</strong> {menu.category}</p>
                                <div className="manager-actions">
                                    <button onClick={() => handleStatusUpdate(menu.id, 'approved')} className="btn btn-approve">Approve</button>
                                    <button onClick={() => handleStatusUpdate(menu.id, 'rejected')} className="btn btn-reject">Reject</button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

export default ManagerDashboard;
