import React, { useState, useEffect } from 'react';
import axios from 'axios';

function CustomerMenu() {
    const [menu, setMenu] = useState({});
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchApprovedMenu = async () => {
            try {
                const response = await axios.get('/api/menus/approved');
                // Group menu items by category
                const groupedMenu = response.data.reduce((acc, item) => {
                    const category = item.category;
                    if (!acc[category]) {
                        acc[category] = [];
                    }
                    acc[category].push(item);
                    return acc;
                }, {});
                setMenu(groupedMenu);
            } catch (error) {
                console.error('Error fetching approved menu:', error);
            } finally {
                setLoading(false);
            }
        };

        fetchApprovedMenu();
    }, []);

    if (loading) {
        return <p>Loading menu...</p>;
    }

    return (
        <div>
            <h1>Our Menu</h1>
            {Object.keys(menu).length === 0 ? (
                <p>The menu is currently empty. Please check back later!</p>
            ) : (
                Object.entries(menu).map(([category, items]) => (
                    <div key={category} className="menu-category">
                        <h2>{category}</h2>
                        <div className="menu-grid">
                            {items.map(item => (
                                <div key={item.id} className="menu-card">
