                                    <div className="menu-card-content">
                                        <div className="menu-card-header">
                                            <h3>{item.name}</h3>
                                            <span className="menu-card-price">${parseFloat(item.price).toFixed(2)}</span>
                                        </div>
                                        <p className="menu-card-description">{item.description}</p>
                                    </div>
                                </div>
                            ))}
