```javascript:script.js
document.addEventListener('DOMContentLoaded', () => {
    // DOM element references
    const imageLoader = document.getElementById('image-loader');
    const thumbnailContainer = document.getElementById('thumbnail-container');
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const mainContent = document.getElementById('main-content');
    const downloadSection = document.getElementById('download-section');
    const downloadBtn = document.getElementById('download-btn');
    const processingStatus = document.getElementById('processing-status');
    const clearAnnotationsBtn = document.getElementById('clear-annotations-btn');

    // Application state
    let images = []; // Stores { file, dataURL, annotations } for each image
    let currentImageIndex = -1;

    // --- Event Listeners ---

    // Listen for file input changes
    imageLoader.addEventListener('change', handleImageUpload);

    // Listen for clicks on thumbnails to switch the active image
    thumbnailContainer.addEventListener('click', handleThumbnailClick);

    // Listen for clicks on the canvas to add an annotation
    canvas.addEventListener('click', handleCanvasClick);

    // Listen for the download button click
    downloadBtn.addEventListener('click', downloadAllImagesAsZip);

    // Listen for the clear annotations button click
    clearAnnotationsBtn.addEventListener('click', clearCurrentAnnotations);


    // --- Functions ---

    /**
     * Handles the selection of image files from the user's computer.
     * @param {Event} e - The file input change event.
     */
    function handleImageUpload(e) {
        const files = e.target.files;
        if (files.length === 0) return;

        // Reset application state
        images = [];
        thumbnailContainer.innerHTML = '';
        currentImageIndex = -1;

        // Show the main content and download sections
        mainContent.classList.remove('hidden');
        downloadSection.classList.remove('hidden');

        // Process each selected file
        Array.from(files).forEach((file, index) => {
            const reader = new FileReader();
            reader.onload = (event) => {
                // Store image data and initialize annotations
                images.push({
                    file: file,
                    dataURL: event.target.result,
                    annotations: []
                });

                // Create and display a thumbnail
                createThumbnail(event.target.result, index);

                // If it's the first image, load it onto the canvas
                if (index === 0) {
                    selectImage(0);
                }
            };
            reader.readAsDataURL(file);
        });
    }

    /**
     * Creates a thumbnail image and adds it to the thumbnail panel.
     * @param {string} dataURL - The data URL of the image.
     * @param {number} index - The index of the image in the `images` array.
     */
    function createThumbnail(dataURL, index) {
        const img = document.createElement('img');
        img.src = dataURL;
        img.classList.add('thumbnail');
        img.dataset.index = index;
        thumbnailContainer.appendChild(img);
    }

    /**
     * Handles clicks on thumbnail images to select them for annotation.
     * @param {Event} e - The click event.
     */
    function handleThumbnailClick(e) {
        if (e.target.classList.contains('thumbnail')) {
            const index = parseInt(e.target.dataset.index, 10);
            selectImage(index);
        }
    }

    /**
     * Selects an image by its index, updates the UI, and loads it onto the canvas.
     * @param {number} index - The index of the image to select.
     */
    function selectImage(index) {
        if (index < 0 || index >= images.length) return;

        currentImageIndex = index;

        // Update active state on thumbnails
        document.querySelectorAll('.thumbnail').forEach((thumb, i) => {
            thumb.classList.toggle('active', i === index);
        });

        // Load the selected image and its annotations onto the canvas
        loadImageOnCanvas(images[index]);
    }

    /**
     * Loads an image onto the canvas and redraws its annotations.
     * @param {object} imageData - The image object from the `images` array.
     */
    function loadImageOnCanvas(imageData) {
        const img = new Image();
        img.onload = () => {
            // Set canvas dimensions to match the image
            canvas.width = img.width;
            canvas.height = img.height;
            // Draw the image
            ctx.drawImage(img, 0, 0);
            // Redraw any existing annotations for this image
            redrawAnnotations();
        };
        img.src = imageData.dataURL;
    }

    /**
     * Handles clicks on the canvas to place a new annotation.
     * @param {Event} e - The mouse click event.
     */
    function handleCanvasClick(e) {
        if (currentImageIndex === -1) return;

        // Get annotation properties from the control inputs
        const text = document.getElementById('annotation-text').value;
        if (!text) {
            alert('Please enter annotation text first.');
            return;
        }
        const fontSize = document.getElementById('font-size').value;
        const color = document.getElementById('font-color').value;

        // Get click coordinates relative to the canvas
        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;
        const x = (e.clientX - rect.left) * scaleX;
        const y = (e.clientY - rect.top) * scaleY;

        // Create and store the new annotation
        const annotation = { text, x, y, fontSize, color };
        images[currentImageIndex].annotations.push(annotation);

        // Redraw the canvas with the new annotation
        redrawAnnotations();
    }

    /**
     * Redraws the current image and all its annotations on the canvas.
     */
    function redrawAnnotations() {
        if (currentImageIndex === -1) return;

        const imageData = images[currentImageIndex];
        const img = new Image();
        img.onload = () => {
            // Clear canvas and redraw the base image
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.drawImage(img, 0, 0);

            // Draw each annotation
            imageData.annotations.forEach(ann => {
                ctx.font = `${ann.fontSize}px Arial`;
                ctx.fillStyle = ann.color;
                ctx.textBaseline = 'top';
                ctx.fillText(ann.text, ann.x, ann.y);
            });
        };
        img.src = imageData.dataURL;
    }

    /**
     * Clears all annotations for the currently selected image.
     */
    function clearCurrentAnnotations() {
        if (currentImageIndex > -1) {
            if (confirm('Are you sure you want to clear all annotations for this image?')) {
                images[currentImageIndex].annotations = [];
                redrawAnnotations();
            }
        }
    }

    /**
     * Generates an annotated image on an off-screen canvas and returns it as a Blob.
     * @param {object} imageData - The image object from the `images` array.
     * @returns {Promise<Blob>} A promise that resolves with the image Blob.
     */
    function generateAnnotatedImage(imageData) {
        return new Promise((resolve) => {
            const offscreenCanvas = document.createElement('canvas');
            const offscreenCtx = offscreenCanvas.getContext('2d');
            const img = new Image();

            img.onload = () => {
                // Set canvas size and draw image
                offscreenCanvas.width = img.width;
                offscreenCanvas.height = img.height;
                offscreenCtx.drawImage(img, 0, 0);

                // Draw annotations
                imageData.annotations.forEach(ann => {
                    offscreenCtx.font = `${ann.fontSize}px Arial`;
                    offscreenCtx.fillStyle = ann.color;
                    offscreenCtx.textBaseline = 'top';
                    offscreenCtx.fillText(ann.text, ann.x, ann.y);
                });

                // Convert canvas to Blob and resolve the promise
                offscreenCanvas.toBlob(blob => {
                    resolve(blob);
                }, 'image/png');
            };
            img.src = imageData.dataURL;
        });
    }

    /**
     * Initiates the process to download all annotated images as a single ZIP file.
     */
    async function downloadAllImagesAsZip() {
        if (images.length === 0) {
            alert('No images to download.');
            return;
        }

        // Update UI to show processing state
        downloadBtn.disabled = true;
        processingStatus.classList.remove('hidden');

        const zip = new JSZip();

        // Generate each annotated image and add it to the zip
        for (const imageData of images) {
            const blob = await generateAnnotatedImage(imageData);
            // Sanitize filename
            const fileName = imageData.file.name.replace(/\.[^/.]+$/, "") + '_annotated.png';
            zip.file(fileName, blob);
        }

        // Generate the ZIP file and trigger download
        zip.generateAsync({ type: 'blob' }).then(content => {
            const link = document.createElement('a');
            link.href = URL.createObjectURL(content);
            link.download = 'annotated_images.zip';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);

            // Reset UI
            downloadBtn.disabled = false;
            processingStatus.classList.add('hidden');
        });
    }
});
```

Of course. As a code expert, I will provide a comprehensive, professional solution for building a video subtitle adding tool. This guide will cover the architecture, backend processing, frontend interface, and potential professional-grade enhancements.

The solution will use a powerful and common stack for this type of task:

*   **Backend:** Python with the **Flask** web framework. Python is excellent for scripting and managing system processes.
*   **Video Processing:** **FFmpeg**, the industry-standard, open-source command-line tool for video and audio manipulation. It's incredibly powerful for tasks like embedding (hardcoding) subtitles.
*   **Frontend:** Standard **HTML, CSS, and JavaScript** for the user interface, without requiring complex frameworks to keep the example clear and focused.

### Conceptual Overview & Architecture

1.  **Frontend (Client-Side):** The user interacts with a web page.
    *   They upload a video file.
    *   The video is displayed in a player, which includes a timeline (slider).
    *   The user adds "subtitle events," specifying the text, start/end times, font, color, and position for each.
    *   When ready, the user clicks "Process." The frontend packages the video file and a JSON object describing all the subtitles and sends it to the backend.

2.  **Backend (Server-Side):** The Flask server receives the request.
    *   It saves the uploaded video to a temporary directory.
    *   It parses the subtitle JSON data.
    *   It dynamically constructs a complex **FFmpeg command** that uses the `drawtext` filter to "burn" each subtitle onto the video frames according to the specified properties.
    *   It executes this command as a system process.
    *   Once FFmpeg finishes, the server provides a download link to the newly created video.

---

### Step 1: Prerequisites and Setup

First, ensure you have the necessary tools installed.

**1. Install Python and Flask:**
If you don't have Python, download it from [python.org](https://python.org). Then, install Flask:
```bash
pip install Flask
```

**2. Install FFmpeg:**
This is the most critical component. It must be installed and accessible from your system's command line (i.e., in your system's PATH).

*   **Windows:** Download from [ffmpeg.org](https://ffmpeg.org/download.html) (get the gpl-shared build) and add the `bin` directory to your system's PATH environment variable.
*   **macOS:** Use Homebrew: `brew install ffmpeg`
*   **Linux (Debian/Ubuntu):** `sudo apt update && sudo apt install ffmpeg`

To verify, open a terminal/command prompt and type `ffmpeg -version`. You should see version information, not an error.

