### Step 3: Backend Development (`app.py`)

This Flask application will handle file uploads and orchestrate the FFmpeg process.

```python
import os
import json
import uuid
import subprocess
from flask import Flask, request, render_template, send_from_directory, jsonify

app = Flask(__name__)

# Configuration
UPLOAD_FOLDER = 'uploads'
OUTPUT_FOLDER = 'outputs'
FONT_FOLDER = 'fonts'
ALLOWED_EXTENSIONS = {'mp4', 'mov', 'avi', 'mkv'}

app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER
app.config['OUTPUT_FOLDER'] = OUTPUT_FOLDER
app.config['FONT_FOLDER'] = FONT_FOLDER

# Ensure directories exist
os.makedirs(UPLOAD_FOLDER, exist_ok=True)
os.makedirs(OUTPUT_FOLDER, exist_ok=True)
os.makedirs(FONT_FOLDER, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_text(text):
    """Sanitizes text for FFmpeg command to prevent injection."""
    # FFmpeg's text filter is sensitive to characters like ':', '\', etc.
    # A simple escape is to wrap in single quotes after escaping internal single quotes.
    return text.replace("'", "'\\''")

@app.route('/')
def index():
    """Serves the main HTML page."""
    return render_template('index.html')

@app.route('/process', methods=['POST'])
def process_video():
    """Handles video upload and subtitle processing."""
    if 'video' not in request.files:
        return jsonify({"error": "No video file part"}), 400

    video_file = request.files['video']
    subtitles_data_str = request.form.get('subtitles')

    if video_file.filename == '' or not subtitles_data_str:
        return jsonify({"error": "Missing video file or subtitle data"}), 400

    if video_file and allowed_file(video_file.filename):
        # Generate unique filenames to avoid conflicts
        unique_id = str(uuid.uuid4())
        input_filename = f"{unique_id}_{video_file.filename}"
        output_filename = f"processed_{input_filename}"
        input_path = os.path.join(app.config['UPLOAD_FOLDER'], input_filename)
        output_path = os.path.join(app.config['OUTPUT_FOLDER'], output_filename)

        video_file.save(input_path)

        try:
            subtitles = json.loads(subtitles_data_str)

            # --- FFmpeg Command Construction ---
            # Base command
            ffmpeg_cmd = [
                'ffmpeg',
                '-i', input_path,
                '-vf' # Video Filter complex graph
            ]

            filter_complex = []
            for sub in subtitles:
                text = sanitize_text(sub['text'])
                start = float(sub['start'])
                end = float(sub['end'])
                pos_x = sub['position']['x']
                pos_y = sub['position']['y']
                font_color = sub['font']['color']
                font_size = int(sub['font']['size'])
                font_file = os.path.join(app.config['FONT_FOLDER'], 'Arial.ttf').replace('\\', '/') # Ensure cross-platform path

                # FFmpeg drawtext filter with semi-transparent background
                drawtext_filter = (
                    f"drawtext="
                    f"fontfile='{font_file}':"
                    f"text='{text}':"
                    f"fontsize={font_size}:"
                    f"fontcolor={font_color}:"
                    f"x={pos_x}:"
                    f"y={pos_y}:"
                    f"box=1:boxcolor=black@0.5:boxborderw=10:" # The magic for the background box
                    f"enable='between(t,{start},{end})'"
                )
                filter_complex.append(drawtext_filter)

            ffmpeg_cmd.append(','.join(filter_complex))
            ffmpeg_cmd.extend(['-c:a', 'copy', output_path]) # Copy audio stream without re-encoding

            # Execute the command
            print("Executing FFmpeg command:", ' '.join(ffmpeg_cmd))
            subprocess.run(ffmpeg_cmd, check=True)

            # Clean up the original uploaded file
            os.remove(input_path)

            return jsonify({"download_url": f"/download/{output_filename}"})

        except json.JSONDecodeError:
            return jsonify({"error": "Invalid subtitle JSON data"}), 400
        except subprocess.CalledProcessError as e:
            # If FFmpeg fails, clean up and report error
            if os.path.exists(input_path): os.remove(input_path)
            if os.path.exists(output_path): os.remove(output_path)
            return jsonify({"error": f"FFmpeg processing failed: {e}"}), 500
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    return jsonify({"error": "Invalid file type"}), 400

@app.route('/download/<filename>')
def download_file(filename):
    """Serves the processed video for download."""
    return send_from_directory(app.config['OUTPUT_FOLDER'], filename, as_attachment=True)

if __name__ == '__main__':
    app.run(debug=True)
