```javascript
document.addEventListener('DOMContentLoaded', () => {
    const videoUpload = document.getElementById('video-upload');
    const videoPlayer = document.getElementById('video-player');
    const mainContent = document.querySelector('.main-content');
    const currentTimeDisplay = document.getElementById('current-time');
    const addSubtitleBtn = document.getElementById('add-subtitle-btn');
    const subtitlesList = document.getElementById('subtitles-list');
    const processVideoBtn = document.getElementById('process-video-btn');
    const statusArea = document.getElementById('status-area');

    let subtitleCounter = 0;

    // 1. Handle Video Upload
    videoUpload.addEventListener('change', (event) => {
        const file = event.target.files[0];
        if (file) {
            const fileURL = URL.createObjectURL(file);
            videoPlayer.src = fileURL;
            mainContent.style.display = 'block';
        }
    });

    // 2. Update Current Time Display
    videoPlayer.addEventListener('timeupdate', () => {
        currentTimeDisplay.textContent = `${videoPlayer.currentTime.toFixed(2)}s`;
    });

    // 3. Add New Subtitle Entry
    addSubtitleBtn.addEventListener('click', () => {
        subtitleCounter++;
        const subtitleId = `subtitle-${subtitleCounter}`;
        const subtitleEntry = document.createElement('div');
        subtitleEntry.classList.add('subtitle-entry');
        subtitleEntry.id = subtitleId;
        subtitleEntry.innerHTML = `
            <h4>Subtitle #${subtitleCounter} <button class="delete-btn" data-target="${subtitleId}">X</button></h4>
            <textarea placeholder="Enter subtitle text..."></textarea>
            <div class="controls">
                <div><label>Start Time (s)</label><input type="number" class="start-time" step="0.1" value="0.0"></div>
                <div><label>End Time (s)</label><input type="number" class="end-time" step="0.1" value="0.0"></div>
                <div><label>Font Size</label><input type="number" class="font-size" value="24"></div>
                <div><label>Font Color</label><input type="color" class="font-color" value="#FFFFFF"></div>
                <div>
                    <label>Position</label>
                    <select class="position">
                        <option value="x=(w-text_w)/2:y=h-th-10" selected>Bottom Center</option>
                        <option value="x=(w-text_w)/2:y=10">Top Center</option>
                        <option value="x=10:y=h-th-10">Bottom Left</option>
                        <option value="x=w-tw-10:y=h-th-10">Bottom Right</option>
                        <option value="x=(w-text_w)/2:y=(h-text_h)/2">Center</option>
                    </select>
                </div>
            </div>
        `;
        subtitlesList.appendChild(subtitleEntry);

        // Add event listener for the new delete button
        subtitleEntry.querySelector('.delete-btn').addEventListener('click', (e) => {
            document.getElementById(e.target.dataset.target).remove();
        });
    });

    // 4. Mark Start/End Time from Video Player
    document.getElementById('mark-start-btn').addEventListener('click', () => {
        const lastEntry = subtitlesList.lastElementChild;
        if (lastEntry) {
            lastEntry.querySelector('.start-time').value = videoPlayer.currentTime.toFixed(2);
        }
    });

    document.getElementById('mark-end-btn').addEventListener('click', () => {
        const lastEntry = subtitlesList.lastElementChild;
        if (lastEntry) {
            lastEntry.querySelector('.end-time').value = videoPlayer.currentTime.toFixed(2);
        }
    });

    // 5. Process Video
    processVideoBtn.addEventListener('click', async () => {
        const videoFile = videoUpload.files[0];
        if (!videoFile) {
            alert('Please upload a video first.');
            return;
        }

        const subtitlesData = [];
        const subtitleEntries = subtitlesList.querySelectorAll('.subtitle-entry');

        subtitleEntries.forEach(entry => {
            const text = entry.querySelector('textarea').value;
            const start = entry.querySelector('.start-time').value;
            const end = entry.querySelector('.end-time').value;
            const positionValue = entry.querySelector('.position').value;
            const [x, y] = positionValue.split(':');

            if (text && start && end) {
                subtitlesData.push({
                    text: text,
                    start: start,
                    end: end,
                    font: {
                        size: entry.querySelector('.font-size').value,
                        color: entry.querySelector('.font-color').value,
                    },
                    position: { x, y }
                });
            }
        });

        if (subtitlesData.length === 0) {
            alert('Please add at least one subtitle.');
            return;
        }

        statusArea.innerHTML = 'Processing... This may take a while. Please do not close this page.';
        processVideoBtn.disabled = true;

        const formData = new FormData();
        formData.append('video', videoFile);
        formData.append('subtitles', JSON.stringify(subtitlesData));

        try {
            const response = await fetch('/process', {
                method: 'POST',
                body: formData
            });

            const result = await response.json();

            if (response.ok) {
                statusArea.innerHTML = `✅ Processing complete! <a href="${result.download_url}" download>Download Your Video</a>`;
            } else {
                throw new Error(result.error || 'An unknown error occurred.');
            }
        } catch (error) {
            statusArea.innerHTML = `❌ Error: ${error.message}`;
        } finally {
            processVideoBtn.disabled = false;
        }
    });
});
