    <script>
        // =================================================================
        // MOCK SERVER
        // In a real application, this would be a separate Node.js server.
        // For this self-contained example, we simulate it with a class.
        // It manages the game state and communicates with all clients.
        // =================================================================
        class MockServer {
            constructor() {
                this.clients = new Map();
                this.state = {
                    players: {},
                    bullets: []
                };
                this.lastBulletId = 0;
                this.map = { width: 800, height: 600 };
                this.playerConfig = {
                    radius: 15,
                    speed: 3,
                    maxHealth: 100,
                    respawnTime: 3000 // 3 seconds
                };
                this.bulletConfig = {
                    radius: 5,
                    speed: 7
                };
            }

            // Start the server's main loop
            start() {
                setInterval(() => this.update(), 1000 / 60); // 60 ticks per second
            }

            // Connect a new client (player)
            connect(client) {
                this.clients.set(client.id, client);
                console.log(`Server: Client ${client.id} connected.`);
            }

            // Handle messages received from clients
            handleMessage(clientId, type, data) {
                switch (type) {
                    case 'join':
                        this.addPlayer(clientId, data.name);
                        break;
                    case 'input':
                        this.updatePlayerInput(clientId, data);
                        break;
                    case 'shoot':
                        this.createBullet(clientId, data);
                        break;
                    case 'chat':
                        this.broadcast('chat', { sender: this.state.players[clientId].name, message: data.message });
                        break;
                }
            }

            // Send a message to all connected clients
            broadcast(type, data) {
                for (const client of this.clients.values()) {
                    client.handleServerMessage(type, data);
                }
            }

            // Add a new player to the game state
            addPlayer(id, name) {
                this.state.players[id] = {
                    id: id,
                    name: name,
                    x: Math.random() * (this.map.width - 100) + 50,
                    y: Math.random() * (this.map.height - 100) + 50,
                    radius: this.playerConfig.radius,
                    color: `hsl(${Math.random() * 360}, 100%, 50%)`,
                    health: this.playerConfig.maxHealth,
                    maxHealth: this.playerConfig.maxHealth,
                    isDead: false,
                    respawnTimer: 0,
                    kills: 0,
                    deaths: 0,
                    input: { left: false, right: false, up: false, down: false }
                };
                this.broadcast('chat', { sender: 'System', message: `${name} has joined the game.` });
            }

            // Update a player's input state
            updatePlayerInput(id, input) {
                const player = this.state.players[id];
                if (player && !player.isDead) {
                    player.input = input;
                }
            }

            // Create a new bullet
            createBullet(ownerId, target) {
                const player = this.state.players[ownerId];
                if (!player || player.isDead) return;

                const angle = Math.atan2(target.y - player.y, target.x - player.x);
                this.state.bullets.push({
                    id: this.lastBulletId++,
                    ownerId: ownerId,
                    x: player.x,
                    y: player.y,
                    radius: this.bulletConfig.radius,
                    color: player.color,
                    dx: Math.cos(angle) * this.bulletConfig.speed,
                    dy: Math.sin(angle) * this.bulletConfig.speed
                });
            }

            // The main server game loop
            update() {
                // Update player positions based on input
                for (const id in this.state.players) {
                    const player = this.state.players[id];
                    if (player.isDead) {
                        player.respawnTimer -= 1000 / 60;
                        if (player.respawnTimer <= 0) {
                            this.respawnPlayer(player);
                        }
                        continue;
                    }

                    const { speed } = this.playerConfig;
                    if (player.input.up) player.y -= speed;
                    if (player.input.down) player.y += speed;
                    if (player.input.left) player.x -= speed;
                    if (player.input.right) player.x += speed;

                    // Map boundaries collision
                    player.x = Math.max(player.radius, Math.min(this.map.width - player.radius, player.x));
                    player.y = Math.max(player.radius, Math.min(this.map.height - player.radius, player.y));
                }

                // Update bullet positions and check for collisions
                const bulletsToRemove = [];
                for (let i = this.state.bullets.length - 1; i >= 0; i--) {
                    const bullet = this.state.bullets[i];
                    bullet.x += bullet.dx;
                    bullet.y += bullet.dy;

                    // Remove bullets that go off-screen
                    if (bullet.x < 0 || bullet.x > this.map.width || bullet.y < 0 || bullet.y > this.map.height) {
                        bulletsToRemove.push(i);
                        continue;
                    }

                    // Check for collision with players
                    for (const id in this.state.players) {
                        const player = this.state.players[id];
                        if (player.isDead || player.id === bullet.ownerId) continue;

                        const distance = Math.hypot(bullet.x - player.x, bullet.y - player.y);
                        if (distance < player.radius + bullet.radius) {
                            this.handlePlayerHit(player, bullet);
                            bulletsToRemove.push(i);
                            break; // Bullet can only hit one player
                        }
                    }
                }

                // Clean up bullets that have been processed
                bulletsToRemove.forEach(index => this.state.bullets.splice(index, 1));

                // Broadcast the updated state to all clients
                this.broadcast('gameState', this.state);
            }

            // Handle a player getting hit
            handlePlayerHit(player, bullet) {
                player.health -= 25;
                if (player.health <= 0) {
                    player.health = 0;
                    player.isDead = true;
                    player.deaths += 1;
                    player.respawnTimer = this.playerConfig.respawnTime;

                    const killer = this.state.players[bullet.ownerId];
                    if (killer) {
                        killer.kills += 1;
                        this.broadcast('chat', { sender: 'System', message: `${killer.name} eliminated ${player.name}.` });
                    }
                }
            }

            // Respawn a player
            respawnPlayer(player) {
                player.isDead = false;
                player.health = this.playerConfig.maxHealth;
                player.x = Math.random() * (this.map.width - 100) + 50;
                player.y = Math.random() * (this.map.height - 100) + 50;
            }
        }

        // =================================================================
        // GAME CLIENT
        // This runs in the user's browser. It handles rendering,
        // user input, and communication with the (mock) server.
        // =================================================================
        class GameClient {
            constructor(canvas, server) {
                this.id = `client_${Math.random().toString(36).substr(2, 9)}`;
                this.canvas = canvas;
                this.ctx = canvas.getContext('2d');
                this.server = server;
                this.state = {};
                this.input = { up: false, down: false, left: false, right: false };
                this.mousePos = { x: 0, y: 0 };
                this.playerName = '';
            }

            // Initialize the client
            init() {
                this.server.connect(this);
                this.setupInputListeners();
                this.gameLoop();
            }

            // Set up keyboard and mouse event listeners
            setupInputListeners() {
                document.addEventListener('keydown', (e) => {
                    if (document.activeElement === document.getElementById('chat-input')) return;
                    switch (e.key.toLowerCase()) {
                        case 'w': this.input.up = true; break;
                        case 's': this.input.down = true; break;
                        case 'a': this.input.left = true; break;
                        case 'd': this.input.right = true; break;
                    }
                });

                document.addEventListener('keyup', (e) => {
                    if (document.activeElement === document.getElementById('chat-input')) return;
                    switch (e.key.toLowerCase()) {
                        case 'w': this.input.up = false; break;
                        case 's': this.input.down = false; break;
                        case 'a': this.input.left = false; break;
                        case 'd': this.input.right = false; break;
                    }
                });

                this.canvas.addEventListener('mousemove', (e) => {
                    const rect = this.canvas.getBoundingClientRect();
                    this.mousePos.x = e.clientX - rect.left;
                    this.mousePos.y = e.clientY - rect.top;
                });

                this.canvas.addEventListener('click', () => {
                    this.sendMessage('shoot', this.mousePos);
                });
            }

            // Join the game with a given name
            joinGame(name) {
                this.playerName = name;
                this.sendMessage('join', { name });
            }

            // Send a message to the server
            sendMessage(type, data) {
                this.server.handleMessage(this.id, type, data);
            }

            // Handle messages received from the server
            handleServerMessage(type, data) {
                switch (type) {
                    case 'gameState':
                        this.state = data;
                        this.updateUI();
                        break;
                    case 'chat':
                        this.displayChatMessage(data.sender, data.message);
                        break;
                }
            }

            // Main game loop for rendering
            gameLoop() {
                // Send current input state to the server
                this.sendMessage('input', this.input);

                // Clear canvas
                this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

                // Draw grid background
                this.drawGrid();

                // Draw players
                for (const id in this.state.players) {
                    this.drawPlayer(this.state.players[id]);
                }

                // Draw bullets
                this.state.bullets?.forEach(bullet => this.drawBullet(bullet));

                requestAnimationFrame(() => this.gameLoop());
            }

            // Draw the map grid
            drawGrid() {
                this.ctx.strokeStyle = '#2c2c2c';
                this.ctx.lineWidth = 1;
                for (let x = 0; x < this.canvas.width; x += 40) {
                    this.ctx.beginPath();
                    this.ctx.moveTo(x, 0);
                    this.ctx.lineTo(x, this.canvas.height);
                    this.ctx.stroke();
                }
                for (let y = 0; y < this.canvas.height; y += 40) {
                    this.ctx.beginPath();
                    this.ctx.moveTo(0, y);
                    this.ctx.lineTo(this.canvas.width, y);
                    this.ctx.stroke();
                }
            }

            // Draw a single player
            drawPlayer(player) {
                if (player.isDead) return;

                // Player circle
                this.ctx.beginPath();
                this.ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
                this.ctx.fillStyle = player.color;
                this.ctx.fill();

                // Player name
                this.ctx.fillStyle = '#fff';
                this.ctx.textAlign = 'center';
                this.ctx.font = '12px sans-serif';
                this.ctx.fillText(player.name, player.x, player.y - player.radius - 12);

                // Health bar
                const healthBarWidth = 40;
                const healthBarHeight = 5;
                this.ctx.fillStyle = '#333';
                this.ctx.fillRect(player.x - healthBarWidth / 2, player.y - player.radius - 8, healthBarWidth, healthBarHeight);
                this.ctx.fillStyle = 'red';
                this.ctx.fillRect(player.x - healthBarWidth / 2, player.y - player.radius - 8, healthBarWidth * (player.health / player.maxHealth), healthBarHeight);

                // Gun barrel for current player
                if (player.id === this.id) {
                    this.ctx.save();
                    this.ctx.translate(player.x, player.y);
                    const angle = Math.atan2(this.mousePos.y - player.y, this.mousePos.x - player.x);
                    this.ctx.rotate(angle);
                    this.ctx.fillStyle = '#999';
                    this.ctx.fillRect(player.radius - 5, -3, 20, 6);
                    this.ctx.restore();
                }
            }

            // Draw a single bullet
            drawBullet(bullet) {
                this.ctx.beginPath();
                this.ctx.arc(bullet.x, bullet.y, bullet.radius, 0, Math.PI * 2);
                this.ctx.fillStyle = bullet.color;
                this.ctx.fill();
            }

            // Update the scoreboard and other UI elements
            updateUI() {
                // Update scoreboard
                const scoreboardBody = document.querySelector('#scoreboard-table tbody');
                const playersArray = Object.values(this.state.players || {}).sort((a, b) => b.kills - a.kills);
                scoreboardBody.innerHTML = playersArray.map(p => `
                    <tr>
                        <td style="color: ${p.color}; font-weight: bold;">${p.name}</td>
                        <td>${p.kills}</td>
                        <td>${p.deaths}</td>
                    </tr>
                `).join('');
            }

            // Display a message in the chat box
            displayChatMessage(sender, message) {
                const chatMessages = document.getElementById('chat-messages');
                const messageElement = document.createElement('div');
                const senderSpan = document.createElement('span');
                senderSpan.style.fontWeight = 'bold';
                senderSpan.textContent = `${sender}: `;
                if (sender === 'System') {
                    senderSpan.style.color = '#4CAF50';
                }

                messageElement.appendChild(senderSpan);
                messageElement.append(document.createTextNode(message));
                chatMessages.appendChild(messageElement);
                chatMessages.scrollTop = chatMessages.scrollHeight; // Auto-scroll to bottom
            }
        }

        // =================================================================
        // MAIN APPLICATION LOGIC
        // =================================================================
        document.addEventListener('DOMContentLoaded', () => {
            const loginScreen = document.getElementById('login-screen');
            const gameArea = document.getElementById('game-area');
            const joinButton = document.getElementById('join-game-btn');
            const nameInput = document.getElementById('player-name-input');
            const canvas = document.getElementById('game-canvas');
            const chatForm = document.getElementById('chat-form');
            const chatInput = document.getElementById('chat-input');

            let gameClient;

            // Handle the "Join Game" button click
            joinButton.addEventListener('click', () => {
                const playerName = nameInput.value.trim();
                if (playerName) {
                    loginScreen.style.display = 'none';
                    gameArea.style.display = 'flex';

                    // Initialize and start the game
                    const server = new MockServer();
                    server.start();

                    gameClient = new GameClient(canvas, server);
                    gameClient.init();
                    gameClient.joinGame(playerName);
                } else {
                    alert('Please enter a name!');
                }
            });

            // Handle chat message submission
            chatForm.addEventListener('submit', (e) => {
                e.preventDefault();
                const message = chatInput.value.trim();
                if (message && gameClient) {
                    gameClient.sendMessage('chat', { message });
                    chatInput.value = '';
                }
            });
        });
    </script>
</body>
</html>
