// script.js
document.addEventListener('DOMContentLoaded', () => {
    // DOM Elements
    const mainAudioInput = document.getElementById('mainAudioInput');
    const mainAudioName = document.getElementById('mainAudioName');
    const watermarkAudioInput = document.getElementById('watermarkAudioInput');
    const watermarkAudioName = document.getElementById('watermarkAudioName');
    const watermarkTextInput = document.getElementById('watermarkTextInput');
    const typeAudioRadio = document.getElementById('typeAudio');
    const typeTextRadio = document.getElementById('typeText');
    const audioWatermarkOptions = document.getElementById('audioWatermarkOptions');
    const textWatermarkOptions = document.getElementById('textWatermarkOptions');
    const placementSelect = document.getElementById('placementSelect');
    const volumeSlider = document.getElementById('volumeSlider');
    const volumeValue = document.getElementById('volumeValue');
    const createButton = document.getElementById('createButton');
    const statusDiv = document.getElementById('status');
    const loader = document.getElementById('loader');
    const loaderText = document.getElementById('loader-text');

    // Web Audio API context
    let audioContext;

    // --- Event Listeners ---

    // Update file name display on selection
    mainAudioInput.addEventListener('change', () => updateFileName(mainAudioInput, mainAudioName));
    watermarkAudioInput.addEventListener('change', () => updateFileName(watermarkAudioInput, watermarkAudioName));

    // Toggle watermark option sections based on radio button selection
    typeAudioRadio.addEventListener('change', toggleWatermarkOptions);
    typeTextRadio.addEventListener('change', toggleWatermarkOptions);

    // Update volume display
    volumeSlider.addEventListener('input', () => {
        volumeValue.textContent = `${Math.round(volumeSlider.value * 100)}%`;
    });

    // Main process trigger
    createButton.addEventListener('click', processAudio);

    // --- UI Functions ---

    function updateFileName(inputElement, nameElement) {
        nameElement.textContent = inputElement.files.length > 0 ? inputElement.files[0].name : 'No file selected';
    }

    function toggleWatermarkOptions() {
        if (typeAudioRadio.checked) {
            audioWatermarkOptions.classList.remove('hidden');
            textWatermarkOptions.classList.add('hidden');
        } else {
            audioWatermarkOptions.classList.add('hidden');
            textWatermarkOptions.classList.remove('hidden');
        }
    }

    function showLoader(text) {
        loaderText.textContent = text;
        loader.classList.remove('hidden');
        createButton.disabled = true;
    }

    function hideLoader() {
        loader.classList.add('hidden');
        createButton.disabled = false;
    }

    function setStatus(message, isError = false) {
        statusDiv.textContent = message;
        statusDiv.style.color = isError ? 'red' : 'green';
    }

    // --- Core Audio Processing ---

    /**
     * Main function to start the audio watermarking process.
     */
    async function processAudio() {
        setStatus('');
        // 1. Validation
        if (!mainAudioInput.files[0]) {
            setStatus('Please select a main audio file.', true);
            return;
        }

        const isAudioWatermark = typeAudioRadio.checked;
        if (isAudioWatermark && !watermarkAudioInput.files[0]) {
            setStatus('Please select a watermark audio file.', true);
            return;
        }
        if (!isAudioWatermark && !watermarkTextInput.value.trim()) {
            setStatus('Please enter text for the watermark.', true);
            return;
        }

        try {
            showLoader('Initializing Audio Context...');
            audioContext = new (window.AudioContext || window.webkitAudioContext)();

            // 2. Load main audio buffer
            showLoader('Loading main audio...');
            const mainAudioBuffer = await loadAudioBuffer(mainAudioInput.files[0]);

            // 3. Load or generate watermark audio buffer
            let watermarkBuffer;
            if (isAudioWatermark) {
                showLoader('Loading watermark audio...');
                watermarkBuffer = await loadAudioBuffer(watermarkAudioInput.files[0]);
            } else {
                showLoader('Generating text watermark...');
                watermarkBuffer = await generateTextToSpeechBuffer(watermarkTextInput.value.trim());
            }

            // 4. Mix audio buffers
            showLoader('Mixing audio...');
            const mixedBuffer = await mixAudio(mainAudioBuffer, watermarkBuffer);

            // 5. Convert final buffer to WAV and trigger download
            showLoader('Encoding final audio...');
            const wavBlob = bufferToWav(mixedBuffer);
            downloadBlob(wavBlob, 'watermarked_audio.wav');
            setStatus('Successfully created and downloaded watermarked audio!');

        } catch (error) {
            console.error('Audio processing failed:', error);
            setStatus(`Error: ${error.message}`, true);
        } finally {
            hideLoader();
            if (audioContext && audioContext.state !== 'closed') {
                audioContext.close();
            }
        }
    }

    /**
     * Loads an audio file and decodes it into an AudioBuffer.
     * @param {File} file - The audio file to load.
     * @returns {Promise<AudioBuffer>} A promise that resolves with the decoded AudioBuffer.
     */
    function loadAudioBuffer(file) {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = (e) => {
                audioContext.decodeAudioData(e.target.result, resolve, reject);
            };
            reader.onerror = (err) => reject(new Error(`File reading error: ${err}`));
            reader.readAsArrayBuffer(file);
        });
    }

    /**
     * Generates an AudioBuffer from text using the Web Speech and MediaRecorder APIs.
     * @param {string} text - The text to convert to speech.
     * @returns {Promise<AudioBuffer>} A promise that resolves with the speech AudioBuffer.
     */
    function generateTextToSpeechBuffer(text) {
        return new Promise((resolve, reject) => {
            if (!('speechSynthesis' in window)) {
                return reject(new Error('Speech Synthesis not supported in this browser.'));
            }

            const utterance = new SpeechSynthesisUtterance(text);
            const destination = audioContext.createMediaStreamDestination();
            const mediaRecorder = new MediaRecorder(destination.stream);
            const chunks = [];

            mediaRecorder.ondataavailable = (event) => chunks.push(event.data);
            mediaRecorder.onstop = async () => {
                const blob = new Blob(chunks, { type: 'audio/webm' });
                const arrayBuffer = await blob.arrayBuffer();
                audioContext.decodeAudioData(arrayBuffer, resolve, reject);
            };

            utterance.onend = () => {
                mediaRecorder.stop();
            };
            utterance.onerror = (e) => reject(new Error(`Speech synthesis error: ${e.error}`));

            // Route the speech output to our recording destination
            const speechSource = audioContext.createConstantSource(); // Dummy source
            speechSource.connect(destination);
            speechSynthesis.speak(utterance);
        });
    }

    /**
     * Mixes the main audio with the watermark audio based on selected options.
     * @param {AudioBuffer} mainBuffer - The main audio buffer.
     * @param {AudioBuffer} watermarkBuffer - The watermark audio buffer.
     * @returns {Promise<AudioBuffer>} A promise that resolves with the mixed AudioBuffer.
     */
    function mixAudio(mainBuffer, watermarkBuffer) {
        const offlineContext = new OfflineAudioContext(
            mainBuffer.numberOfChannels,
            mainBuffer.length,
            mainBuffer.sampleRate
        );

        // 1. Create source for the main audio
        const mainSource = offlineContext.createBufferSource();
        mainSource.buffer = mainBuffer;
        mainSource.connect(offlineContext.destination);
        mainSource.start(0);

        // 2. Create gain node for watermark volume control
        const watermarkGain = offlineContext.createGain();
        watermarkGain.gain.value = parseFloat(volumeSlider.value);
        watermarkGain.connect(offlineContext.destination);

        // 3. Create and schedule watermark source(s) based on placement
        const placement = placementSelect.value;
        const mainDuration = mainBuffer.duration;
        const watermarkDuration = watermarkBuffer.duration;

        if (placement === 'repeat') {
            const interval = 15; // Repeat every 15 seconds
            for (let time = 0; time < mainDuration; time += interval) {
                const watermarkSource = offlineContext.createBufferSource();
                watermarkSource.buffer = watermarkBuffer;
                watermarkSource.connect(watermarkGain);
                watermarkSource.start(time);
            }
        } else {
            let startTime = 0;
            if (placement === 'middle') {
                startTime = Math.max(0, (mainDuration - watermarkDuration) / 2);
            } else if (placement === 'end') {
                startTime = Math.max(0, mainDuration - watermarkDuration);
            }

            const watermarkSource = offlineContext.createBufferSource();
            watermarkSource.buffer = watermarkBuffer;
            watermarkSource.connect(watermarkGain);
            watermarkSource.start(startTime);
        }

        return offlineContext.startRendering();
    }

    // --- File Saving ---

    /**
     * Converts an AudioBuffer to a WAV file Blob.
     * @param {AudioBuffer} buffer - The audio buffer to convert.
     * @returns {Blob} A Blob representing the WAV file.
     */
    function bufferToWav(buffer) {
        const numOfChan = buffer.numberOfChannels;
        const length = buffer.length * numOfChan * 2 + 44;
        const bufferArr = new ArrayBuffer(length);
        const view = new DataView(bufferArr);
        const channels = [];
        let i, sample;
        let offset = 0;
        let pos = 0;

        // Helper function to write strings
        const writeString = (s) => {
            for (i = 0; i < s.length; i++) {
                view.setUint8(pos++, s.charCodeAt(i));
            }
        };

        // WAV header
        writeString('RIFF');
        view.setUint32(pos, 36 + buffer.length * numOfChan * 2, true); pos += 4;
        writeString('WAVE');
        writeString('fmt ');
        view.setUint32(pos, 16, true); pos += 4;
        view.setUint16(pos, 1, true); pos += 2;
        view.setUint16(pos, numOfChan, true); pos += 2;
        view.setUint32(pos, buffer.sampleRate, true); pos += 4;
        view.setUint32(pos, buffer.sampleRate * 2 * numOfChan, true); pos += 4;
        view.setUint16(pos, numOfChan * 2, true); pos += 2;
        view.setUint16(pos, 16, true); pos += 2;
        writeString('data');
        view.setUint32(pos, buffer.length * numOfChan * 2, true); pos += 4;

        // Write PCM data
        for (i = 0; i < buffer.numberOfChannels; i++) {
            channels.push(buffer.getChannelData(i));
        }

        while (pos < length) {
            for (i = 0; i < numOfChan; i++) {
                sample = Math.max(-1, Math.min(1, channels[i][offset]));
                sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767) | 0;
                view.setInt16(pos, sample, true);
                pos += 2;
            }
            offset++;
        }

        return new Blob([view], { type: 'audio/wav' });
    }

    /**
     * Triggers a browser download for a given Blob.
     * @param {Blob} blob - The Blob to download.
     * @param {string} filename - The desired name for the downloaded file.
     */
    function downloadBlob(blob, filename) {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.style.display = 'none';
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
        a.remove();
    }
});
```

