    <script>
        document.addEventListener('DOMContentLoaded', () => {
            // --- DOM Element References ---
            const audioFileInput = document.getElementById('audio-file');
            const currentFileNameSpan = document.getElementById('current-file-name');
            const labelInput = document.getElementById('label-input');
            const addLabelBtn = document.getElementById('add-label-btn');
            const labelsList = document.getElementById('labels-list');
            const exportBtn = document.getElementById('export-btn');

            let wavesurfer = null;
            let activeRegion = null;
            let labeledRegions = [];

            // --- Utility Functions ---
            const formatTime = (seconds) => {
                const date = new Date(null);
                date.setSeconds(seconds);
                return date.toISOString().substr(11, 12);
            };

            const updateLabelsList = () => {
                labelsList.innerHTML = '';
                labeledRegions.forEach(region => {
                    const li = document.createElement('li');

                    const labelInfo = document.createElement('span');
                    labelInfo.className = 'label-info';
                    labelInfo.textContent = region.data.label;

                    const timeInfo = document.createElement('span');
                    timeInfo.className = 'time-info';
                    timeInfo.textContent = `${formatTime(region.start)} - ${formatTime(region.end)}`;

                    const deleteBtn = document.createElement('button');
                    deleteBtn.className = 'delete-btn';
                    deleteBtn.textContent = 'Delete';
                    deleteBtn.onclick = () => {
                        region.remove();
                        labeledRegions = labeledRegions.filter(r => r.id !== region.id);
                        updateLabelsList();
                        updateExportButtonState();
                    };

                    li.appendChild(labelInfo);
                    li.appendChild(timeInfo);
                    li.appendChild(deleteBtn);
                    labelsList.appendChild(li);
                });
            };

            const updateExportButtonState = () => {
                exportBtn.disabled = labeledRegions.length === 0;
            };

            // --- Wavesurfer Initialization ---
            const initializeWavesurfer = () => {
                if (wavesurfer) {
                    wavesurfer.destroy();
                }

                wavesurfer = WaveSurfer.create({
                    container: '#waveform',
                    waveColor: 'rgb(200, 200, 200)',
                    progressColor: 'rgb(100, 100, 100)',
                    height: 128,
                    plugins: [
                        WaveSurfer.Regions.create({})
                    ]
                });

                // --- Wavesurfer Event Listeners ---
                wavesurfer.on('ready', () => {
                    console.log('Waveform is ready');
                });

                wavesurfer.on('region-created', (region) => {
                    // Deselect other regions
                    Object.values(wavesurfer.regions.list).forEach(r => {
                        if (r.id !== region.id) {
                            r.setOptions({ color: 'rgba(0, 0, 0, 0.1)' });
                        }
                    });

                    activeRegion = region;
                    activeRegion.setOptions({ color: 'rgba(0, 123, 255, 0.2)' });
                    addLabelBtn.disabled = false;
                    labelInput.focus();
                });

                wavesurfer.on('region-updated', (region) => {
                    activeRegion = region;
                });

                wavesurfer.on('region-out', (region) => {
                    if (activeRegion === region) {
                        addLabelBtn.disabled = true;
                        activeRegion = null;
                    }
                });
            };

            // --- Application Event Listeners ---
            audioFileInput.addEventListener('change', (event) => {
                const file = event.target.files[0];
                if (file) {
                    currentFileNameSpan.textContent = file.name;
                    const url = URL.createObjectURL(file);

                    initializeWavesurfer();
                    wavesurfer.load(url);

                    // Reset state
                    labeledRegions = [];
                    updateLabelsList();
                    updateExportButtonState();
                }
            });

            addLabelBtn.addEventListener('click', () => {
                const labelText = labelInput.value.trim();
                if (activeRegion && labelText) {
                    activeRegion.data = { label: labelText };
                    activeRegion.setOptions({
                        content: labelText,
                        color: 'rgba(40, 167, 69, 0.3)' // A green color for labeled regions
                    });

                    labeledRegions.push(activeRegion);

                    updateLabelsList();
                    updateExportButtonState();

                    // Reset for next label
                    labelInput.value = '';
                    activeRegion = null;
                    addLabelBtn.disabled = true;
                }
            });

            exportBtn.addEventListener('click', () => {
                if (labeledRegions.length === 0) return;

                const exportData = labeledRegions.map(region => ({
                    label: region.data.label,
                    start_time: region.start,
                    end_time: region.end
                }));

                const jsonString = JSON.stringify(exportData, null, 2);
                const blob = new Blob([jsonString], { type: 'application/json' });
                const url = URL.createObjectURL(blob);

                const a = document.createElement('a');
                a.href = url;
                a.download = 'audio_labels.json';
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                URL.revokeObjectURL(url);
            });

            // Initial state
            initializeWavesurfer();
        });
    </script>
</body>
</html>
