#### 3. JavaScript (`script.js`)
This is the core of the application, handling all logic, data management, and DOM manipulation.

```javascript
document.addEventListener('DOMContentLoaded', () => {
    // DOM Element References
    const productForm = document.getElementById('product-form');
    const formTitle = document.getElementById('form-title');
    const productIdInput = document.getElementById('product-id');
    const productNameInput = document.getElementById('product-name');
    const productPriceInput = document.getElementById('product-price');
    const productQuantityInput = document.getElementById('product-quantity');
    const alertThresholdInput = document.getElementById('alert-threshold');
    const submitBtn = document.getElementById('submit-btn');
    const cancelBtn = document.getElementById('cancel-btn');
    const inventoryList = document.getElementById('inventory-list');

    // Application State
    let products = JSON.parse(localStorage.getItem('inventory_products')) || [];

    // --- DATA LOGIC ---

    const saveProducts = () => {
        localStorage.setItem('inventory_products', JSON.stringify(products));
    };

    const getProductById = (id) => {
        return products.find(p => p.id === id);
    };

    const addProduct = (product) => {
        products.push(product);
        saveProducts();
    };

    const updateProduct = (updatedProduct) => {
        products = products.map(p => p.id === updatedProduct.id ? updatedProduct : p);
        saveProducts();
    };

    const deleteProduct = (id) => {
        if (confirm('Are you sure you want to delete this product?')) {
            products = products.filter(p => p.id !== id);
            saveProducts();
            renderInventory();
        }
    };

    // --- UI LOGIC ---

    const renderInventory = () => {
        inventoryList.innerHTML = ''; // Clear current list

        if (products.length === 0) {
            inventoryList.innerHTML = '<tr><td colspan="5" style="text-align:center;">No products in inventory.</td></tr>';
            return;
        }

        products.forEach(product => {
            const isLowStock = product.quantity <= product.alertThreshold;
            const row = document.createElement('tr');

            if (isLowStock) {
                row.classList.add('low-stock-row');
            }

            row.innerHTML = `
                <td>${product.name}</td>
                <td>$${parseFloat(product.price).toFixed(2)}</td>
                <td>${product.quantity}</td>
                <td>
                    <span class="status-badge ${isLowStock ? 'status-low' : 'status-ok'}">
                        ${isLowStock ? 'Low Stock' : 'In Stock'}
                    </span>
                </td>
                <td>
                    <button class="action-btn edit-btn" data-id="${product.id}">Edit</button>
                    <button class="action-btn delete-btn" data-id="${product.id}">Delete</button>
                </td>
            `;
            inventoryList.appendChild(row);
        });
    };

    const resetForm = () => {
        productForm.reset();
        productIdInput.value = '';
        formTitle.textContent = 'Add New Product';
        submitBtn.textContent = 'Add Product';
        cancelBtn.classList.add('hidden');
    };

    const populateFormForEdit = (id) => {
        const product = getProductById(id);
        if (!product) return;

        productIdInput.value = product.id;
        productNameInput.value = product.name;
        productPriceInput.value = product.price;
        productQuantityInput.value = product.quantity;
        alertThresholdInput.value = product.alertThreshold;

        formTitle.textContent = 'Edit Product';
        submitBtn.textContent = 'Save Changes';
        cancelBtn.classList.remove('hidden');

        window.scrollTo(0, 0); // Scroll to top to see the form
    };

    // --- EVENT LISTENERS ---

    productForm.addEventListener('submit', (e) => {
        e.preventDefault();

        const id = productIdInput.value;
        const productData = {
            name: productNameInput.value,
            price: parseFloat(productPriceInput.value),
            quantity: parseInt(productQuantityInput.value, 10),
            alertThreshold: parseInt(alertThresholdInput.value, 10)
        };

        if (id) {
            // Update existing product
            productData.id = id;
            updateProduct(productData);
        } else {
            // Add new product
            productData.id = `prod_${new Date().getTime()}`; // Simple unique ID
            addProduct(productData);
        }

        resetForm();
        renderInventory();
    });

    cancelBtn.addEventListener('click', () => {
        resetForm();
    });

    inventoryList.addEventListener('click', (e) => {
        const target = e.target;
        const id = target.dataset.id;

        if (target.classList.contains('edit-btn')) {
            populateFormForEdit(id);
        } else if (target.classList.contains('delete-btn')) {
            deleteProduct(id);
        }
    });

    // --- INITIALIZATION ---
    renderInventory();
});
```

