### `src/App.js`
```javascript
import React, { useState, useRef, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import anime from 'animejs';

import Toolbox from './components/Toolbox';
import PropertiesPanel from './components/PropertiesPanel';
import CanvasComponent from './components/CanvasComponent';
import Timeline from './components/Timeline';

import './App.css';

// Constants for the canvas and timeline
const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const TIMELINE_DURATION = 10000; // 10 seconds in ms

function App() {
  // State to hold all graphic objects and their properties/animations
  const [objects, setObjects] = useState({});
  // State for the currently selected object's ID
  const [selectedObjectId, setSelectedObjectId] = useState(null);
  // State for timeline playback
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  // State for video export
  const [exporting, setExporting] = useState(false);
  const [exportProgress, setExportProgress] = useState(0);

  // Refs to hold instances of Fabric.js canvas and Anime.js timeline
  const fabricCanvasRef = useRef(null);
  const animeTimelineRef = useRef(null);

  // Memoized callback to add a new object to the canvas and state
  const addObject = useCallback((type) => {
    const id = uuidv4();
    const canvas = fabricCanvasRef.current;
    if (!canvas) return;

    let newObject;
    const commonProps = {
      id,
      left: CANVAS_WIDTH / 2 - 50,
      top: CANVAS_HEIGHT / 2 - 50,
    };

    // Create different shapes based on the type
    switch (type) {
      case 'rect':
        newObject = new fabric.Rect({ ...commonProps, width: 100, height: 100, fill: '#61dafb' });
        break;
      case 'circle':
        newObject = new fabric.Circle({ ...commonProps, radius: 50, fill: '#ff69b4' });
        break;
      case 'triangle':
        newObject = new fabric.Triangle({ ...commonProps, width: 100, height: 100, fill: '#4caf50' });
        break;
      // A simulated icon (star shape) using a path
      case 'icon':
        const starPath = 'M 50 0 L 61 35 L 98 35 L 68 57 L 79 91 L 50 70 L 21 91 L 32 57 L 2 35 L 39 35 Z';
        newObject = new fabric.Path(starPath, { ...commonProps, fill: '#f4d03f', scaleX: 0.8, scaleY: 0.8 });
        break;
      default:
        return;
    }

    canvas.add(newObject);
    canvas.setActiveObject(newObject);
    canvas.renderAll();

    // Update the state with the new object
    setObjects(prev => ({
      ...prev,
      [id]: {
        id,
        type,
        fabricObject: newObject,
        animations: [],
      },
    }));
    setSelectedObjectId(id);
  }, []);

  // Memoized callback to update an object's properties or animations
  const updateObject = useCallback((id, updates) => {
    setObjects(prev => {
      if (!prev[id]) return prev;
      const updatedObject = { ...prev[id], ...updates };
      return { ...prev, [id]: updatedObject };
    });
  }, []);

  // Memoized callback to delete an object
  const deleteObject = useCallback((id) => {
    const canvas = fabricCanvasRef.current;
    const objectData = objects[id];
    if (canvas && objectData) {
      canvas.remove(objectData.fabricObject);
      canvas.renderAll();
      setObjects(prev => {
        const newObjects = { ...prev };
        delete newObjects[id];
        return newObjects;
      });
      if (selectedObjectId === id) {
        setSelectedObjectId(null);
      }
    }
  }, [objects, selectedObjectId]);

  // Function to build and control the Anime.js timeline
  const setupAndPlayTimeline = (onComplete) => {
    const canvas = fabricCanvasRef.current;
    if (!canvas) return;

    // Reset object properties to their initial state before playing
    Object.values(objects).forEach(objData => {
      const initialProps = {};
      objData.animations.forEach(anim => {
        if (anim.property in objData.fabricObject) {
          initialProps[anim.property] = anim.from;
        }
      });
      objData.fabricObject.set(initialProps);
    });
    canvas.renderAll();

    // Create a new Anime.js timeline
    animeTimelineRef.current = anime.timeline({
      duration: TIMELINE_DURATION,
      easing: 'easeInOutQuad',
      autoplay: false,
      update: (anim) => {
        // Update the current time state as the animation plays
        setCurrentTime(anim.currentTime);
        canvas.renderAll();
      },
      complete: () => {
        setIsPlaying(false);
        if (onComplete) onComplete();
      },
    });

    // Add each animation from our state to the Anime.js timeline
    Object.values(objects).forEach(objData => {
      objData.animations.forEach(anim => {
        animeTimelineRef.current.add({
          targets: objData.fabricObject,
          [anim.property]: anim.to,
          duration: anim.duration,
          delay: anim.startTime,
        }, 0);
      });
    });

    animeTimelineRef.current.play();
    setIsPlaying(true);
  };

  // Handlers for timeline controls
  const handlePlay = () => {
    if (isPlaying) {
      animeTimelineRef.current?.pause();
      setIsPlaying(false);
    } else {
      setupAndPlayTimeline();
    }
  };

  const handleSeek = (time) => {
    setCurrentTime(time);
    if (!animeTimelineRef.current || !isPlaying) {
      // If not playing, manually seek through the animation states
      Object.values(objects).forEach(objData => {
        objData.animations.forEach(anim => {
          const progress = Math.max(0, Math.min(1, (time - anim.startTime) / anim.duration));
          const value = parseFloat(anim.from) + (parseFloat(anim.to) - parseFloat(anim.from)) * progress;
          objData.fabricObject.set(anim.property, value);
        });
      });
      fabricCanvasRef.current.renderAll();
    }
    animeTimelineRef.current?.seek(time);
  };

  // Video export functionality using CCapture.js
  const handleExport = () => {
    if (exporting) return;
    setExporting(true);
    setExportProgress(0);

    // CCapture is loaded from a script tag in index.html
    const capturer = new window.CCapture({
      format: 'webm',
      framerate: 30,
      verbose: true,
      name: 'dynamic-graphic-video',
    });

    capturer.start();

    const canvasEl = fabricCanvasRef.current.getElement();
    let frame = 0;
    const totalFrames = (TIMELINE_DURATION / 1000) * 30; // 30 FPS

    function captureFrame() {
      if (frame > totalFrames) {
        // End of capture
        setExporting(false);
        setExportProgress(100);
        capturer.stop();
        capturer.save();
        return;
      }

      const time = (frame / totalFrames) * TIMELINE_DURATION;
      handleSeek(time); // Seek the animation to the current frame's time

      capturer.capture(canvasEl);
      setExportProgress((frame / totalFrames) * 100);

      frame++;
      requestAnimationFrame(captureFrame);
    }

    captureFrame();
  };

  const selectedObject = selectedObjectId ? objects[selectedObjectId] : null;

  return (
    <div className="app-container">
      <div className="main-content">
        <header className="header">
          <h1>Dynamic Graphic Video Generator</h1>
        </header>
        <div className="canvas-container">
          <div className="canvas-wrapper">
            <CanvasComponent
              width={CANVAS_WIDTH}
              height={CANVAS_HEIGHT}
              setFabricCanvas={(canvas) => (fabricCanvasRef.current = canvas)}
              onObjectSelect={setSelectedObjectId}
            />
          </div>
        </div>
        <Timeline
          currentTime={currentTime}
          duration={TIMELINE_DURATION}
          isPlaying={isPlaying}
          onPlay={handlePlay}
          onSeek={handleSeek}
        />
      </div>
      <aside className="sidebar">
        <Toolbox onAddObject={addObject} />
        <PropertiesPanel
          selectedObject={selectedObject}
          onUpdateObject={updateObject}
          onDeleteObject={deleteObject}
        />
        <div className="panel">
          <h3>Export</h3>
          <button onClick={handleExport} disabled={exporting} className="btn success">
            {exporting ? `Exporting... ${exportProgress.toFixed(0)}%` : 'Export as WebM Video'}
          </button>
          {exporting && <div className="export-status">Please wait, video generation is in progress...</div>}
        </div>
      </aside>
    </div>
  );
}

export default App;
```

