### `src/components/CanvasComponent.js`
```javascript
import React, { useRef, useEffect } from 'react';
import { fabric } from 'fabric';

/**
 * A React component that wraps the Fabric.js canvas.
 * It handles canvas initialization and event listeners.
 */
const CanvasComponent = ({ width, height, setFabricCanvas, onObjectSelect }) => {
  const canvasEl = useRef(null);

  useEffect(() => {
    // Initialize the Fabric canvas
    const canvas = new fabric.Canvas(canvasEl.current, {
      width,
      height,
      backgroundColor: '#f0f0f0',
    });

    // Pass the canvas instance to the parent component (App.js)
    setFabricCanvas(canvas);

    // Event listener for when an object is selected
    const handleSelection = (e) => {
      const selected = e.selected[0];
      if (selected) {
        onObjectSelect(selected.id);
      } else {
        onObjectSelect(null);
      }
    };

    // Event listener for when selection is cleared
    const handleSelectionCleared = () => {
      onObjectSelect(null);
    };

    canvas.on('selection:created', handleSelection);
    canvas.on('selection:updated', handleSelection);
    canvas.on('selection:cleared', handleSelectionCleared);

    // Cleanup function to dispose of the canvas and remove listeners
    return () => {
      canvas.off('selection:created', handleSelection);
      canvas.off('selection:updated', handleSelection);
      canvas.off('selection:cleared', handleSelectionCleared);
      canvas.dispose();
    };
  }, [width, height, setFabricCanvas, onObjectSelect]);

  return <canvas ref={canvasEl} />;
};

export default CanvasComponent;
```

