```javascript
import React from 'react';
import { v4 as uuidv4 } from 'uuid';

/**
 * A panel to display and edit properties of the selected graphic object.
 * This includes its animations.
 */
const PropertiesPanel = ({ selectedObject, onUpdateObject, onDeleteObject }) => {
  if (!selectedObject) {
    return (
      <div className="panel">
        <h3>Properties</h3>
        <p>Select an object on the canvas to see its properties.</p>
      </div>
    );
  }

  const { id, fabricObject, animations } = selectedObject;

  // Handler for changing basic object properties (e.g., color)
  const handlePropertyChange = (prop, value) => {
    fabricObject.set(prop, value);
    fabricObject.canvas.renderAll();
    // Note: We don't need to call onUpdateObject here as the fabric object is a reference.
    // However, if we were storing properties in React state, we would.
  };

  // Handler for changing animation properties
  const handleAnimationChange = (animId, prop, value) => {
    const newAnimations = animations.map(anim =>
      anim.id === animId ? { ...anim, [prop]: value } : anim
    );
    onUpdateObject(id, { animations: newAnimations });
  };

  // Add a new animation to the selected object
  const addAnimation = () => {
    const newAnimation = {
      id: uuidv4(),
      property: 'left',
      from: fabricObject.left,
      to: fabricObject.left + 100,
      startTime: 0,
      duration: 1000,
    };
    onUpdateObject(id, { animations: [...animations, newAnimation] });
  };

  // Remove an animation
  const removeAnimation = (animId) => {
    const newAnimations = animations.filter(anim => anim.id !== animId);
    onUpdateObject(id, { animations: newAnimations });
  };

  return (
    <div className="panel properties-form">
      <h3>Properties: {selectedObject.type}</h3>

      {/* Basic Properties */}
      <div className="form-group">
        <label htmlFor="fill">Fill Color</label>
        <input
          type="color"
          id="fill"
          defaultValue={fabricObject.fill}
          onChange={(e) => handlePropertyChange('fill', e.target.value)}
        />
      </div>

      {/* Animations Section */}
      <h4>Animations</h4>
      {animations.map(anim => (
        <div key={anim.id} className="animation-item">
          <div className="form-group">
            <label>Property</label>
            <select
              value={anim.property}
              onChange={(e) => handleAnimationChange(anim.id, 'property', e.target.value)}
            >
              <option value="left">X Position</option>
              <option value="top">Y Position</option>
              <option value="angle">Rotation</option>
              <option value="scaleX">Scale X</option>
              <option value="scaleY">Scale Y</option>
              <option value="opacity">Opacity</option>
            </select>
          </div>
          <div className="form-group">
            <label>From</label>
            <input
              type="number"
              value={anim.from}
              onChange={(e) => handleAnimationChange(anim.id, 'from', e.target.value)}
            />
          </div>
          <div className="form-group">
            <label>To</label>
            <input
              type="number"
              value={anim.to}
              onChange={(e) => handleAnimationChange(anim.id, 'to', e.target.value)}
            />
          </div>
          <div className="form-group">
            <label>Start Time (ms)</label>
            <input
              type="number"
              value={anim.startTime}
              onChange={(e) => handleAnimationChange(anim.id, 'startTime', parseInt(e.target.value))}
            />
          </div>
          <div className="form-group">
            <label>Duration (ms)</label>
            <input
              type="number"
              value={anim.duration}
              onChange={(e) => handleAnimationChange(anim.id, 'duration', parseInt(e.target.value))}
            />
          </div>
          <button onClick={() => removeAnimation(anim.id)} className="btn danger">
            Remove Animation
          </button>
        </div>
      ))}
      <button onClick={addAnimation} className="btn">Add Animation</button>

      {/* Delete Object Button */}
      <div style={{ marginTop: '1rem' }}>
        <button onClick={() => onDeleteObject(id)} className="btn danger">
          Delete Object
        </button>
      </div>
    </div>
  );
};

export default PropertiesPanel;
