import React from 'react';

/**
 * A component for controlling the animation playback.
 * Includes a play/pause button and a seekable progress bar.
 */
const Timeline = ({ currentTime, duration, isPlaying, onPlay, onSeek }) => {
  // Format time from milliseconds to a MM:SS.ms string
  const formatTime = (ms) => {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    const milliseconds = ms % 1000;
    return `${String(minutes).padStart(2, '0')}:${String(remainingSeconds).padStart(2, '0')}.${String(milliseconds).padStart(3, '0')}`;
  };

  return (
    <div className="panel timeline-container">
      <h3>Timeline</h3>
      <div className="timeline-controls">
        <button onClick={onPlay} className="btn">
          {isPlaying ? 'Pause' : 'Play'}
        </button>
        <span>{formatTime(currentTime)} / {formatTime(duration)}</span>
      </div>
      <input
        type="range"
        min="0"
        max={duration}
        value={currentTime}
        onChange={(e) => onSeek(parseInt(e.target.value, 10))}
        className="timeline-progress"
      />
    </div>
  );
};

export default Timeline;
