document.addEventListener('DOMContentLoaded', () => {
    // --- DOM Elements ---
    const deviceListView = document.getElementById('device-list-view');
    const deviceDetailsView = document.getElementById('device-details-view');
    const deviceListContainer = document.getElementById('device-list');
    const addDeviceModal = document.getElementById('add-device-modal');
    const showAddDeviceModalBtn = document.getElementById('show-add-device-modal-btn');
    const closeModalBtn = document.querySelector('.modal .close-btn');
    const addDeviceForm = document.getElementById('add-device-form');
    const backToListBtn = document.getElementById('back-to-list-btn');
    const addMaintenanceForm = document.getElementById('add-maintenance-form');

    // --- App State ---
    let devices = [];

    // --- Data Layer ---

    /**
     * Loads devices from localStorage or initializes with sample data.
     */
    function loadData() {
        const storedDevices = localStorage.getItem('maintenanceDevices');
        if (storedDevices) {
            devices = JSON.parse(storedDevices);
        } else {
            // Initialize with sample data if no data is found
            devices = getSampleData();
            saveData();
        }
    }

    /**
     * Saves the current devices array to localStorage.
     */
    function saveData() {
        localStorage.setItem('maintenanceDevices', JSON.stringify(devices));
    }

    /**
     * Provides initial sample data for the application.
     */
    function getSampleData() {
        const now = new Date();
        return [
            {
                id: `device-${Date.now()}-1`,
                name: 'CNC Machine X-2000',
                cycleType: 'days',
                cycleValue: 90,
                lastMaintenanceValue: new Date(now.setDate(now.getDate() - 20)).toISOString().split('T')[0], // 20 days ago
                currentHours: null,
                maintenanceHistory: [
                    { date: '2023-10-01', value: '2023-10-01', performedBy: 'Tech Team', consumables: 'Coolant, Spindle Oil' }
                ]
            },
            {
                id: `device-${Date.now()}-2`,
                name: 'Air Compressor 50L',
                cycleType: 'days',
                cycleValue: 30,
                lastMaintenanceValue: new Date(now.setDate(now.getDate() - 5)).toISOString().split('T')[0], // 25 days ago (relative to previous)
                currentHours: null,
                maintenanceHistory: []
            },
            {
                id: `device-${Date.now()}-3`,
                name: 'Forklift T-150',
                cycleType: 'days',
                cycleValue: 180,
                lastMaintenanceValue: new Date(now.setDate(now.getDate() - 185)).toISOString().split('T')[0], // 185 days ago
                currentHours: null,
                maintenanceHistory: []
            },
            {
                id: `device-${Date.now()}-4`,
                name: 'Laser Cutter Pro',
                cycleType: 'hours',
                cycleValue: 500,
                lastMaintenanceValue: 1200,
                currentHours: 1350,
                maintenanceHistory: [
                     { date: '2024-03-15', value: 1200, performedBy: 'Jane Smith', consumables: 'Laser lens, Nozzle' }
                ]
            },
            {
                id: `device-${Date.now()}-5`,
                name: '3D Printer Mark II',
                cycleType: 'hours',
                cycleValue: 200,
                lastMaintenanceValue: 4000,
                currentHours: 4180,
                maintenanceHistory: []
            },
            {
                id: `device-${Date.now()}-6`,
                name: 'Welding Robot Arm',
                cycleType: 'hours',
                cycleValue: 1000,
                lastMaintenanceValue: 8500,
                currentHours: 9600,
                maintenanceHistory: []
            }
        ];
    }

    // --- Logic Layer ---

    /**
     * Calculates the maintenance status of a device.
     * @param {object} device - The device object.
     * @returns {object} An object containing status class and text.
     */
    function getDeviceStatus(device) {
        const now = new Date();
        if (device.cycleType === 'days') {
            const lastMaintenanceDate = new Date(device.lastMaintenanceValue);
            const nextDueDate = new Date(lastMaintenanceDate.setDate(lastMaintenanceDate.getDate() + device.cycleValue));
            const daysUntilDue = (nextDueDate - now) / (1000 * 60 * 60 * 24);

            if (daysUntilDue < 0) {
                return { class: 'status-overdue', text: `Overdue by ${Math.abs(Math.round(daysUntilDue))} days` };
            } else if (daysUntilDue <= 7) {
                return { class: 'status-warning', text: `Due in ${Math.round(daysUntilDue)} days` };
            } else {
                return { class: 'status-normal', text: `Due in ${Math.round(daysUntilDue)} days` };
            }
        } else { // hours
            const hoursUntilDue = (device.lastMaintenanceValue + device.cycleValue) - device.currentHours;
            const warningThreshold = device.cycleValue * 0.1; // Warning when 10% of cycle hours remain

            if (hoursUntilDue < 0) {
                return { class: 'status-overdue', text: `Overdue by ${Math.abs(hoursUntilDue)} hours` };
            } else if (hoursUntilDue <= warningThreshold) {
                return { class: 'status-warning', text: `Due in ${hoursUntilDue} hours` };
            } else {
                return { class: 'status-normal', text: `Due in ${hoursUntilDue} hours` };
            }
        }
    }

    // --- View Layer ---

    /**
     * Renders the list of all devices on the main page.
     */
    function renderDeviceList() {
        deviceListContainer.innerHTML = '';
        if (devices.length === 0) {
            deviceListContainer.innerHTML = '<p>No devices registered. Add one to get started!</p>';
            return;
        }

        devices.forEach(device => {
            const status = getDeviceStatus(device);
            const card = document.createElement('div');
            card.className = `device-card ${status.class}`;
            card.dataset.deviceId = device.id;

            let maintenanceInfo = '';
            if (device.cycleType === 'days') {
                maintenanceInfo = `
                    <p><strong>Cycle:</strong> Every ${device.cycleValue} days</p>
                    <p><strong>Last Maintenance:</strong> ${device.lastMaintenanceValue}</p>
                `;
            } else {
                maintenanceInfo = `
                    <p><strong>Cycle:</strong> Every ${device.cycleValue} hours</p>
                    <p><strong>Last Maintenance at:</strong> ${device.lastMaintenanceValue} hrs</p>
                    <p><strong>Current Hours:</strong> ${device.currentHours} hrs</p>
                `;
            }

            card.innerHTML = `
                <h3>${device.name}</h3>
                ${maintenanceInfo}
                <p class="status-text">${status.text}</p>
            `;
            card.addEventListener('click', () => showDeviceDetails(device.id));
            deviceListContainer.appendChild(card);
        });
    }

    /**
     * Renders the details and maintenance history for a specific device.
     * @param {string} deviceId - The ID of the device to display.
     */
    function renderDeviceDetails(deviceId) {
        const device = devices.find(d => d.id === deviceId);
        if (!device) return;

        const contentEl = document.getElementById('device-details-content');
        const historyEl = document.getElementById('maintenance-history-list');
        const status = getDeviceStatus(device);

        let maintenanceInfo = '';
        if (device.cycleType === 'days') {
            maintenanceInfo = `
                <p><strong>Cycle:</strong> Every ${device.cycleValue} days</p>
                <p><strong>Last Maintenance:</strong> ${device.lastMaintenanceValue}</p>
            `;
        } else {
            maintenanceInfo = `
                <p><strong>Cycle:</strong> Every ${device.cycleValue} hours</p>
                <p><strong>Last Maintenance at:</strong> ${device.lastMaintenanceValue} hrs</p>
                <p><strong>Current Hours:</strong> ${device.currentHours} hrs</p>
            `;
        }

        contentEl.innerHTML = `
            <h2>${device.name}</h2>
            <p><strong>Status:</strong> <span class="${status.class.replace('status-', '')}">${status.text}</span></p>
            ${maintenanceInfo}
        `;

        // Render history
        historyEl.innerHTML = '';
        if (device.maintenanceHistory.length === 0) {
            historyEl.innerHTML = '<p>No maintenance records found.</p>';
        } else {
            // Sort history newest first
            const sortedHistory = [...device.maintenanceHistory].sort((a, b) => new Date(b.date) - new Date(a.date));
            sortedHistory.forEach(record => {
                const item = document.createElement('div');
                item.className = 'history-item';
                const recordValue = device.cycleType === 'days' ? record.value : `${record.value} hrs`;
                item.innerHTML = `
                    <p><strong>Date / Hours:</strong> ${record.date} / ${recordValue}</p>
                    <p><strong>Performed By:</strong> ${record.performedBy}</p>
                    <p><strong>Consumables:</strong> ${record.consumables || 'N/A'}</p>
                `;
                historyEl.appendChild(item);
            });
        }

        // Prepare the "Add Maintenance" form
        const maintenanceValueLabel = document.getElementById('maintenance-value-label');
        const dateInput = document.getElementById('maintenance-value-date');
        const hoursInput = document.getElementById('maintenance-value-hours');
        document.getElementById('maintenance-device-id').value = device.id;

        if (device.cycleType === 'days') {
            maintenanceValueLabel.textContent = 'Maintenance Date';
            dateInput.classList.remove('hidden');
            hoursInput.classList.add('hidden');
            dateInput.value = new Date().toISOString().split('T')[0];
        } else {
            maintenanceValueLabel.textContent = 'Current Operating Hours at Maintenance';
            dateInput.classList.add('hidden');
            hoursInput.classList.remove('hidden');
            hoursInput.value = device.currentHours;
            hoursInput.min = device.lastMaintenanceValue;
        }
    }

    /**
     * Switches the active view.
     * @param {string} viewId - The ID of the view to show.
     */
    function switchView(viewId) {
        document.querySelectorAll('.view').forEach(view => view.classList.remove('active'));
        document.getElementById(viewId).classList.add('active');
    }

    function showDeviceDetails(deviceId) {
        renderDeviceDetails(deviceId);
        switchView('device-details-view');
    }

    // --- Event Handlers ---

    // Show "Add Device" modal
    showAddDeviceModalBtn.addEventListener('click', () => {
        addDeviceForm.reset();
        // Reset form visibility to default
        document.getElementById('last-maintenance-date').classList.remove('hidden');
        document.getElementById('last-maintenance-hours').classList.add('hidden');
        document.getElementById('current-hours-group').classList.add('hidden');
        document.getElementById('last-maintenance-label').textContent = 'Last Maintenance Date';
        addDeviceModal.style.display = 'block';
    });

    // Close "Add Device" modal
    closeModalBtn.addEventListener('click', () => {
        addDeviceModal.style.display = 'none';
    });
    window.addEventListener('click', (event) => {
        if (event.target === addDeviceModal) {
            addDeviceModal.style.display = 'none';
        }
    });

    // Handle cycle type change in the "Add Device" form
    addDeviceForm.querySelector('#cycle-type').addEventListener('change', (e) => {
        const isHours = e.target.value === 'hours';
        document.getElementById('last-maintenance-date').classList.toggle('hidden', isHours);
        document.getElementById('last-maintenance-hours').classList.toggle('hidden', !isHours);
        document.getElementById('current-hours-group').classList.toggle('hidden', !isHours);
        document.getElementById('last-maintenance-label').textContent = isHours ? 'Hours at Last Maintenance' : 'Last Maintenance Date';
    });

    // Handle "Add Device" form submission
    addDeviceForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const cycleType = document.getElementById('cycle-type').value;
        const isHours = cycleType === 'hours';

        const newDevice = {
            id: `device-${Date.now()}`,
            name: document.getElementById('device-name').value,
            cycleType: cycleType,
            cycleValue: parseInt(document.getElementById('cycle-value').value),
            lastMaintenanceValue: isHours
                ? parseInt(document.getElementById('last-maintenance-hours').value)
                : document.getElementById('last-maintenance-date').value,
            currentHours: isHours
                ? parseInt(document.getElementById('current-hours').value)
                : null,
            maintenanceHistory: []
        };

        devices.push(newDevice);
        saveData();
        renderDeviceList();
        addDeviceModal.style.display = 'none';
    });

    // Handle "Add Maintenance Record" form submission
    addMaintenanceForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const deviceId = document.getElementById('maintenance-device-id').value;
        const device = devices.find(d => d.id === deviceId);
        if (!device) return;

        const newRecord = {
            date: new Date().toISOString().split('T')[0],
            value: device.cycleType === 'days'
                ? document.getElementById('maintenance-value-date').value
                : parseInt(document.getElementById('maintenance-value-hours').value),
            performedBy: document.getElementById('maintenance-personnel').value,
            consumables: document.getElementById('maintenance-consumables').value
        };

        // Add to history
        device.maintenanceHistory.push(newRecord);

        // Update device's last maintenance value
        device.lastMaintenanceValue = newRecord.value;
        if (device.cycleType === 'hours') {
            device.currentHours = newRecord.value;
        }

        saveData();
        renderDeviceDetails(deviceId); // Re-render details to show new record
        addMaintenanceForm.reset(); // Clear the form
    });

    // Handle "Back to List" button click
    backToListBtn.addEventListener('click', () => {
        renderDeviceList(); // Refresh list in case data changed
        switchView('device-list-view');
    });

    // --- Initialization ---
    function init() {
        loadData();
        renderDeviceList();
    }

    init();
});
