// script.js
document.addEventListener('DOMContentLoaded', () => {
    // --- DOM Elements ---
    const mediaBin = document.getElementById('media-bin');
    const addMediaBtn = document.getElementById('add-media-btn');
    const fileInput = document.getElementById('file-input');
    const tracks = document.querySelectorAll('.track-clips');
    const exportBtn = document.getElementById('export-btn');
    const exportModal = document.getElementById('export-modal');
    const closeModalBtn = document.querySelector('.close-button');
    const exportOutput = document.getElementById('export-output');
    const ruler = document.querySelector('.ruler');

    // --- State Management ---
    let mediaFiles = {}; // Store media file data (src, duration, type, name)
    let timelineData = {
        'video-track-1': [],
        'audio-track-1': [],
    };
    let mediaCounter = 0; // To generate unique IDs for media files

    // --- Constants ---
    const TIMELINE_DURATION_SECONDS = 60; // Total duration of the timeline in seconds
    const PIXELS_PER_SECOND = 10; // How many pixels represent one second

    // --- Initialization ---
    function initialize() {
        loadMockData();
        renderMediaBin();
        setupEventListeners();
        drawRuler();
    }

    /**
     * Loads mock media data to populate the media bin on startup.
     * This provides an immediate runnable experience without requiring user uploads.
     */
    function loadMockData() {
        const mockMedia = [
            { id: 'media_0', name: 'Sample Video 1.mp4', type: 'video', duration: 15.2, src: 'https://placehold.co/600x400.mp4?text=Video+1' },
            { id: 'media_1', name: 'Sample Video 2.mp4', type: 'video', duration: 8.5, src: 'https://placehold.co/600x400.mp4?text=Video+2' },
            { id: 'media_2', name: 'Background Music.mp3', type: 'audio', duration: 25.0, src: '#' } // Audio src is placeholder
        ];
        mockMedia.forEach(media => {
            mediaFiles[media.id] = media;
        });
        mediaCounter = mockMedia.length;
    }

    /**
     * Draws the time markers on the timeline ruler.
     */
    function drawRuler() {
        ruler.innerHTML = ''; // Clear existing ruler
        const timelineWidth = TIMELINE_DURATION_SECONDS * PIXELS_PER_SECOND;
        ruler.style.width = `${timelineWidth}px`;

        for (let i = 0; i <= TIMELINE_DURATION_SECONDS; i += 5) {
            const marker = document.createElement('div');
            marker.className = 'time-marker';
            marker.style.left = `${i * PIXELS_PER_SECOND}px`;
            marker.textContent = `${i}s`;
            ruler.appendChild(marker);
        }
    }

    // --- UI Rendering ---

    /**
     * Renders all items from the `mediaFiles` state into the media bin UI.
     */
    function renderMediaBin() {
        mediaBin.innerHTML = ''; // Clear bin before rendering
        Object.values(mediaFiles).forEach(file => {
            const mediaItem = document.createElement('div');
            mediaItem.className = 'media-item';
            mediaItem.setAttribute('draggable', true);
            mediaItem.dataset.mediaId = file.id;

            mediaItem.innerHTML = `
                <p>${file.name}</p>
                <p class="media-info">${file.type.toUpperCase()} - ${file.duration.toFixed(1)}s</p>
            `;
            mediaBin.appendChild(mediaItem);
        });
    }

    /**
     * Renders all clips from `timelineData` onto their respective tracks.
     */
    function renderTimeline() {
        tracks.forEach(trackContainer => {
            trackContainer.innerHTML = ''; // Clear track
            const trackId = trackContainer.parentElement.id;
            const clips = timelineData[trackId] || [];

            clips.forEach(clip => {
                const clipElement = document.createElement('div');
                clipElement.className = 'timeline-clip';
                clipElement.dataset.clipId = clip.clipId;
                clipElement.dataset.type = clip.type;
                clipElement.textContent = clip.name;

                // Position and size the clip based on its start time and duration
                clipElement.style.left = `${clip.startTime * PIXELS_PER_SECOND}px`;
                clipElement.style.width = `${clip.duration * PIXELS_PER_SECOND}px`;

                trackContainer.appendChild(clipElement);
            });
        });
    }

    // --- Event Handlers ---
    function setupEventListeners() {
        // Button to trigger file input
        addMediaBtn.addEventListener('click', () => fileInput.click());

        // Handle file selection
        fileInput.addEventListener('change', handleFileSelect);

        // Drag and Drop for Media Bin items
        mediaBin.addEventListener('dragstart', handleMediaDragStart);

        // Drag and Drop for Timeline Tracks
        tracks.forEach(track => {
            track.addEventListener('dragover', handleTrackDragOver);
            track.addEventListener('drop', handleTrackDrop);
        });

        // Export functionality
        exportBtn.addEventListener('click', handleExport);
        closeModalBtn.addEventListener('click', () => exportModal.style.display = 'none');
        window.addEventListener('click', (event) => {
            if (event.target == exportModal) {
                exportModal.style.display = 'none';
            }
        });
    }

    /**
     * Handles user selecting local files.
     * @param {Event} event - The file input change event.
     */
    async function handleFileSelect(event) {
        const files = event.target.files;
        if (!files.length) return;

        for (const file of files) {
            const mediaType = file.type.startsWith('video') ? 'video' : 'audio';
            const mediaUrl = URL.createObjectURL(file);

            try {
                const duration = await getMediaDuration(mediaUrl, mediaType);
                const mediaId = `media_${mediaCounter++}`;
                mediaFiles[mediaId] = {
                    id: mediaId,
                    name: file.name,
                    type: mediaType,
                    duration: duration,
                    src: mediaUrl
                };
            } catch (error) {
                console.error(`Could not get duration for ${file.name}:`, error);
            }
        }
        renderMediaBin(); // Re-render the bin with new files
    }

    /**
     * Gets the duration of a media file.
     * @param {string} src - The URL of the media file.
     * @param {string} type - 'video' or 'audio'.
     * @returns {Promise<number>} A promise that resolves with the media duration in seconds.
     */
    function getMediaDuration(src, type) {
        return new Promise((resolve, reject) => {
            const mediaElement = document.createElement(type);
            mediaElement.src = src;
            mediaElement.addEventListener('loadedmetadata', () => {
                resolve(mediaElement.duration);
            });
            mediaElement.addEventListener('error', (e) => {
                reject(new Error(`Error loading media: ${e.message}`));
            });
        });
    }

    /**
     * Handles the start of a drag operation from the media bin.
     * @param {DragEvent} event
     */
    function handleMediaDragStart(event) {
        const mediaItem = event.target.closest('.media-item');
        if (mediaItem) {
            event.dataTransfer.setData('text/plain', mediaItem.dataset.mediaId);
            event.dataTransfer.effectAllowed = 'copy';
            mediaItem.classList.add('dragging');
            // Remove class after drag ends, regardless of outcome
            mediaItem.addEventListener('dragend', () => mediaItem.classList.remove('dragging'), { once: true });
        }
    }

    /**
     * Allows a track to be a valid drop target.
     * @param {DragEvent} event
     */
    function handleTrackDragOver(event) {
        event.preventDefault();
        event.dataTransfer.dropEffect = 'copy';
    }

    /**
     * Handles dropping a media item onto a track.
     * @param {DragEvent} event
     */
    function handleTrackDrop(event) {
        event.preventDefault();
        const mediaId = event.dataTransfer.getData('text/plain');
        const mediaInfo = mediaFiles[mediaId];
        const trackElement = event.target.closest('.track');
        const trackType = trackElement.dataset.trackType;
        const trackId = trackElement.id;

        // Ensure media type matches track type
        if (mediaInfo.type !== trackType) {
            alert(`Cannot place ${mediaInfo.type} clip on a ${trackType} track.`);
            return;
        }

        // Calculate drop position in seconds
        const trackRect = event.target.getBoundingClientRect();
        const dropX = event.clientX - trackRect.left;
        const startTime = dropX / PIXELS_PER_SECOND;

        // Create a new clip object
        const newClip = {
            clipId: `clip_${Date.now()}`,
            mediaId: mediaId,
            name: mediaInfo.name,
            type: mediaInfo.type,
            duration: mediaInfo.duration,
            startTime: Math.max(0, startTime) // Ensure start time is not negative
        };

        // Add clip to the timeline data and re-render
        timelineData[trackId].push(newClip);
        renderTimeline();
    }

    /**
     * Simulates the video export process by generating a summary of the timeline.
     */
    function handleExport() {
        let output = "Starting video export process...\n\n";
        output += "================================\n";
        output += "      VIDEO COMPOSITION\n";
        output += "================================\n\n";

        let totalDuration = 0;

        Object.keys(timelineData).forEach(trackId => {
            const clips = timelineData[trackId];
            if (clips.length > 0) {
                const trackName = trackId.replace(/-/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
                output += `--- ${trackName} ---\n`;
                clips.sort((a, b) => a.startTime - b.startTime); // Sort clips by start time

                clips.forEach(clip => {
                    output += `  - Clip: ${clip.name}\n`;
                    output += `    - Starts at: ${clip.startTime.toFixed(2)}s\n`;
                    output += `    - Duration: ${clip.duration.toFixed(2)}s\n`;
                    output += `    - Ends at: ${(clip.startTime + clip.duration).toFixed(2)}s\n\n`;

                    const clipEnd = clip.startTime + clip.duration;
                    if (clipEnd > totalDuration) {
                        totalDuration = clipEnd;
                    }
                });
            }
        });

        if (totalDuration === 0) {
            output += "Timeline is empty. Nothing to export.\n";
        } else {
            output += `\nTotal Estimated Video Duration: ${totalDuration.toFixed(2)} seconds\n`;
        }

        output += "\nExport Complete (Simulation).";

        exportOutput.textContent = output;
        exportModal.style.display = 'block';
    }

    // --- Start the application ---
    initialize();
});
