```javascript
document.addEventListener('DOMContentLoaded', () => {
    // --- DOM Element References ---
    const audioUpload = document.getElementById('audio-upload');
    const fileNameDisplay = document.getElementById('file-name');
    const delaySlider = document.getElementById('delay-slider');
    const delayValueDisplay = document.getElementById('delay-value');
    const intensitySlider = document.getElementById('intensity-slider');
    const intensityValueDisplay = document.getElementById('intensity-value');
    const processButton = document.getElementById('process-button');
    const downloadButton = document.getElementById('download-button');
    const originalPlayer = document.getElementById('original-player');
    const processedPlayer = document.getElementById('processed-player');

    // --- Web Audio API Setup ---
    // Create an AudioContext. This is the central point for all web audio operations.
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    const audioContext = new AudioContext();

    // --- State Variables ---
    let originalAudioBuffer = null; // To store the decoded audio data of the uploaded file
    let processedAudioBuffer = null; // To store the audio data after applying the echo effect

    // --- Event Listeners ---

    // Handle file upload
    audioUpload.addEventListener('change', handleFileUpload);

    // Update slider value displays
    delaySlider.addEventListener('input', () => {
        delayValueDisplay.textContent = parseFloat(delaySlider.value).toFixed(2);
    });

    intensitySlider.addEventListener('input', () => {
        intensityValueDisplay.textContent = parseFloat(intensitySlider.value).toFixed(2);
    });

    // Process the audio when the "Add Echo" button is clicked
    processButton.addEventListener('click', applyEchoEffect);

    // Download the processed audio
    downloadButton.addEventListener('click', downloadProcessedAudio);

    // --- Core Functions ---

    /**
     * Handles the file upload event. Reads the file, decodes it into an AudioBuffer,
     * and prepares the UI for processing.
     * @param {Event} event - The file input change event.
     */
    async function handleFileUpload(event) {
        const file = event.target.files[0];
        if (!file) return;

        fileNameDisplay.textContent = file.name;

        // Create a URL for the original audio file to be played in the <audio> element
        const objectURL = URL.createObjectURL(file);
        originalPlayer.src = objectURL;

        // Read the file as an ArrayBuffer for decoding
        const arrayBuffer = await file.arrayBuffer();

        // Decode the audio data into an AudioBuffer
        try {
            originalAudioBuffer = await audioContext.decodeAudioData(arrayBuffer);
            processButton.disabled = false; // Enable the process button
            downloadButton.disabled = true; // Reset download button
            processedPlayer.src = ''; // Clear previous processed audio
            processedAudioBuffer = null;
        } catch (error) {
            console.error('Error decoding audio data:', error);
            alert('Could not decode the audio file. Please try a different format (e.g., WAV, MP3).');
            processButton.disabled = true;
        }
    }

    /**
     * Applies the echo effect to the uploaded audio using an OfflineAudioContext.
     * This renders the audio with effects without playing it in real-time.
     */
    async function applyEchoEffect() {
        if (!originalAudioBuffer) {
            alert('Please upload an audio file first.');
            return;
        }

        // Get current settings from sliders
        const delayTime = parseFloat(delaySlider.value);
        const feedbackGain = parseFloat(intensitySlider.value);

        // --- Setup OfflineAudioContext for processing ---
        // This context will render the audio as fast as possible to a buffer.
        const offlineContext = new OfflineAudioContext(
            originalAudioBuffer.numberOfChannels,
            originalAudioBuffer.length,
            originalAudioBuffer.sampleRate
        );

        // --- Create Audio Nodes ---
        // 1. Source Node: The original audio
        const sourceNode = offlineContext.createBufferSource();
        sourceNode.buffer = originalAudioBuffer;

        // 2. Delay Node: Creates the time delay
        const delayNode = offlineContext.createDelay(delayTime + 1); // Max delay
        delayNode.delayTime.value = delayTime;

        // 3. Feedback Gain Node: Controls the intensity/decay of the echo
        const feedbackNode = offlineContext.createGain();
        feedbackNode.gain.value = feedbackGain;

        // --- Connect the Audio Graph (Signal Flow) ---
        // Dry signal (original sound) goes directly to the output
        sourceNode.connect(offlineContext.destination);

        // Wet signal (echo effect) path
        // source -> delay -> feedback -> back to delay (for repeating echoes)
        //              |
        //              -> output
        sourceNode.connect(delayNode);
        delayNode.connect(feedbackNode);
        feedbackNode.connect(delayNode); // This creates the feedback loop
        delayNode.connect(offlineContext.destination); // Send the delayed signal to the output

        // Start the source node at the beginning
        sourceNode.start(0);

        // --- Render the Audio ---
        console.log('Rendering audio with echo...');
        processButton.textContent = 'Processing...';
        processButton.disabled = true;

        try {
            // Start rendering and wait for it to complete
            processedAudioBuffer = await offlineContext.startRendering();

            // Convert the rendered buffer to a playable URL and set it to the player
            const wavBlob = bufferToWave(processedAudioBuffer, processedAudioBuffer.length);
            const processedURL = URL.createObjectURL(wavBlob);
            processedPlayer.src = processedURL;

            // Enable the download button
            downloadButton.disabled = false;
            console.log('Rendering complete.');
        } catch (error) {
            console.error('Error rendering audio:', error);
            alert('An error occurred while processing the audio.');
        } finally {
            processButton.textContent = 'Add Echo Effect';
            processButton.disabled = false;
        }
    }

    /**
     * Triggers the download of the processed audio buffer as a WAV file.
     */
    function downloadProcessedAudio() {
        if (!processedAudioBuffer) {
            alert('No processed audio to download. Please add an echo effect first.');
            return;
        }

        // Convert the buffer to a WAV Blob
        const blob = bufferToWave(processedAudioBuffer, processedAudioBuffer.length);

        // Create a temporary link element to trigger the download
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = 'echo-audio.wav'; // Set the filename for the download
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    }

    /**
     * Converts an AudioBuffer to a WAV file (Blob).
     * This function handles the creation of the WAV header and interleaving of channel data.
     * @param {AudioBuffer} abuffer - The AudioBuffer to convert.
     * @param {number} len - The length of the buffer to use.
     * @returns {Blob} A Blob object representing the WAV file.
     */
    function bufferToWave(abuffer, len) {
        let numOfChan = abuffer.numberOfChannels,
            length = len * numOfChan * 2 + 44,
            buffer = new ArrayBuffer(length),
            view = new DataView(buffer),
            channels = [],
            i, sample,
            offset = 0,
            pos = 0;

        // write WAVE header
        setUint32(0x46464952); // "RIFF"
        setUint32(length - 8); // file length - 8
        setUint32(0x45564157); // "WAVE"

        setUint32(0x20746d66); // "fmt " chunk
        setUint32(16); // length = 16
        setUint16(1); // PCM (uncompressed)
        setUint16(numOfChan);
        setUint32(abuffer.sampleRate);
        setUint32(abuffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
        setUint16(numOfChan * 2); // block-align
        setUint16(16); // 16-bit audio

        setUint32(0x61746164); // "data" - chunk
        setUint32(length - pos - 4); // chunk length

        // write interleaved data
        for (i = 0; i < abuffer.numberOfChannels; i++)
            channels.push(abuffer.getChannelData(i));

        while (pos < length) {
            for (i = 0; i < numOfChan; i++) { // interleave channels
                sample = Math.max(-1, Math.min(1, channels[i][offset])); // clamp
                sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767) | 0; // scale to 16-bit signed int
                view.setInt16(pos, sample, true); // write 16-bit sample
                pos += 2;
            }
            offset++; // next source sample
        }

        return new Blob([view], { type: 'audio/wav' });

        function setUint16(data) {
            view.setUint16(pos, data, true);
            pos += 2;
        }

        function setUint32(data) {
            view.setUint32(pos, data, true);
            pos += 4;
        }
    }
});
