#### 3. `script.js` (The Core Logic)

This is where the magic happens. The script handles capture triggers, the selection mechanism, and all the canvas editing logic.

```javascript
document.addEventListener('DOMContentLoaded', () => {
    // --- DOM Elements ---
    const captureSelectBtn = document.getElementById('capture-select');
    const captureVisibleBtn = document.getElementById('capture-visible');
    const captureFullBtn = document.getElementById('capture-full');
    const editorModal = document.getElementById('editor-modal');
    const closeModalBtn = document.getElementById('close-editor-btn');
    const downloadBtn = document.getElementById('download-btn');
    const canvas = document.getElementById('editor-canvas');
    const ctx = canvas.getContext('2d');
    const selectionOverlay = document.getElementById('selection-overlay');
    const toolBtns = document.querySelectorAll('.tool-btn');
    const colorPicker = document.getElementById('color-picker');

    // --- State ---
    let isDrawing = false;
    let startX, startY;
    let currentTool = 'rect';
    let originalImage = null;

    // --- Capture Logic ---

    // 1. Capture Selected Area
    captureSelectBtn.addEventListener('click', () => {
        selectionOverlay.style.display = 'block';
        let selectionBox = null;
        let startX, startY, endX, endY;

        const onMouseDown = (e) => {
            startX = e.clientX;
            startY = e.clientY;
            selectionBox = document.createElement('div');
            selectionBox.classList.add('selection-box');
            selectionBox.style.left = `${startX}px`;
            selectionBox.style.top = `${startY}px`;
            document.body.appendChild(selectionBox);
            selectionOverlay.addEventListener('mousemove', onMouseMove);
        };

        const onMouseMove = (e) => {
            endX = e.clientX;
            endY = e.clientY;
            const width = Math.abs(endX - startX);
            const height = Math.abs(endY - startY);
            const left = Math.min(startX, endX);
            const top = Math.min(startY, endY);
            selectionBox.style.width = `${width}px`;
            selectionBox.style.height = `${height}px`;
            selectionBox.style.left = `${left}px`;
            selectionBox.style.top = `${top}px`;
        };

        const onMouseUp = () => {
            selectionOverlay.style.display = 'none';
            selectionOverlay.removeEventListener('mousedown', onMouseDown);
            selectionOverlay.removeEventListener('mousemove', onMouseMove);
            selectionOverlay.removeEventListener('mouseup', onMouseUp);
            if (selectionBox) {
                document.body.removeChild(selectionBox);
            }

            const rect = {
                x: Math.min(startX, endX),
                y: Math.min(startY, endY),
                width: Math.abs(endX - startX),
                height: Math.abs(endY - startY)
            };

            if (rect.width > 10 && rect.height > 10) {
                captureScreen({
                    x: rect.x,
                    y: rect.y,
                    width: rect.width,
                    height: rect.height
                });
            }
        };

        selectionOverlay.addEventListener('mousedown', onMouseDown);
        selectionOverlay.addEventListener('mouseup', onMouseUp);
    });

    // 2. Capture Visible Window
    captureVisibleBtn.addEventListener('click', () => {
        captureScreen();
    });

    // 3. Capture Entire Page
    captureFullBtn.addEventListener('click', () => {
        captureScreen({
            windowWidth: document.documentElement.scrollWidth,
            windowHeight: document.documentElement.scrollHeight
        });
    });

    // Generic capture function using html2canvas
    const captureScreen = (options = {}) => {
        // Hide controls to avoid them in the screenshot
        document.querySelector('.controls').style.visibility = 'hidden';
        html2canvas(document.body, {
            ...options,
            useCORS: true, // Important for external images
            logging: false
        }).then(capturedCanvas => {
            document.querySelector('.controls').style.visibility = 'visible';
            showEditor(capturedCanvas);
        }).catch(err => {
            console.error("Oops, something went wrong!", err);
            document.querySelector('.controls').style.visibility = 'visible';
        });
    };

    // --- Editor Logic ---

    const showEditor = (sourceCanvas) => {
        editorModal.style.display = 'flex';

        // Resize canvas to fit the modal while maintaining aspect ratio
        const modalContent = editorModal.querySelector('.modal-content');
        const toolbarHeight = editorModal.querySelector('.editor-toolbar').offsetHeight;
        const maxWidth = modalContent.clientWidth - 40; // 20px padding on each side
        const maxHeight = modalContent.clientHeight - toolbarHeight - 60; // Paddings and margins

        const ratio = Math.min(maxWidth / sourceCanvas.width, maxHeight / sourceCanvas.height);
        canvas.width = sourceCanvas.width;
        canvas.height = sourceCanvas.height;
        canvas.style.width = `${sourceCanvas.width * ratio}px`;
        canvas.style.height = `${sourceCanvas.height * ratio}px`;

        ctx.drawImage(sourceCanvas, 0, 0);
        originalImage = ctx.getImageData(0, 0, canvas.width, canvas.height);
    };

    closeModalBtn.addEventListener('click', () => {
        editorModal.style.display = 'none';
        originalImage = null;
    });

    // Tool selection
    toolBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelector('.tool-btn.active')?.classList.remove('active');
            btn.classList.add('active');
            currentTool = btn.dataset.tool;
            canvas.style.cursor = currentTool === 'text' ? 'text' : 'crosshair';
        });
    });
    // Set default tool
    document.querySelector('.tool-btn[data-tool="rect"]').classList.add('active');
    canvas.style.cursor = 'crosshair';


    // Drawing on canvas
    canvas.addEventListener('mousedown', (e) => {
        isDrawing = true;
        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;
        startX = (e.clientX - rect.left) * scaleX;
        startY = (e.clientY - rect.top) * scaleY;

        if (currentTool === 'text') {
            addTextInput(startX, startY);
            isDrawing = false;
        }
    });

    canvas.addEventListener('mousemove', (e) => {
        if (!isDrawing) return;
        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;
        const currentX = (e.clientX - rect.left) * scaleX;
        const currentY = (e.clientY - rect.top) * scaleY;

        // Restore original image to prevent smearing
        ctx.putImageData(originalImage, 0, 0);

        ctx.strokeStyle = colorPicker.value;
        ctx.fillStyle = colorPicker.value;
        ctx.lineWidth = 3;

        switch (currentTool) {
            case 'rect':
                ctx.strokeRect(startX, startY, currentX - startX, currentY - startY);
                break;
            case 'arrow':
                drawArrow(startX, startY, currentX, currentY);
                break;
        }
    });

    canvas.addEventListener('mouseup', (e) => {
        if (!isDrawing) return;
        isDrawing = false;
        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;
        const endX = (e.clientX - rect.left) * scaleX;
        const endY = (e.clientY - rect.top) * scaleY;

        // Draw final shape and update the original image data
        ctx.putImageData(originalImage, 0, 0);
        switch (currentTool) {
            case 'rect':
                ctx.strokeRect(startX, startY, endX - startX, endY - startY);
                break;
            case 'arrow':
                drawArrow(startX, startY, endX, endY);
                break;
        }
        originalImage = ctx.getImageData(0, 0, canvas.width, canvas.height);
    });

    // --- Drawing Helper Functions ---

    function drawArrow(fromX, fromY, toX, toY) {
        const headlen = 15; // length of head in pixels
        const dx = toX - fromX;
        const dy = toY - fromY;
        const angle = Math.atan2(dy, dx);
        ctx.beginPath();
        ctx.moveTo(fromX, fromY);
        ctx.lineTo(toX, toY);
        ctx.lineTo(toX - headlen * Math.cos(angle - Math.PI / 6), toY - headlen * Math.sin(angle - Math.PI / 6));
        ctx.moveTo(toX, toY);
        ctx.lineTo(toX - headlen * Math.cos(angle + Math.PI / 6), toY - headlen * Math.sin(angle + Math.PI / 6));
        ctx.stroke();
    }

    function addTextInput(x, y) {
        const input = document.createElement('input');
        input.type = 'text';
        input.style.position = 'absolute';
        const rect = canvas.getBoundingClientRect();
        input.style.left = `${x / (canvas.width / rect.width) + rect.left}px`;
        input.style.top = `${y / (canvas.height / rect.height) + rect.top}px`;
        input.style.border = '1px solid #000';
        input.style.font = '20px sans-serif';
        input.style.background = 'white';
        input.style.color = 'black';
        document.body.appendChild(input);
        input.focus();

        const onFinish = () => {
            if (input.value) {
                ctx.font = '20px sans-serif';
                ctx.fillStyle = colorPicker.value;
                ctx.fillText(input.value, x, y + 20); // +20 for better alignment
                originalImage = ctx.getImageData(0, 0, canvas.width, canvas.height);
            }
            document.body.removeChild(input);
        };

        input.addEventListener('blur', onFinish);
        input.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                input.blur();
            }
        });
    }

    // --- Download Logic ---
    downloadBtn.addEventListener('click', () => {
        const link = document.createElement('a');
        link.download = `screenshot-${Date.now()}.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
    });
});
```

