### Step 3: The Audio Engine (`src/AudioEngine.js`)

This class will encapsulate all the Web Audio API logic. It will manage the `AudioContext` and the creation, connection, and modification of all `AudioNode`s. This separation of concerns is crucial for a professional architecture.

```javascript
// src/AudioEngine.js

// Create a single, shared AudioContext
const audioContext = new (window.AudioContext || window.webkitAudioContext)();
const nodes = new Map(); // Store all created AudioNodes

// ADSR Envelope values
const adsrParams = {
  attack: 0.1,
  decay: 0.2,
  sustain: 0.7,
  release: 0.5,
};

export const createNode = (id, type, initialData = {}) => {
  if (nodes.has(id)) return; // Avoid creating duplicates

  let node;
  switch (type) {
    case 'oscillator':
      node = audioContext.createOscillator();
      node.type = initialData.type || 'sine';
      node.frequency.setValueAtTime(initialData.frequency || 440, audioContext.currentTime);
      node.start();
      break;
    case 'filter':
      node = audioContext.createBiquadFilter();
      node.type = initialData.type || 'lowpass';
      node.frequency.setValueAtTime(initialData.frequency || 1000, audioContext.currentTime);
      node.Q.setValueAtTime(initialData.q || 1, audioContext.currentTime);
      break;
    case 'adsr':
      // This is a "virtual" node that controls a GainNode
      node = audioContext.createGain();
      node.gain.setValueAtTime(0, audioContext.currentTime);
      break;
    case 'output':
      node = audioContext.createGain(); // Use a GainNode as the master output
      node.connect(audioContext.destination);
      break;
    default:
      return;
  }
  nodes.set(id, node);
};

export const removeNode = (id) => {
  const node = nodes.get(id);
  if (node) {
    if (node.stop) node.stop(); // Stop oscillator if it exists
    node.disconnect();
    nodes.delete(id);
  }
};

export const updateNodeParam = (id, param, value) => {
  const node = nodes.get(id);
  if (!node) return;

  if (node[param] instanceof AudioParam) {
    // Use setTargetAtTime for smooth parameter changes
    node[param].setTargetAtTime(value, audioContext.currentTime, 0.01);
  } else {
    node[param] = value;
  }
};

export const updateADSRParam = (param, value) => {
    adsrParams[param] = parseFloat(value);
};

export const connectNodes = (sourceId, targetId) => {
  const sourceNode = nodes.get(sourceId);
  const targetNode = nodes.get(targetId);
  if (sourceNode && targetNode) {
    // Special handling for ADSR: connect to the GainNode's gain AudioParam
    if (targetNode.constructor.name === 'GainNode' && sourceNode.constructor.name === 'OscillatorNode') {
        // This is a typical audio signal connection
        sourceNode.connect(targetNode);
    } else {
        // Generic connection
        sourceNode.connect(targetNode);
    }
  }
};

export const disconnectNodes = (sourceId, targetId) => {
  const sourceNode = nodes.get(sourceId);
  const targetNode = nodes.get(targetId);
  if (sourceNode && targetNode) {
    try {
      sourceNode.disconnect(targetNode);
    } catch (e) {
      console.warn("Could not disconnect nodes:", e);
    }
  }
};

// --- Playback Logic ---
export const playNote = () => {
  // Find all ADSR nodes and trigger their envelope
  nodes.forEach((node, id) => {
    if (id.includes('adsr')) {
      const now = audioContext.currentTime;
      const gainParam = node.gain;
      gainParam.cancelScheduledValues(now);
      // Attack
      gainParam.linearRampToValueAtTime(1.0, now + adsrParams.attack);
      // Decay to Sustain
      gainParam.linearRampToValueAtTime(adsrParams.sustain, now + adsrParams.attack + adsrParams.decay);
    }
  });
};

export const stopNote = () => {
  nodes.forEach((node, id) => {
    if (id.includes('adsr')) {
      const now = audioContext.currentTime;
      const gainParam = node.gain;
      gainParam.cancelScheduledValues(now);
      // Release
      gainParam.linearRampToValueAtTime(0, now + adsrParams.release);
    }
  });
};

// --- Audio Export Logic ---
export const exportAudio = async (duration = 2) => {
    const offlineCtx = new OfflineAudioContext(2, 44100 * duration, 44100);
    const offlineNodes = new Map();

    // Recreate the entire node graph in the offline context
    nodes.forEach((originalNode, id) => {
        let newNode;
        const nodeType = id.split('-')[0];
        switch (nodeType) {
            case 'oscillator':
                newNode = offlineCtx.createOscillator();
                newNode.type = originalNode.type;
                newNode.frequency.value = originalNode.frequency.value;
                newNode.start(0);
                break;
            case 'filter':
                newNode = offlineCtx.createBiquadFilter();
                newNode.type = originalNode.type;
                newNode.frequency.value = originalNode.frequency.value;
                newNode.Q.value = originalNode.Q.value;
                break;
            case 'adsr':
                newNode = offlineCtx.createGain();
                newNode.gain.value = 0; // Start silent
                break;
            case 'output':
                newNode = offlineCtx.createGain();
                newNode.connect(offlineCtx.destination);
                break;
            default: return;
        }
        offlineNodes.set(id, newNode);
    });

    // Reconnect nodes in the offline context
    // This assumes a simple linear chain for export. A more complex graph would require traversing connections.
    // For this demo, let's assume a fixed chain: osc -> filter -> adsr -> output
    const osc = Array.from(offlineNodes.entries()).find(([id]) => id.startsWith('oscillator'))?.[1];
    const filter = Array.from(offlineNodes.entries()).find(([id]) => id.startsWith('filter'))?.[1];
    const adsr = Array.from(offlineNodes.entries()).find(([id]) => id.startsWith('adsr'))?.[1];
    const output = Array.from(offlineNodes.entries()).find(([id]) => id.startsWith('output'))?.[1];

    if (osc && filter && adsr && output) {
        osc.connect(filter);
        filter.connect(adsr);
        adsr.connect(output);

        // Simulate note press for the envelope
        const gainParam = adsr.gain;
        gainParam.setValueAtTime(0, 0);
        gainParam.linearRampToValueAtTime(1.0, adsrParams.attack);
        gainParam.linearRampToValueAtTime(adsrParams.sustain, adsrParams.attack + adsrParams.decay);
        gainParam.linearRampToValueAtTime(0, duration - adsrParams.release);
    } else {
        console.error("Could not find all required nodes for export.");
        return;
    }

    const renderedBuffer = await offlineCtx.startRendering();
    const wav = bufferToWave(renderedBuffer);
    const blob = new Blob([wav], { type: 'audio/wav' });

    const anchor = document.createElement('a');
    anchor.href = URL.createObjectURL(blob);
    anchor.download = 'synth-output.wav';
    anchor.click();
};

// Helper function to convert AudioBuffer to a WAV file
