### Step 5: The Main Application (`src/App.js`)

This file ties everything together. It manages the React Flow state and communicates with our `AudioEngine`.

```javascript
// src/App.js
import React, { useState, useCallback, useMemo } from 'react';
import ReactFlow, {
  ReactFlowProvider,
  addEdge,
  removeElements,
  Controls,
} from 'reactflow';
import 'reactflow/dist/style.css';
import './index.css';

import OscillatorNode from './components/OscillatorNode';
import FilterNode from './components/FilterNode';
import ADSRNode from './components/ADSRNode';
import OutputNode from './components/OutputNode';

import * as AudioEngine from './AudioEngine';

const initialElements = [
  { id: 'output-1', type: 'output', position: { x: 650, y: 100 }, data: {} },
];

let id = 0;
const getId = (type) => `${type}-${id++}`;

const App = () => {
  const [elements, setElements] = useState(initialElements);

  const onElementsRemove = useCallback((elementsToRemove) => {
    elementsToRemove.forEach(el => AudioEngine.removeNode(el.id));
    setElements((els) => removeElements(elementsToRemove, els));
  }, []);

  const onConnect = useCallback((params) => {
    AudioEngine.connectNodes(params.source, params.target);
    setElements((els) => addEdge(params, els));
  }, []);

  const onEdgesDelete = useCallback((edgesToRemove) => {
    edgesToRemove.forEach(edge => AudioEngine.disconnectNodes(edge.source, edge.target));
  }, []);

  const nodeTypes = useMemo(() => ({
    oscillator: OscillatorNode,
    filter: FilterNode,
    adsr: ADSRNode,
    output: OutputNode,
  }), []);

  const addNode = (type) => {
    const newId = getId(type);
    const newNode = {
      id: newId,
      type,
      position: {
        x: Math.random() * 400,
        y: Math.random() * 400,
      },
      data: {},
    };
    AudioEngine.createNode(newId, type);
    setElements((els) => els.concat(newNode));
  };

  return (
    <div className="app-container">
      <div className="controls-panel">
        <h2>Modules</h2>
        <button onClick={() => addNode('oscillator')}>Add Oscillator</button>
        <button onClick={() => addNode('filter')}>Add Filter</button>
        <button onClick={() => addNode('adsr')}>Add ADSR</button>
        <hr />
        <h2>Playback</h2>
        <button onMouseDown={AudioEngine.playNote} onMouseUp={AudioEngine.stopNote}>
          Play Note
        </button>
        <hr />
        <h2>Export</h2>
        <button onClick={() => AudioEngine.exportAudio(2)}>Export 2s WAV</button>
      </div>
      <div className="react-flow-wrapper">
        <ReactFlowProvider>
          <ReactFlow
            elements={elements}
            onElementsRemove={onElementsRemove}
            onConnect={onConnect}
            onEdgesDelete={onEdgesDelete}
            nodeTypes={nodeTypes}
            snapToGrid={true}
            snapGrid={[15, 15]}
          >
            <Controls />
          </ReactFlow>
        </ReactFlowProvider>
      </div>
    </div>
  );
};

export default App;
```

