### Step 1: Backend Setup (Node.js Server)

First, navigate to the `dynamic-sticker-tool` directory in your terminal.

1.  **Initialize the project and install dependencies:**

    ```bash
    npm init -y
    npm install express multer fluent-ffmpeg
    ```

2.  **Create `server.js`:**

    This file will handle file uploads and the core FFmpeg processing.

    ```javascript
    // server.js
    const express = require('express');
    const multer = require('multer');
    const ffmpeg = require('fluent-ffmpeg');
    const path = require('path');
    const fs = require('fs');

    const app = express();
    const port = 3000;

    // Ensure necessary directories exist
    ['uploads', 'generated'].forEach(dir => {
        if (!fs.existsSync(dir)) {
            fs.mkdirSync(dir);
        }
    });

    // --- Multer Setup for File Uploads ---
    const storage = multer.diskStorage({
        destination: (req, file, cb) => {
            cb(null, 'uploads/');
        },
        filename: (req, file, cb) => {
            cb(null, Date.now() + path.extname(file.originalname));
        }
    });
    const upload = multer({ storage: storage });

    // --- Middleware ---
    app.use(express.static('public')); // Serve frontend files
    app.use('/generated', express.static('generated')); // Serve generated files
    app.use(express.json());
    app.use(express.urlencoded({ extended: true }));

    // --- API Endpoint for Processing ---
    app.post('/api/process', upload.single('baseImage'), (req, res) => {
        console.log('Processing request received...');
        const baseImagePath = req.file.path;
        const stickers = JSON.parse(req.body.stickers);
        const outputFormat = req.body.format || 'gif';
        const outputFilename = `${Date.now()}.${outputFormat}`;
        const outputPath = path.join('generated', outputFilename);

        // Create a base FFmpeg command
        const command = ffmpeg(baseImagePath)
            .loop(0); // Loop GIF/video indefinitely

        // Dynamically build the filter chain to overlay stickers
        const filterComplex = stickers.map((sticker, index) => {
            const stickerPath = path.join(__dirname, 'public', sticker.src);
            // FFmpeg filter expressions for animation
            // This is a simplified example. More complex animations require more complex expressions.
            let x = sticker.x;
            let y = sticker.y;
            switch (sticker.animation) {
                case 'wobble':
                    // Wobbles horizontally. 't' is timestamp in seconds.
                    x = `${sticker.x} + sin(t*5)*10`;
                    break;
                case 'bounce':
                    // Bounces vertically
                    y = `${sticker.y} - abs(sin(t*3)*20)`;
                    break;
                // Add more animation cases here
            }
            // [0:v] is the base image. [${index + 1}:v] is the current sticker.
            // The output of each overlay is named (e.g., [v${index}]) and used as input for the next.
            const inputChain = index === 0 ? '[0:v]' : `[v${index - 1}]`;
            const outputChain = `[v${index}]`;
            return `${inputChain}[${index + 1}:v]overlay=x=${x}:y=${y}:shortest=1${index === stickers.length - 1 ? '' : outputChain}`;
        }).join(';');

        // Add sticker files as inputs
        stickers.forEach(sticker => {
            command.input(path.join(__dirname, 'public', sticker.src));
        });

        command
            .complexFilter(filterComplex)
            .outputOptions(outputFormat === 'gif' ? [
                '-vf', 'fps=15,scale=500:-1:flags=lanczos,split[s0][s1];[s0]palettegen[p];[s1][p]paletteuse'
            ] : []) // GIF optimization options
            .toFormat(outputFormat)
            .on('end', () => {
                console.log('Processing finished successfully.');
                res.json({ success: true, fileUrl: `/${outputPath}` });
            })
            .on('error', (err) => {
                console.error('Error processing:', err.message);
                res.status(500).json({ success: false, error: err.message });
            })
            .save(outputPath);
    });

    app.listen(port, () => {
        console.log(`Server running at http://localhost:${port}`);
    });
    ```

