3.  **Create `public/script.js`:**

    This is the most complex part of the frontend. It manages the canvas, animations, and communication with the backend.

    ```javascript
    // public/script.js
    document.addEventListener('DOMContentLoaded', () => {
        const canvas = new fabric.Canvas('editor-canvas');
        const imageLoader = document.getElementById('image-loader');
        const stickerPanel = document.getElementById('sticker-panel');
        const addTextBtn = document.getElementById('add-text-btn');
        const exportBtn = document.getElementById('export-btn');
        const deleteBtn = document.getElementById('delete-btn');
        const resultArea = document.getElementById('result-area');

        let baseImageFile = null;

        // --- Sticker & Animation Data ---
        const STICKERS = [
            { src: 'stickers/emoji-laugh.gif', animation: 'wobble' },
            { src: 'stickers/emoji-cool.gif', animation: 'bounce' },
            { src: 'stickers/text-wow.gif', animation: 'none' }
        ];

        // Populate sticker panel
        STICKERS.forEach(sticker => {
            const img = document.createElement('img');
            img.src = sticker.src;
            img.dataset.animation = sticker.animation;
            img.title = `Add Sticker (Animation: ${sticker.animation})`;
            img.onclick = () => addSticker(sticker.src, sticker.animation);
            stickerPanel.appendChild(img);
        });

        // --- Canvas Event Handlers ---
        imageLoader.addEventListener('change', (e) => {
            const file = e.target.files[0];
            if (!file) return;
            baseImageFile = file;
            const reader = new FileReader();
            reader.onload = (f) => {
                fabric.Image.fromURL(f.target.result, (img) => {
                    canvas.setBackgroundImage(img, canvas.renderAll.bind(canvas), {
                        scaleX: canvas.width / img.width,
                        scaleY: canvas.height / img.height
                    });
                });
            };
            reader.readAsDataURL(file);
        });

        function addSticker(src, animationType) {
            fabric.Image.fromURL(src, (img) => {
                img.scale(0.3).set({
                    left: 100,
                    top: 100,
                    // Custom properties to store our data
                    customData: {
                        type: 'sticker',
                        src: src,
                        animation: animationType
                    }
                });
                canvas.add(img);
            }, { crossOrigin: 'anonymous' });
        }

        addTextBtn.addEventListener('click', () => {
            const text = new fabric.IText('Hello!', {
                left: 150,
                top: 150,
                fill: '#ff0000',
                fontFamily: 'Arial',
                customData: {
                    type: 'text',
                    animation: 'wobble' // Default animation for text
                }
            });
            canvas.add(text);
        });

        deleteBtn.addEventListener('click', () => {
            const activeObject = canvas.getActiveObject();
            if (activeObject) {
                canvas.remove(activeObject);
            }
        });

        // --- Animation Preview Loop ---
        let startTime = Date.now();
        function animate() {
            const time = (Date.now() - startTime) / 1000; // time in seconds

            canvas.getObjects().forEach(obj => {
                if (obj.customData && obj.customData.animation) {
                    const originalLeft = obj.left;
                    const originalTop = obj.top;

                    switch (obj.customData.animation) {
                        case 'wobble':
                            obj.set('left', originalLeft + Math.sin(time * 5) * 5);
                            break;
                        case 'bounce':
                            obj.set('top', originalTop - Math.abs(Math.sin(time * 3) * 10));
                            break;
                    }
                }
            });

            canvas.renderAll();
            requestAnimationFrame(animate);
        }
        animate();

        // --- Export Logic ---
        exportBtn.addEventListener('click', async () => {
            if (!baseImageFile) {
                alert('Please upload a base image first!');
                return;
            }

            resultArea.innerHTML = '<p>Processing... This may take a moment.</p>';

            // 1. Collect sticker data
            const stickerData = canvas.getObjects().map(obj => {
                // We need to get the position relative to the original image size, not the canvas size.
                const bg = canvas.backgroundImage;
                const scaleX = bg.width / canvas.width;
                const scaleY = bg.height / canvas.height;

                return {
                    type: obj.customData.type,
                    src: obj.customData.src, // For stickers
                    text: obj.text, // For text objects
                    x: obj.left * scaleX,
                    y: obj.top * scaleY,
                    scaleX: obj.scaleX * scaleX,
                    scaleY: obj.scaleY * scaleY,
                    angle: obj.angle,
                    animation: obj.customData.animation
                };
            });

            // 2. Create FormData to send to server
            const formData = new FormData();
            formData.append('baseImage', baseImageFile);
            formData.append('stickers', JSON.stringify(stickerData));
            formData.append('format', document.getElementById('format-selector').value);

            // 3. Send to backend
            try {
                const response = await fetch('/api/process', {
                    method: 'POST',
                    body: formData
                });
                const result = await response.json();

                if (result.success) {
                    const format = document.getElementById('format-selector').value;
                    if (format === 'gif') {
                        resultArea.innerHTML = `
                            <img src="${result.fileUrl}" alt="Generated GIF">
                            <a href="${result.fileUrl}" download>Download GIF</a>
                        `;
                    } else {
                        resultArea.innerHTML = `
                            <video src="${result.fileUrl}" controls autoplay loop></video>
                            <a href="${result.fileUrl}" download>Download Video</a>
                        `;
                    }
                } else {
                    resultArea.innerHTML = `<p>Error: ${result.error}</p>`;
                }
            } catch (error) {
                resultArea.innerHTML = `<p>An unexpected error occurred: ${error.message}</p>`;
            }
        });
    });
    ```

