 * This script contains the core logic for the image annotation tool.
 * It handles image loading, drawing on the canvas, managing annotations,
 * and exporting the final image.
 */
document.addEventListener('DOMContentLoaded', () => {

    // --- DOM Element References ---
    const canvas = document.getElementById('annotationCanvas');
    const ctx = canvas.getContext('2d');
    const imageLoader = document.getElementById('imageLoader');
    const toolButtons = document.querySelectorAll('.tool-btn');
    const colorPicker = document.getElementById('annotationColor');
    const exportBtn = document.getElementById('exportBtn');

    // --- State Management ---
    let image = new Image();
    let annotations = []; // Array to store all annotation objects
    let currentTool = 'select'; // The currently active tool
    let isDrawing = false; // Flag for when the user is actively drawing a shape
    let isDragging = false; // Flag for when the user is moving an annotation
    let selectedAnnotation = null; // The currently selected annotation object
    let startX, startY; // Coordinates for the start of a draw/drag action
    let offsetX, offsetY; // Offset for dragging an object from a point other than its top-left corner

    // --- Initial Setup ---
    // Load a sample image by default for demonstration purposes
    image.src = 'assets/sample-image.jpg';
    image.onload = () => {
        // Set canvas dimensions to match the loaded image
        canvas.width = image.width;
        canvas.height = image.height;
        redrawCanvas();
    };

    // --- Event Listeners ---

    // Handles loading a new image from the user's computer
    imageLoader.addEventListener('change', (e) => {
        const file = e.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (event) => {
                image.src = event.target.result;
                // Reset annotations when a new image is loaded
                annotations = [];
                selectedAnnotation = null;
            };
            reader.readAsDataURL(file);
        }
    });

    // Handles tool selection from the toolbar
    toolButtons.forEach(button => {
        button.addEventListener('click', () => {
            // Set the current tool based on the button's data attribute
            currentTool = button.dataset.tool;
            // Update the UI to show which tool is active
            document.querySelector('.tool-btn.active').classList.remove('active');
            button.classList.add('active');
            // Deselect any annotation when switching tools
            selectedAnnotation = null;
            redrawCanvas();
        });
    });

    // Handles the start of a mouse action (drawing or selecting)
    canvas.addEventListener('mousedown', (e) => {
        const pos = getMousePos(canvas, e);
        startX = pos.x;
        startY = pos.y;

        if (currentTool === 'select') {
            // Check if the click is on an existing annotation
            selectedAnnotation = getAnnotationAtPosition(startX, startY);
            if (selectedAnnotation) {
                isDragging = true;
                // Calculate offset for smooth dragging
                offsetX = startX - selectedAnnotation.x;
                offsetY = startY - selectedAnnotation.y;
            } 
        } else {
            // If using a drawing tool, start drawing
            isDrawing = true;
        }
        redrawCanvas();
    });

    // Handles mouse movement for drawing or dragging
    canvas.addEventListener('mousemove', (e) => {
        const pos = getMousePos(canvas, e);
        updateCursor(pos.x, pos.y);

        if (isDrawing) {
            redrawCanvas(); // Redraw to show the shape being created in real-time
            drawCurrentShape(pos.x, pos.y);
        } else if (isDragging && selectedAnnotation) {
            // Update the position of the selected annotation
            selectedAnnotation.x = pos.x - offsetX;
            selectedAnnotation.y = pos.y - offsetY;
            redrawCanvas();
        }
    });

    // Handles the end of a mouse action (finishing a drawing or drag)
    canvas.addEventListener('mouseup', (e) => {
        if (isDrawing) {
            const pos = getMousePos(canvas, e);
            addAnnotation(pos.x, pos.y);
        }
        isDrawing = false;
        isDragging = false;
    });

    // Handles keyboard events, specifically for deleting annotations
    document.addEventListener('keydown', (e) => {
        if ((e.key === 'Delete' || e.key === 'Backspace') && selectedAnnotation) {
            // Remove the selected annotation from the array
            annotations = annotations.filter(a => a !== selectedAnnotation);
            selectedAnnotation = null;
            redrawCanvas();
        }
    });

    // Handles exporting the canvas content as a PNG image
    exportBtn.addEventListener('click', () => {
        // Temporarily deselect to avoid exporting with selection handles
        const wasSelected = selectedAnnotation;
        selectedAnnotation = null;
        redrawCanvas();

        // Create a download link for the image
        const link = document.createElement('a');
        link.download = 'annotated-image.png';
        link.href = canvas.toDataURL('image/png');
        link.click();

        // Restore selection if an item was selected before exporting
        if (wasSelected) {
            selectedAnnotation = wasSelected;
            redrawCanvas();
        }
    });

    // --- Core Functions ---

    /**
     * Clears and redraws the entire canvas, including the background image
     * and all annotations.
     */
    function redrawCanvas() {
        // Clear the canvas completely
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        // Draw the background image
        ctx.drawImage(image, 0, 0, canvas.width, canvas.height);

        // Draw all stored annotations
        annotations.forEach(annotation => {
            drawAnnotation(annotation);
        });

        // If an annotation is selected, draw a highlight/handles around it
        if (selectedAnnotation) {
            drawSelection(selectedAnnotation);
        }
    }

    /**
     * Adds a newly created annotation to the main annotations array.
     * @param {number} endX - The final X coordinate of the mouse.
     * @param {number} endY - The final Y coordinate of the mouse.
     */
    function addAnnotation(endX, endY) {
        const color = colorPicker.value;
        let newAnnotation = null;

        switch (currentTool) {
            case 'rectangle':
                newAnnotation = {
                    type: 'rectangle',
                    x: Math.min(startX, endX),
                    y: Math.min(startY, endY),
                    width: Math.abs(endX - startX),
                    height: Math.abs(endY - startY),
                    color: color
                };
                break;
            case 'circle':
                const radius = Math.sqrt(Math.pow(endX - startX, 2) + Math.pow(endY - startY, 2));
                newAnnotation = {
                    type: 'circle',
                    x: startX, // Center x
                    y: startY, // Center y
                    radius: radius,
                    color: color
                };
                break;
            case 'text':
                const text = prompt('Enter text:');
                if (text) {
                    newAnnotation = {
                        type: 'text',
                        x: startX,
                        y: startY,
                        text: text,
                        color: color,
                        font: '20px Arial'
                    };
                }
                break;
        }

        if (newAnnotation && (newAnnotation.width > 2 || newAnnotation.height > 2 || newAnnotation.radius > 2 || newAnnotation.type === 'text')) {
            annotations.push(newAnnotation);
        }
        redrawCanvas();
    }

    /**
     * Draws a single annotation on the canvas based on its type and properties.
     * @param {object} annotation - The annotation object to draw.
     */
    function drawAnnotation(annotation) {
        ctx.fillStyle = annotation.color;
        ctx.strokeStyle = annotation.color;
        ctx.lineWidth = 2;

        switch (annotation.type) {
            case 'rectangle':
                ctx.strokeRect(annotation.x, annotation.y, annotation.width, annotation.height);
                break;
            case 'circle':
                ctx.beginPath();
                ctx.arc(annotation.x, annotation.y, annotation.radius, 0, 2 * Math.PI);
                ctx.stroke();
                break;
            case 'text':
                ctx.font = annotation.font;
                ctx.fillText(annotation.text, annotation.x, annotation.y);
                break;
        }
    }

    /**
     * Draws the shape currently being created by the user in real-time.
     * @param {number} currentX - The current X coordinate of the mouse.
     * @param {number} currentY - The current Y coordinate of the mouse.
     */
    function drawCurrentShape(currentX, currentY) {
        ctx.strokeStyle = colorPicker.value;
        ctx.lineWidth = 2;
        ctx.setLineDash([5, 5]); // Dashed line for preview

        switch (currentTool) {
            case 'rectangle':
                const width = currentX - startX;
                const height = currentY - startY;
                ctx.strokeRect(startX, startY, width, height);
                break;
            case 'circle':
                const radius = Math.sqrt(Math.pow(currentX - startX, 2) + Math.pow(currentY - startY, 2));
                ctx.beginPath();
                ctx.arc(startX, startY, radius, 0, 2 * Math.PI);
                ctx.stroke();
                break;
        }
        ctx.setLineDash([]); // Reset line dash
    }

    /**
     * Draws a selection box around the currently selected annotation.
     * @param {object} annotation - The selected annotation object.
     */
    function drawSelection(annotation) {
        ctx.strokeStyle = '#007bff';
        ctx.lineWidth = 2;
        ctx.setLineDash([6, 3]);

        let x, y, w, h;
        switch (annotation.type) {
            case 'rectangle':
                x = annotation.x; y = annotation.y; w = annotation.width; h = annotation.height;
                break;
            case 'circle':
                x = annotation.x - annotation.radius; y = annotation.y - annotation.radius;
                w = annotation.radius * 2; h = annotation.radius * 2;
                break;
            case 'text':
                ctx.font = annotation.font;
                const textMetrics = ctx.measureText(annotation.text);
                x = annotation.x; y = annotation.y - 20; // Approximate height
                w = textMetrics.width; h = 20;
                break;
        }
        // Draw a bounding box slightly larger than the shape
        ctx.strokeRect(x - 5, y - 5, w + 10, h + 10);
        ctx.setLineDash([]);
    }

    // --- Helper Functions ---

    /**
     * Calculates the mouse position relative to the canvas element.
     * @param {HTMLCanvasElement} canvasEl - The canvas element.
     * @param {MouseEvent} evt - The mouse event.
     * @returns {object} An object with x and y coordinates.
     */
    function getMousePos(canvasEl, evt) {
        const rect = canvasEl.getBoundingClientRect();
        const scaleX = canvasEl.width / rect.width;
        const scaleY = canvasEl.height / rect.height;
        return {
            x: (evt.clientX - rect.left) * scaleX,
            y: (evt.clientY - rect.top) * scaleY
        };
    }

    /**
     * Finds the topmost annotation at a given canvas position.
     * @param {number} x - The X coordinate.
     * @param {number} y - The Y coordinate.
     * @returns {object|null} The found annotation object or null.
     */
    function getAnnotationAtPosition(x, y) {
        // Iterate backwards to select the topmost annotation first
        for (let i = annotations.length - 1; i >= 0; i--) {
            const annotation = annotations[i];
            if (isPointInAnnotation(x, y, annotation)) {
                return annotation;
            }
        }
        return null;
    }

    /**
     * Checks if a point is inside the bounds of a given annotation.
     * @param {number} x - The point's X coordinate.
     * @param {number} y - The point's Y coordinate.
     * @param {object} annotation - The annotation to check against.
     * @returns {boolean} True if the point is inside, false otherwise.
     */
    function isPointInAnnotation(x, y, annotation) {
        const buffer = 10; // Add a small buffer for easier selection
        switch (annotation.type) {
            case 'rectangle':
                return (x >= annotation.x - buffer && x <= annotation.x + annotation.width + buffer &&
                        y >= annotation.y - buffer && y <= annotation.y + annotation.height + buffer);
            case 'circle':
                const distance = Math.sqrt(Math.pow(x - annotation.x, 2) + Math.pow(y - annotation.y, 2));
                return distance <= annotation.radius + buffer;
            case 'text':
                ctx.font = annotation.font;
                const textMetrics = ctx.measureText(annotation.text);
                const textWidth = textMetrics.width;
                const textHeight = 20; // Approximate height
                return (x >= annotation.x - buffer && x <= annotation.x + textWidth + buffer &&
                        y >= annotation.y - textHeight - buffer && y <= annotation.y + buffer);
        }
        return false;
    }

    /**
     * Updates the canvas cursor style based on the current tool and mouse position.
     * @param {number} x - The current X coordinate of the mouse.
     * @param {number} y - The current Y coordinate of the mouse.
     */
    function updateCursor(x, y) {
        if (currentTool === 'select') {
            if (getAnnotationAtPosition(x, y)) {
                canvas.style.cursor = 'move';
            } else {
                canvas.style.cursor = 'default';
            }
        } else {
            canvas.style.cursor = 'crosshair';
        }
    }
});
