### 3. JavaScript (`script.js`)

This is the core of the application. It handles file loading, LRC parsing, audio synchronization, UI updates, and the export functionality.

```javascript
document.addEventListener('DOMContentLoaded', () => {
    const audioUpload = document.getElementById('audio-upload');
    const lrcUpload = document.getElementById('lrc-upload');
    const audioPlayer = document.getElementById('audio-player');
    const lyricsContainer = document.getElementById('lyrics-container');
    const offsetInput = document.getElementById('offset-input');
    const offsetIncreaseBtn = document.getElementById('offset-increase');
    const offsetDecreaseBtn = document.getElementById('offset-decrease');
    const exportBtn = document.getElementById('export-lrc');

    let lyrics = [];
    let currentLineIndex = -1;
    let lyricsOffset = 0;

    // File Handlers
    audioUpload.addEventListener('change', (e) => {
        const file = e.target.files[0];
        if (file) {
            audioPlayer.src = URL.createObjectURL(file);
        }
    });

    lrcUpload.addEventListener('change', (e) => {
        const file = e.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (event) => {
                lyrics = parseLRC(event.target.result);
                renderLyrics();
                exportBtn.disabled = false;
            };
            reader.readAsText(file);
        }
    });

    // LRC Parser
    function parseLRC(lrcContent) {
        const lines = lrcContent.split('\n');
        const parsedLyrics = [];
        const timeRegex = /\[(\d{2}):(\d{2})\.(\d{2,3})\]/;

        for (const line of lines) {
            const timeMatch = line.match(timeRegex);
            if (timeMatch) {
                const minutes = parseInt(timeMatch[1], 10);
                const seconds = parseInt(timeMatch[2], 10);
                const milliseconds = parseInt(timeMatch[3].padEnd(3, '0'), 10);
                const time = minutes * 60 + seconds + milliseconds / 1000;

                const text = line.replace(timeRegex, '').trim();

                // Enhanced LRC: Check for word timestamps
                const wordTimeRegex = /<(\d{2}):(\d{2})\.(\d{2,3})>/g;
                const words = [];
                let lastIndex = 0;
                let wordMatch;

                const plainTextWithoutTimestamps = text.replace(/<[^>]+>/g, '');

                if (text.match(wordTimeRegex)) {
                    // Reset regex state
                    wordTimeRegex.lastIndex = 0; 
                    while ((wordMatch = wordTimeRegex.exec(text)) !== null) {
                        const wordMinutes = parseInt(wordMatch[1], 10);
                        const wordSeconds = parseInt(wordMatch[2], 10);
                        const wordMilliseconds = parseInt(wordMatch[3].padEnd(3, '0'), 10);
                        const wordTime = wordMinutes * 60 + wordSeconds + wordMilliseconds / 1000;

                        const wordText = text.substring(lastIndex, wordMatch.index).replace(/<[^>]+>/g, '').trim();
                        if (wordText) {
                            // This logic handles the text between timestamps
                            const previousWord = words.length > 0 ? words[words.length - 1] : { time: time };
                            words.push({ time: previousWord.time, text: wordText });
                        }

                        lastIndex = wordTimeRegex.lastIndex;
                    }
                    // Add the last part of the text
                    const lastWordText = text.substring(lastIndex).replace(/<[^>]+>/g, '').trim();
                    if (lastWordText) {
                        const lastWordTime = words.length > 0 ? words[words.length - 1].time : time;
                        words.push({ time: lastWordTime, text: lastWordText });
                    }

                    // Re-assign correct times
                    let wordTimes = text.match(/<(\d{2}):(\d{2})\.(\d{2,3})>/g).map(t => {
                        const m = t.match(/(\d{2}):(\d{2})\.(\d{2,3})/);
                        return parseInt(m[1])*60 + parseInt(m[2]) + parseInt(m[3].padEnd(3,'0'))/1000;
                    });

                    words.forEach((word, index) => {
                        if(wordTimes[index]) word.time = wordTimes[index];
                    });

                }

                parsedLyrics.push({ time, text: plainTextWithoutTimestamps, words });
            }
        }
        return parsedLyrics;
    }

    // UI Rendering
    function renderLyrics() {
        lyricsContainer.innerHTML = '';
        if (lyrics.length === 0) {
            lyricsContainer.innerHTML = '<p class="placeholder">Lyrics will appear here.</p>';
            return;
        }
        lyrics.forEach((line, index) => {
            const lineEl = document.createElement('div');
            lineEl.classList.add('lyrics-line');
            lineEl.dataset.index = index;

            if (line.words && line.words.length > 0) {
                line.words.forEach((word, wordIndex) => {
                    const wordEl = document.createElement('span');
                    wordEl.classList.add('word');
                    wordEl.dataset.wordIndex = wordIndex;
                    wordEl.textContent = word.text + ' ';
                    lineEl.appendChild(wordEl);
                });
            } else {
                lineEl.textContent = line.text;
            }
            lyricsContainer.appendChild(lineEl);
        });
    }

    // Synchronization Logic
    audioPlayer.addEventListener('timeupdate', () => {
        if (lyrics.length === 0) return;

        const currentTime = audioPlayer.currentTime + lyricsOffset;

        // Find current line
        let newLineIndex = -1;
        for (let i = lyrics.length - 1; i >= 0; i--) {
            if (lyrics[i].time <= currentTime) {
                newLineIndex = i;
                break;
            }
        }

        if (newLineIndex !== currentLineIndex) {
            // Remove old highlight
            const oldLine = lyricsContainer.querySelector(`[data-index="${currentLineIndex}"]`);
            if (oldLine) oldLine.classList.remove('current');

            // Add new highlight
            const newLine = lyricsContainer.querySelector(`[data-index="${newLineIndex}"]`);
            if (newLine) {
                newLine.classList.add('current');
                // Scroll into view
                newLine.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
            currentLineIndex = newLineIndex;
        }

        // Word-by-word highlighting
        if (currentLineIndex !== -1) {
            const currentLineData = lyrics[currentLineIndex];
            const currentLineEl = lyricsContainer.querySelector(`[data-index="${currentLineIndex}"]`);

            if (currentLineData.words && currentLineData.words.length > 0 && currentLineEl) {
                const wordEls = currentLineEl.querySelectorAll('.word');
                let currentWordIndex = -1;

                for (let i = currentLineData.words.length - 1; i >= 0; i--) {
                    if (currentLineData.words[i].time <= currentTime) {
                        currentWordIndex = i;
                        break;
                    }
                }

                wordEls.forEach((wordEl, index) => {
                    wordEl.classList.remove('past', 'current');
                    if (index < currentWordIndex) {
                        wordEl.classList.add('past');
                    } else if (index === currentWordIndex) {
                        wordEl.classList.add('current');
                    }
                });
            }
        }
    });

    // Offset Controls
    function updateOffset(newOffset) {
        lyricsOffset = newOffset;
        offsetInput.value = lyricsOffset.toFixed(1);
        // Trigger a timeupdate event to re-sync immediately
        audioPlayer.dispatchEvent(new Event('timeupdate'));
    }

    offsetIncreaseBtn.addEventListener('click', () => updateOffset(lyricsOffset + 0.1));
    offsetDecreaseBtn.addEventListener('click', () => updateOffset(lyricsOffset - 0.1));
    offsetInput.addEventListener('change', () => updateOffset(parseFloat(offsetInput.value)));

    // Export Logic
    function formatTime(timeInSeconds) {
        const minutes = Math.floor(timeInSeconds / 60);
        const seconds = Math.floor(timeInSeconds % 60);
        const milliseconds = Math.round((timeInSeconds - Math.floor(timeInSeconds)) * 1000);
        return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}.${String(milliseconds).padStart(3, '0').slice(0,2)}`;
    }

    exportBtn.addEventListener('click', () => {
        if (lyrics.length === 0) return;

        let lrcString = '';
        lyrics.forEach(line => {
            const newTime = line.time - lyricsOffset;
            lrcString += `[${formatTime(newTime)}]`;

            if (line.words && line.words.length > 0) {
                line.words.forEach(word => {
                    const newWordTime = word.time - lyricsOffset;
                    lrcString += `<${formatTime(newWordTime)}>${word.text}`;
                });
            } else {
                lrcString += line.text;
            }
            lrcString += '\n';
        });

        const blob = new Blob([lrcString], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'lyrics_modified.lrc';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    });
});
