    <script>
        document.addEventListener('DOMContentLoaded', () => {
            // --- 1. DOM Element References ---
            const bpmSlider = document.getElementById('bpm-slider');
            const bpmValue = document.getElementById('bpm-value');
            const startBtn = document.getElementById('start-btn');
            const stopBtn = document.getElementById('stop-btn');
            const metronomeIndicator = document.getElementById('metronome-indicator');
            const tapButton = document.getElementById('tap-button');
            const statusMessage = document.getElementById('status-message');
            const scoreDisplay = document.getElementById('score-display');

            // --- 2. State Management ---
            let state = {
                bpm: 120,
                isPlaying: false,
                phase: 'idle', // 'idle', 'listening', 'playing', 'finished'
                beatInterval: 0,
                nextBeatTime: 0,
                timerId: null,
                userTaps: [],
                standardBeats: [],
                beatCount: 0,
                totalBeats: 8 // Number of beats for listening and playing phases
            };

            // --- 3. Web Audio API Setup for Low-Latency Sound ---
            let audioContext;
            try {
                audioContext = new (window.AudioContext || window.webkitAudioContext)();
            } catch (e) {
                console.error("Web Audio API is not supported in this browser.");
                alert("This application requires a modern browser with Web Audio API support.");
            }

            function playSound(time) {
                if (!audioContext) return;
                const oscillator = audioContext.createOscillator();
                const gainNode = audioContext.createGain();

                oscillator.connect(gainNode);
                gainNode.connect(audioContext.destination);

                oscillator.type = 'sine';
                oscillator.frequency.setValueAtTime(880, time); // A5 note
                gainNode.gain.setValueAtTime(0.5, time);

                gainNode.gain.exponentialRampToValueAtTime(0.001, time + 0.1);
                oscillator.start(time);
                oscillator.stop(time + 0.1);
            }

            // --- 4. Core Application Logic ---

            function updateBPM() {
                state.bpm = parseInt(bpmSlider.value, 10);
                bpmValue.textContent = `${state.bpm} BPM`;
                state.beatInterval = 60000 / state.bpm; // in milliseconds
            }

            function visualBeat() {
                metronomeIndicator.classList.add('beat-flash');
                setTimeout(() => {
                    metronomeIndicator.classList.remove('beat-flash');
                }, 100);
            }

            function scheduleBeat() {
                if (!state.isPlaying) return;

                const currentTime = audioContext.currentTime;
                const lookahead = 0.1; // seconds

                while (state.nextBeatTime < currentTime + lookahead) {
                    playSound(state.nextBeatTime);

                    // We need to schedule the visual flash slightly ahead of the audio
                    // to account for human perception and screen latency.
                    const visualTime = (state.nextBeatTime - currentTime) * 1000;
                    setTimeout(visualBeat, visualTime);

                    if (state.phase === 'playing') {
                        state.standardBeats.push(state.nextBeatTime * 1000); // Store in ms
                    }

                    state.beatCount++;
                    state.nextBeatTime += (60 / state.bpm);

                    // Phase transition logic
                    if (state.beatCount > state.totalBeats) {
                        if (state.phase === 'listening') {
                            startPlayingPhase();
                            return;
                        } else if (state.phase === 'playing') {
                            finishSession();
                            return;
                        }
                    }
                }
                state.timerId = setTimeout(scheduleBeat, 25); // Check every 25ms
            }

            function startTraining() {
                if (state.isPlaying) return;

                // Reset state for a new session
                state.isPlaying = true;
                state.userTaps = [];
                state.standardBeats = [];
                scoreDisplay.innerHTML = '';

                // UI updates
                startBtn.disabled = true;
                stopBtn.disabled = false;
                bpmSlider.disabled = true;
                tapButton.disabled = true;

                startListeningPhase();
            }

            function startListeningPhase() {
                state.phase = 'listening';
                state.beatCount = 0;
                statusMessage.textContent = `Listen for ${state.totalBeats} beats...`;

                if (audioContext.state === 'suspended') {
                    audioContext.resume();
                }
                state.nextBeatTime = audioContext.currentTime + 0.1;
                scheduleBeat();
            }

            function startPlayingPhase() {
                state.phase = 'playing';
                state.beatCount = 0;
                statusMessage.textContent = `Your turn! Tap ${state.totalBeats} beats...`;
                tapButton.disabled = false;

                // The scheduler continues from the listening phase for seamless transition
            }

            function stopTraining() {
                if (!state.isPlaying) return;

                state.isPlaying = false;
                clearTimeout(state.timerId);
                state.phase = 'idle';

                // UI reset
                startBtn.disabled = false;
                stopBtn.disabled = true;
                bpmSlider.disabled = false;
                tapButton.disabled = true;
                statusMessage.textContent = 'Training stopped. Click Start to try again.';
            }

            function handleTap() {
                if (state.phase !== 'playing' || !state.isPlaying) return;
                state.userTaps.push(performance.now());

                // Visual feedback for the tap
                tapButton.style.transform = 'scale(0.95)';
                setTimeout(() => {
                    tapButton.style.transform = 'scale(1)';
                }, 100);
            }

            function finishSession() {
                state.phase = 'finished';
                stopTraining(); // Stops timers and resets basic state
                statusMessage.textContent = 'Finished! Calculating score...';
                calculateScore();
            }

            function calculateScore() {
                const tolerance = state.beatInterval / 2; // Max allowed deviation in ms
                let totalAccuracy = 0;
                let hits = 0;
                let resultsHtml = '<h4>Beat Analysis:</h4><ul>';

                // Use performance.now() as the reference start time for comparison
                const startTime = state.standardBeats[0] - state.beatInterval;

                state.standardBeats.forEach((beatTime, index) => {
                    const relativeBeatTime = beatTime - startTime;

                    // Find the user's tap closest to this standard beat
                    let closestTapDiff = Infinity;
                    let closestTap = null;

                    state.userTaps.forEach(tapTime => {
                        const diff = Math.abs((tapTime - startTime) - relativeBeatTime);
                        if (diff < closestTapDiff) {
                            closestTapDiff = diff;
                            closestTap = tapTime;
                        }
                    });

                    // Remove the matched tap so it can't be used again
                    if (closestTap) {
                        state.userTaps.splice(state.userTaps.indexOf(closestTap), 1);
                    }

                    let accuracy = 0;
                    let deviationText = '';

                    if (closestTapDiff <= tolerance) {
                        hits++;
                        // Score is 100 for perfect, decreasing to 0 at the tolerance edge
                        accuracy = 100 * (1 - (closestTapDiff / tolerance));
                        totalAccuracy += accuracy;

                        const deviation = ((closestTap - startTime) - relativeBeatTime).toFixed(1);
                        deviationText = deviation > 0 ? `+${deviation}ms (late)` : `${deviation}ms (early)`;
                        resultsHtml += `<li style="color: var(--green);">Beat ${index + 1}: Hit! Accuracy: ${accuracy.toFixed(1)}% (${deviationText})</li>`;
                    } else {
                        resultsHtml += `<li style="color: var(--red);">Beat ${index + 1}: Miss!</li>`;
                    }
                });

                resultsHtml += '</ul>';
                const finalScore = hits > 0 ? (totalAccuracy / state.totalBeats) : 0;

                statusMessage.textContent = `Final Score: ${finalScore.toFixed(1)}%`;
                scoreDisplay.innerHTML = `
                    <p>You hit <strong>${hits}</strong> out of <strong>${state.totalBeats}</strong> beats.</p>
                    ${resultsHtml}
                `;
            }

            // --- 5. Event Listeners ---
            bpmSlider.addEventListener('input', updateBPM);
            startBtn.addEventListener('click', startTraining);
            stopBtn.addEventListener('click', stopTraining);
            tapButton.addEventListener('click', handleTap);

            // Initialize
            updateBPM();
        });
    </script>

</body>
