            (Math.random() - 0.5) * 0.2
        );
        fragment.lifespan = 100 + Math.random() * 50; // Frames to live
        asteroidFragments.push(fragment);
        scene.add(fragment);
    }
}

// BACKGROUND (STARS)
const starVertices = [];
for (let i = 0; i < 10000; i++) {
    const x = (Math.random() - 0.5) * 2000;
    const y = (Math.random() - 0.5) * 2000;
    const z = (Math.random() - 0.5) * 2000;
    starVertices.push(x, y, z);
}
const starGeometry = new THREE.BufferGeometry();
starGeometry.setAttribute('position', new THREE.Float32BufferAttribute(starVertices, 3));
const starMaterial = new THREE.PointsMaterial({ color: 0xffffff, size: 0.7 });
const stars = new THREE.Points(starGeometry, starMaterial);
scene.add(stars);

// Set initial camera position
camera.position.set(0, 10, 15);
camera.lookAt(shipGroup.position);

// Spawn initial asteroids
for (let i = 0; i < 10; i++) {
    createAsteroid();
}
setInterval(createAsteroid, 3000); // Spawn a new asteroid every 3 seconds

// ANIMATION LOOP
function animate(time) {
    if (isGameOver) return;

    requestAnimationFrame(animate);

    // DYNAMIC LIGHTING UPDATE
    const hue = (time / 10000) % 1; // Cycle hue every 10 seconds
    directionalLight.color.setHSL(hue, 0.6, 0.5);

    // PLAYER MOVEMENT LOGIC
    playerVelocity.set(0, 0, 0);
    if (keys['w']) playerVelocity.z -= 1;
    if (keys['s']) playerVelocity.z += 1;
    if (keys['a']) playerVelocity.x -= 1;
    if (keys['d']) playerVelocity.x += 1;

    playerVelocity.normalize().multiplyScalar(playerSpeed);
    shipGroup.position.add(playerVelocity);

    // Keep player within bounds
    const playArea = 40;
    shipGroup.position.x = Math.max(-playArea, Math.min(playArea, shipGroup.position.x));
    shipGroup.position.z = Math.max(-playArea, Math.min(playArea, shipGroup.position.z));

    // PLAYER AIMING LOGIC
    raycaster.setFromCamera(mouse, camera);
    raycaster.ray.intersectPlane(aimPlane, aimPoint);
    shipGroup.lookAt(aimPoint.x, shipGroup.position.y, aimPoint.z);

    // CAMERA FOLLOW LOGIC
    const cameraOffset = new THREE.Vector3(0, 8, 12);
    const desiredCameraPosition = shipGroup.position.clone().add(cameraOffset);
    camera.position.lerp(desiredCameraPosition, 0.05);
    camera.lookAt(shipGroup.position);

    // PROJECTILE UPDATE
    for (let i = projectiles.length - 1; i >= 0; i--) {
        const p = projectiles[i];
        p.position.add(p.velocity);
        if (p.position.length() > 100) { // Remove if too far
            scene.remove(p);
            projectiles.splice(i, 1);
        }
    }

    // ASTEROID UPDATE
    for (let i = asteroids.length - 1; i >= 0; i--) {
        const a = asteroids[i];
        a.position.add(a.velocity);
        a.rotation.x += 0.005;
        a.rotation.y += 0.005;
        if (a.position.length() > 100) { // Remove if too far
            scene.remove(a);
            asteroids.splice(i, 1);
        }
    }

    // FRAGMENT UPDATE
    for (let i = asteroidFragments.length - 1; i >= 0; i--) {
        const f = asteroidFragments[i];
        f.position.add(f.velocity);
        f.lifespan--;
        if (f.lifespan <= 0) {
            scene.remove(f);
            asteroidFragments.splice(i, 1);
        }
    }

    // COLLISION DETECTION
    const playerBox = new THREE.Box3().setFromObject(shipGroup);

    // Asteroids vs Player
    for (let i = asteroids.length - 1; i >= 0; i--) {
        const asteroid = asteroids[i];
        const asteroidBox = new THREE.Box3().setFromObject(asteroid);
        if (playerBox.intersectsBox(asteroidBox)) {
            shield -= 25;
            shieldEl.textContent = Math.max(0, shield);

            // Trigger shield impact effect
            shieldImpactMaterial.opacity = 1;

            // Asteroid is destroyed on impact with player
            createFragments(asteroid.position, 15, 0x888888);
            scene.remove(asteroid);
            asteroids.splice(i, 1);

            if (shield <= 0) {
                endGame();
            }
            break; // Only one collision per frame
        }
    }

    // Projectiles vs Asteroids
    for (let i = projectiles.length - 1; i >= 0; i--) {
        const projectile = projectiles[i];
        const projectileBox = new THREE.Box3().setFromObject(projectile);

        for (let j = asteroids.length - 1; j >= 0; j--) {
            const asteroid = asteroids[j];
            const asteroidBox = new THREE.Box3().setFromObject(asteroid);

            if (projectileBox.intersectsBox(asteroidBox)) {
                // On hit, remove both and create fragments
                createFragments(asteroid.position, 10, 0x888888);
                scene.remove(projectile);
                projectiles.splice(i, 1);
                scene.remove(asteroid);
                asteroids.splice(j, 1);

                // Update score
                score += 100;
                scoreEl.textContent = score;
                break; // Projectile can only hit one asteroid
            }
        }
    }

    // SHIELD EFFECT UPDATE
    if (shieldImpactMaterial.opacity > 0) {
        shieldImpactMaterial.opacity -= 0.02;
        shieldImpactMesh.scale.setScalar(1 + (1 - shieldImpactMaterial.opacity) * 2);
    }

    renderer.render(scene, camera);
}

function endGame() {
    isGameOver = true;
    gameOverEl.style.display = 'block';
    // Create a large explosion for the player ship
    createFragments(shipGroup.position, 30, 0x0077ff);
    scene.remove(shipGroup);
}

// Handle window resizing
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start the game
animate(0);
```

Of course. As a code expert, I will provide a comprehensive solution for a client-side task scheduler. This solution will be robust, well-documented, and encapsulated within a class for easy management and extension.

### Professional Task Scheduler Solution

This solution is composed of three main parts:
1.  **The `TaskScheduler` Class:** A self-contained class that manages the lifecycle of tasks—adding, removing, and checking them on a regular interval.
2.  **Schedule Helper Functions:** Utility functions to make defining common schedules (like daily or hourly) more intuitive.
3.  **A Complete HTML/JavaScript Example:** A working demonstration that you can run directly in your browser.

---

### Core Concepts and Architecture

*   **Encapsulation:** All scheduling logic is contained within the `TaskScheduler` class. This makes the code clean, reusable, and easy to maintain.
*   **Task Object:** Each task is represented by a JavaScript object with a defined structure, including its schedule, notification details, and the action to perform.
*   **Central Timer:** A single `setInterval` loop runs every second to check all scheduled tasks. This is efficient and avoids the overhead of creating a separate timer for each task.
*   **Flexible Scheduling:** The `schedule` property of a task is a function that returns `true` when the task is due. This provides maximum flexibility, allowing for any conceivable schedule logic (e.g., "every Tuesday at 4 PM," "on the last day of the month," etc.).
*   **System Notifications:** We will use the browser's native [Notification API](https://developer.mozilla.org/en-US/docs/Web/API/notification), which requires user permission.
*   **Safe Code Execution:** Custom JavaScript actions are passed as functions, avoiding the security risks and performance issues associated with `eval()`.

---

### The Code

Here is the complete, executable code. You can save this as a single `scheduler.html` file and open it in your browser.

```html
