    </style>
</head>
<body>

    <div class="container">
        <h1>Professional Task Scheduler</h1>
        <p>This scheduler runs in the browser and can trigger system notifications and execute custom JavaScript code.</p>

        <div class="controls">
            <button id="startButton">Start Scheduler</button>
            <button id="stopButton" disabled>Stop Scheduler</button>
        </div>

        <h2>Execution Log</h2>
        <div id="log-container"></div>
    </div>

    <script>
    /**
     * A robust client-side task scheduler.
     */
    class TaskScheduler {
        /**
         * Initializes the scheduler.
         */
        constructor() {
            this.tasks = [];
            this.timerId = null;
            this.logElement = document.getElementById('log-container');
        }

        /**
         * Adds a new task to the scheduler.
         * @param {object} task - The task object.
         * @param {string} task.id - A unique identifier for the task.
         * @param {function(Date): boolean} task.schedule - A function that returns true if the task should run.
         * @param {object} task.notification - Details for the system notification.
         * @param {string} task.notification.title - The title of the notification.
         * @param {string} task.notification.body - The body text of the notification.
         * @param {function(): void} task.action - The JavaScript function to execute.
         */
        addTask(task) {
            // Add a property to track the last run time to prevent multiple executions in the same second.
            const newTask = { ...task, lastRun: null };
            this.tasks.push(newTask);
            this._log(`Task added: "${task.id}"`);
        }

        /**
         * Removes a task by its ID.
         * @param {string} taskId - The ID of the task to remove.
         */
        removeTask(taskId) {
            this.tasks = this.tasks.filter(task => task.id !== taskId);
            this._log(`Task removed: "${taskId}"`);
        }

        /**
         * Starts the scheduler's main loop.
         * Requests notification permission before starting.
         */
        async start() {
            if (this.timerId) {
                this._log("Scheduler is already running.");
                return;
            }

            // 1. Request permission for notifications
            if (Notification.permission !== 'granted') {
                this._log("Requesting notification permission...");
                const permission = await Notification.requestPermission();
                if (permission !== 'granted') {
                    this._log("Notification permission denied. Notifications will not be shown.");
                } else {
                    this._log("Notification permission granted.");
                }
            }

            // 2. Start the timer
            this._log("Scheduler started. Checking tasks every second.");
            this.timerId = setInterval(() => this._tick(), 1000);
        }

        /**
         * Stops the scheduler's main loop.
         */
        stop() {
            if (!this.timerId) {
                this._log("Scheduler is not running.");
                return;
            }
            clearInterval(this.timerId);
            this.timerId = null;
            this._log("Scheduler stopped.");
        }

        /**
         * The main tick function, called every second.
         * @private
         */
        _tick() {
            const now = new Date();
            const currentMinute = now.getMinutes();

            for (const task of this.tasks) {
                // Prevent re-running a task within the same minute.
                // This is useful for tasks scheduled for a specific minute (e.g., daily at 9:00).
                if (task.lastRun && task.lastRun.getMinutes() === currentMinute && task.lastRun.getHours() === now.getHours()) {
                    continue;
                }

                if (task.schedule(now)) {
                    task.lastRun = now; // Mark as run for this minute
                    this._triggerTask(task);
                }
            }
        }

        /**
         * Executes a task's notification and action.
         * @param {object} task - The task to trigger.
         * @private
         */
        _triggerTask(task) {
            this._log(`Triggering task: "${task.id}"`);

            // 1. Show notification
            if (Notification.permission === 'granted' && task.notification) {
                new Notification(task.notification.title, {
                    body: task.notification.body,
                    icon: 'https://via.placeholder.com/128' // Optional icon
                });
            }

            // 2. Execute action
            if (task.action && typeof task.action === 'function') {
                try {
                    task.action();
                } catch (error) {
                    console.error(`Error executing action for task "${task.id}":`, error);
                    this._log(`Error in task "${task.id}": ${error.message}`);
                }
            }
        }

        /**
         * Logs a message to the on-page console.
         * @param {string} message - The message to log.
         * @private
         */
        _log(message) {
            if (!this.logElement) return;
            const timestamp = new Date().toLocaleTimeString();
            const entry = document.createElement('div');
            entry.className = 'log-entry';
            entry.innerHTML = `<span class="log-time">[${timestamp}]</span> ${message}`;
            this.logElement.appendChild(entry);
            this.logElement.scrollTop = this.logElement.scrollHeight; // Auto-scroll
        }
    }

    // --- Schedule Helper Functions ---

    /**
     * Creates a schedule function that triggers daily at a specific time.
     * @param {number} hour - The hour (0-23).
     * @param {number} minute - The minute (0-59).
     * @returns {function(Date): boolean}
     */
    const dailyAt = (hour, minute) => (now) => {
        return now.getHours() === hour && now.getMinutes() === minute;
    };

    /**
     * Creates a schedule function that triggers hourly at a specific minute.
     * @param {number} minute - The minute (0-59).
     * @returns {function(Date): boolean}
     */
    const hourlyAt = (minute) => (now) => {
        return now.getMinutes() === minute;
    };

    /**
     * Creates a schedule function that triggers every N seconds.
     * @param {number} seconds - The interval in seconds.
     * @returns {function(Date): boolean}
     */
    const everyNSeconds = (n) => (now) => {
        return now.getSeconds() % n === 0;
    };


    // --- Main Application Logic ---

    document.addEventListener('DOMContentLoaded', () => {
        const scheduler = new TaskScheduler();
        const startButton = document.getElementById('startButton');
        const stopButton = document.getElementById('stopButton');

        // --- Define Tasks ---

        // Task 1: Hourly time announcement at the top of the hour.
        scheduler.addTask({
            id: 'hourly-time-announcement',
            schedule: hourlyAt(0), // Runs at XX:00
            notification: {
                title: 'Time Check!',
                body: `The time is now ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}.`
            },
            action: () => {
                console.log('Hourly task executed.');
                // You could add more complex logic here, like fetching data.
            }
        });

        // Task 2: Daily reminder at 9:00 AM.
        scheduler.addTask({
            id: 'daily-morning-reminder',
            schedule: dailyAt(9, 0),
            notification: {
                title: 'Good Morning!',
                body: 'Time for your daily stand-up meeting.'
            },
            action: () => {
                alert('This is your 9:00 AM daily reminder!');
            }
        });

        // Task 3: A frequent task that reloads the page (for demonstration).
        // Note: This is disruptive. It's set to run every 90 seconds.
        scheduler.addTask({
            id: 'periodic-page-reload',
            schedule: everyNSeconds(90),
            notification: {
                title: 'Scheduled Reload',
                body: 'The page will reload in 3 seconds as scheduled.'
            },
            action: () => {
                // Use a timeout to allow the user to see the notification before reload.
                setTimeout(() => {
                    location.reload();
                }, 3000);
            }
        });

        // --- Control Logic ---
        startButton.addEventListener('click', async () => {
            await scheduler.start();
            startButton.disabled = true;
            stopButton.disabled = false;
        });

        stopButton.addEventListener('click', () => {
            scheduler.stop();
            startButton.disabled = false;
            stopButton.disabled = true;
        });
    });

    </script>
</body>
</html>
```

### How to Use and Extend

1.  **Save and Run:** Save the code above as an HTML file (e.g., `scheduler.html`) and open it in a modern web browser like Chrome, Firefox, or Edge.
2.  **Start the Scheduler:** Click the "Start Scheduler" button. Your browser will prompt you for permission to show notifications. You must **Allow** this for the notifications to work.
3.  **Observe:** The log will show the scheduler starting and tasks being added. When a task's scheduled time arrives, you will see it trigger in the log, receive a system notification, and its custom action will execute.

#### Extending the Scheduler

*   **Adding New Tasks:** To add your own tasks, simply call `scheduler.addTask()` with a new task object inside the `DOMContentLoaded` event listener.
*   **Creating Custom Schedules:** The power of this system is the `schedule` function. You can write any logic you need. For example, to create a task that runs every Monday at noon:
    ```javascript
    const mondayAtNoon = (now) => {
        // getDay() returns 1 for Monday
        return now.getDay() === 1 && now.getHours() === 12 && now.getMinutes() === 0;
    };

    scheduler.addTask({
        id: 'monday-meeting-reminder',
        schedule: mondayAtNoon,
        notification: { title: 'Meeting Reminder', body: 'Weekly sync meeting starts now.' },
        action: () => console.log('Monday meeting time!')
    });
    ```

### Important Professional Considerations

*   **Browser Tab Lifecycle:** JavaScript `setInterval` can be throttled or paused by browsers when a tab is inactive or in the background to save resources. For critical tasks, a [Web Worker](https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API) would be a more reliable solution as it runs in a separate background thread.
*   **Persistence:** This scheduler is in-memory. If the user closes the tab or browser, all state is lost. To make tasks persist, you would need to store the task definitions in `localStorage` and re-initialize the scheduler when the page loads.
*   **Time Zones:** All `new Date()` operations are based on the user's local system time. If you are building an application that needs to coordinate actions across different time zones, all time calculations should be done in UTC.
*   **User Experience:** Always request notification permissions in response to a clear user action (like clicking a "Start" or "Enable Notifications" button). Do not request it automatically on page load, as this is considered poor practice and may be blocked by browsers.

