### `script.js`

This is the core of the application, containing the logic for the geometric objects, the proof engine, canvas drawing, and UI interactions.

```javascript
document.addEventListener('DOMContentLoaded', () => {
    // --- MODEL: Data Structures ---

    // Represents a point in 2D space
    class Point {
        constructor(x, y, label) {
            this.x = x;
            this.y = y;
            this.label = label;
        }
    }

    // Represents a line segment defined by two points
    class Line {
        constructor(p1, p2) {
            this.p1 = p1;
            this.p2 = p2;
            this.label = p1.label + p2.label;
        }
    }

    // Represents an angle defined by three points (vertex is the middle point)
    class Angle {
        constructor(p1, vertex, p3) {
            this.p1 = p1;
            this.vertex = vertex;
            this.p3 = p3;
            this.label = `∠${p1.label}${vertex.label}${p3.label}`;
        }
    }

    // Represents a triangle defined by three points
    class Triangle {
        constructor(p1, p2, p3) {
            this.points = [p1, p2, p3].sort((a, b) => a.label.localeCompare(b.label));
            this.label = `△${this.points.map(p => p.label).join('')}`;
            this.sides = [
                new Line(this.points[0], this.points[1]),
                new Line(this.points[1], this.points[2]),
                new Line(this.points[0], this.points[2])
            ];
            this.angles = [
                new Angle(this.points[1], this.points[0], this.points[2]),
                new Angle(this.points[0], this.points[1], this.points[2]),
                new Angle(this.points[0], this.points[2], this.points[1])
            ];
        }
    }

    // Represents a single fact in the proof
    class Fact {
        constructor(type, objects, reason, premises = []) {
            this.type = type; // e.g., 'EQUALS_LENGTH', 'CONGRUENT_TRIANGLES'
            this.objects = objects; // array of geometric objects
            this.reason = reason; // e.g., 'Given', 'SSS Congruence'
            this.premises = premises; // array of fact indices this fact is derived from
            this.id = this.generateId();
            this.statement = this.generateStatement();
        }

        // Generates a unique ID for the fact to avoid duplicates
        generateId() {
            const objectLabels = this.objects.map(o => o.label).sort().join(',');
            return `${this.type}:${objectLabels}`;
        }

        // Generates a human-readable statement for the fact
        generateStatement() {
            const labels = this.objects.map(o => o.label);
            switch (this.type) {
                case 'EQUALS_LENGTH': return `${labels[0]} ≅ ${labels[1]}`;
                case 'EQUALS_ANGLES': return `${labels[0]} ≅ ${labels[1]}`;
                case 'MIDPOINT': return `${labels[0].label} is the midpoint of ${labels[1].label}`;
                case 'CONGRUENT_TRIANGLES': return `${labels[0]} ≅ ${labels[1]}`;
                default: return 'Unknown Fact';
            }
        }
    }

    // --- GLOBAL STATE ---
    let canvas, ctx;
    let points = [], lines = [], triangles = [], angles = [];
    let givens = [], proof = [], goal = null;
    const knownFacts = new Map(); // Using a Map to store facts by ID for quick lookup

    // --- PROOF ENGINE ---

    // Defines the geometric theorems and postulates as rules
    const THEOREMS = [
        { name: "Reflexive Property", apply: applyReflexiveProperty },
        { name: "Definition of Midpoint", apply: applyDefinitionOfMidpoint },
        { name: "Side-Side-Side (SSS) Congruence", apply: applySSSCongruence },
        { name: "Corresponding Parts of Congruent Triangles are Congruent (CPCTC)", apply: applyCPCTC }
    ];

    function applyReflexiveProperty(currentFacts, allObjects) {
        const newFacts = [];
        allObjects.lines.forEach(line => {
            const fact = new Fact('EQUALS_LENGTH', [line, line], 'Reflexive Property');
            if (!currentFacts.has(fact.id)) {
                newFacts.push(fact);
            }
        });
        return newFacts;
    }

    function applyDefinitionOfMidpoint(currentFacts) {
        const newFacts = [];
        currentFacts.forEach((fact, id) => {
            if (fact.type === 'MIDPOINT') {
                const [midpoint, line] = fact.objects;
                const segment1 = new Line(line.p1, midpoint);
                const segment2 = new Line(midpoint, line.p2);
                const newFact = new Fact('EQUALS_LENGTH', [segment1, segment2], 'Definition of Midpoint', [id]);
                if (!currentFacts.has(newFact.id)) {
                    newFacts.push(newFact);
                }
            }
        });
        return newFacts;
    }

    function applySSSCongruence(currentFacts, allObjects) {
        const newFacts = [];
        const lengthFacts = new Map();
        currentFacts.forEach(fact => {
            if (fact.type === 'EQUALS_LENGTH') {
                const key = fact.objects.map(o => o.label).sort().join('-');
                lengthFacts.set(key, fact.id);
            }
        });

        for (let i = 0; i < allObjects.triangles.length; i++) {
            for (let j = i + 1; j < allObjects.triangles.length; j++) {
                const t1 = allObjects.triangles[i];
                const t2 = allObjects.triangles[j];

                const premises = [];
                let matchCount = 0;

                for (const s1 of t1.sides) {
                    for (const s2 of t2.sides) {
                        const key = [s1.label, s2.label].sort().join('-');
                        if (lengthFacts.has(key)) {
                            premises.push(lengthFacts.get(key));
                            matchCount++;
                            break; 
                        }
                    }
                }

                if (matchCount === 3) {
                    const fact = new Fact('CONGRUENT_TRIANGLES', [t1, t2], 'SSS Congruence', premises);
                    if (!currentFacts.has(fact.id)) {
                        newFacts.push(fact);
                    }
                }
            }
        }
        return newFacts;
    }

    function applyCPCTC(currentFacts) {
        const newFacts = [];
        currentFacts.forEach((fact, id) => {
            if (fact.type === 'CONGRUENT_TRIANGLES') {
                const [t1, t2] = fact.objects;
                // Match corresponding sides and angles
                for (let i = 0; i < 3; i++) {
                    // This is a simplified correspondence mapping. A real system would need a more robust way.
                    // For this demo, we assume points are ordered A,B,C and D,E,F for correspondence.
                    // Our triangle constructor sorts points, so we rely on that consistent ordering.
                    const side1 = t1.sides[i];
                    const side2 = t2.sides[i];
                    const angle1 = t1.angles[i];
                    const angle2 = t2.angles[i];

                    const lengthFact = new Fact('EQUALS_LENGTH', [side1, side2], 'CPCTC', [id]);
                    if (!currentFacts.has(lengthFact.id)) newFacts.push(lengthFact);

                    const angleFact = new Fact('EQUALS_ANGLES', [angle1, angle2], 'CPCTC', [id]);
                    if (!currentFacts.has(angleFact.id)) newFacts.push(angleFact);
                }
            }
        });
        return newFacts;
    }


    // Main proof generation function
    function generateProof() {
        proof = [];
        knownFacts.clear();

        // 1. Add all givens to the known facts
        givens.forEach(given => {
            knownFacts.set(given.id, given);
            proof.push(given);
        });

        // 2. Iteratively apply theorems until no new facts can be derived
        let newFactsFound = true;
        while (newFactsFound) {
            newFactsFound = false;
            const allObjects = { points, lines, triangles, angles };

            THEOREMS.forEach(theorem => {
                const derivedFacts = theorem.apply(knownFacts, allObjects);
                derivedFacts.forEach(fact => {
                    if (!knownFacts.has(fact.id)) {
                        knownFacts.set(fact.id, fact);
                        proof.push(fact);
                        newFactsFound = true;
                    }
                });
            });
        }
        renderProofTree();
    }

    // --- VIEW: Canvas & UI Rendering ---

    function drawCanvas() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.strokeStyle = '#333';
        ctx.fillStyle = '#333';
        ctx.lineWidth = 2;
        ctx.font = '16px Arial';

        // Draw lines
        lines.forEach(line => {
            ctx.beginPath();
            ctx.moveTo(line.p1.x, line.p1.y);
            ctx.lineTo(line.p2.x, line.p2.y);
            ctx.stroke();
        });

        // Draw points and labels
        points.forEach(point => {
            ctx.beginPath();
            ctx.arc(point.x, point.y, 5, 0, 2 * Math.PI);
            ctx.fill();
            ctx.fillText(point.label, point.x + 10, point.y - 10);
        });
    }

    function renderProofTree() {
        const proofTreeEl = document.getElementById('proofTree');
        proofTreeEl.innerHTML = '';
        if (proof.length === 0) {
            proofTreeEl.innerHTML = '<li>No proof generated yet.</li>';
            return;
        }
        proof.forEach((fact, index) => {
            const li = document.createElement('li');
            li.innerHTML = `<strong>Step ${index + 1}:</strong> ${fact.statement} <em>(${fact.reason})</em>`;
            li.dataset.index = index;
            li.addEventListener('click', () => showDetails(index));
            proofTreeEl.appendChild(li);
        });
    }

    function renderGivensAndGoal() {
        const givenListEl = document.getElementById('givenList');
        givenListEl.innerHTML = '';
        givens.forEach(g => {
            const li = document.createElement('li');
            li.textContent = g.statement;
            givenListEl.appendChild(li);
        });

        const goalStatementEl = document.getElementById('goalStatement');
        goalStatementEl.textContent = goal ? goal.statement : 'None';
    }

    function updateDropdowns(containerId, type) {
        const container = document.getElementById(containerId);
        container.innerHTML = '';
        const createSelect = (options) => {
            const select = document.createElement('select');
            options.forEach(opt => {
                const option = document.createElement('option');
                option.value = opt.label;
                option.textContent = opt.label;
                select.appendChild(option);
            });
            return select;
        };

        switch (type) {
            case 'EQUALS_LENGTH':
                container.appendChild(createSelect(lines));
                container.appendChild(createSelect(lines));
                break;
            case 'EQUALS_ANGLES':
                container.appendChild(createSelect(angles));
                container.appendChild(createSelect(angles));
                break;
            case 'MIDPOINT':
                container.appendChild(createSelect(points));
                container.appendChild(createSelect(lines));
                break;
            case 'CONGRUENT_TRIANGLES':
                container.appendChild(createSelect(triangles));
                container.appendChild(createSelect(triangles));
                break;
        }
    }

    function showDetails(index) {
        const fact = proof[index];
        if (!fact) return;

        document.getElementById('modalStatement').textContent = fact.statement;
        document.getElementById('modalReason').textContent = fact.reason;

        const premisesList = document.getElementById('modalPremises');
        premisesList.innerHTML = '';
        if (fact.premises.length > 0) {
            fact.premises.forEach(premiseId => {
                const premiseFact = knownFacts.get(premiseId);
                if (premiseFact) {
                    const li = document.createElement('li');
                    const stepIndex = proof.findIndex(p => p.id === premiseId);
                    li.textContent = `Step ${stepIndex + 1}: ${premiseFact.statement}`;
                    premisesList.appendChild(li);
                }
            });
        } else {
            premisesList.innerHTML = '<li>This is a given or a fundamental property.</li>';
        }

        document.getElementById('detailsModal').style.display = 'block';
    }

    // --- CONTROLLER: Event Handlers & Initialization ---

    function setupInitialScenario() {
        // Create a classic isosceles triangle scenario
        const A = new Point(250, 50, 'A');
        const B = new Point(100, 300, 'B');
        const C = new Point(400, 300, 'C');
        const D = new Point(250, 300, 'D');

        points.push(A, B, C, D);

        const AB = new Line(A, B);
        const AC = new Line(A, C);
        const BC = new Line(B, C);
        const AD = new Line(A, D);
        const BD = new Line(B, D);
        const CD = new Line(C, D);

        // Note: The line from B to C is composed of BD and DC
        lines.push(AB, AC, AD, BC, BD, CD);

        const triABD = new Triangle(A, B, D);
        const triACD = new Triangle(A, C, D);
        triangles.push(triABD, triACD);

        angles.push(...triABD.angles, ...triACD.angles);

        drawCanvas();
        updateDropdowns('givenInputs', document.getElementById('givenType').value);
        updateDropdowns('goalInputs', document.getElementById('goalType').value);
    }

    function findObjectByLabel(label, type) {
        const collection = {
            'Point': points, 'Line': lines, 'Triangle': triangles, 'Angle': angles
        }[type] || [...points, ...lines, ...triangles, ...angles];
        return collection.find(o => o.label === label);
    }

    function handleAddGiven() {
        const type = document.getElementById('givenType').value;
        const inputs = document.getElementById('givenInputs').querySelectorAll('select');
        const selectedLabels = Array.from(inputs).map(s => s.value);

        let objects = [];
        if (type === 'MIDPOINT') {
            objects = [findObjectByLabel(selectedLabels[0]), findObjectByLabel(selectedLabels[1])];
        } else {
            objects = selectedLabels.map(label => findObjectByLabel(label));
        }

        const newGiven = new Fact(type, objects, 'Given');
        if (!givens.some(g => g.id === newGiven.id)) {
            givens.push(newGiven);
        }
        renderGivensAndGoal();
    }

    function handleSetGoal() {
        const type = document.getElementById('goalType').value;
        const inputs = document.getElementById('goalInputs').querySelectorAll('select');
        const selectedLabels = Array.from(inputs).map(s => s.value);
        const objects = selectedLabels.map(label => findObjectByLabel(label));

        goal = new Fact(type, objects, 'Goal');
        renderGivensAndGoal();
    }

    function handleVerify() {
        const resultEl = document.getElementById('verificationResult');
        if (!goal) {
            resultEl.textContent = 'Verification failed: No goal has been set.';
            resultEl.style.color = '#e74c3c';
            return;
        }
        if (proof.length === 0) {
            resultEl.textContent = 'Verification failed: Proof has not been generated.';
            resultEl.style.color = '#e74c3c';
            return;
        }

        const goalIsProven = knownFacts.has(goal.id);

        if (goalIsProven) {
            resultEl.textContent = 'Success! The goal has been proven.';
            resultEl.style.color = '#2ecc71';
        } else {
            resultEl.textContent = 'Incomplete. The goal could not be proven with the current givens and theorems.';
            resultEl.style.color = '#f39c12';
        }
    }

    function init() {
        canvas = document.getElementById('geometryCanvas');
        ctx = canvas.getContext('2d');

        setupInitialScenario();

        // Event Listeners
        document.getElementById('addGivenBtn').addEventListener('click', handleAddGiven);
        document.getElementById('setGoalBtn').addEventListener('click', handleSetGoal);
        document.getElementById('generateProofBtn').addEventListener('click', generateProof);
        document.getElementById('verifyBtn').addEventListener('click', handleVerify);

        document.getElementById('givenType').addEventListener('change', (e) => updateDropdowns('givenInputs', e.target.value));
        document.getElementById('goalType').addEventListener('change', (e) => updateDropdowns('goalInputs', e.target.value));

        // Modal listeners
        const modal = document.getElementById('detailsModal');
        const closeBtn = document.querySelector('.close-btn');
        closeBtn.onclick = () => { modal.style.display = 'none'; };
        window.onclick = (event) => {
            if (event.target == modal) {
                modal.style.display = 'none';
            }
        };
    }

    init();
});
