        map: colorTexture,
        displacementMap: heightmapTexture,
        displacementScale: TERRAIN_MAX_HEIGHT,
        metalness: 0.2,
        roughness: 0.8,
    });

    terrainMesh = new THREE.Mesh(geometry, material);
    terrainMesh.rotation.x = -Math.PI / 2;
    terrainMesh.receiveShadow = true;
    scene.add(terrainMesh);
}

function updateHeightmapTexture() {
    const ctx = heightmapCanvas.getContext('2d');
    const imageData = ctx.createImageData(TERRAIN_SIZE, TERRAIN_SIZE);
    for (let i = 0; i < TERRAIN_SIZE; i++) {
        for (let j = 0; j < TERRAIN_SIZE; j++) {
            const height = heightmap[i][j];
            const colorVal = Math.floor(height * 255);
            const index = (i + j * TERRAIN_SIZE) * 4;
            imageData.data[index] = colorVal;
            imageData.data[index + 1] = colorVal;
            imageData.data[index + 2] = colorVal;
            imageData.data[index + 3] = 255;
        }
    }
    ctx.putImageData(imageData, 0, 0);
    if (heightmapTexture) heightmapTexture.needsUpdate = true;
}

function updateColorTexture() {
    const ctx = colorCanvas.getContext('2d');
    const imageData = ctx.createImageData(TERRAIN_SIZE, TERRAIN_SIZE);
    for (let i = 0; i < TERRAIN_SIZE; i++) {
        for (let j = 0; j < TERRAIN_SIZE; j++) {
            const height = heightmap[i][j];
            const index = (i + j * TERRAIN_SIZE) * 4;
            let r, g, b;

            if (fluidGrid[i][j] === FLUID_TYPE.WATER || fluidGrid[i][j] === FLUID_TYPE.SOURCE) {
                r = 64; g = 164; b = 223; // Blue for water
            } else if (height < 0.3) {
                r = 210; g = 180; b = 140; // Sand
            } else if (height < 0.7) {
                r = 34; g = 139; b = 34; // Grass
            } else {
                r = 139; g = 137; b = 137; // Rock
            }

            imageData.data[index] = r;
            imageData.data[index + 1] = g;
            imageData.data[index + 2] = b;
            imageData.data[index + 3] = 255;
        }
    }
    ctx.putImageData(imageData, 0, 0);
    if (colorTexture) colorTexture.needsUpdate = true;
}

// ===== TERRAIN DESTRUCTION =====
function deformTerrain(worldX, worldZ, radius, depth) {
    // Convert world coordinates to grid coordinates
    const gridX = Math.floor(worldX + TERRAIN_SIZE / 2);
    const gridZ = Math.floor(worldZ + TERRAIN_SIZE / 2);

    for (let i = -radius; i <= radius; i++) {
        for (let j = -radius; j <= radius; j++) {
            const x = gridX + i;
            const z = gridZ + j;

            if (x >= 0 && x < TERRAIN_SIZE && z >= 0 && z < TERRAIN_SIZE) {
                const distance = Math.sqrt(i * i + j * j);
                if (distance < radius) {
                    // Use a cosine falloff for a smooth crater
                    const deformation = depth * (Math.cos(distance / radius * Math.PI / 2));
                    heightmap[x][z] = Math.max(0, heightmap[x][z] - deformation);
                }
            }
        }
    }
    updateHeightmapTexture();
    updateColorTexture(); // Also update color in case new elevations change biome
}

// ===== FLUID SIMULATION =====
function placeWaterContainers() {
    // Place a few water sources on the map
    for (let i = 0; i < 5; i++) {
        const x = Math.floor(Math.random() * TERRAIN_SIZE);
        const z = Math.floor(Math.random() * TERRAIN_SIZE);
        if (fluidGrid[x][z] === FLUID_TYPE.TERRAIN) {
            fluidGrid[x][z] = FLUID_TYPE.SOURCE;
        }
    }
    updateColorTexture();
}

function updateFluid() {
    const newGrid = fluidGrid.map(arr => arr.slice());
    let changed = false;

    for (let i = 0; i < TERRAIN_SIZE; i++) {
        for (let j = 0; j < TERRAIN_SIZE; j++) {
            if (fluidGrid[i][j] !== FLUID_TYPE.WATER) continue;

            // Rule 1: Water falls down
            const belowHeight = heightmap[i][j] * TERRAIN_MAX_HEIGHT;
            if (j > 0 && fluidGrid[i][j - 1] === FLUID_TYPE.TERRAIN && heightmap[i][j - 1] * TERRAIN_MAX_HEIGHT < belowHeight) {
                newGrid[i][j] = FLUID_TYPE.TERRAIN;
                newGrid[i][j - 1] = FLUID_TYPE.WATER;
                changed = true;
                continue;
            }

            // Rule 2: Water spreads sideways
            const spreadDir = Math.random() > 0.5 ? 1 : -1;
            for (let d = 0; d < 2; d++) {
                const ni = i + (d === 0 ? spreadDir : -spreadDir);
                if (ni >= 0 && ni < TERRAIN_SIZE && fluidGrid[ni][j] === FLUID_TYPE.TERRAIN && heightmap[ni][j] * TERRAIN_MAX_HEIGHT <= belowHeight) {
                    newGrid[i][j] = FLUID_TYPE.TERRAIN;
                    newGrid[ni][j] = FLUID_TYPE.WATER;
                    changed = true;
                    break;
                }
            }
        }
    }

    if (changed) {
        fluidGrid = newGrid;
        updateColorTexture();
    }
}

// ===== SHOOTING & INTERACTION =====
const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();

function shoot(isWaterBullet) {
    raycaster.setFromCamera(mouse, camera);
    const intersects = raycaster.intersectObject(terrainMesh);

    if (intersects.length > 0) {
        const point = intersects[0].point;

        // Create a visual effect for the bullet hit
        const hitEffect = new THREE.Mesh(
            new THREE.SphereGeometry(0.5, 8, 8),
            new THREE.MeshBasicMaterial({ color: isWaterBullet ? 0x0000ff : 0xffa500 })
        );
        hitEffect.position.copy(point);
        scene.add(hitEffect);
        setTimeout(() => scene.remove(hitEffect), 200);

        const gridX = Math.floor(point.x + TERRAIN_SIZE / 2);
        const gridZ = Math.floor(point.z + TERRAIN_SIZE / 2);

        if (isWaterBullet) {
            if (gridX >= 0 && gridX < TERRAIN_SIZE && gridZ >= 0 && gridZ < TERRAIN_SIZE) {
                if (fluidGrid[gridX][gridZ] === FLUID_TYPE.SOURCE) {
                    fluidGrid[gridX][gridZ] = FLUID_TYPE.WATER; // Release the water!
                    updateColorTexture();
                }
            }
        } else {
            deformTerrain(point.x, point.z, 5, 0.1);
        }
    }
}

// ===== PLAYER MOVEMENT =====
function setupControls() {
    document.addEventListener('click', () => controls.lock());
    document.addEventListener('keydown', (event) => { keyState[event.code] = true; });
    document.addEventListener('keyup', (event) => { keyState[event.code] = false; });
    document.addEventListener('mousedown', (event) => {
        if (controls.isLocked) {
            shoot(event.button === 2); // Right-click for water bullet
        }
    });
}

function updatePlayer(deltaTime) {
    if (!controls.isLocked) return;

    const speed = player.speed * deltaTime;
    player.velocity.x -= player.velocity.x * 10.0 * deltaTime;
    player.velocity.z -= player.velocity.z * 10.0 * deltaTime;

    player.direction.z = Number(keyState['KeyW']) - Number(keyState['KeyS']);
    player.direction.x = Number(keyState['KeyD']) - Number(keyState['KeyA']);
    player.direction.normalize();

    moveForward.setFromMatrixColumn(camera.matrix, 0);
    moveForward.cross(camera.up);
    moveRight.setFromMatrixColumn(camera.matrix, 0);

    let currentSpeed = speed;
    const playerGridX = Math.floor(controls.getObject().position.x + TERRAIN_SIZE / 2);
    const playerGridZ = Math.floor(controls.getObject().position.z + TERRAIN_SIZE / 2);

    if (playerGridX >= 0 && playerGridX < TERRAIN_SIZE && playerGridZ >= 0 && playerGridZ < TERRAIN_SIZE) {
        if (fluidGrid[playerGridX][playerGridZ] === FLUID_TYPE.WATER) {
            currentSpeed *= 0.3; // Slow down in water
        }
    }

    if (keyState['KeyW'] || keyState['KeyS']) player.velocity.z -= moveForward.z * player.direction.z * currentSpeed;
    if (keyState['KeyA'] || keyState['KeyD']) player.velocity.x -= moveRight.x * player.direction.x * currentSpeed;

    controls.moveRight(-player.velocity.x * deltaTime);
    controls.moveForward(-player.velocity.z * deltaTime);

    // Simple gravity and terrain collision
    const playerPos = controls.getObject().position;
    const terrainX = Math.floor(playerPos.x + TERRAIN_SIZE / 2);
    const terrainZ = Math.floor(playerPos.z + TERRAIN_SIZE / 2);

    if (terrainX >= 0 && terrainX < TERRAIN_SIZE && terrainZ >= 0 && terrainZ < TERRAIN_SIZE) {
        const terrainHeight = heightmap[terrainX][terrainZ] * TERRAIN_MAX_HEIGHT;
        if (playerPos.y < terrainHeight + 5) {
            player.velocity.y = 0;
            playerPos.y = terrainHeight + 5;
            player.onGround = true;
        } else {
            player.velocity.y -= 9.8 * 2.0 * deltaTime; // Gravity
            player.onGround = false;
        }
    }
    playerPos.y += player.velocity.y * deltaTime;
}

// ===== MAIN LOOP =====
const clock = new THREE.Clock();
let fluidUpdateTimer = 0;

function animate() {
    requestAnimationFrame(animate);
    const deltaTime = clock.getDelta();

    updatePlayer(deltaTime);

    // Update fluid simulation at a slower rate for performance
    fluidUpdateTimer += deltaTime;
    if (fluidUpdateTimer > 0.1) {
        updateFluid();
        fluidUpdateTimer = 0;
    }

    renderer.render(scene, camera);
}

// ===== INITIALIZATION =====
generateTerrain();
placeWaterContainers();
setupControls();
animate();

window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});
```

### How to Run the Game

1.  Save the three files (`index.html`, `style.css`, `main.js`) in a new folder.
2.  You need a local web server. If you have Node.js installed, the easiest way is:
    *   Open a terminal or command prompt in your project folder.
    *   Run `npx http-server`.
    *   Open your web browser and navigate to the URL provided (e.g., `http://127.0.0.1:8080`).
3.  Click on the screen to lock the pointer. Use WASD to move, and the mouse to look around.
    *   **Left-click** to fire a standard bullet that deforms the terrain.
    *   **Right-click** to fire a "water" bullet. If you hit a water container (represented by a blue square on the terrain), it will break and release water.

### Professional Enhancements & Next Steps

This prototype successfully demonstrates the core mechanics. To evolve this into a full-fledged game, consider these professional-grade improvements:

1.  **Performance Optimization (GPGPU):** For larger terrains or more complex simulations, the JavaScript-based updates will become a bottleneck. The next step is to move the deformation and fluid simulation logic to the GPU using custom GLSL shaders (a technique known as GPGPU). This would provide a massive performance boost.

2.  **Advanced Graphics:**
    *   **Normal Map Recalculation:** When the terrain is deformed, the surface normals change. For correct lighting, the normal map should be recalculated in real-time, which can also be done in a shader.
    *   **Water Rendering:** Implement a more advanced water shader with transparency, refraction (distorting the view of the terrain below), and specular highlights for a realistic water surface.
    *   **Particle Effects:** Add particle systems for explosions, bullet impacts, and water splashes to enhance visual feedback.

3.  **Physics Engine:** The current player controller is very basic. Integrating a dedicated WebGL physics engine like **Cannon.js** or **Rapier.js** would allow for more realistic movement, collision detection with complex shapes (enemies, props), and projectile physics.

4.  **Gameplay & AI:**
    *   Add enemy models with basic AI (e.g., pathfinding on the dynamic terrain, taking cover).
    *   Implement a health system for the player and enemies.
    *   Design objectives, scoring, and a complete game loop.

