#### `backend/server.js`
This is the core of the backend, running an Express server for API endpoints and a WebSocket server for real-time communication.

```javascript
// Import required modules
const express = require('express');
const http = require('http');
const { WebSocketServer } = require('ws');
const cors = require('cors');

// --- Server Setup ---
const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ server });

// Use middleware
app.use(cors()); // Enable Cross-Origin Resource Sharing
app.use(express.json()); // Parse JSON request bodies

// --- In-Memory Data Store (Mock Database) ---
// We use simple in-memory arrays to store data for this demonstration.
// In a real-world application, you would use a database like PostgreSQL, MongoDB, etc.

// List of available meeting rooms
const rooms = [
    { id: 1, name: 'Conference Room A' },
    { id: 2, name: 'Conference Room B' },
    { id: 3, name: 'Small Meeting Room' }
];

// Store reservations. Each reservation has a unique ID.
let reservations = [
    // Mock data for demonstration
    { id: 1, roomId: 1, userId: 'Alice', date: '2023-10-28', timeSlot: '10:00' },
    { id: 2, roomId: 2, userId: 'Bob', date: '2023-10-28', timeSlot: '14:00' }
];
let nextReservationId = 3; // Counter for new reservation IDs

// --- WebSocket Logic ---

// Function to broadcast a message to all connected WebSocket clients
const broadcast = (data) => {
    wss.clients.forEach(client => {
        if (client.readyState === client.OPEN) {
            client.send(JSON.stringify(data));
        }
    });
};

// Handle new WebSocket connections
wss.on('connection', (ws) => {
    console.log('Client connected');
    ws.on('close', () => {
        console.log('Client disconnected');
    });
});

// --- API Endpoints ---

// GET /api/rooms - Fetches the list of all meeting rooms
app.get('/api/rooms', (req, res) => {
    res.json(rooms);
});

// GET /api/reservations?date=YYYY-MM-DD - Fetches all reservations for a specific date
app.get('/api/reservations', (req, res) => {
    const { date } = req.query;
    if (!date) {
        return res.status(400).json({ error: 'Date query parameter is required' });
    }
    const filteredReservations = reservations.filter(r => r.date === date);
    res.json(filteredReservations);
});

// GET /api/reservations/all - Fetches all reservations (for the admin panel)
app.get('/api/reservations/all', (req, res) => {
    // Join room name with reservation data for easier display on the admin page
    const detailedReservations = reservations.map(res => {
        const room = rooms.find(r => r.id === res.roomId);
        return { ...res, roomName: room ? room.name : 'Unknown Room' };
    });
    res.json(detailedReservations);
});

// POST /api/reservations - Creates a new reservation
app.post('/api/reservations', (req, res) => {
    const { roomId, userId, date, timeSlot } = req.body;

    // Basic validation
    if (!roomId || !userId || !date || !timeSlot) {
        return res.status(400).json({ error: 'Missing required fields' });
    }

    // Check for booking conflicts
    const conflict = reservations.some(
        r => r.roomId === roomId && r.date === date && r.timeSlot === timeSlot
    );

    if (conflict) {
        return res.status(409).json({ error: 'This time slot is already booked' });
    }

    // Create and store the new reservation
    const newReservation = { id: nextReservationId++, roomId, userId, date, timeSlot };
    reservations.push(newReservation);

    // Notify all clients about the update
    broadcast({ type: 'UPDATE', date });

    res.status(201).json(newReservation);
});

// DELETE /api/reservations/:id - Deletes a reservation (Admin action)
app.delete('/api/reservations/:id', (req, res) => {
    const id = parseInt(req.params.id, 10);
    const reservationIndex = reservations.findIndex(r => r.id === id);

    if (reservationIndex === -1) {
        return res.status(404).json({ error: 'Reservation not found' });
    }

    const deletedReservation = reservations.splice(reservationIndex, 1)[0];

    // Notify all clients about the update
    broadcast({ type: 'UPDATE', date: deletedReservation.date });

    res.status(204).send(); // No content
});

// PUT /api/reservations/:id - Updates a reservation (Admin action)
app.put('/api/reservations/:id', (req, res) => {
    const id = parseInt(req.params.id, 10);
    const { userId } = req.body;
    const reservation = reservations.find(r => r.id === id);

    if (!reservation) {
        return res.status(404).json({ error: 'Reservation not found' });
    }

    if (!userId) {
        return res.status(400).json({ error: 'User ID is required for update' });
    }

    reservation.userId = userId;

    // Notify all clients about the update
    broadcast({ type: 'UPDATE', date: reservation.date });

    res.json(reservation);
});


// --- Start Server ---
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server is running on http://localhost:${PORT}`);
});
