document.addEventListener('DOMContentLoaded', () => {
    // --- DOM Elements ---
    const roomSelect = document.getElementById('room-select');
    const datePicker = document.getElementById('date-picker');
    const timeSlotsContainer = document.getElementById('time-slots-container');
    const scheduleTitle = document.getElementById('schedule-title');

    // --- API and WebSocket Configuration ---
    const API_URL = 'http://localhost:3000/api';
    const WS_URL = 'ws://localhost:3000';

    // --- Application State ---
    let rooms = [];
    let reservations = [];
    const timeSlots = ['09:00', '10:00', '11:00', '12:00', '13:00', '14:00', '15:00', '16:00', '17:00'];

    // --- WebSocket Connection ---
    const ws = new WebSocket(WS_URL);

    ws.onopen = () => console.log('Connected to WebSocket server');
    ws.onmessage = (event) => {
        const data = JSON.parse(event.data);
        // If the update is for the currently selected date, refresh the view
        if (data.type === 'UPDATE' && data.date === datePicker.value) {
            console.log('Real-time update received. Refreshing schedule...');
            fetchReservations();
        }
    };
    ws.onclose = () => console.log('Disconnected from WebSocket server');
    ws.onerror = (error) => console.error('WebSocket error:', error);

    // --- Functions ---

    // Set default date to today
    const setDefaultDate = () => {
        const today = new Date();
        const year = today.getFullYear();
        const month = String(today.getMonth() + 1).padStart(2, '0');
        const day = String(today.getDate()).padStart(2, '0');
        datePicker.value = `${year}-${month}-${day}`;
    };

    // Fetch available rooms from the backend
    const fetchRooms = async () => {
        try {
            const response = await fetch(`${API_URL}/rooms`);
            rooms = await response.json();
            populateRoomSelect();
        } catch (error) {
            console.error('Error fetching rooms:', error);
        }
    };

    // Populate the room selection dropdown
    const populateRoomSelect = () => {
        roomSelect.innerHTML = rooms.map(room => `<option value="${room.id}">${room.name}</option>`).join('');
        // After populating, fetch reservations for the default selection
        fetchReservations();
    };

    // Fetch reservations for the selected room and date
    const fetchReservations = async () => {
        const selectedDate = datePicker.value;
        if (!selectedDate) return;

        try {
            const response = await fetch(`${API_URL}/reservations?date=${selectedDate}`);
            reservations = await response.json();
            renderTimeSlots();
        } catch (error) {
            console.error('Error fetching reservations:', error);
        }
    };

    // Render the time slots grid
    const renderTimeSlots = () => {
        const selectedRoomId = parseInt(roomSelect.value, 10);
        const selectedRoom = rooms.find(r => r.id === selectedRoomId);

        if (!selectedRoom) return;

        scheduleTitle.textContent = `Schedule for ${selectedRoom.name} on ${datePicker.value}`;
        timeSlotsContainer.innerHTML = ''; // Clear previous slots

        timeSlots.forEach(slot => {
            const reservation = reservations.find(r => r.roomId === selectedRoomId && r.timeSlot === slot);
            const slotDiv = document.createElement('div');
            slotDiv.classList.add('time-slot');
            slotDiv.dataset.time = slot;

            if (reservation) {
                slotDiv.classList.add('booked');
                slotDiv.innerHTML = `${slot}<span class="user">Booked by ${reservation.userId}</span>`;
            } else {
                slotDiv.classList.add('available');
                slotDiv.textContent = slot;
                slotDiv.addEventListener('click', () => handleSlotClick(slot));
            }
            timeSlotsContainer.appendChild(slotDiv);
        });
    };

    // Handle clicking on an available time slot
    const handleSlotClick = (timeSlot) => {
        const userId = prompt('Please enter your name to book this slot:');
        if (userId) {
            bookTimeSlot(timeSlot, userId);
        }
    };

    // Send a request to book a time slot
    const bookTimeSlot = async (timeSlot, userId) => {
        const reservationDetails = {
            roomId: parseInt(roomSelect.value, 10),
            userId: userId,
            date: datePicker.value,
            timeSlot: timeSlot
        };

        try {
            const response = await fetch(`${API_URL}/reservations`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(reservationDetails)
            });

            if (response.ok) {
                alert('Reservation successful!');
                // The WebSocket will trigger a refresh, but we can also call it manually for immediate feedback
                fetchReservations();
            } else if (response.status === 409) {
                alert('This time slot has just been booked by someone else. Please choose another one.');
                fetchReservations(); // Refresh to show the updated status
            } else {
                const errorData = await response.json();
                alert(`Error: ${errorData.error}`);
            }
        } catch (error) {
            console.error('Error booking time slot:', error);
            alert('An error occurred while booking.');
        }
    };

    // --- Event Listeners ---
    roomSelect.addEventListener('change', fetchReservations);
    datePicker.addEventListener('change', fetchReservations);

    // --- Initial Load ---
    const initialize = async () => {
        setDefaultDate();
        await fetchRooms(); // This will trigger the first fetchReservations call
    };

    initialize();
});
