import fitz  # PyMuPDF
import os
import re

# --- Conference Formatting Standards ---
MAX_PAGES = 10
REQUIRED_FONTS = {"Times", "Times New Roman", "Times-Roman", "Helvetica", "Arial"}
MIN_MARGIN_INCH = 1.0  # 1 inch margin

class PDFProcessor:
    def __init__(self, file_path):
        self.file_path = file_path
        self.doc = fitz.open(file_path)
        self.results = {
            "page_count": len(self.doc),
            "margin_check": "Failed",
            "font_check": "Failed",
            "format_status": "Failed"
        }

    def check_format(self):
        """Runs all format checks and returns a summary."""
        page_ok = self._check_page_count()
        margins_ok = self._check_margins()
        fonts_ok = self._check_fonts()

        if page_ok and margins_ok and fonts_ok:
            self.results["format_status"] = "Passed"

        return self.results

    def _check_page_count(self):
        if self.results["page_count"] <= MAX_PAGES:
            return True
        return False

    def _check_margins(self):
        """Checks margins on the first page. 72 points = 1 inch."""
        margin_points = MIN_MARGIN_INCH * 72
        page = self.doc[0]
        text_bbox = page.get_text_bbox() # Bounding box of all text on the page

        if not text_bbox: # Handle empty pages
            self.results["margin_check"] = "Passed (Empty Page)"
            return True

        page_width = page.rect.width
        page_height = page.rect.height

        left_margin = text_bbox.x0
        right_margin = page_width - text_bbox.x1
        top_margin = text_bbox.y0
        bottom_margin = page_height - text_bbox.y1

        if left_margin < margin_points:
            self.results["margin_check"] = f"Failed: Left Margin ({left_margin:.1f}pt < {margin_points}pt)"
            return False
        if right_margin < margin_points:
            self.results["margin_check"] = f"Failed: Right Margin ({right_margin:.1f}pt < {margin_points}pt)"
            return False

        self.results["margin_check"] = "Passed"
        return True

    def _check_fonts(self):
        """Checks if all fonts used in the document are allowed."""
        fonts = set()
        for page in self.doc:
            for font in page.get_fonts():
                base_font = font[3].split('+')[-1].split(',')[0] # Clean font name
                fonts.add(base_font)

        disallowed_fonts = fonts - REQUIRED_FONTS
        if not disallowed_fonts:
            self.results["font_check"] = "Passed"
            return True
        else:
            self.results["font_check"] = f"Failed: Prohibited Font ({list(disallowed_fonts)[0]})"
            return False

    def anonymize(self, output_path):
        """Creates an anonymized version of the PDF for double-blind review."""
        # 1. Remove metadata
        self.doc.set_metadata({})

        # 2. Redact author-identifying keywords on the first page
        # This is a heuristic and can be improved with more advanced NLP
        keywords = ["author", "email", "university", "institute", "department", "acknowledgment"]
        page = self.doc[0]

        for keyword in keywords:
            areas = page.search_for(keyword, flags=fitz.TEXT_INHIBIT_SPACES | fitz.IGNORE_CASE)
            for inst in areas:
                # Expand the redaction area slightly to cover surrounding text
                expanded_rect = fitz.Rect(inst.x0 - 10, inst.y0 - 5, inst.x1 + 200, inst.y1 + 5)
                page.add_redact_annot(expanded_rect, fill=(0, 0, 0))

        page.apply_redactions()
        self.doc.save(output_path, garbage=4, deflate=True, clean=True)
        return output_path

    def close(self):
        self.doc.close()
