from flask import Flask, request, jsonify
from flask_cors import CORS
from models import db, Submission
from pdf_processor import PDFProcessor
import os
import uuid
import threading
import time
import random
import requests

# --- App Configuration ---
app = Flask(__name__)
CORS(app) # Allow frontend to connect
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///submissions.db'
app.config['UPLOAD_FOLDER'] = 'uploads'
db.init_app(app)

# --- Mock Turnitin API ---
MOCK_TURNITIN_ENDPOINT = "http://127.0.0.1:5000/mock_turnitin_callback"

def trigger_turnitin_check(submission_id):
    """Simulates calling the Turnitin API and waiting for a callback."""
    def task():
        print(f"Submitting paper {submission_id} to Turnitin...")
        time.sleep(5) # Simulate API call and processing time

        # Turnitin calls our callback endpoint when done
        callback_data = {
            "submission_id": submission_id,
            "status": "Complete",
            "score": random.randint(2, 25)
        }
        requests.post(MOCK_TURNITIN_ENDPOINT, json=callback_data)

    # In production, this would be a Celery task
    thread = threading.Thread(target=task)
    thread.start()

@app.route('/mock_turnitin_callback', methods=['POST'])
def mock_turnitin_callback():
    """This endpoint is what our mock Turnitin service 'calls' when processing is done."""
    data = request.json
    with app.app_context():
        submission = Submission.query.get(data['submission_id'])
        if submission:
            submission.turnitin_status = data['status']
            submission.turnitin_score = data['score']
            db.session.commit()
            print(f"Received Turnitin callback for submission {submission.id}, score: {submission.turnitin_score}")
    return jsonify({"status": "callback received"}), 200

# --- Core API Endpoints ---
@app.route('/upload', methods=['POST'])
def upload_paper():
    if 'file' not in request.files:
        return jsonify({"error": "No file part"}), 400
    file = request.files['file']
    if file.filename == '':
        return jsonify({"error": "No selected file"}), 400

    if file and file.filename.endswith('.pdf'):
        # 1. Save original file
        original_filename = file.filename
        unique_id = str(uuid.uuid4())
        original_path = os.path.join(app.config['UPLOAD_FOLDER'], f"{unique_id}_{original_filename}")
        file.save(original_path)

        # 2. Process PDF for format checks
        processor = PDFProcessor(original_path)
        format_results = processor.check_format()

        # 3. Create anonymized version for review
        anonymized_filename = f"{unique_id}_anonymized.pdf"
        anonymized_path = os.path.join(app.config['UPLOAD_FOLDER'], anonymized_filename)
        processor.anonymize(anonymized_path)
        processor.close()

        # 4. Create database record
        new_submission = Submission(
            original_filename=original_filename,
            page_count=format_results['page_count'],
            margin_check=format_results['margin_check'],
            font_check=format_results['font_check'],
            format_status=format_results['format_status'],
            anonymized_path=anonymized_path,
            turnitin_status="In Progress"
        )
        db.session.add(new_submission)
        db.session.commit()

        # 5. Trigger async plagiarism check
        trigger_turnitin_check(new_submission.id)

        return jsonify({
            "message": "File uploaded and processing started.",
            "submission": new_submission.to_dict()
        }), 201

    return jsonify({"error": "Invalid file type, only PDF allowed"}), 400

@app.route('/submissions', methods=['GET'])
def get_submissions():
    submissions = Submission.query.order_by(Submission.submission_timestamp.desc()).all()
    return jsonify([s.to_dict() for s in submissions]), 200

if __name__ == '__main__':
    with app.app_context():
        if not os.path.exists(app.config['UPLOAD_FOLDER']):
            os.makedirs(app.config['UPLOAD_FOLDER'])
        db.create_all()
    app.run(debug=True, port=5000)
