```javascript
import React, { useState } from 'react';
import axios from 'axios';

const API_URL = 'http://127.0.0.1:5000';

function SubmissionForm({ onUploadSuccess }) {
    const [file, setFile] = useState(null);
    const [uploading, setUploading] = useState(false);
    const [message, setMessage] = useState('');
    const [isError, setIsError] = useState(false);

    const handleFileChange = (e) => {
        setFile(e.target.files[0]);
        setMessage('');
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!file) {
            setMessage('Please select a PDF file to upload.');
            setIsError(true);
            return;
        }

        const formData = new FormData();
        formData.append('file', file);

        setUploading(true);
        setMessage('Uploading and processing...');
        setIsError(false);

        try {
            const response = await axios.post(`${API_URL}/upload`, formData, {
                headers: {
                    'Content-Type': 'multipart/form-data',
                },
            });
            setMessage(response.data.message);
            setIsError(false);
            onUploadSuccess(); // Refresh the dashboard
            setFile(null); // Clear the file input
            document.getElementById('file-input').value = null;
        } catch (error) {
            setMessage(error.response?.data?.error || 'An unknown error occurred.');
            setIsError(true);
        } finally {
            setUploading(false);
        }
    };

    return (
        <div className="submission-form">
            <form onSubmit={handleSubmit}>
                <input id="file-input" type="file" accept=".pdf" onChange={handleFileChange} />
                <button type="submit" disabled={uploading || !file}>
                    {uploading ? 'Submitting...' : 'Submit Paper'}
                </button>
            </form>
            {message && (
                <p className={`message ${isError ? 'error' : 'success'}`}>{message}</p>
            )}
        </div>
    );
}

export default SubmissionForm;
```

