```javascript
import React, { useState, useEffect } from 'react';
import axios from 'axios';

const API_URL = 'http://127.0.0.1:5000';

const StatusBadge = ({ status }) => {
    let className = 'status-badge ';
    switch (status.toLowerCase()) {
        case 'passed':
            className += 'status-passed';
            break;
        case 'failed':
            className += 'status-failed';
            break;
        case 'in progress':
            className += 'status-inprogress';
            break;
        default:
            className += 'status-pending';
    }
    return <span className={className}>{status}</span>;
};

function SubmissionDashboard({ refreshKey }) {
    const [submissions, setSubmissions] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchSubmissions = async () => {
            try {
                setLoading(true);
                const response = await axios.get(`${API_URL}/submissions`);
                setSubmissions(response.data);
            } catch (error) {
                console.error("Failed to fetch submissions:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchSubmissions();

        // Set up polling to get real-time updates for Turnitin status
        const interval = setInterval(fetchSubmissions, 5000); // Poll every 5 seconds

        return () => clearInterval(interval); // Cleanup on component unmount
    }, [refreshKey]);

    if (loading && submissions.length === 0) return <p>Loading submissions...</p>;

    return (
        <div className="submission-dashboard">
            <h2>Submission Status</h2>
            {submissions.length === 0 ? (
                <p>No submissions yet. Upload a paper to begin.</p>
            ) : (
                <table className="dashboard-table">
                    <thead>
                        <tr>
                            <th>Filename</th>
                            <th>Format Status</th>
                            <th>Plagiarism Check</th>
                            <th>Details</th>
                            <th>Submitted</th>
                        </tr>
                    </thead>
                    <tbody>
                        {submissions.map(sub => (
                            <tr key={sub.id}>
                                <td data-label="Filename">{sub.filename}</td>
                                <td data-label="Format Status"><StatusBadge status={sub.format_status} /></td>
                                <td data-label="Plagiarism Check">
                                    <StatusBadge status={sub.turnitin_status} />
                                    {sub.turnitin_score && ` (${sub.turnitin_score}%)`}
                                </td>
                                <td data-label="Details">
                                    Pages: {sub.checks.pages}<br />
                                    Margins: {sub.checks.margins}<br />
                                    Fonts: {sub.checks.fonts}
                                </td>
                                <td data-label="Submitted">{new Date(sub.timestamp).toLocaleString()}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            )}
        </div>
    );
}

export default SubmissionDashboard;
