### **Step 2: Build the Backend (`server.js`)**

This is the core of our application. It will set up a web server, define an API endpoint to receive a URL, launch a headless browser, take the screenshot, and return the path to the generated image.

Create the file `server.js`:

```javascript
// server.js
const express = require('express');
const puppeteer = require('puppeteer');
const path = require('path');
const fs = require('fs');
const { URL } = require('url');

const app = express();
const PORT = process.env.PORT || 3000;

// --- Middleware ---
// Serve static files from the 'public' directory (for our frontend)
app.use(express.static('public'));
// Serve generated screenshots from the 'screenshots' directory
app.use('/screenshots', express.static(path.join(__dirname, 'screenshots')));
// Parse JSON bodies from incoming requests
app.use(express.json());

// Ensure the screenshots directory exists
const screenshotsDir = path.join(__dirname, 'screenshots');
if (!fs.existsSync(screenshotsDir)) {
    fs.mkdirSync(screenshotsDir);
}

// --- API Endpoint for taking screenshots ---
app.post('/api/screenshot', async (req, res) => {
    const { url } = req.body;

    // --- Input Validation ---
    if (!url) {
        return res.status(400).json({ error: 'URL is required.' });
    }

    try {
        // Validate and normalize the URL
        const parsedUrl = new URL(url);
        const cleanUrl = parsedUrl.href;

        console.log(`Processing screenshot for: ${cleanUrl}`);

        // --- Puppeteer Logic ---
        const browser = await puppeteer.launch({
            // Recommended for running in Docker/CI environments
            args: ['--no-sandbox', '--disable-setuid-sandbox'] 
        });
        const page = await browser.newPage();

        // Set a standard viewport for consistent thumbnail size
        await page.setViewport({
            width: 1280,
            height: 720,
            deviceScaleFactor: 1,
        });

        // Navigate to the URL
        await page.goto(cleanUrl, {
            waitUntil: 'networkidle2', // Wait until the page is mostly loaded
            timeout: 30000 // 30-second timeout
        });

        // Generate a unique filename
        const filename = `${Date.now()}.png`;
        const outputPath = path.join(screenshotsDir, filename);

        // Take the screenshot and save it
        await page.screenshot({ path: outputPath });

        // Close the browser to free up resources
        await browser.close();

        // --- Success Response ---
        // Return the path to the generated image
        res.json({
            success: true,
            screenshotUrl: `/screenshots/${filename}`
        });

    } catch (error) {
        console.error('Screenshot failed:', error);
        // --- Error Handling ---
        res.status(500).json({
            success: false,
            error: 'Failed to capture screenshot. The URL may be invalid or the page timed out.'
        });
    }
});

// --- Start the Server ---
app.listen(PORT, () => {
    console.log(`Server is running on http://localhost:${PORT}`);
});
```

