#### **`public/script.js`**

This script handles the form submission, sends the URL to the backend, and displays the result.

```javascript
// public/script.js
document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('screenshot-form');
    const urlInput = document.getElementById('url-input');
    const submitBtn = document.getElementById('submit-btn');

    const loader = document.getElementById('loader');
    const resultContainer = document.getElementById('result-container');
    const screenshotImage = document.getElementById('screenshot-image');
    const downloadBtn = document.getElementById('download-btn');

    const errorContainer = document.getElementById('error-container');
    const errorMessage = document.getElementById('error-message');

    form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const url = urlInput.value.trim();

        if (!url) {
            showError('Please enter a valid URL.');
            return;
        }

        // --- UI State Management ---
        // Reset UI
        hideError();
        resultContainer.classList.add('hidden');
        // Show loader and disable button
        loader.classList.remove('hidden');
        submitBtn.disabled = true;
        submitBtn.textContent = 'Capturing...';

        try {
            const response = await fetch('/api/screenshot', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ url }),
            });

            const result = await response.json();

            if (!response.ok || !result.success) {
                throw new Error(result.error || 'An unknown error occurred.');
            }

            // --- Display the result ---
            screenshotImage.src = result.screenshotUrl;
            downloadBtn.href = result.screenshotUrl;
            resultContainer.classList.remove('hidden');

        } catch (error) {
            showError(error.message);
        } finally {
            // --- UI State Reset ---
            loader.classList.add('hidden');
            submitBtn.disabled = false;
            submitBtn.textContent = 'Capture';
        }
    });

    function showError(message) {
        errorMessage.textContent = message;
        errorContainer.classList.remove('hidden');
    }

    function hideError() {
        errorContainer.classList.add('hidden');
    }
});
```

