#### Step 3: Authentication and API Routes

**`backend/middleware/authMiddleware.js`**
Middleware to protect routes by verifying the JWT.

```javascript
const jwt = require('jsonwebtoken');
const { User } = require('../models');

const protect = async (req, res, next) => {
  let token;
  if (req.headers.authorization && req.headers.authorization.startsWith('Bearer')) {
    try {
      token = req.headers.authorization.split(' ')[1];
      const decoded = jwt.verify(token, 'your_jwt_secret'); // Use a strong secret in production
      req.user = await User.findByPk(decoded.id, { attributes: { exclude: ['password'] } });
      next();
    } catch (error) {
      res.status(401).json({ message: 'Not authorized, token failed' });
    }
  }
  if (!token) {
    res.status(401).json({ message: 'Not authorized, no token' });
  }
};

const admin = (req, res, next) => {
  if (req.user && req.user.role === 'admin') {
    next();
  } else {
    res.status(403).json({ message: 'Not authorized as an admin' });
  }
};

module.exports = { protect, admin };
```

**`backend/routes/auth.js`**
Handles user login.

```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const { User } = require('../models');
const router = express.Router();

router.post('/login', async (req, res) => {
  const { username, password } = req.body;
  const user = await User.findOne({ where: { username } });

  if (user && (await user.isValidPassword(password))) {
    res.json({
      id: user.id,
      username: user.username,
      role: user.role,
      token: jwt.sign({ id: user.id, role: user.role }, 'your_jwt_secret', { expiresIn: '1d' }),
    });
  } else {
    res.status(401).json({ message: 'Invalid username or password' });
  }
});

module.exports = router;
