**`backend/routes/instruments.js`**
CRUD operations for instruments and their maintenance records.

```javascript
const express = require('express');
const { Op } = require('sequelize');
const { Instrument, MaintenanceRecord } = require('../models');
const { protect, admin } = require('../middleware/authMiddleware');
const router = express.Router();

// GET all instruments (public, with search)
router.get('/', async (req, res) => {
  const { search } = req.query;
  let where = {};
  if (search) {
    where = {
      [Op.or]: [
        { name: { [Op.like]: `%${search}%` } },
        { model: { [Op.like]: `%${search}%` } },
        { manufacturer: { [Op.like]: `%${search}%` } },
      ],
    };
  }
  const instruments = await Instrument.findAll({ where, order: [['name', 'ASC']] });
  res.json(instruments);
});

// GET a single instrument by ID (public)
router.get('/:id', async (req, res) => {
  const instrument = await Instrument.findByPk(req.params.id, {
    include: { model: MaintenanceRecord, order: [['date', 'DESC']] },
  });
  if (instrument) {
    res.json(instrument);
  } else {
    res.status(404).json({ message: 'Instrument not found' });
  }
});

// POST a new instrument (admin only)
router.post('/', protect, admin, async (req, res) => {
  try {
    const instrument = await Instrument.create(req.body);
    res.status(201).json(instrument);
  } catch (error) {
    res.status(400).json({ message: 'Error creating instrument', error: error.message });
  }
});

// PUT update an instrument (admin only)
router.put('/:id', protect, admin, async (req, res) => {
  const instrument = await Instrument.findByPk(req.params.id);
  if (instrument) {
    await instrument.update(req.body);
    res.json(instrument);
  } else {
    res.status(404).json({ message: 'Instrument not found' });
  }
});

// POST a new maintenance record (admin only)
router.post('/:id/maintenance', protect, admin, async (req, res) => {
  const instrument = await Instrument.findByPk(req.params.id);
  if (instrument) {
    const record = await MaintenanceRecord.create({
      ...req.body,
      instrumentId: instrument.id,
    });
    res.status(201).json(record);
  } else {
    res.status(404).json({ message: 'Instrument not found' });
  }
});

module.exports = router;
```

