```javascript
import React, { useState, useRef } from 'react';
import VideoPlayer from './components/VideoPlayer';
import Timeline from './components/Timeline';
import BookmarkList from './components/BookmarkList';
import './App.css';

function App() {
    const [bookmarks, setBookmarks] = useState([]);
    const [duration, setDuration] = useState(0);
    const [currentTime, setCurrentTime] = useState(0);
    const videoRef = useRef(null);
    const fileInputRef = useRef(null);

    const handleAddBookmark = () => {
        const video = videoRef.current;
        if (!video) return;

        // Create a canvas to capture the thumbnail
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const thumbnail = canvas.toDataURL('image/jpeg');

        const newBookmark = {
            id: Date.now(),
            time: video.currentTime,
            note: 'New bookmark...',
            thumbnail,
        };
        setBookmarks([...bookmarks, newBookmark].sort((a, b) => a.time - b.time));
    };

    const handleSeek = (time) => {
        if (videoRef.current) {
            videoRef.current.currentTime = time;
        }
    };

    const handleUpdateNote = (id, newNote) => {
        setBookmarks(bookmarks.map(b => b.id === id ? { ...b, note: newNote } : b));
    };

    const handleDeleteBookmark = (id) => {
        setBookmarks(bookmarks.filter(b => b.id !== id));
    };

    const handleExport = () => {
        const projectData = {
            videoFile: videoRef.current ? videoRef.current.src.split('/').pop() : '',
            bookmarks: bookmarks,
        };
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(projectData, null, 2));
        const downloadAnchorNode = document.createElement('a');
        downloadAnchorNode.setAttribute("href", dataStr);
        downloadAnchorNode.setAttribute("download", "video_markers_project.json");
        document.body.appendChild(downloadAnchorNode);
        downloadAnchorNode.click();
        downloadAnchorNode.remove();
    };

    const handleImport = (event) => {
        const file = event.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (e) => {
                try {
                    const data = JSON.parse(e.target.result);
                    if (data.bookmarks) {
                        setBookmarks(data.bookmarks);
                    }
                } catch (error) {
                    alert('Error parsing project file.');
                }
            };
            reader.readAsText(file);
        }
    };

    return (
        <div className="app-container">
            <header className="app-header">
                <h1>Video Timeline Marking Tool</h1>
                <div className="project-controls">
                    <button onClick={handleExport}>Export Project</button>
                    <button onClick={() => fileInputRef.current.click()}>Import Project</button>
                    <input type="file" ref={fileInputRef} style={{ display: 'none' }} onChange={handleImport} accept=".json" />
                </div>
            </header>
            <main className="main-content">
                <div className="video-section">
                    <VideoPlayer
                        ref={videoRef}
                        src="/sample-video.mp4"
                        onTimeUpdate={setCurrentTime}
                        onDurationChange={setDuration}
                    />
                    <Timeline
                        currentTime={currentTime}
                        duration={duration}
                        bookmarks={bookmarks}
                        onSeek={handleSeek}
                    />
                    <div className="controls">
                        <button onClick={handleAddBookmark}>Add Bookmark at Current Time</button>
                    </div>
                </div>
                <div className="bookmarks-section">
                    <BookmarkList
                        bookmarks={bookmarks}
                        onSeek={handleSeek}
                        onUpdateNote={handleUpdateNote}
                        onDelete={handleDeleteBookmark}
                    />
                </div>
            </main>
        </div>
    );
}

export default App;
```

#### **`src/components/VideoPlayer.js`**

This component handles the video element and its events.

```javascript
import React, { forwardRef, useImperativeHandle, useRef, useEffect } from 'react';

const VideoPlayer = forwardRef(({ src, onTimeUpdate, onDurationChange }, ref) => {
    const localVideoRef = useRef(null);

    // Expose the video element to the parent component (App.js)
    useImperativeHandle(ref, () => localVideoRef.current);

    useEffect(() => {
        const video = localVideoRef.current;
        if (!video) return;

        const handleTimeUpdate = () => onTimeUpdate(video.currentTime);
        const handleLoadedMetadata = () => onDurationChange(video.duration);

        video.addEventListener('timeupdate', handleTimeUpdate);
        video.addEventListener('loadedmetadata', handleLoadedMetadata);

        return () => {
            video.removeEventListener('timeupdate', handleTimeUpdate);
            video.removeEventListener('loadedmetadata', handleLoadedMetadata);
        };
    }, [onTimeUpdate, onDurationChange]);

    return (
        <video
            ref={localVideoRef}
            controls
            width="100%"
            src={src}
        >
            Your browser does not support the video tag.
        </video>
    );
});

export default VideoPlayer;
```

#### **`src/components/Timeline.js`**

This component displays the interactive timeline with progress and bookmark markers.

```javascript
import React from 'react';

const Timeline = ({ currentTime, duration, bookmarks, onSeek }) => {
    const formatTime = (time) => {
        const minutes = Math.floor(time / 60);
        const seconds = Math.floor(time % 60).toString().padStart(2, '0');
        return `${minutes}:${seconds}`;
    };

    const handleTimelineClick = (e) => {
        const timeline = e.currentTarget;
        const rect = timeline.getBoundingClientRect();
        const clickX = e.clientX - rect.left;
        const percentage = clickX / rect.width;
        onSeek(duration * percentage);
    };

    return (
        <div className="timeline-container">
            <div className="timeline" onClick={handleTimelineClick}>
                <div
                    className="timeline-progress"
                    style={{ width: `${(currentTime / duration) * 100}%` }}
                ></div>
                {bookmarks.map(bookmark => (
                    <div
                        key={bookmark.id}
                        className="bookmark-marker"
                        style={{ left: `${(bookmark.time / duration) * 100}%` }}
                        title={`Bookmark at ${formatTime(bookmark.time)}`}
                        onClick={(e) => { e.stopPropagation(); onSeek(bookmark.time); }}
                    ></div>
                ))}
            </div>
            <div className="time-display">
                <span>{formatTime(currentTime)}</span> / <span>{formatTime(duration)}</span>
            </div>
        </div>
    );
};

export default Timeline;
```

