```javascript
// server.js
const express = require('express');
const bodyParser = require('body-parser');
const session = require('express-session');

const app = express();
const PORT = 3000;

// --- Middleware Setup ---
app.use(express.static('public')); // Serve static files from the 'public' directory
app.use(bodyParser.json()); // Parse JSON bodies
app.use(session({
    secret: 'super-secret-key-for-drone-system', // A secret key for signing the session ID cookie
    resave: false,
    saveUninitialized: false,
    cookie: { secure: false, maxAge: 3600000 } // Cookie settings (1 hour)
}));

// --- In-Memory Data Store (Simulated Database) ---
let drones = [
    { id: 1, name: 'DJI Mavic 3 Pro', status: 'Landed' },
    { id: 2, name: 'Autel EVO II', status: 'Landed' },
    { id: 3, name: 'Parrot Anafi USA', status: 'Charging' },
    { id: 4, name: 'Skydio 2+', status: 'In-Flight' },
    { id: 5, name: 'DJI Matrice 300', status: 'Malfunction' }
];
let nextDroneId = 6;

// --- Admin Credentials ---
const ADMIN_USERNAME = 'uavadmin';
const ADMIN_PASSWORD = '321321';

// --- Authentication Middleware ---
// Middleware to check if a user is logged in
const checkAuth = (req, res, next) => {
    if (req.session.isLoggedIn) {
        next();
    } else {
        res.status(401).json({ message: 'Unauthorized: Please log in.' });
    }
};

// Middleware to check if a user is an admin
const checkAdmin = (req, res, next) => {
    if (req.session.isAdmin) {
        next();
    } else {
        res.status(403).json({ message: 'Forbidden: Admin access required.' });
    }
};


// --- API Routes ---

// POST /api/login - Handle user login
app.post('/api/login', (req, res) => {
    const { username, password } = req.body;

    if (username === ADMIN_USERNAME && password === ADMIN_PASSWORD) {
        req.session.isLoggedIn = true;
        req.session.isAdmin = true;
        req.session.username = username;
        res.json({ message: 'Admin login successful!', isAdmin: true, username });
    } else if (username && password) { // Simulate any other valid employee login
        req.session.isLoggedIn = true;
        req.session.isAdmin = false;
        req.session.username = username;
        res.json({ message: 'Employee login successful!', isAdmin: false, username });
    } else {
        res.status(400).json({ message: 'Invalid username or password.' });
    }
});

// GET /api/logout - Handle user logout
app.get('/api/logout', (req, res) => {
    req.session.destroy(err => {
        if (err) {
            return res.status(500).json({ message: 'Could not log out.' });
        }
        res.clearCookie('connect.sid'); // Clear the session cookie
        res.json({ message: 'Logout successful.' });
    });
});

// GET /api/session - Check current session status
app.get('/api/session', (req, res) => {
    if (req.session.isLoggedIn) {
        res.json({
            isLoggedIn: true,
            isAdmin: req.session.isAdmin,
            username: req.session.username
        });
    } else {
        res.json({ isLoggedIn: false });
    }
});

// GET /api/drones - Get all drones
app.get('/api/drones', checkAuth, (req, res) => {
    res.json(drones);
});

// POST /api/drones - Add a new drone (Admin only)
app.post('/api/drones', checkAuth, checkAdmin, (req, res) => {
    const { name } = req.body;
    if (!name) {
        return res.status(400).json({ message: 'Drone name is required.' });
    }
    const newDrone = {
        id: nextDroneId++,
        name: name,
        status: 'Landed' // New drones are always landed initially
    };
    drones.push(newDrone);
    res.status(201).json(newDrone);
});

// PUT /api/drones/:id/control - Control a drone's flight status
app.put('/api/drones/:id/control', checkAuth, (req, res) => {
    const droneId = parseInt(req.params.id, 10);
    const { action } = req.body; // 'takeoff' or 'land'

    const drone = drones.find(d => d.id === droneId);

    if (!drone) {
        return res.status(404).json({ message: 'Drone not found.' });
    }

    if (action === 'takeoff') {
        if (drone.status === 'Landed' || drone.status === 'Charging') {
            drone.status = 'In-Flight';
            res.json({ message: `${drone.name} has taken off.`, drone });
        } else {
            res.status(400).json({ message: `Cannot take off. Drone status is currently '${drone.status}'.` });
        }
    } else if (action === 'land') {
        if (drone.status === 'In-Flight') {
            drone.status = 'Landed';
            res.json({ message: `${drone.name} has landed.`, drone });
        } else {
            res.status(400).json({ message: `Cannot land. Drone is not in flight.` });
        }
    } else {
        res.status(400).json({ message: 'Invalid action specified.' });
    }
});


// --- Start Server ---
app.listen(PORT, () => {
    console.log(`Server is running on http://localhost:${PORT}`);
});
