// public/app.js
document.addEventListener('DOMContentLoaded', () => {
    // --- STATE ---
    const state = {
        isLoggedIn: false,
        isAdmin: false,
        username: null,
        drones: [],
    };

    // --- DOM ELEMENTS ---
    const loginView = document.getElementById('login-view');
    const dashboardView = document.getElementById('dashboard-view');
    const loginForm = document.getElementById('login-form');
    const loginError = document.getElementById('login-error');
    const userGreeting = document.getElementById('user-greeting');
    const logoutBtn = document.getElementById('logout-btn');
    const adminPanel = document.getElementById('admin-panel');
    const addDroneForm = document.getElementById('add-drone-form');
    const adminError = document.getElementById('admin-error');
    const droneListContainer = document.getElementById('drone-list-container');

    // --- API HELPERS ---
    const api = {
        async request(endpoint, options = {}) {
            try {
                const response = await fetch(`/api${endpoint}`, {
                    headers: { 'Content-Type': 'application/json' },
                    ...options,
                });
                if (!response.ok) {
                    const errorData = await response.json();
                    throw new Error(errorData.message || `HTTP error! status: ${response.status}`);
                }
                // Handle responses that might not have a JSON body (e.g., 204 No Content)
                const contentType = response.headers.get("content-type");
                if (contentType && contentType.indexOf("application/json") !== -1) {
                    return response.json();
                }
                return; // Return undefined for non-JSON responses
            } catch (error) {
                console.error(`API Error on ${endpoint}:`, error);
                throw error;
            }
        },
        login(username, password) {
            return this.request('/login', {
                method: 'POST',
                body: JSON.stringify({ username, password }),
            });
        },
        logout() {
            return this.request('/logout');
        },
        checkSession() {
            return this.request('/session');
        },
        getDrones() {
            return this.request('/drones');
        },
        addDrone(name) {
            return this.request('/drones', {
                method: 'POST',
                body: JSON.stringify({ name }),
            });
        },
        controlDrone(id, action) {
            return this.request(`/drones/${id}/control`, {
                method: 'PUT',
                body: JSON.stringify({ action }),
            });
        },
    };

    // --- RENDER FUNCTIONS ---
    const renderDrones = () => {
        droneListContainer.innerHTML = '';
        if (state.drones.length === 0) {
            droneListContainer.innerHTML = '<p>No drones in the fleet.</p>';
            return;
        }

        state.drones.forEach(drone => {
            const statusClass = `status-${drone.status.toLowerCase().replace(' ', '-')}`;
            const canTakeOff = ['Landed', 'Charging'].includes(drone.status);
            const canLand = drone.status === 'In-Flight';

            const card = document.createElement('div');
            card.className = 'drone-card';
            card.innerHTML = `
                <h3>${drone.name} (ID: ${drone.id})</h3>
                <div class="drone-status">
                    <span class="status-indicator ${statusClass}"></span>
                    <span class="status-text">${drone.status}</span>
                </div>
                <div class="drone-controls">
                    <button class="btn btn-success" data-action="takeoff" data-id="${drone.id}" ${!canTakeOff ? 'disabled' : ''}>Take Off</button>
                    <button class="btn btn-secondary" data-action="land" data-id="${drone.id}" ${!canLand ? 'disabled' : ''}>Land</button>
                </div>
            `;
            droneListContainer.appendChild(card);
        });
    };

    const updateUI = () => {
        if (state.isLoggedIn) {
            loginView.classList.add('hidden');
            dashboardView.classList.remove('hidden');
            userGreeting.textContent = `Welcome, ${state.isAdmin ? 'Admin' : 'Employee'} (${state.username})`;
            adminPanel.classList.toggle('hidden', !state.isAdmin);
            fetchAndRenderDrones();
        } else {
            loginView.classList.remove('hidden');
            dashboardView.classList.add('hidden');
        }
    };

    // --- DATA FETCHING ---
    const fetchAndRenderDrones = async () => {
        try {
            const drones = await api.getDrones();
            state.drones = drones;
            renderDrones();
        } catch (error) {
            droneListContainer.innerHTML = `<p class="error-message">Error fetching drones: ${error.message}</p>`;
        }
    };

    // --- EVENT HANDLERS ---
    const handleLogin = async (e) => {
        e.preventDefault();
        loginError.textContent = '';
        const username = loginForm.username.value.trim();
        const password = loginForm.password.value.trim();

        try {
            const data = await api.login(username, password);
            state.isLoggedIn = true;
            state.isAdmin = data.isAdmin;
            state.username = data.username;
            loginForm.reset();
            updateUI();
        } catch (error) {
            loginError.textContent = error.message;
        }
    };

    const handleLogout = async () => {
        try {
            await api.logout();
            state.isLoggedIn = false;
            state.isAdmin = false;
            state.username = null;
            state.drones = [];
            updateUI();
        } catch (error) {
            alert(`Logout failed: ${error.message}`);
        }
    };

    const handleAddDrone = async (e) => {
        e.preventDefault();
        adminError.textContent = '';
        const droneNameInput = document.getElementById('drone-name');
        const name = droneNameInput.value.trim();

        if (!name) {
            adminError.textContent = 'Drone name cannot be empty.';
            return;
        }

        try {
            await api.addDrone(name);
            droneNameInput.value = ''; // Clear input
            fetchAndRenderDrones(); // Refresh the list
        } catch (error) {
            adminError.textContent = error.message;
        }
    };

    const handleDroneControl = async (e) => {
        const target = e.target;
        if (target.tagName === 'BUTTON' && target.dataset.action) {
            const id = target.dataset.id;
            const action = target.dataset.action;

            try {
                await api.controlDrone(id, action);
                fetchAndRenderDrones(); // Refresh the list to show updated status
            } catch (error) {
                alert(`Action failed: ${error.message}`);
            }
        }
    };

    // --- INITIALIZATION ---
    const initialize = async () => {
        try {
            const sessionData = await api.checkSession();
            if (sessionData.isLoggedIn) {
                state.isLoggedIn = true;
                state.isAdmin = sessionData.isAdmin;
                state.username = sessionData.username;
            }
        } catch (error) {
            // If session check fails, assume logged out
            console.error("Session check failed, proceeding as logged out.", error);
            state.isLoggedIn = false;
        }
        updateUI();
    };

    // --- ATTACH EVENT LISTENERS ---
    loginForm.addEventListener('submit', handleLogin);
    logoutBtn.addEventListener('click', handleLogout);
    addDroneForm.addEventListener('submit', handleAddDrone);
    droneListContainer.addEventListener('click', handleDroneControl);

    // --- START THE APP ---
    initialize();
});
