    <script>
        // Mock Data: A Base64 encoded sample image to allow immediate use of the tool.
        const MOCK_IMAGE_DATA = "data:image/jpeg;base64,-";

        document.addEventListener('DOMContentLoaded', () => {
            // DOM element references
            const imageLoader = document.getElementById('imageLoader');
            const brushSizeSlider = document.getElementById('brushSize');
            const brushSizeValue = document.getElementById('brushSizeValue');
            const processBtn = document.getElementById('processBtn');
            const downloadBtn = document.getElementById('downloadBtn');
            const clearMaskBtn = document.getElementById('clearMaskBtn');

            const editorContainer = document.getElementById('editor');
            const resultViewer = document.getElementById('resultViewer');

            const imageCanvas = document.getElementById('imageCanvas');
            const maskCanvas = document.getElementById('maskCanvas');
            const resultCanvas = document.getElementById('resultCanvas');

            const imageCtx = imageCanvas.getContext('2d');
            const maskCtx = maskCanvas.getContext('2d');
            const resultCtx = resultCanvas.getContext('2d');

            // State variables
            let isDrawing = false;
            let lastX = 0;
            let lastY = 0;
            let brushSize = 40;
            let originalImage = null;

            /**
             * Initializes the application by setting up event listeners and loading a default image.
             */
            function init() {
                // Event Listeners
                imageLoader.addEventListener('change', handleImageUpload);
                brushSizeSlider.addEventListener('input', handleBrushSizeChange);
                processBtn.addEventListener('click', applyMatting);
                downloadBtn.addEventListener('click', downloadImage);
                clearMaskBtn.addEventListener('click', clearMask);

                // Mouse events for drawing on the mask canvas
                maskCanvas.addEventListener('mousedown', startDrawing);
                maskCanvas.addEventListener('mousemove', draw);
                maskCanvas.addEventListener('mouseup', stopDrawing);
                maskCanvas.addEventListener('mouseout', stopDrawing);

                // Load a default image for demonstration purposes
                loadDefaultImage();
            }

            /**
             * Loads a default image from a Base64 string.
             */
            function loadDefaultImage() {
                const img = new Image();
                img.crossOrigin = "Anonymous"; // Handle potential CORS issues if loading from URL
                img.onload = () => {
                    originalImage = img;
                    setupCanvases(img);
                };
                img.src = MOCK_IMAGE_DATA;
            }

            /**
             * Handles the user uploading a new image file.
             * @param {Event} e - The file input change event.
             */
            function handleImageUpload(e) {
                const file = e.target.files[0];
                if (!file) return;

                const reader = new FileReader();
                reader.onload = (event) => {
                    const img = new Image();
                    img.onload = () => {
                        originalImage = img;
                        setupCanvases(img);
                    };
                    img.src = event.target.result;
                };
                reader.readAsDataURL(file);
            }

            /**
             * Sets up the dimensions and content of the canvases based on the loaded image.
             * @param {HTMLImageElement} img - The image to display.
             */
            function setupCanvases(img) {
                const { width, height } = img;

                // Set canvas dimensions
                [imageCanvas, maskCanvas, resultCanvas].forEach(canvas => {
                    canvas.width = width;
                    canvas.height = height;
                });

                // Set container dimensions
                editorContainer.style.width = `${width}px`;
                editorContainer.style.height = `${height}px`;
                resultViewer.style.width = `${width}px`;
                resultViewer.style.height = `${height}px`;

                // Draw the image on the image canvas
                imageCtx.drawImage(img, 0, 0);

                // Clear any previous mask and result
                clearMask();
                resultCtx.clearRect(0, 0, width, height);
                resultViewer.classList.add('hidden');
                downloadBtn.classList.add('hidden');

                // Enable controls
                processBtn.disabled = false;
                clearMaskBtn.disabled = false;
            }

            /**
             * Clears the user-drawn mask from the mask canvas.
             */
            function clearMask() {
                maskCtx.clearRect(0, 0, maskCanvas.width, maskCanvas.height);
            }

            /**
             * Handles changes to the brush size slider.
             */
            function handleBrushSizeChange() {
                brushSize = this.value;
                brushSizeValue.textContent = `${brushSize}px`;
            }

            /**
             * Gets the mouse position relative to the canvas.
             * @param {MouseEvent} e - The mouse event.
             * @returns {{x: number, y: number}} The coordinates.
             */
            function getMousePos(e) {
                const rect = maskCanvas.getBoundingClientRect();
                return {
                    x: e.clientX - rect.left,
                    y: e.clientY - rect.top
                };
            }

            /**
             * Starts the drawing process on mousedown.
             * @param {MouseEvent} e - The mouse event.
             */
            function startDrawing(e) {
                isDrawing = true;
                const pos = getMousePos(e);
                [lastX, lastY] = [pos.x, pos.y];
            }

            /**
             * Draws a line on the mask canvas as the mouse moves.
             * @param {MouseEvent} e - The mouse event.
             */
            function draw(e) {
                if (!isDrawing) return;

                const pos = getMousePos(e);
                maskCtx.beginPath();
                maskCtx.strokeStyle = 'rgba(255, 0, 150, 1)'; // A bright color for the mask
                maskCtx.lineWidth = brushSize;
                maskCtx.lineCap = 'round';
                maskCtx.lineJoin = 'round';
                maskCtx.moveTo(lastX, lastY);
                maskCtx.lineTo(pos.x, pos.y);
                maskCtx.stroke();

                [lastX, lastY] = [pos.x, pos.y];
            }

            /**
             * Stops the drawing process on mouseup or mouseout.
             */
            function stopDrawing() {
                isDrawing = false;
            }

            /**
             * Core matting logic. It combines the original image and the mask
             * to create a new image with a transparent background.
             */
            function applyMatting() {
                if (!originalImage) {
                    alert("Please load an image first.");
                    return;
                }

                const width = imageCanvas.width;
                const height = imageCanvas.height;

                // Get pixel data from both the original image and the drawn mask
                const imageData = imageCtx.getImageData(0, 0, width, height);
                const maskData = maskCtx.getImageData(0, 0, width, height);

                const imagePixels = imageData.data;
                const maskPixels = maskData.data;

                // Create a new ImageData object for the result
                const resultImageData = resultCtx.createImageData(width, height);
                const resultPixels = resultImageData.data;

                // Iterate over each pixel (each pixel has 4 values: R, G, B, A)
                for (let i = 0; i < imagePixels.length; i += 4) {
                    // The mask is drawn in a solid color. We only care about its alpha channel.
                    // If the mask pixel's alpha is > 0, it means the user has painted there.
                    const isMasked = maskPixels[i + 3] > 0;

                    if (isMasked) {
                        // Copy the original pixel's color (R, G, B)
                        resultPixels[i] = imagePixels[i];
                        resultPixels[i + 1] = imagePixels[i + 1];
                        resultPixels[i + 2] = imagePixels[i + 2];
                        // Set the alpha to fully opaque
                        resultPixels[i + 3] = 255;
                    } else {
                        // If not masked, make the pixel fully transparent
                        // R, G, B values don't matter but we set them to 0
                        resultPixels[i] = 0;
                        resultPixels[i + 1] = 0;
                        resultPixels[i + 2] = 0;
                        // Set the alpha to fully transparent
                        resultPixels[i + 3] = 0;
                    }
                }

                // Put the new pixel data onto the result canvas
                resultCtx.putImageData(resultImageData, 0, 0);

                // Show the result viewer and download button
                resultViewer.classList.remove('hidden');
                downloadBtn.classList.remove('hidden');
            }

            /**
             * Triggers a download of the result canvas content as a PNG file.
             */
            function downloadImage() {
                // Create a temporary link element
                const link = document.createElement('a');

                // Set the download filename
                link.download = 'matted-image.png';

                // Convert the canvas to a PNG data URL. PNG is required for transparency.
                link.href = resultCanvas.toDataURL('image/png');

                // Programmatically click the link to start the download
                link.click();
            }

            // Start the application
            init();
        });
    </script>

</body>
