import json
from flask import Flask, jsonify, request, render_template
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy import func
import datetime

# --- App & DB Configuration ---
app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///learning_partners.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
db = SQLAlchemy(app)

# --- Database Models ---
class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80), unique=True, nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)
    profile = db.relationship('Profile', backref='user', uselist=False, cascade="all, delete-orphan")

class Profile(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    learning_goals = db.Column(db.String(500), nullable=False) # Stored as JSON string
    interests = db.Column(db.String(500), nullable=False) # Stored as JSON string
    availability = db.Column(db.String(500), nullable=False) # Stored as JSON string
    reputation_score = db.Column(db.Float, default=4.0)

class Partnership(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    user1_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    user2_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    start_date = db.Column(db.DateTime, default=datetime.datetime.utcnow)
    status = db.Column(db.String(20), default='active')

class Feedback(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    partnership_id = db.Column(db.Integer, db.ForeignKey('partnership.id'), nullable=False)
    reviewer_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    reviewee_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    rating = db.Column(db.Integer, nullable=False) # 1-5 scale

# --- Helper Functions ---
def jaccard_similarity(set1, set2):
    """Calculates the Jaccard similarity between two sets."""
    intersection = len(set1.intersection(set2))
    union = len(set1.union(set2))
    return intersection / union if union != 0 else 0

def calculate_match_score(profile1, profile2):
    """The core matching algorithm."""
    # Weights for each component
    W_GOALS = 0.4
    W_INTERESTS = 0.2
    W_TIME = 0.3
    W_REPUTATION = 0.1

    # Decode JSON strings into Python objects
    goals1 = set(json.loads(profile1.learning_goals))
    goals2 = set(json.loads(profile2.learning_goals))
    interests1 = set(json.loads(profile1.interests))
    interests2 = set(json.loads(profile2.interests))
    avail1 = json.loads(profile1.availability)
    avail2 = json.loads(profile2.availability)

    # Calculate component scores
    score_goals = jaccard_similarity(goals1, goals2)
    score_interests = jaccard_similarity(interests1, interests2)

    # Time score: count overlapping available slots
    common_slots = sum(1 for k in avail1 if k in avail2 and avail1[k] and avail2[k])
    total_slots = len(set(avail1.keys()) | set(avail2.keys()))
    score_time = common_slots / total_slots if total_slots > 0 else 0

    # Reputation score (normalized from 1-5 to 0-1)
    score_reputation = (profile2.reputation_score - 1) / 4

    # Final weighted score
    final_score = (W_GOALS * score_goals) + \
                  (W_INTERESTS * score_interests) + \
                  (W_TIME * score_time) + \
                  (W_REPUTATION * score_reputation)

    return final_score

# --- API Endpoints ---
@app.route('/')
def index():
    return render_template('index.html')

@app.route('/api/users', methods=['GET'])
def get_users():
    users = User.query.all()
    return jsonify([{'id': u.id, 'name': u.name} for u in users])

@app.route('/api/match/<int:user_id>', methods=['GET'])
def get_matches(user_id):
    current_user = User.query.get_or_404(user_id)
    current_profile = current_user.profile

    if not current_profile:
        return jsonify({"error": "Current user does not have a profile"}), 404

    all_other_users = User.query.filter(User.id != user_id).all()

    # Get history of partners to avoid re-matching immediately
    past_partners_ids = {p.user2_id for p in Partnership.query.filter_by(user1_id=user_id).all()} | \
                        {p.user1_id for p in Partnership.query.filter_by(user2_id=user_id).all()}

    matches = []
    for other_user in all_other_users:
        if other_user.id in past_partners_ids:
            continue # Skip past partners for this demo

        other_profile = other_user.profile
        if other_profile:
            score = calculate_match_score(current_profile, other_profile)
            if score > 0.2: # Set a threshold to only show relevant matches
                matches.append({
                    'user_id': other_user.id,
                    'name': other_user.name,
                    'score': round(score * 100, 2),
                    'details': {
                        'learning_goals': json.loads(other_profile.learning_goals),
                        'interests': json.loads(other_profile.interests)
                    }
                })

    # Sort matches by score in descending order
    matches.sort(key=lambda x: x['score'], reverse=True)
    return jsonify(matches)

