```javascript
document.addEventListener('DOMContentLoaded', () => {
    const userSelect = document.getElementById('user-select');
    const findMatchesBtn = document.getElementById('find-matches-btn');
    const matchesList = document.getElementById('matches-list');

    // Fetch all users to populate the dropdown
    async function populateUsers() {
        try {
            const response = await fetch('/api/users');
            const users = await response.json();
            users.forEach(user => {
                const option = document.createElement('option');
                option.value = user.id;
                option.textContent = user.name;
                userSelect.appendChild(option);
            });
        } catch (error) {
            console.error('Failed to load users:', error);
        }
    }

    // Find and display matches for the selected user
    async function findMatches() {
        const userId = userSelect.value;
        if (!userId) return;

        matchesList.innerHTML = '<p class="placeholder">Finding best matches...</p>';

        try {
            const response = await fetch(`/api/match/${userId}`);
            const matches = await response.json();
            displayMatches(matches);
        } catch (error) {
            console.error('Failed to find matches:', error);
            matchesList.innerHTML = '<p class="placeholder">Error finding matches. Please try again.</p>';
        }
    }

    // Render the list of matches
    function displayMatches(matches) {
        matchesList.innerHTML = ''; // Clear previous results

        if (matches.length === 0) {
            matchesList.innerHTML = '<p class="placeholder">No suitable matches found at this time.</p>';
            return;
        }

        matches.forEach(match => {
            const card = document.createElement('div');
            card.className = 'match-card';

            const goalsHtml = match.details.learning_goals.map(g => `<span class="tag">${g}</span>`).join('');
            const interestsHtml = match.details.interests.map(i => `<span class="tag">${i}</span>`).join('');

            card.innerHTML = `
                <div class="match-info">
                    <h3>${match.name}</h3>
                    <div class="match-details">
                        <strong>Goals:</strong> ${goalsHtml}<br>
                        <strong>Interests:</strong> ${interestsHtml}
                    </div>
                </div>
                <div class="match-actions">
                    <div class="match-score">${match.score}%</div>
                    <button class="invite-btn" data-to-id="${match.user_id}">Invite</button>
                </div>
            `;
            matchesList.appendChild(card);
        });
    }

    // Handle invitation clicks
    matchesList.addEventListener('click', async (event) => {
        if (event.target.classList.contains('invite-btn')) {
            const fromId = userSelect.value;
            const toId = event.target.dataset.toId;

            event.target.disabled = true;
            event.target.textContent = 'Sent!';

            try {
                const response = await fetch('/api/invite', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ from_id: fromId, to_id: toId })
                });
                const result = await response.json();
                console.log(result.message);
            } catch (error) {
                console.error('Failed to send invitation:', error);
                event.target.textContent = 'Failed';
            }
        }
    });

    findMatchesBtn.addEventListener('click', findMatches);
    populateUsers();
});
