def start_negotiation():
    """
    Initiates a price negotiation for a product.
    Simulates a buyer making an offer.
    """
    data = request.get_json()
    product_id = data.get('productId')
    offer_price = data.get('offerPrice')
    buyer_id = data.get('buyerId') # In a real app, this would come from session/token

    if not all([product_id, offer_price, buyer_id]):
        return jsonify({"error": "Missing data"}), 400

    product = DB['products'].get(product_id)
    if not product:
        return jsonify({"error": "Product not found"}), 404

    negotiation_id = len(DB['negotiations']) + 1
    new_negotiation = {
        "id": negotiation_id,
        "product_id": product_id,
        "buyer_id": buyer_id,
        "seller_id": product['seller_id'],
        "offer_price": float(offer_price),
        "status": "pending", # 'pending', 'accepted', 'rejected', 'paid'
        "timestamp": datetime.datetime.now()
    }
    DB['negotiations'][negotiation_id] = new_negotiation

    # Simulate seller response after a short delay
    if float(offer_price) >= product['price'] * 0.85: # Auto-accept if offer is >= 85% of price
        new_negotiation['status'] = 'accepted'
    else:
        new_negotiation['status'] = 'rejected'

    return jsonify({
        "message": "Negotiation initiated!",
        "negotiation_id": negotiation_id,
        "status": new_negotiation['status']
    }), 201

@app.route('/api/negotiations/<int:negotiation_id>/pay', methods=['POST'])
def complete_payment(negotiation_id):
    """Simulates completing the payment after a deal is accepted."""
    negotiation = DB['negotiations'].get(negotiation_id)
    if not negotiation:
        return jsonify({"error": "Negotiation not found"}), 404

    if negotiation['status'] != 'accepted':
        return jsonify({"error": "Offer not accepted yet"}), 400

    negotiation['status'] = 'paid'
    product_id = negotiation['product_id']
    DB['products'][product_id]['status'] = 'sold'

    return jsonify({
        "message": "Payment successful! The item is yours.",
        "product_id": product_id
    })

# --- Main Execution ---
if __name__ == '__main__':
    app.run(debug=True)
