### **Step 4: Frontend - JavaScript Logic (`static/js/app.js`)**

This file handles all the dynamic behavior of the application.

```javascript
// static/js/app.js
document.addEventListener('DOMContentLoaded', () => {
    const API_BASE_URL = 'http://127.0.0.1:5000';
    const CURRENT_USER_ID = 2; // Simulate logged-in user (Bob)

    // View elements
    const productListingView = document.getElementById('product-listing-view');
    const productDetailView = document.getElementById('product-detail-view');
    const productGrid = document.getElementById('product-grid');
    const sortSelect = document.getElementById('sort-by');
    const homeLink = document.getElementById('home-link');

    // Modal elements
    const negotiationModal = document.getElementById('negotiation-modal');
    const closeModalBtn = negotiationModal.querySelector('.close-button');
    const submitOfferBtn = document.getElementById('submit-offer-btn');
    const negotiationStatusDiv = document.getElementById('negotiation-status');

    let currentProductId = null;

    // --- API Fetch Functions ---

    const fetchProducts = async (sortBy = 'time_desc') => {
        try {
            const response = await fetch(`${API_BASE_URL}/api/products?sort_by=${sortBy}`);
            if (!response.ok) throw new Error('Network response was not ok');
            const products = await response.json();
            renderProductGrid(products);
        } catch (error) {
            console.error('Failed to fetch products:', error);
            productGrid.innerHTML = '<p>Error loading products. Please try again later.</p>';
        }
    };

    const fetchProductDetail = async (productId) => {
        try {
            const response = await fetch(`${API_BASE_URL}/api/products/${productId}`);
            if (!response.ok) throw new Error('Network response was not ok');
            const product = await response.json();
            renderProductDetail(product);
            showView('detail');
        } catch (error) {
            console.error(`Failed to fetch product ${productId}:`, error);
        }
    };

    // --- Render Functions ---

    const renderProductGrid = (products) => {
        productGrid.innerHTML = ''; // Clear existing products
        products.forEach(product => {
            const card = document.createElement('div');
            card.className = 'product-card';
            card.dataset.productId = product.id;
            card.innerHTML = `
                <img src="${product.image_url}" alt="${product.title}">
                <div class="product-card-info">
                    <h3>${product.title}</h3>
                    <p class="product-price">$${product.price.toFixed(2)}</p>
                    <p class="product-seller">Seller Rating: ${product.seller_rating} ★</p>
                </div>
            `;
            card.addEventListener('click', () => fetchProductDetail(product.id));
            productGrid.appendChild(card);
        });
    };

    const renderProductDetail = (product) => {
        currentProductId = product.id;
        productDetailView.innerHTML = `
            <div class="product-image">
                <img src="${product.image_url}" alt="${product.title}">
            </div>
            <div class="product-details">
                <h2>${product.title}</h2>
                <p class="product-price" style="font-size: 1.5rem;">$${product.price.toFixed(2)}</p>
                <p>${product.description}</p>
                <div class="seller-info">
                    <h4>Seller Information</h4>
                    <p><strong>Username:</strong> ${product.seller.username}</p>
                    <p><strong>Rating:</strong> ${product.seller.rating} ★ (${product.seller.items_sold} items sold)</p>
                </div>
                <div class="action-buttons">
                    <button id="negotiate-btn">Negotiate Price</button>
                    <button id="back-to-list-btn">Back to List</button>
                </div>
            </div>
        `;
        // Add event listeners for the new buttons
        document.getElementById('back-to-list-btn').addEventListener('click', () => showView('listing'));
        document.getElementById('negotiate-btn').addEventListener('click', () => openNegotiationModal(product));
    };

    // --- View Management ---

    const showView = (viewName) => {
        productListingView.classList.add('hidden');
        productDetailView.classList.add('hidden');

        if (viewName === 'listing') {
            productListingView.classList.remove('hidden');
        } else if (viewName === 'detail') {
            productDetailView.classList.remove('hidden');
        }
    };

    // --- Negotiation Modal Logic ---

    const openNegotiationModal = (product) => {
        document.getElementById('modal-product-title').textContent = product.title;
        document.getElementById('modal-list-price').textContent = `$${product.price.toFixed(2)}`;
        document.getElementById('offer-price').value = '';
        negotiationStatusDiv.innerHTML = '';
        negotiationStatusDiv.className = 'negotiation-status';
        negotiationModal.classList.remove('hidden');
    };

    const closeNegotiationModal = () => {
        negotiationModal.classList.add('hidden');
    };

    const handleOfferSubmit = async () => {
        const offerPrice = document.getElementById('offer-price').value;
        if (!offerPrice || isNaN(offerPrice) || offerPrice <= 0) {
            alert('Please enter a valid offer price.');
            return;
        }

        negotiationStatusDiv.className = 'negotiation-status status-pending';
        negotiationStatusDiv.textContent = 'Submitting your offer...';

        try {
            const response = await fetch(`${API_BASE_URL}/api/negotiations`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    productId: currentProductId,
                    offerPrice: parseFloat(offerPrice),
                    buyerId: CURRENT_USER_ID
                })
            });
            const result = await response.json();

            if (response.ok) {
                if (result.status === 'accepted') {
                    negotiationStatusDiv.className = 'negotiation-status status-success';
                    negotiationStatusDiv.innerHTML = `Offer accepted! You can now proceed to payment. <button id="pay-btn" data-neg-id="${result.negotiation_id}">Pay Now</button>`;
                    document.getElementById('pay-btn').addEventListener('click', handlePayment);
                } else {
                    negotiationStatusDiv.className = 'negotiation-status status-fail';
                    negotiationStatusDiv.textContent = 'Sorry, your offer was not accepted by the seller.';
                }
            } else {
                throw new Error(result.error || 'Failed to submit offer.');
            }
        } catch (error) {
            negotiationStatusDiv.className = 'negotiation-status status-fail';
            negotiationStatusDiv.textContent = `Error: ${error.message}`;
        }
    };

    const handlePayment = async (event) => {
        const negotiationId = event.target.dataset.negId;
        negotiationStatusDiv.className = 'negotiation-status status-pending';
        negotiationStatusDiv.textContent = 'Processing payment...';

        try {
            const response = await fetch(`${API_BASE_URL}/api/negotiations/${negotiationId}/pay`, { method: 'POST' });
            const result = await response.json();
            if (!response.ok) throw new Error(result.error);

            negotiationStatusDiv.className = 'negotiation-status status-success';
            negotiationStatusDiv.textContent = result.message;

            // After successful payment, refresh list and go home
            setTimeout(() => {
                closeNegotiationModal();
                showView('listing');
                fetchProducts(sortSelect.value);
            }, 2000);

        } catch (error) {
            negotiationStatusDiv.className = 'negotiation-status status-fail';
            negotiationStatusDiv.textContent = `Payment failed: ${error.message}`;
        }
    };

    // --- Event Listeners ---

    sortSelect.addEventListener('change', (e) => {
        fetchProducts(e.target.value);
    });

    homeLink.addEventListener('click', (e) => {
        e.preventDefault();
        showView('listing');
    });

    closeModalBtn.addEventListener('click', closeNegotiationModal);
    submitOfferBtn.addEventListener('click', handleOfferSubmit);

    // --- Initial Load ---
    fetchProducts();
});
```

