### 3. `wav-encoder.js` (Audio Encoding Utility)

This standalone module handles the complex task of converting the raw audio data (`AudioBuffer`) from the Web Audio API into a standard WAV file format (`Blob`). This promotes code modularity.

```javascript
/**
 * Encodes an AudioBuffer into a WAV file format (Blob).
 * This function is self-contained and does not rely on external libraries.
 * @param {AudioBuffer} buffer The audio buffer to encode.
 * @returns {Blob} A blob representing the WAV file.
 */
function bufferToWav(buffer) {
    const numOfChan = buffer.numberOfChannels;
    const length = buffer.length * numOfChan * 2 + 44;
    const buffer_ = new ArrayBuffer(length);
    const view = new DataView(buffer_);
    const channels = [];
    let i;
    let sample;
    let offset = 0;
    let pos = 0;

    // Helper function to write strings
    function writeString(view, offset, string) {
        for (let i = 0; i < string.length; i++) {
            view.setUint8(offset + i, string.charCodeAt(i));
        }
    }

    // RIFF chunk descriptor
    writeString(view, pos, 'RIFF'); pos += 4;
    view.setUint32(pos, length - 8, true); pos += 4;
    writeString(view, pos, 'WAVE'); pos += 4;

    // FMT sub-chunk
    writeString(view, pos, 'fmt '); pos += 4;
    view.setUint32(pos, 16, true); pos += 4; // Subchunk1Size
    view.setUint16(pos, 1, true); pos += 2; // AudioFormat (PCM)
    view.setUint16(pos, numOfChan, true); pos += 2; // NumChannels
    view.setUint32(pos, buffer.sampleRate, true); pos += 4; // SampleRate
    view.setUint32(pos, buffer.sampleRate * 2 * numOfChan, true); pos += 4; // ByteRate
    view.setUint16(pos, numOfChan * 2, true); pos += 2; // BlockAlign
    view.setUint16(pos, 16, true); pos += 2; // BitsPerSample

    // DATA sub-chunk
    writeString(view, pos, 'data'); pos += 4;
    view.setUint32(pos, length - pos - 4, true); pos += 4;

    // Write the PCM samples
    for (i = 0; i < buffer.numberOfChannels; i++) {
        channels.push(buffer.getChannelData(i));
    }

    while (pos < length) {
        for (i = 0; i < numOfChan; i++) {
            sample = Math.max(-1, Math.min(1, channels[i][offset])); // Clamp
            sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767) | 0; // Scale to 16-bit signed int
            view.setInt16(pos, sample, true);
            pos += 2;
        }
        offset++;
    }

    return new Blob([view], { type: 'audio/wav' });
}
```

