### 4. `script.js` (The Core Application Logic)

This is the heart of the application, handling user interactions, recording, audio processing, and visualization.

```javascript
document.addEventListener('DOMContentLoaded', () => {
    // DOM Element References
    const recordBtn = document.getElementById('recordBtn');
    const stopBtn = document.getElementById('stopBtn');
    const playBtn = document.getElementById('playBtn');
    const downloadBtn = document.getElementById('downloadBtn');
    const trimBtn = document.getElementById('trimBtn');
    const addSfxBtn = document.getElementById('addSfxBtn');
    const statusText = document.getElementById('status');
    const waveformCanvas = document.getElementById('waveformCanvas');
    const editingControls = document.getElementById('editing-controls');
    const trimStartInput = document.getElementById('trimStart');
    const trimEndInput = document.getElementById('trimEnd');
    const sfxTimeInput = document.getElementById('sfxTime');

    // Web Audio API Setup
    const audioContext = new (window.AudioContext || window.webkitAudioContext)();

    // App State
    let mediaRecorder;
    let recordedChunks = [];
    let audioBuffer; // This will hold the decoded audio data for editing
    let sfxBuffer;   // This will hold the sound effect audio data

    // --- Core Functions ---

    /**
     * Initializes the application, requests microphone access, and loads sound effects.
     */
    async function initialize() {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            setupMediaRecorder(stream);
            await loadSoundEffect('assets/click.wav');
            statusText.textContent = 'Status: Ready to record';
        } catch (err) {
            console.error('Error accessing microphone:', err);
            statusText.textContent = 'Error: Microphone access denied.';
            alert('Microphone access is required to use this application.');
        }
    }

    /**
     * Sets up the MediaRecorder instance with the provided audio stream.
     * @param {MediaStream} stream The audio stream from the microphone.
     */
    function setupMediaRecorder(stream) {
        mediaRecorder = new MediaRecorder(stream);

        mediaRecorder.ondataavailable = (event) => {
            if (event.data.size > 0) {
                recordedChunks.push(event.data);
            }
        };

        mediaRecorder.onstop = async () => {
            const audioBlob = new Blob(recordedChunks, { type: 'audio/webm' });
            recordedChunks = []; // Clear chunks for next recording

            // Decode the audio blob into an AudioBuffer for processing
            const arrayBuffer = await audioBlob.arrayBuffer();
            audioBuffer = await audioContext.decodeAudioData(arrayBuffer);

            updateUIForEditing();
            drawWaveform(audioBuffer);
        };
    }

    /**
     * Loads a sound effect from a URL and decodes it into an AudioBuffer.
     * @param {string} url The URL of the sound effect file.
     */
    async function loadSoundEffect(url) {
        try {
            const response = await fetch(url);
            const arrayBuffer = await response.arrayBuffer();
            sfxBuffer = await audioContext.decodeAudioData(arrayBuffer);
            console.log('Sound effect loaded successfully.');
        } catch (error) {
            console.error('Failed to load sound effect:', error);
        }
    }

    // --- UI Update Functions ---

    function updateUIForRecording() {
        statusText.textContent = 'Status: Recording...';
        recordBtn.disabled = true;
        stopBtn.disabled = false;
        editingControls.classList.add('hidden');
    }

    function updateUIForEditing() {
        statusText.textContent = 'Status: Ready to edit/play';
        recordBtn.disabled = false;
        stopBtn.disabled = true;
        playBtn.disabled = false;
        downloadBtn.disabled = false;
        editingControls.classList.remove('hidden');

        // Set trim input defaults to the full duration
        const duration = audioBuffer.duration.toFixed(1);
        trimStartInput.value = 0;
        trimEndInput.value = duration;
        trimEndInput.max = duration;
        sfxTimeInput.max = duration;
    }

    // --- Audio Processing and Visualization ---

    /**
     * Draws the waveform of an AudioBuffer onto a canvas.
     * @param {AudioBuffer} buffer The audio buffer to visualize.
     */
    function drawWaveform(buffer) {
        const canvas = waveformCanvas;
        const ctx = canvas.getContext('2d');
        const width = canvas.width;
        const height = canvas.height;
        const data = buffer.getChannelData(0);

        ctx.clearRect(0, 0, width, height);
        ctx.lineWidth = 2;
        ctx.strokeStyle = 'rgb(74, 144, 226)';
        ctx.beginPath();

        const sliceWidth = width * 1.0 / data.length;
        let x = 0;

        for (let i = 0; i < data.length; i++) {
            const v = data[i] * height / 2;
            const y = height / 2 + v;

            if (i === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
            x += sliceWidth;
        }

        ctx.lineTo(width, height / 2);
        ctx.stroke();
    }

    /**
     * Plays a segment of the current audio buffer.
     * @param {number} startTime The time in seconds to start playback.
     * @param {number} duration The duration in seconds to play.
     */
    function playAudio(startTime = 0, duration = audioBuffer.duration) {
        const source = audioContext.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(audioContext.destination);
        source.start(0, startTime, duration);
    }

    // --- Event Listeners ---

    recordBtn.addEventListener('click', () => {
        if (mediaRecorder && mediaRecorder.state === 'inactive') {
            mediaRecorder.start();
            updateUIForRecording();
        }
    });

    stopBtn.addEventListener('click', () => {
        if (mediaRecorder && mediaRecorder.state === 'recording') {
            mediaRecorder.stop();
        }
    });

    playBtn.addEventListener('click', () => {
        if (audioBuffer) {
            playAudio();
        }
    });

    trimBtn.addEventListener('click', () => {
        if (!audioBuffer) return;

        const startTime = parseFloat(trimStartInput.value);
        const endTime = parseFloat(trimEndInput.value);

        if (startTime >= endTime || startTime < 0 || endTime > audioBuffer.duration) {
            alert('Invalid trim times.');
            return;
        }

        const startOffset = Math.floor(startTime * audioBuffer.sampleRate);
        const endOffset = Math.floor(endTime * audioBuffer.sampleRate);
        const frameCount = endOffset - startOffset;

        const newBuffer = audioContext.createBuffer(
            audioBuffer.numberOfChannels,
            frameCount,
            audioBuffer.sampleRate
        );

        for (let i = 0; i < audioBuffer.numberOfChannels; i++) {
            const channelData = audioBuffer.getChannelData(i);
            const newChannelData = newBuffer.getChannelData(i);
            newChannelData.set(channelData.subarray(startOffset, endOffset));
        }

        audioBuffer = newBuffer; // Replace the old buffer with the trimmed one
        drawWaveform(audioBuffer);
        updateUIForEditing(); // Update inputs with new duration
        statusText.textContent = 'Status: Trim applied.';
    });

    addSfxBtn.addEventListener('click', async () => {
        if (!audioBuffer || !sfxBuffer) return;

        const sfxTime = parseFloat(sfxTimeInput.value);
        if (sfxTime < 0 || sfxTime > audioBuffer.duration) {
            alert('Invalid sound effect time.');
            return;
        }

        // Use an OfflineAudioContext for non-real-time mixing
        const offlineCtx = new OfflineAudioContext(
            audioBuffer.numberOfChannels,
            audioBuffer.length,
            audioBuffer.sampleRate
        );

        // Add original audio source
        const mainSource = offlineCtx.createBufferSource();
        mainSource.buffer = audioBuffer;
        mainSource.connect(offlineCtx.destination);
        mainSource.start(0);

        // Add sound effect source
        const sfxSource = offlineCtx.createBufferSource();
        sfxSource.buffer = sfxBuffer;
        sfxSource.connect(offlineCtx.destination);
        sfxSource.start(sfxTime);

        // Render the mixed audio
        const mixedBuffer = await offlineCtx.startRendering();

        audioBuffer = mixedBuffer; // Replace buffer with the mixed version
        drawWaveform(audioBuffer);
        statusText.textContent = 'Status: Sound effect added.';
    });

    downloadBtn.addEventListener('click', () => {
        if (audioBuffer) {
            const wavBlob = bufferToWav(audioBuffer);
            const url = URL.createObjectURL(wavBlob);
            const a = document.createElement('a');
            a.style.display = 'none';
            a.href = url;
            a.download = 'edited-audio.wav';
            document.body.appendChild(a);
            a.click();
            window.URL.revokeObjectURL(url);
            a.remove();
        }
    });

    // --- Initializer Call ---
    initialize();
});
```

