const express = require('express');
const cors = require('cors');
const Handlebars = require('handlebars');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(cors());
app.use(express.json());

// --- In-Memory Database ---
let campaigns = {};
let sendLogs = {};

// --- 1. Template Processing & A/B Testing Logic ---
app.post('/api/campaigns/send', (req, res) => {
    const { contacts, versionA, versionB } = req.body;
    const campaignId = `camp_${uuidv4()}`;

    const campaign = {
        id: campaignId,
        totalSent: contacts.length,
        variants: {
            A: { name: versionA.name, sent: 0, opens: 0, template: versionA.template },
            B: { name: versionB.name, sent: 0, opens: 0, template: versionB.template }
        },
        createdAt: new Date()
    };

    // Simple 50/50 A/B split
    contacts.forEach((contact, index) => {
        const variantKey = index % 2 === 0 ? 'A' : 'B';
        const variant = campaign.variants[variantKey];
        const sendId = uuidv4();

        // a. Compile template with contact data
        const template = Handlebars.compile(variant.template);
        let htmlBody = template(contact);

        // b. Inject tracking pixel
        const trackingPixel = `<img src="http://localhost:4000/track/open/${sendId}" width="1" height="1" alt="" />`;
        htmlBody += trackingPixel;

        // c. Log the send event
        sendLogs[sendId] = { campaignId, variantKey, opened: false };
        variant.sent++;

        // d. Simulate sending email (in a real app, call AWS SES here)
        console.log(`--- SENDING EMAIL ---`);
        console.log(`To: ${contact.email}`);
        console.log(`Subject: ${variant.name}`);
        console.log(`Body: ${htmlBody}`);
        console.log(`---------------------\n`);
    });

    campaigns[campaignId] = campaign;
    res.status(201).json({ message: "Campaign sent successfully!", campaignId });
});

// --- 2. Open Tracking Endpoint ---
app.get('/track/open/:sendId', (req, res) => {
    const { sendId } = req.params;
    const log = sendLogs[sendId];

    if (log && !log.opened) {
        log.opened = true;
        const campaign = campaigns[log.campaignId];
        if (campaign) {
            campaign.variants[log.variantKey].opens++;
        }
        console.log(`[Tracker] Marked sendId ${sendId} as opened.`);
    }

    // Return a 1x1 transparent GIF
    const pixel = Buffer.from('R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7', 'base64');
    res.set({
        'Content-Type': 'image/gif',
        'Content-Length': pixel.length,
        'Cache-Control': 'no-cache, no-store, must-revalidate',
        'Pragma': 'no-cache',
        'Expires': 0
    });
    res.send(pixel);
});

// --- 3. Statistics Endpoint ---
app.get('/api/campaigns/:id/stats', (req, res) => {
    const { id } = req.params;
    const campaign = campaigns[id];

    if (!campaign) {
        return res.status(404).json({ error: "Campaign not found" });
    }

    const stats = {
        campaignId: campaign.id,
        totalSent: campaign.totalSent,
        variants: Object.entries(campaign.variants).map(([key, variant]) => {
            return {
                name: variant.name,
                sent: variant.sent,
                opens: variant.opens,
                openRate: variant.sent > 0 ? (variant.opens / variant.sent) * 100 : 0
            };
        })
    };

    res.json(stats);
});

const PORT = 4000;
app.listen(PORT, () => console.log(`Backend server running on http://localhost:${PORT}`));
```

