const API_URL = 'http://localhost:4000';

function App() {
  const [versionA, setVersionA] = useState({ name: 'Subject: Welcome to our Newsletter!', template: '<h1>Hello {{name}}!</h1><p>This is Version A. Thanks for signing up.</p>' });
  const [versionB, setVersionB] = useState({ name: 'Subject: You are in!', template: '<h1>Hey {{name}},</h1><p>Welcome aboard! This is Version B.</p>' });
  const [campaignId, setCampaignId] = useState(null);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleSendCampaign = async () => {
    setLoading(true);
    setStats(null);
    const contacts = [
      { name: 'Alice', email: 'alice@example.com', isPremium: true },
      { name: 'Bob', email: 'bob@example.com', isPremium: false },
      { name: 'Charlie', email: 'charlie@example.com', isPremium: false },
      { name: 'Diana', email: 'diana@example.com', isPremium: true },
    ];

    try {
      const response = await axios.post(`${API_URL}/api/campaigns/send`, { contacts, versionA, versionB });
      setCampaignId(response.data.campaignId);
      alert(`Campaign sent! Campaign ID: ${response.data.campaignId}`);
    } catch (error) {
      console.error("Error sending campaign:", error);
      alert("Failed to send campaign.");
    }
    setLoading(false);
  };

  useEffect(() => {
    if (!campaignId) return;

    const interval = setInterval(async () => {
      try {
        const response = await axios.get(`${API_URL}/api/campaigns/${campaignId}/stats`);
        setStats(response.data);
      } catch (error) {
        console.error("Error fetching stats:", error);
      }
    }, 2000); // Poll for stats every 2 seconds

    return () => clearInterval(interval);
  }, [campaignId]);

  const chartData = {
    labels: stats ? stats.variants.map(v => v.name) : [],
    datasets: [
      {
        label: 'Open Rate (%)',
        data: stats ? stats.variants.map(v => v.openRate.toFixed(2)) : [],
        backgroundColor: ['rgba(54, 162, 235, 0.6)', 'rgba(255, 99, 132, 0.6)'],
        borderColor: ['rgba(54, 162, 235, 1)', 'rgba(255, 99, 132, 1)'],
        borderWidth: 1,
      },
    ],
  };

  return (
    <div className="container">
      <h1>Intelligent Email Template Generator</h1>

      <div className="editor-grid">
        <div className="editor-container">
          <h2>Version A</h2>
          <input 
            type="text" 
            value={versionA.name} 
            onChange={(e) => setVersionA({ ...versionA, name: e.target.value })}
            placeholder="Subject Line A"
          />
          <ReactQuill theme="snow" value={versionA.template} onChange={(val) => setVersionA({ ...versionA, template: val })} />
        </div>
        <div className="editor-container">
          <h2>Version B</h2>
          <input 
            type="text" 
            value={versionB.name} 
            onChange={(e) => setVersionB({ ...versionB, name: e.target.value })}
            placeholder="Subject Line B"
          />
          <ReactQuill theme="snow" value={versionB.template} onChange={(val) => setVersionB({ ...versionB, template: val })} />
        </div>
      </div>

      <button onClick={handleSendCampaign} disabled={loading}>
        {loading ? 'Sending...' : '🚀 Send A/B Test Campaign'}
      </button>

      {campaignId && (
        <div className="stats-container">
          <h2>Campaign Results (ID: {campaignId})</h2>
          {stats ? (
            <>
              <div className="stats-grid">
                {stats.variants.map(v => (
                  <div key={v.name} className="stat-card">
                    <h3>{v.name}</h3>
                    <p>Sent: {v.sent}</p>
                    <p>Opens: {v.opens}</p>
                    <p><strong>Open Rate: {v.openRate.toFixed(2)}%</strong></p>
                  </div>
                ))}
              </div>
              <div className="chart-container">
                <Bar 
                  data={chartData} 
                  options={{ 
                    responsive: true, 
                    plugins: { legend: { position: 'top' }, title: { display: true, text: 'A/B Test Open Rate Comparison' } },
                    scales: { y: { beginAtZero: true, max: 100 } }
                  }} 
                />
              </div>
            </>
          ) : <p>Fetching stats...</p>}
        </div>
      )}
    </div>
  );
}

export default App;
```

