### Step 2: Backend Implementation (Node.js & Express)

Now, let's build the server. It will have two main responsibilities:
1.  Receive individual file chunks and store them temporarily.
2.  Receive a "merge" request to combine the chunks into the final file.

**`server.js`**

```javascript
const express = require('express');
const multer = require('multer');
const cors = require('cors');
const path = require('path');
const fs = require('fs-extra');

const app = express();
const PORT = 3000;

// --- Directory Constants ---
const UPLOAD_DIR = path.join(__dirname, 'uploads');
const TEMP_DIR = path.join(__dirname, 'temp_chunks');

// --- Ensure directories exist ---
fs.ensureDirSync(UPLOAD_DIR);
fs.ensureDirSync(TEMP_DIR);

// --- Middleware ---
app.use(cors()); // Enable CORS for all routes
app.use(express.static(path.join(__dirname, 'public'))); // Serve static frontend files

// --- Multer Setup for Chunk Storage ---
// We configure multer to store chunks in our temporary directory without changing their names.
const storage = multer.diskStorage({
    destination: (req, file, cb) => {
        // Chunks are stored in a temporary directory named after the file hash
        const { fileHash } = req.body;
        const chunkDir = path.join(TEMP_DIR, fileHash);
        fs.ensureDirSync(chunkDir);
        cb(null, chunkDir);
    },
    filename: (req, file, cb) => {
        // Chunks are named by their index
        const { chunkIndex } = req.body;
        cb(null, chunkIndex);
    },
});

const upload = multer({ storage });

// --- API Endpoints ---

/**
 * @route POST /upload
 * @description Handles the upload of a single file chunk.
 */
app.post('/upload', upload.single('chunk'), (req, res) => {
    // The 'chunk' in upload.single('chunk') must match the FormData key from the frontend.
    if (!req.file) {
        return res.status(400).send('No chunk uploaded.');
    }
    res.status(200).send('Chunk uploaded successfully.');
});

/**
 * @route POST /merge
 * @description Merges the uploaded chunks into a single file.
 */
app.post('/merge', express.json(), async (req, res) => {
    const { fileName, fileHash } = req.body;
    if (!fileName || !fileHash) {
        return res.status(400).send('Missing fileName or fileHash.');
    }

    const chunkDir = path.join(TEMP_DIR, fileHash);
    const finalFilePath = path.join(UPLOAD_DIR, fileName);

    try {
        // Read all chunk filenames from the temporary directory
        const chunkFiles = await fs.readdir(chunkDir);

        // Sort chunks by their index to ensure correct order
        chunkFiles.sort((a, b) => parseInt(a) - parseInt(b));

        // Create a write stream for the final file
        const writeStream = fs.createWriteStream(finalFilePath);

        // Sequentially merge each chunk
        for (const chunkFile of chunkFiles) {
            const chunkPath = path.join(chunkDir, chunkFile);
            const chunkBuffer = await fs.readFile(chunkPath);
            writeStream.write(chunkBuffer);
            await fs.unlink(chunkPath); // Delete chunk after merging
        }

        writeStream.end();

        // Clean up the temporary directory for this file
        await fs.rmdir(chunkDir);

        res.status(200).json({ message: 'File merged successfully!', filePath: `/uploads/${fileName}` });

    } catch (error) {
        console.error('Error merging chunks:', error);
        res.status(500).send('Error merging file.');
    }
});


// --- Start Server ---
app.listen(PORT, () => {
    console.log(`Server is running on http://localhost:${PORT}`);
});
```

