**`public/script.js`**

```javascript
document.addEventListener('DOMContentLoaded', () => {
    const fileInput = document.getElementById('fileInput');
    const uploadButton = document.getElementById('uploadButton');
    const progressBar = document.getElementById('progressBar');
    const statusDiv = document.getElementById('status');

    const CHUNK_SIZE = 5 * 1024 * 1024; // 5MB chunk size
    const SERVER_URL = 'http://localhost:3000';

    uploadButton.addEventListener('click', async () => {
        const file = fileInput.files[0];
        if (!file) {
            updateStatus('Please select a file first.');
            return;
        }

        uploadButton.disabled = true;
        updateStatus('Starting upload...');

        try {
            // 1. Calculate file hash (for unique identification on the server)
            updateStatus('Calculating file hash...');
            const fileHash = await calculateFileHash(file);

            // 2. Create chunks
            const totalChunks = Math.ceil(file.size / CHUNK_SIZE);
            const chunks = [];
            for (let i = 0; i < totalChunks; i++) {
                const start = i * CHUNK_SIZE;
                const end = Math.min(start + CHUNK_SIZE, file.size);
                chunks.push(file.slice(start, end));
            }

            // 3. Upload chunks
            let uploadedChunks = 0;
            for (let i = 0; i < chunks.length; i++) {
                const formData = new FormData();
                formData.append('chunk', chunks[i]);
                formData.append('fileHash', fileHash);
                formData.append('chunkIndex', i);

                await fetch(`${SERVER_URL}/upload`, {
                    method: 'POST',
                    body: formData,
                });

                uploadedChunks++;
                const progress = Math.round((uploadedChunks / totalChunks) * 100);
                updateProgress(progress);
                updateStatus(`Uploading chunk ${uploadedChunks} of ${totalChunks}...`);
            }

            // 4. Send merge request
            updateStatus('All chunks uploaded. Merging file...');
            const response = await fetch(`${SERVER_URL}/merge`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    fileName: file.name,
                    fileHash: fileHash,
                }),
            });

            if (!response.ok) {
                throw new Error('Failed to merge file on server.');
            }

            const result = await response.json();
            updateStatus(`Upload complete! File available at: ${result.filePath}`);
            updateProgress(100);

        } catch (error) {
            console.error('Upload failed:', error);
            updateStatus(`Error: ${error.message}`);
            updateProgress(0); // Reset progress on failure
        } finally {
            uploadButton.disabled = false;
        }
    });

    /**
     * Calculates the SHA-256 hash of a file.
     * @param {File} file - The file to hash.
     * @returns {Promise<string>} The hex-encoded hash.
     */
    async function calculateFileHash(file) {
        const buffer = await file.arrayBuffer();
        const hashBuffer = await crypto.subtle.digest('SHA-256', buffer);
        const hashArray = Array.from(new Uint8Array(hashBuffer));
        return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    }

    function updateStatus(message) {
        statusDiv.textContent = message;
    }

    function updateProgress(percentage) {
        progressBar.style.width = `${percentage}%`;
    }
});
```

